/* v47 generated 2014 SRD spell catalogue — 319 records. */
((root)=>{'use strict';const schools={"Abjuration":"Koruma","Conjuration":"Çağırma","Divination":"Kehanet","Enchantment":"Etkileme","Evocation":"Yıkım","Illusion":"İllüzyon","Necromancy":"Nekromansi","Transmutation":"Dönüşüm"};const scrollTable={"0":{"rarity":"common","rarityLabel":"Yaygın","dc":13,"attack":5},"1":{"rarity":"common","rarityLabel":"Yaygın","dc":13,"attack":5},"2":{"rarity":"uncommon","rarityLabel":"Seyrek","dc":13,"attack":5},"3":{"rarity":"uncommon","rarityLabel":"Seyrek","dc":15,"attack":7},"4":{"rarity":"rare","rarityLabel":"Nadir","dc":15,"attack":7},"5":{"rarity":"rare","rarityLabel":"Nadir","dc":17,"attack":9},"6":{"rarity":"veryRare","rarityLabel":"Çok Nadir","dc":17,"attack":9},"7":{"rarity":"veryRare","rarityLabel":"Çok Nadir","dc":18,"attack":10},"8":{"rarity":"veryRare","rarityLabel":"Çok Nadir","dc":18,"attack":10},"9":{"rarity":"legendary","rarityLabel":"Efsanevi","dc":19,"attack":11}};const spells=[{"id":"acid-arrow","name":"Acid Arrow","nameTr":"Asit Oku","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"90 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Toz haline getirilmiş ravent yaprağı ve bir engerek midesi.","materialSource":"Powdered rhubarb leaf and an adder's stomach.","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Parıldayan yeşil bir ok menzil içindeki bir hedefe doğru ilerliyor ve bir acid spreyi halinde patlıyor. Hedefe karşı bir menzilli spell attack yapın. Hedef, bir vuruşta anında 4d4 acid hasarı alır ve bir sonraki turun sonunda 2d4 acid hasarı alır. İsabetsiz kaldığında ok, ilk hasarın yarısı kadar acid ile hedefe sıçrar ve bir sonraki turun sonunda hiç hasar vermez.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar (hem başlangıçta hem de daha sonra), 2. seviyenin üzerindeki her yuva seviyesi için 1d4 artar.","sourceText":"A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd."},{"id":"acid-splash","name":"Acid Splash","nameTr":"Asit Sıçraması","level":0,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":null,"description":"Bir acid balonu fırlatırsınız. Menzil dahilindeki bir yaratığı seçin veya menzil içinde birbirinin 5 ft yakınında bulunan iki yaratık seçin. Bir hedef DEX saving throw üzerinde başarılı olmalı veya 1d6 acid hasarı almalıdır.\nBu büyünün hasarı, 5. seviyeye (2d6), 11. seviyeye (3d6) ve 17. seviyeye (4d6) ulaştığınızda 1d6 artar.","higher":"","sourceText":"You hurl a bubble of acid. Choose one creature within range, or choose two creatures within range that are within 5 feet of each other. A target must succeed on a dexterity saving throw or take 1d6 acid damage.\n\nThis spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).","higherSource":""},{"id":"aid","name":"Aid","nameTr":"Yardım","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir beyaz kumaş şeridi.","materialSource":"A tiny strip of white cloth.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyünüz müttefiklerinizi dayanıklılık ve kararlılıkla güçlendirir. Menzil içindeki en fazla üç yaratık seçin. Her hedefin maksimum can puanı ve mevcut HP, bu süre boyunca 5 birim artar.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hedefin HP'si 2. seviyenin üzerindeki her slot seviyesi için ilave 5 artar.","sourceText":"Your spell bolsters your allies with toughness and resolve. Choose up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, a target's hit points increase by an additional 5 for each slot level above 2nd."},{"id":"alarm","name":"Alarm","nameTr":"Alarm","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Ranger","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"30 feet","duration":"8 hours","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Minik bir çan ve bir parça ince gümüş tel.","materialSource":"A tiny bell and a piece of fine silver wire.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":20},"description":"İstenmeyen izinsiz girişlere karşı bir alarm ayarlarsınız. Menzil dahilindeki bir 20 ft küpünden daha büyük olmayan bir kapı, pencere veya alan seçin. Büyü bitene kadar, Minik veya daha büyük bir yaratık korunan alana dokunduğunda veya girdiğinde bir alarm sizi uyarır. Büyüyü yaptığınızda alarmı çalıştırmayacak yaratıkları belirleyebilirsiniz. Ayrıca alarmın zihinsel mi yoksa sesli mi olacağını da seçersiniz.\nKorunan bölgenin 1 mil yakınındaysanız, zihinsel bir alarm zihninizde bir ping sesiyle sizi uyarır. Uyuyorsanız bu ping sizi uyandırır.\nSesli bir alarm, 60 ft dahilinde 10 saniye boyunca bir el zili sesi üretir.","higher":"","sourceText":"You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won't set off the alarm. You also choose whether the alarm is mental or audible.\n\nA mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping.\n\nAn audible alarm produces the sound of a hand bell for 10 seconds within 60 feet.","higherSource":""},{"id":"alter-self","name":"Alter Self","nameTr":"Kendini Değiştir","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Farklı bir forma bürünürsünüz. Büyüyü yaptığınızda, etkileri büyünün süresi boyunca devam edecek olan aşağıdaki seçeneklerden birini seçin. Büyü devam ederken, farklı bir seçeneğin faydalarını elde etmek için bir seçeneği eylem olarak sonlandırabilirsiniz.\n***Suya Adaptasyon.*** Solungaçlarınız filizlenerek ve parmaklarınızın arasında ağlar oluşturarak vücudunuzu su ortamına adapte edersiniz. Su altında nefes alabilir ve yürüme hızınıza eşit bir yüzme hızı kazanabilirsiniz.\n***Görünümü Değiştir.*** Görünümünüzü dönüştürürsünüz. Boyunuz, kilonuz, yüz hatlarınız, sesinizin tonu, saç uzunluğunuz, renginiz ve varsa ayırt edici özellikleriniz dahil olmak üzere neye benzeyeceğinize siz karar verirsiniz. İstatistiklerinizin hiçbiri değişmese de kendinizi başka bir ırkın üyesi gibi gösterebilirsiniz. Ayrıca sizden farklı büyüklükte bir yaratık olarak görünemezsiniz ve temel şekliniz aynı kalır; Örneğin iki ayaklıysanız bu büyüyü dört ayaklı olmak için kullanamazsınız. Büyünün süresi boyunca istediğiniz zaman, eyleminizi kullanarak görünümünüzü tekrar bu şekilde değiştirebilirsiniz.\n***Doğal Silahlar.*** Pençeler, dişler, dikenler, boynuzlar veya seçtiğiniz farklı bir doğal silah yetiştirirsiniz. Silahsız saldırılarınız, seçtiğiniz doğal silaha uygun olarak 1d6 bludgeoning, piercing veya slashing hasarı verir ve silahsız saldırılarınızda ustalaşırsınız. Son olarak, doğal silah sihirdir ve onu kullanarak yaptığınız saldırı ve hasar atışlarına +1 bonus verirsiniz.","higher":"","sourceText":"You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.\n\n***Aquatic Adaptation.*** You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.\n\n***Change Appearance.*** You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can't appear as a creature of a different size than you, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.\n\n***Natural Weapons.*** You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it.","higherSource":""},{"id":"animal-friendship","name":"Animal Friendship","nameTr":"Hayvan Dostluğu","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Druid","Ranger"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir lokma yiyecek.","materialSource":"A morsel of food.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bu büyü, bir canavarı ona zarar vermek istemediğinize ikna etmenizi sağlar. Menzil içinde görebileceğiniz bir canavar seçin. Seni görmeli ve duymalı. Canavarın INT'si 4 veya daha yüksekse büyü başarısız olur. Aksi takdirde, canavarın WIS saving throw üzerinde başarılı olması veya büyü süresi boyunca sizin tarafınızdan charmed olması gerekir. Siz veya arkadaşlarınızdan biri hedefe zarar verirse büyüler sona erer.","higher":"","sourceText":"This spell lets you convince a beast that you mean it no harm. Choose a beast that you can see within range. It must see and hear you. If the beast's Intelligence is 4 or higher, the spell fails. Otherwise, the beast must succeed on a wisdom saving throw or be charmed by you for the spell's duration. If you or one of your companions harms the target, the spells ends.","higherSource":""},{"id":"animal-messenger","name":"Animal Messenger","nameTr":"Hayvan Habercisi","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"24 hours","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir lokma yiyecek.","materialSource":"A morsel of food.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü sayesinde bir hayvanı kullanarak mesaj iletebilirsiniz. Sincap, mavi alakarga veya yarasa gibi menzil içinde görebileceğiniz minik bir canavarı seçin. Ziyaret etmiş olmanız gereken bir konumu ve \"kasaba muhafızı üniforması giymiş bir erkek veya kadın\" veya \"sivri şapkalı kızıl saçlı bir cüce\" ​​gibi genel bir tanıma uyan bir alıcıyı belirtirsiniz. Ayrıca yirmi beş kelimeye kadar bir mesaj söylüyorsunuz. Hedef canavar, büyünün süresi boyunca belirtilen konuma doğru seyahat eder ve uçan bir haberci için 24 saatte yaklaşık 50 mil veya diğer hayvanlar için 25 mil kat eder.\nHaberci geldiğinde, sesinizi taklit ederek mesajınızı tanımladığınız yaratığa iletir. Haberci yalnızca verdiğiniz tanıma uyan bir yaratıkla konuşuyor. Eğer haberci büyü sona ermeden hedefine ulaşamazsa mesaj kaybolur ve canavar bu büyüyü yaptığınız yere geri döner.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaparsanız, büyünün süresi 2. seviyenin üzerindeki her yuva seviyesi için 48 saat artar.","sourceText":"By means of this spell, you use an animal to deliver a message. Choose a Tiny beast you can see within range, such as a squirrel, a blue jay, or a bat. You specify a location, which you must have visited, and a recipient who matches a general description, such as \"a man or woman dressed in the uniform of the town guard\" or \"a red-haired dwarf wearing a pointed hat.\" You also speak a message of up to twenty-five words. The target beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger, or 25 miles for other animals.\n\nWhen the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. The messenger speaks only to a creature matching the description you gave. If the messenger doesn't reach its destination before the spell ends, the message is lost, and the beast makes its way back to where you cast this spell.","higherSource":"If you cast this spell using a spell slot of 3nd level or higher, the duration of the spell increases by 48 hours for each slot level above 2nd."},{"id":"animal-shapes","name":"Animal Shapes","nameTr":"Hayvan Şekilleri","level":8,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 24 hours","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Sihriniz başkalarını canavara dönüştürüyor. Menzil içinde görebileceğiniz herhangi bir sayıda istekli yaratığı seçin. Her hedefi, meydan okuma derecesi 4 veya daha düşük olan Büyük veya daha küçük bir canavar biçimine dönüştürürsünüz. Sonraki turlarda eyleminizi etkilenen yaratıkları yeni formlara dönüştürmek için kullanabilirsiniz.\nDönüşüm, her hedefin süresi boyunca veya hedef 0 HP'ye düşene veya ölene kadar sürer. Her hedef için farklı bir form seçebilirsiniz. Hedefin oyun istatistikleri, seçilen canavarın istatistikleriyle değiştirilir, ancak hedef hizalamasını ve INT, WIS ve CHA puanlarını korur. Hedef, yeni formundaki HP'yi alır ve normal formuna döndüğünde, dönüşmeden önceki HP sayısına geri döner. 0 HP'ye düşme sonucunda geri dönerse, fazla hasar normal formuna taşınır. Aşırı hasar yaratığın normal formunu 0 HP'ye düşürmediği sürece, unconscious devrilmez. Canlı, yeni formunun doğası gereği yapabileceği eylemlerde sınırlıdır, konuşamaz ve büyü yapamaz.\nHedefin donanımı yeni forma dönüşür. Hedef, ekipmanlarından herhangi birini etkinleştiremez, kullanamaz veya başka şekilde yararlanamaz.","higher":"","sourceText":"Your magic turns others into beasts. Choose any number of willing creatures that you can see within range. You transform each target into the form of a Large or smaller beast with a challenge rating of 4 or lower. On subsequent turns, you can use your action to transform affected creatures into new forms.\n\nThe transformation lasts for the duration for each target, or until the target drops to 0 hit points or dies. You can choose a different form for each target. A target's game statistics are replaced by the statistics of the chosen beast, though the target retains its alignment and Intelligence, Wisdom, and Charisma scores. The target assumes the hit points of its new form, and when it reverts to its normal form, it returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious. The creature is limited in the actions it can perform by the nature of its new form, and it can't speak or cast spells.\n\nThe target's gear melds into the new form. The target can't activate, wield, or otherwise benefit from any of its equipment.","higherSource":""},{"id":"animate-dead","name":"Animate Dead","nameTr":"Ölüleri Canlandır","level":3,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla kan, bir parça et ve bir tutam kemik tozu.","materialSource":"A drop of blood, a piece of flesh, and a pinch of bone dust.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü ölümsüz bir hizmetçi yaratır. Menzildeki bir kemik yığınını veya Orta veya Küçük bir insansı cesedi seçin. Büyünüz hedefe kötü bir yaşam taklidi aşılayarak onu ölümsüz bir yaratık olarak yükseltir. Hedef, kemikleri seçerseniz bir iskelete, bir cesedi seçerseniz bir zombiye dönüşür (GM, yaratığın oyun istatistiklerine sahiptir).\nHer turunuzda, eğer yaratık 60 ft yakınınızdaysa, bu büyüyle yaptığınız herhangi bir yaratığa zihinsel olarak komut vermek için bir Bonus Action kullanabilirsiniz (birden fazla yaratığı kontrol ediyorsanız, bunların herhangi birine veya tümüne aynı anda komut verebilirsiniz, her birine aynı komutu verebilirsiniz). Yaratığın bir sonraki dönüşte hangi eylemi gerçekleştireceğine ve nereye hareket edeceğine siz karar verirsiniz veya belirli bir odayı veya koridoru korumak gibi genel bir komut verebilirsiniz. Hiçbir komut vermezseniz yaratık yalnızca kendisini düşman yaratıklara karşı savunur. Bir emir verildiğinde yaratık, görevi tamamlanana kadar onu takip etmeye devam eder.\nYaratık 24 saat boyunca sizin kontrolünüz altındadır ve sonrasında ona verdiğiniz hiçbir komuta uymayı bırakır. Yaratığın kontrolünü 24 saat daha sürdürmek için, mevcut 24 saatlik süre sona ermeden bu büyüyü yaratığa tekrar yapmalısınız. Büyünün bu kullanımı, yeni bir canlıyı canlandırmak yerine, bu büyüyle canlandırdığınız en fazla dört yaratık üzerinde kontrolünüzü yeniden sağlar.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 3. seviyenin üzerindeki her yuva seviyesi için iki ek ölümsüz yaratığı canlandırır veya yeniden kontrol altına alırsınız. Yaratıkların her biri farklı bir cesetten veya kemik yığınından gelmiş olmalı.","sourceText":"This spell creates an undead servant. Choose a pile of bones or a corpse of a Medium or Small humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse (the GM has the creature's game statistics).\n\nOn each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you've given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over up to four creatures you have animated with this spell, rather than animating a new one.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, you animate or reassert control over two additional undead creatures for each slot level above 3rd. Each of the creatures must come from a different corpse or pile of bones."},{"id":"animate-objects","name":"Animate Objects","nameTr":"Nesneleri Canlandır","level":5,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Nesneler emrinizde canlanıyor. Menzildeki, giyilmeyen veya taşınmayan on adede kadar sihirli olmayan nesneyi seçin. Orta büyüklükteki hedefler iki nesne olarak sayılır, Büyük hedefler dört nesne olarak sayılır, Büyük hedefler sekiz nesne olarak sayılır. Devasa boyuttan daha büyük herhangi bir nesneyi canlandıramazsınız. Her hedef, büyü bitene veya 0 HP'ye düşene kadar canlandırılır ve kontrolünüz altında bir yaratık haline gelir.\nBir Bonus Action olarak, eğer yaratık 500 ft yakınınızdaysa, bu büyüyle yaptığınız herhangi bir yaratığa zihinsel olarak komut verebilirsiniz (birden fazla yaratığı kontrol ediyorsanız, bunların herhangi birine veya hepsine aynı anda komut verebilirsiniz, her birine aynı komutu verebilirsiniz). Yaratığın bir sonraki dönüşte hangi eylemi gerçekleştireceğine ve nereye hareket edeceğine siz karar verirsiniz veya belirli bir odayı veya koridoru korumak gibi genel bir komut verebilirsiniz. Hiçbir komut vermezseniz yaratık yalnızca kendisini düşman yaratıklara karşı savunur. Bir emir verildiğinde yaratık, görevi tamamlanana kadar onu takip etmeye devam eder.\n##### Animasyonlu Nesne İstatistikleri\n| Boyut | HP | klima | Saldırı | Cadde | Dex |\n|---|---|---|---|---|---|\n| Minik | 20 | 18 | Vuruş için +8, 1d4+4 hasar | 4 | 18 |\n| Küçük | 25 | 16 | Vuruş için +6, 1d8+2 hasar | 6 | 14 |\n| Orta | 40 | 13 | Vuruş için +5, 2d6+1 hasar | 10 | 12 |\n| Büyük | 50 | 10 | Vuruş için +6, 2d10+2 hasar | 14 | 10 |\n| Devasa | 80 | 10 | Vuruş için +8, 2d12+4 hasar | 18 | 6 |\nAnimasyonlu bir nesne, boyutuna göre belirlenen AC, HP, saldırılar, STR ve DEX içeren bir yapıdır. CON'si 10, INT ve WIS'si 3, CHA'si 1'dir. Hızı 30 ft'dir; nesnenin hareket için kullanabileceği bacakları veya diğer uzantıları yoksa, bunun yerine 30 ft uçuş hızına sahiptir ve havada asılı kalabilir. Nesne bir yüzeye veya duvara cıvatalanmış bir zincir gibi daha büyük bir nesneye güvenli bir şekilde tutturulmuşsa hızı 0'dır. 30 ft yarıçaplı kör görüşe sahiptir ve bu mesafenin ötesinde kördür. Animasyonlu nesne 0 HP'ye düştüğünde orijinal nesne formuna geri döner ve kalan hasar orijinal nesne formuna taşınır.\nBir nesneye saldırı komutunu verirseniz, 5 ft içindeki bir yaratığa tek bir yakın dövüş saldırısı yapabilir. Boyutuna göre belirlenen saldırı bonusu ve bludgeoning hasarıyla çarpma saldırısı yapar. GM, belirli bir nesnenin biçimine bağlı olarak slashing veya piercing hasarına neden olduğuna karar verebilir.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaparsanız, 5. seviyenin üzerindeki her yuva seviyesi için iki ek nesneyi canlandırabilirsiniz.","sourceText":"Objects come to life at your command. Choose up to ten nonmagical objects within range that are not being worn or carried. Medium targets count as two objects, Large targets count as four objects, Huge targets count as eight objects. You can't animate any object larger than Huge. Each target animates and becomes a creature under your control until the spell ends or until reduced to 0 hit points.\n\nAs a bonus action, you can mentally command any creature you made with this spell if the creature is within 500 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\n##### Animated Object Statistics\n\n| Size | HP | AC | Attack | Str | Dex |\n\n|---|---|---|---|---|---|\n\n| Tiny | 20 | 18 | +8 to hit, 1d4 + 4 damage | 4 | 18 |\n\n| Small | 25 | 16 | +6 to hit, 1d8 + 2 damage | 6 | 14 |\n\n| Medium | 40 | 13 | +5 to hit, 2d6 + 1 damage | 10 | 12 |\n\n| Large | 50 | 10 | +6 to hit, 2d10 + 2 damage | 14 | 10 |\n\n| Huge | 80 | 10 | +8 to hit, 2d12 + 4 damage | 18 | 6 |\n\nAn animated object is a construct with AC, hit points, attacks, Strength, and Dexterity determined by its size. Its Constitution is 10 and its Intelligence and Wisdom are 3, and its Charisma is 1. Its speed is 30 feet; if the object lacks legs or other appendages it can use for locomotion, it instead has a flying speed of 30 feet and can hover. If the object is securely attached to a surface or a larger object, such as a chain bolted to a wall, its speed is 0. It has blindsight with a radius of 30 feet and is blind beyond that distance. When the animated object drops to 0 hit points, it reverts to its original object form, and any remaining damage carries over to its original object form.\n\nIf you command an object to attack, it can make a single melee attack against a creature within 5 feet of it. It makes a slam attack with an attack bonus and bludgeoning damage determined by its size. The GM might rule that a specific object inflicts slashing or piercing damage based on its form.","higherSource":"If you cast this spell using a spell slot of 6th level or higher, you can animate two additional objects for each slot level above 5th."},{"id":"antilife-shell","name":"Antilife Shell","nameTr":"Hayat Karşıtı Kabuk","level":5,"school":"Abjuration","schoolTr":"Koruma","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":10},"description":"Parıldayan bir bariyer 10 ft yarıçapında sizden dışarı doğru uzanır ve sizinle birlikte hareket eder, üzerinizde merkezde kalır ve yaşayan ölüler ve yapılar dışındaki yaratıkları dışarıda bırakır. Bariyer bu süre boyunca sürer.\nBariyer, etkilenen canlının geçmesini veya uzanmasını engeller. Etkilenen bir yaratık, bariyeri aşarak büyü yapabilir veya menzilli veya erişimli silahlarla saldırı yapabilir.\nEtkilenen bir yaratığın bariyerden geçmesini sağlayacak şekilde hareket ederseniz büyü sona erer.","higher":"","sourceText":"A shimmering barrier extends out from you in a 10-foot radius and moves with you, remaining centered on you and hedging out creatures other than undead and constructs. The barrier lasts for the duration.\n\nThe barrier prevents an affected creature from passing or reaching through. An affected creature can cast spells or make attacks with ranged or reach weapons through the barrier.\n\nIf you move so that an affected creature is forced to pass through the barrier, the spell ends.","higherSource":""},{"id":"antimagic-field","name":"Antimagic Field","nameTr":"Antisihir Alanı","level":8,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam toz demir veya demir talaşı.","materialSource":"A pinch of powdered iron or iron filings.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":10},"description":"10 ft yarıçap invisible antisihir küresi sizi çevreliyor. Bu alan çoklu evrene yayılan büyülü enerjiden ayrılmıştır. Kürenin içinde büyüler yapılamaz, çağrılan yaratıklar ortadan kaybolur ve hatta büyülü eşyalar bile sıradan hale gelir. Büyü sona erene kadar küre sizinle birlikte hareket eder ve sizi merkeze alır.\nBir eser veya tanrı tarafından yaratılanlar dışındaki büyüler ve diğer büyülü etkiler kürede bastırılır ve kürenin içine taşamaz. Bastırılmış bir büyüyü yapmak için harcanan slot tüketilir. Bir etki bastırıldığında çalışmaz ancak bastırılmış olarak harcadığı zaman, süresine göre sayılır.\n***Hedefli Etkiler.*** Küredeki bir yaratığı veya nesneyi hedef alan büyüler ve sihirli füze ve insanı büyüleme gibi diğer büyülü efektlerin, o hedef üzerinde hiçbir etkisi yoktur.\n***Büyü Alanları.*** Ateş topu gibi başka bir büyünün veya büyülü etkinin alanı kürenin içine kadar uzanamaz. Küre bir büyü alanıyla örtüşürse alanın küre tarafından kaplanan kısmı bastırılır. Örneğin, fire'den oluşan bir duvarın oluşturduğu alevler küre içinde bastırılır ve örtüşme yeterince büyükse duvarda bir boşluk oluşturulur.\n***Büyüler.*** Küredeki bir yaratık ya da nesne üzerindeki herhangi bir aktif büyü ya da başka bir büyülü etki, yaratık ya da nesne onun içindeyken bastırılır.\n***Sihirli Eşyalar.*** Kürede sihirli eşyaların özellikleri ve güçleri bastırılır. Örneğin, küredeki +1 uzun kılıç, büyülü olmayan bir uzun kılıç işlevi görür.\nBüyülü bir silahın özellikleri ve güçleri, küredeki bir hedefe karşı kullanılırsa veya küredeki bir saldırgan tarafından kullanılırsa bastırılır. Eğer sihirli bir silah veya bir parça sihirli mühimmat küreyi tamamen terk ederse (örneğin, kürenin dışındaki bir hedefe sihirli bir ok atarsanız veya sihirli bir mızrak atarsanız), eşyanın büyüsü, çıktığı anda bastırılmaz.\n***Büyülü Seyahat.*** Işınlanma ve düzlemsel seyahat, kürenin bu tür sihirli bir seyahatin varış noktası ya da kalkış noktası olmasına bakılmaksızın, kürede işe yaramaz. Başka bir konuma, dünyaya veya varoluş düzlemine açılan bir portalın yanı sıra ip numarası büyüsü tarafından yaratılan boyut dışı bir alana açılan bir açıklık, küre içindeyken geçici olarak kapanır.\n***Yaratıklar ve Nesneler*** Büyüyle çağrılan veya yaratılan bir yaratık veya nesne, küredeki varlığı geçici olarak yok olur. Böyle bir yaratık, yaratığın kapladığı alan artık kürenin içinde olmadığında anında yeniden ortaya çıkar.\n***Büyüyü Gider.*** Büyüyü ortadan kaldır gibi büyü ve büyülü efektlerin küre üzerinde hiçbir etkisi yoktur. Aynı şekilde, farklı büyü karşıtı alan büyüleri tarafından oluşturulan küreler de birbirini etkisiz hale getirmez.","higher":"","sourceText":"A 10-foot-radius invisible sphere of antimagic surrounds you. This area is divorced from the magical energy that suffuses the multiverse. Within the sphere, spells can't be cast, summoned creatures disappear, and even magic items become mundane. Until the spell ends, the sphere moves with you, centered on you.\n\nSpells and other magical effects, except those created by an artifact or a deity, are suppressed in the sphere and can't protrude into it. A slot expended to cast a suppressed spell is consumed. While an effect is suppressed, it doesn't function, but the time it spends suppressed counts against its duration.\n\n***Targeted Effects.*** Spells and other magical effects, such as magic missile and charm person, that target a creature or an object in the sphere have no effect on that target.\n\n***Areas of Magic.*** The area of another spell or magical effect, such as fireball, can't extend into the sphere. If the sphere overlaps an area of magic, the part of the area that is covered by the sphere is suppressed. For example, the flames created by a wall of fire are suppressed within the sphere, creating a gap in the wall if the overlap is large enough.\n\n***Spells.*** Any active spell or other magical effect on a creature or an object in the sphere is suppressed while the creature or object is in it.\n\n***Magic Items.*** The properties and powers of magic items are suppressed in the sphere. For example, a +1 longsword in the sphere functions as a nonmagical longsword.\n\nA magic weapon's properties and powers are suppressed if it is used against a target in the sphere or wielded by an attacker in the sphere. If a magic weapon or a piece of magic ammunition fully leaves the sphere (for example, if you fire a magic arrow or throw a magic spear at a target outside the sphere), the magic of the item ceases to be suppressed as soon as it exits.\n\n***Magical Travel.*** Teleportation and planar travel fail to work in the sphere, whether the sphere is the destination or the departure point for such magical travel. A portal to another location, world, or plane of existence, as well as an opening to an extradimensional space such as that created by the rope trick spell, temporarily closes while in the sphere.\n\n***Creatures and Objects.*** A creature or object summoned or created by magic temporarily winks out of existence in the sphere. Such a creature instantly reappears once the space the creature occupied is no longer within the sphere.\n\n***Dispel Magic.*** Spells and magical effects such as dispel magic have no effect on the sphere. Likewise, the spheres created by different antimagic field spells don't nullify each other.","higherSource":""},{"id":"antipathy-sympathy","name":"Antipathy/Sympathy","nameTr":"Antipati/Sempati","level":8,"school":"Enchantment","schoolTr":"Etkileme","classes":["Druid","Wizard"],"subclasses":[],"castingTime":"1 hour","range":"60 feet","duration":"10 days","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Antipati etkisi için sirkeye batırılmış bir parça şap ya da sempati etkisi için bir damla bal.","materialSource":"Either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":{"type":"cube","size":200},"description":"Bu büyü, seçtiğiniz yaratıkları çeker veya uzaklaştırır. Menzil içindeki bir şeyi, çok büyük veya daha küçük bir nesneyi veya yaratığı veya 200 ft küpünden daha büyük olmayan bir alanı hedeflersiniz. Daha sonra kırmızı ejderhalar, goblinler veya vampirler gibi bir tür akıllı yaratık belirtin. Hedefe, belirtilen yaratıkları bu süre boyunca çeken veya iten bir aura yerleştirirsiniz. Auranın etkisi olarak antipatiyi veya sempatiyi seçin.\n***Antipati.*** Büyü, belirlediğiniz türden yaratıkların, bölgeyi terk etme ve hedeften kaçınma konusunda yoğun bir istek duymasına neden olur. Böyle bir yaratık hedefi görebildiğinde veya 60 ft yakınına geldiğinde, yaratığın bir WIS saving throw üzerinde başarılı olması veya frightened olması gerekir. Yaratık, hedefi görebildiği veya onun 60 ft yakınında olduğu sürece frightened olarak kalır. frightened hedefin yanındayken yaratık, hedefi göremediği en yakın güvenli noktaya hareket etmek için hareketini kullanmalıdır. Yaratık hedeften 60 ft'den daha fazla uzaklaşırsa ve onu göremezse, yaratık artık frightened değildir, ancak hedefi yeniden görürse veya 60 ft içinde hareket ederse yaratık tekrar frightened olur.\n***Sempati.*** Büyü, belirtilen yaratıkların 60 ft içindeyken veya onu görebiliyorken hedefe yaklaşmak için yoğun bir dürtü hissetmelerine neden olur. Böyle bir yaratık hedefi görebildiğinde veya onun 60 ft yakınına geldiğinde, yaratığın bir WIS saving throw üzerinde başarılı olması veya alana girmek veya hedefe ulaşmak için hareket etmek için her dönüşte hareketini kullanması gerekir. Yaratık bunu yaptığında hedeften kendi isteğiyle uzaklaşamaz.\nHedef, etkilenen bir yaratığa zarar verirse veya başka şekilde zarar verirse, etkilenen yaratık, aşağıda açıklandığı gibi etkiyi sona erdirmek için bir WIS saving throw yapabilir.\n***Etkiyi Sona Erdirme.*** Etkilenen bir yaratık, hedefin 60 ft yakınında değilken veya onu görebilir durumdayken sırasını bitirirse, yaratık bir WIS saving throw yapar. Başarılı bir kurtarmanın ardından yaratık artık hedeften etkilenmez ve tiksinti veya çekicilik duygusunun büyülü olduğunu fark eder. Ek olarak, büyüden etkilenen bir yaratığa, büyü devam ettiği sürece her 24 saatte bir başka bir WIS saving throw yapılmasına izin verilir.\nBu etkiye karşı başarıyla kurtulan canlı, 1 dakika boyunca bu etkiye karşı bağışıklık kazanır, bu süre sonunda tekrar etkilenebilir.","higher":"","sourceText":"This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200-foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura's effect.\n\n***Antipathy.*** The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can't see the target. If the creature moves more than 60 feet from the target and can't see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it.\n\n***Sympathy.*** The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a wisdom saving throw or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can't willingly move away from the target.\n\nIf the target damages or otherwise harms an affected creature, the affected creature can make a wisdom saving throw to end the effect, as described below.\n\n***Ending the Effect.*** If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a wisdom saving throw. On a successful save, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another wisdom saving throw every 24 hours while the spell persists.\n\nA creature that successfully saves against this effect is immune to it for 1 minute, after which time it can be affected again.","higherSource":""},{"id":"arcane-eye","name":"Arcane Eye","nameTr":"Gizemli Göz","level":4,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric","Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz yarasa kürkü.","materialSource":"A bit of bat fur.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Bu süre boyunca havada asılı kalan, menzil içinde sihirli bir göz olan invisible'yi yaratırsınız.\n30 ft'ye giden, normal görüşe ve karanlık görüşe sahip olan gözden zihinsel olarak görsel bilgi alırsınız. Göz her yöne bakabilir.\nBir eylem olarak gözünüzü herhangi bir yönde 30 ft'ye doğru hareket ettirebilirsiniz. Gözün sizden ne kadar uzağa hareket edebileceğinin bir sınırı yoktur, ancak başka bir varoluş düzlemine giremez. Sağlam bir bariyer gözün hareketini engeller ancak göz, çapı 1 inç kadar küçük bir açıklıktan geçebilir.","higher":"","sourceText":"You create an invisible, magical eye within range that hovers in the air for the duration.\n\nYou mentally receive visual information from the eye, which has normal vision and darkvision out to 30 feet. The eye can look in every direction.\n\nAs an action, you can move the eye up to 30 feet in any direction. There is no limit to how far away from you the eye can move, but it can't enter another plane of existence. A solid barrier blocks the eye's movement, but the eye can pass through an opening as small as 1 inch in diameter.","higherSource":""},{"id":"arcane-hand","name":"Arcane Hand","nameTr":"Esrarlı El","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir yumurta kabuğu ve yılan derisi bir eldiven.","materialSource":"An eggshell and a snakeskin glove.","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz boş bir alanda parıldayan, yarı saydam force'den oluşan Büyük bir el yaratırsınız. El, büyünün süresi boyunca kalır ve sizin emrinizle hareket ederek kendi elinizin hareketlerini taklit eder.\nEl, maksimum vuruş noktanıza eşit AC 20 ve HP değerine sahip bir nesnedir. 0 HP'ye düşerse büyü sona erer. STR 26 (+8) ve DEX 10 (+0) değerine sahiptir. El yerini doldurmaz.\nBüyüyü yaptığınızda ve sonraki turlarınızda bir Bonus Action olarak, elinizi 60 ft'ye kadar hareket ettirebilir ve ardından onunla aşağıdaki efektlerden birini oluşturabilirsiniz.\n***Sıkılmış Yumruk.*** El, 5 ft içindeki bir yaratığa veya nesneye çarpar. Oyun istatistiklerinizi kullanarak el için bir yakın spell attack yapın. Bir vuruşta hedef 4d8 force hasarı alır.\n***Güçlü El*** El, 5 ft içindeki bir yaratığı seçtiğiniz yöne doğru itmeye çalışır. Hedefin STR (Atletizm) kontrolü ile itiraz edilen elin STR'si ile bir kontrol yapın. Hedef Orta veya daha küçükse kontrolde avantaj bulunur. Başarılı olursanız, el, hedefi 5 ft artı büyü yapma yeteneği değiştiricinizin beş katına eşit bir fit sayısına kadar iter. El, hedefin 5 ft dahilinde kalacak şekilde hedefle birlikte hareket eder.\n***Kavrayan El.*** El, 5 ft içindeki Devasa veya daha küçük bir yaratığı yakalamaya çalışır. Kıskacı çözmek için elin STR puanını kullanırsınız. Hedef Orta veya daha küçükse kontrolde avantaj bulunur. El hedefi yakalarken, elin hedefi ezmesi için Bonus Action kullanabilirsiniz. Bunu yaptığınızda hedef, 2d6 + büyü yapma yeteneği değiştiricinize eşit bludgeoning hasarı alır.\n***Araya Giren El.*** Siz elinize farklı bir komut verene kadar el, sizinle seçtiğiniz bir yaratık arasına girer. El sizinle hedef arasında kalacak şekilde hareket ederek hedefe karşı yarım koruma sağlar. STR puanı elin STR puanından küçük veya ona eşitse hedef elin boşluğunda hareket edemez. STR puanı elin STR puanından yüksekse, hedef elin alanı boyunca size doğru hareket edebilir ancak bu alan hedef için zorlu bir alandır.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, sıkılı yumruk seçeneğinin verdiği hasar 2d8 artar ve kavrayan elden gelen hasar 5. seviyenin üzerindeki her yuva seviyesi için 2d6 artar.","sourceText":"You create a Large hand of shimmering, translucent force in an unoccupied space that you can see within range. The hand lasts for the spell's duration, and it moves at your command, mimicking the movements of your own hand.\n\nThe hand is an object that has AC 20 and hit points equal to your hit point maximum. If it drops to 0 hit points, the spell ends. It has a Strength of 26 (+8) and a Dexterity of 10 (+0). The hand doesn't fill its space.\n\nWhen you cast the spell and as a bonus action on your subsequent turns, you can move the hand up to 60 feet and then cause one of the following effects with it.\n\n***Clenched Fist.*** The hand strikes one creature or object within 5 feet of it. Make a melee spell attack for the hand using your game statistics. On a hit, the target takes 4d8 force damage.\n\n***Forceful Hand.*** The hand attempts to push a creature within 5 feet of it in a direction you choose. Make a check with the hand's Strength contested by the Strength (Athletics) check of the target. If the target is Medium or smaller, you have advantage on the check. If you succeed, the hand pushes the target up to 5 feet plus a number of feet equal to five times your spellcasting ability modifier. The hand moves with the target to remain within 5 feet of it.\n\n***Grasping Hand.*** The hand attempts to grapple a Huge or smaller creature within 5 feet of it. You use the hand's Strength score to resolve the grapple. If the target is Medium or smaller, you have advantage on the check. While the hand is grappling the target, you can use a bonus action to have the hand crush it. When you do so, the target takes bludgeoning damage equal to 2d6 + your spellcasting ability modifier.\n\n***Interposing Hand.*** The hand interposes itself between you and a creature you choose until you give the hand a different command. The hand moves to stay between you and the target, providing you with half cover against the target. The target can't move through the hand's space if its Strength score is less than or equal to the hand's Strength score. If its Strength score is higher than the hand's Strength score, the target can move toward you through the hand's space, but that space is difficult terrain for the target.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the damage from the clenched fist option increases by 2d8 and the damage from the grasping hand increases by 2d6 for each slot level above 5th."},{"id":"arcane-lock","name":"Arcane Lock","nameTr":"Gizemli Kilit","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 25gp değerindeki altın tozu.","materialSource":"Gold dust worth at least 25gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kapalı bir kapıya, pencereye, kapıya, sandığa veya başka bir giriş yoluna dokunduğunuzda bu süre boyunca kilitli kalır. Bu büyüyü yaptığınızda siz ve belirlediğiniz yaratıklar nesneyi normal şekilde açabilirsiniz. Ayrıca nesnenin 5 ft içinde söylendiğinde bu büyüyü 1 dakika boyunca bastıracak bir şifre de ayarlayabilirsiniz. Aksi takdirde, bozuluncaya veya büyü bozuluncaya veya bastırılıncaya kadar geçilemez. Nesneye vurmak, büyü kilidini 10 dakika boyunca bastırır.\nBu büyüden etkilenirken nesnenin kırılması veya force açılması daha zordur; DC'yi kırmak veya üzerindeki herhangi bir kilidi açmak için 10 artar.","higher":"","sourceText":"You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes.\n\nWhile affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10.","higherSource":""},{"id":"arcane-sword","name":"Arcane Sword","nameTr":"Esrarlı Kılıç","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"250 gp değerinde, kabzası ve kulp kısmı bakır ve çinkodan yapılmış minyatür bir platin kılıç.","materialSource":"A miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp.","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde uçan, kılıç şeklinde bir force düzlemi yaratırsınız. Süresi boyunca devam eder.\nKılıç göründüğünde, kılıcın 5 ft içindeki seçtiğiniz bir hedefe karşı yakın spell attack yaparsınız. Bir vuruşta hedef 3d10 force hasarı alır. Büyü bitene kadar, her turunuzda bir Bonus Action kullanarak kılıcı 20 ft'ye kadar görebileceğiniz bir noktaya hareket ettirebilir ve bu saldırıyı aynı hedefe veya farklı bir hedefe karşı tekrarlayabilirsiniz.","higher":"","sourceText":"You create a sword-shaped plane of force that hovers within range. It lasts for the duration.\n\nWhen the sword appears, you make a melee spell attack against a target of your choice within 5 feet of the sword. On a hit, the target takes 3d10 force damage. Until the spell ends, you can use a bonus action on each of your turns to move the sword up to 20 feet to a spot you can see and repeat this attack against the same target or a different one.","higherSource":""},{"id":"arcanists-magic-aura","name":"Arcanist's Magic Aura","nameTr":"Arcanist'in Büyülü Aurası","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir kare ipek.","materialSource":"A small square of silk.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz bir yaratığa veya nesneye illüzyon yerleştirirsiniz, böylece kehanet büyüleri onun hakkında yanlış bilgiler ortaya çıkarır. Hedef istekli bir yaratık ya da başka bir canlı tarafından taşınmayan ya da giyilmeyen bir nesne olabilir.\nBüyüyü yaparken aşağıdaki efektlerden birini veya her ikisini de seçin. Etki süre boyunca sürer. Bu büyüyü 30 gün boyunca her gün aynı yaratık veya nesneye yaparsanız, her seferinde aynı etkiyi verirseniz, illüzyon ortadan kalkana kadar devam eder.\n***Yanlış Aura.*** Büyülü auraları algılayan büyü tespit etme gibi büyülere ve büyülü efektlere hedefin görünme şeklini değiştirirsiniz. Büyülü olmayan bir nesnenin büyülü görünmesini sağlayabilir, büyülü bir nesnenin büyülü olmayan görünmesini sağlayabilir veya nesnenin büyülü aurasını, seçtiğiniz belirli bir büyü okuluna aitmiş gibi görünecek şekilde değiştirebilirsiniz. Bu efekti bir nesne üzerinde kullandığınızda, sahte büyüyü, öğeyi kullanan herhangi bir yaratığın görmesini sağlayabilirsiniz.\n***Maske.*** Şövalyenin İlahi Duyusu veya bir sembol büyüsünün tetikleyicisi gibi yaratık türlerini tespit eden büyülere ve büyülü etkilere hedefin görünme şeklini değiştirirsiniz. Bir yaratık türü seçersiniz ve diğer büyüler ve büyülü etkiler, hedefe sanki o türde veya bu hizada bir yaratıkmış gibi davranır.","higher":"","sourceText":"You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn't being carried or worn by another creature.\n\nWhen you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.\n\n***False Aura.*** You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object's magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.\n\n***Mask.*** You change the way the target appears to spells and magical effects that detect creature types, such as a paladin's Divine Sense or the trigger of a symbol spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment.","higherSource":""},{"id":"astral-projection","name":"Astral Projection","nameTr":"Astral Projeksiyon","level":9,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Warlock","Wizard"],"subclasses":[],"castingTime":"1 hour","range":"10 feet","duration":"Special","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bu büyüyle etkilediğiniz her yaratık için, en az 1000 gp değerinde bir sümbül ve en az 100 gp değerinde süslü bir şekilde oyulmuş gümüş külçe sağlamalısınız; bunların tümü büyü tarafından tüketilir.","materialSource":"For each creature you affect with this spell, you must provide one jacinth worth at least 1,000gp and one ornately carved bar of silver worth at least 100gp, all of which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Siz ve menzil içindeki en fazla sekiz istekli yaratık, astral bedenlerinizi Astral Düzlem'e yansıtırsınız (büyü başarısız olur ve eğer zaten o düzlemdeyseniz, büyü boşa gider). Arkanızda bıraktığınız maddi gövde unconscious'dir ve animasyonu askıya alınmış durumdadır; yiyeceğe veya havaya ihtiyacı yoktur ve yaşlanmaz.\nAstral bedeniniz, oyun istatistiklerinizi ve sahip olduklarınızı kopyalayarak neredeyse her bakımdan ölümlü formunuza benzer. Temel fark, kürek kemiklerinizin arasından uzanan ve arkanızda uzanan, 1 ft'den sonra görünmez hale gelen gümüş renkli bir kordonun eklenmesidir. Bu kordon maddi bedeninize olan bağınızdır. İp sağlam kaldığı sürece evin yolunu bulabilirsin. Eğer kordon kesilirse (bu ancak bir etkinin bunu özellikle belirtmesi durumunda meydana gelebilecek bir durumdur) ruhunuz ve bedeniniz ayrılır ve sizi anında öldürür.\nAstral formunuz Astral Düzlemde özgürce seyahat edebilir ve oradaki portallardan geçerek başka herhangi bir düzeye gidebilir. Yeni bir uçağa girerseniz veya bu büyüyü yaparken bulunduğunuz uçağa geri dönerseniz, bedeniniz ve eşyalarınız gümüş kordon boyunca taşınarak yeni uçağa girerken bedeninize yeniden girmenizi sağlar. Astral formunuz ayrı bir enkarnasyondur. Ona uygulanan herhangi bir hasar veya diğer etkilerin fiziksel bedeniniz üzerinde hiçbir etkisi yoktur ve ona geri döndüğünüzde bunlar devam etmez.\nBüyüyü etkisiz hale getirmek için eyleminizi kullandığınızda büyü siz ve arkadaşlarınız için sona erer. Büyü sona erdiğinde etkilenen yaratık fiziksel bedenine döner ve uyanır.\nBüyü sizin veya arkadaşlarınızdan biri için de erken bitebilir. Astral veya fiziksel bir bedene karşı kullanılan başarılı bir yok etme büyüsü, o yaratığın büyüsünü sona erdirir. Bir yaratığın orijinal bedeni veya astral formu 0 HP'ye düşerse büyü o yaratık için sona erer. Büyü sona ererse ve gümüş kordon sağlamsa, kordon yaratığın astral formunu vücuduna geri çekerek askıya alınmış animasyon durumuna son verir.\nVücudunuza vaktinden önce geri dönerseniz, arkadaşlarınız astral formlarında kalır ve genellikle 0 HP'ye düşerek bedenlerine geri dönüş yolunu bulmak zorundadır.","higher":"","sourceText":"You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane). The material body you leave behind is unconscious and in a state of suspended animation; it doesn't need food or air and doesn't age.\n\nYour astral body resembles your mortal form in almost every way, replicating your game statistics and possessions. The principal difference is the addition of a silvery cord that extends from between your shoulder blades and trails behind you, fading to invisibility after 1 foot. This cord is your tether to your material body. As long as the tether remains intact, you can find your way home. If the cord is cut--something that can happen only when an effect specifically states that it does--your soul and body are separated, killing you instantly.\n\nYour astral form can freely travel through the Astral Plane and can pass through portals there leading to any other plane. If you enter a new plane or return to the plane you were on when casting this spell, your body and possessions are transported along the silver cord, allowing you to re-enter your body as you enter the new plane. Your astral form is a separate incarnation. Any damage or other effects that apply to it have no effect on your physical body, nor do they persist when you return to it.\n\nThe spell ends for you and your companions when you use your action to dismiss it. When the spell ends, the affected creature returns to its physical body, and it awakens.\n\nThe spell might also end early for you or one of your companions. A successful dispel magic spell used against an astral or physical body ends the spell for that creature. If a creature's original body or its astral form drops to 0 hit points, the spell ends for that creature. If the spell ends and the silver cord is intact, the cord pulls the creature's astral form back to its body, ending its state of suspended animation.\n\nIf you are returned to your body prematurely, your companions remain in their astral forms and must find their own way back to their bodies, usually by dropping to 0 hit points.","higherSource":""},{"id":"augury","name":"Augury","nameTr":"Kehanet","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 minute","range":"Self","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"En az 25gp değerinde, özel olarak işaretlenmiş çubuklar, kemikler veya benzeri jetonlar.","materialSource":"Specially marked sticks, bones, or similar tokens worth at least 25gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Mücevher işlemeli çubuklar atarak, ejderha kemiklerini yuvarlayarak, süslü kartlar dizerek veya başka bir kehanet aracı kullanarak, önümüzdeki 30 dakika içinde gerçekleştirmeyi planladığınız belirli bir eylem planının sonuçları hakkında başka bir dünyaya ait bir varlıktan bir kehanet alırsınız. GM aşağıdaki olası alametler arasından seçim yapar:\n- İyi sonuçlar için iyi şanslar\n- Vay, kötü sonuçlara\n- Hem iyi hem de kötü sonuçlar için refah ve keder\n- Hiçbir şey, özellikle iyi ya da kötü olmayan sonuçlar için\nBüyü, ek büyü yapılması veya bir yoldaşın kaybedilmesi veya kazanılması gibi sonucu değiştirebilecek olası koşulları hesaba katmaz.\nBir sonraki uzun dinlenmenizi tamamlamadan önce büyüyü iki veya daha fazla kez yaparsanız, ilkinden sonraki her kullanım için rastgele bir okuma alma şansınız kümülatif yüzde 25'tir. GM bu atışı gizlice yapar.","higher":"","sourceText":"By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:\n\n- Weal, for good results\n\n- Woe, for bad results\n\n- Weal and woe, for both good and bad results\n\n- Nothing, for results that aren't especially good or bad\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret.","higherSource":""},{"id":"awaken","name":"Awaken","nameTr":"Uyan","level":5,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid"],"subclasses":[],"castingTime":"8 hours","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 1.000 gp değerinde bir akik.","materialSource":"An agate worth at least 1,000 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Değerli bir değerli taş içindeki sihirli yolları takip ederek döküm süresini harcadıktan sonra, Büyük veya daha küçük bir canavara veya bitkiye dokunursunuz. Hedefin INT puanı olmamalı veya INT puanı 3 veya daha az olmalıdır. Hedef 10 üzerinden INT kazanır. Hedef aynı zamanda bildiğiniz bir dili konuşma yeteneğini de kazanır. Hedef bir bitki ise, uzuvlarını, köklerini, sarmaşıklarını, sürüngenlerini vb. hareket ettirme yeteneği kazanır ve insana benzer duyular kazanır. GM'niz, uyanmış çalı veya uyanmış ağaç istatistikleri gibi, uyanmış bitkiye uygun istatistikleri seçer.\nUyandırılan canavar veya bitki, 30 gün boyunca veya siz veya arkadaşlarınız ona zararlı bir şey yapana kadar sizin tarafınızdan charmed olacaktır. charmed durumu sona erdiğinde, uyanan yaratık, charmed iken ona nasıl davrandığınıza bağlı olarak sizinle dost kalıp kalmayacağını seçer.","higher":"","sourceText":"After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller beast or plant. The target must have either no Intelligence score or an Intelligence of 3 or less. The target gains an Intelligence of 10. The target also gains the ability to speak one language you know. If the target is a plant, it gains the ability to move its limbs, roots, vines, creepers, and so forth, and it gains senses similar to a human's. Your GM chooses statistics appropriate for the awakened plant, such as the statistics for the awakened shrub or the awakened tree.\n\nThe awakened beast or plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you, based on how you treated it while it was charmed.","higherSource":""},{"id":"bane","name":"Bane","nameTr":"Felaket","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla kan.","materialSource":"A drop of blood.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebileceğiniz, seçtiğiniz en fazla üç yaratık CHA saving throw’lar olmalıdır. Bu saving throw'yi başaramayan bir hedef, büyü sona ermeden önce saldırı zarı veya saving throw yaptığında, hedefin bir d4 atması ve saldırı zarı veya saving throw'den gelen sayıyı çıkarması gerekir.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her yuva seviyesi için ilave bir yaratığı hedefleyebilirsiniz.","sourceText":"Up to three creatures of your choice that you can see within range must make charisma saving throws. Whenever a target that fails this saving throw makes an attack roll or a saving throw before the spell ends, the target must roll a d4 and subtract the number rolled from the attack roll or saving throw.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."},{"id":"banishment","name":"Banishment","nameTr":"Sürgün","level":4,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Hedef için tatsız bir öğe.","materialSource":"An item distasteful to the target.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":null,"description":"Menzilde gördüğünüz bir canlıyı başka bir varoluş düzlemine göndermeye çalışıyorsunuz. Hedef bir CHA saving throw üzerinde başarılı olmalı veya sürgüne gönderilmelidir.\nHedef, bulunduğunuz varoluş düzleminin yerlisiyse, hedefi zararsız bir yarı uçağa sürgün edersiniz. Oradayken hedef incapacitated'dir. Hedef, büyü bitene kadar orada kalır; bu noktada hedef, bıraktığı alanda veya o alan doluysa en yakın boş alanda yeniden belirir.\nHedef, sizin bulunduğunuz düzlemden farklı bir varoluş düzleminin yerlisiyse, hedef hafif bir patlama sesiyle sürgüne gönderilir ve ana düzlemine geri döner. Büyü 1 dakika dolmadan sona ererse, hedef kaldığı alanda veya o alan doluysa en yakın boş alanda yeniden belirir. Aksi takdirde hedef geri dönmez.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 4. seviyenin üzerindeki her slot seviyesi için ilave bir yaratığı hedefleyebilirsiniz.","sourceText":"You attempt to send one creature that you can see within range to another plane of existence. The target must succeed on a charisma saving throw or be banished.\n\nIf the target is native to the plane of existence you're on, you banish the target to a harmless demiplane. While there, the target is incapacitated. The target remains there until the spell ends, at which point the target reappears in the space it left or in the nearest unoccupied space if that space is occupied.\n\nIf the target is native to a different plane of existence than the one you're on, the target is banished with a faint popping noise, returning to its home plane. If the spell ends before 1 minute has passed, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied. Otherwise, the target doesn't return.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th."},{"id":"barkskin","name":"Barkskin","nameTr":"Barkskin","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir avuç meşe kabuğu.","materialSource":"A handful of oak bark.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunuyorsun. Büyü bitene kadar hedefin derisi kaba, havlamaya benzer bir görünüme sahip olur ve ne tür bir zırh giydiğine bakılmaksızın hedefin AC'si 16'dan az olamaz.","higher":"","sourceText":"You touch a willing creature. Until the spell ends, the target's skin has a rough, bark-like appearance, and the target's AC can't be less than 16, regardless of what kind of armor it is wearing.","higherSource":""},{"id":"beacon-of-hope","name":"Beacon of Hope","nameTr":"Umut Feneri","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric"],"subclasses":["Devotion","Life","Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Bu büyü umut ve canlılık verir. Menzil içindeki istediğiniz sayıda yaratığı seçin. Bu süre boyunca her hedef, WIS saving throw’lar üzerinde avantaj'ye sahiptir ve saving throw’lar'yi öldürür ve herhangi bir iyileştirmeden mümkün olan maksimum HP sayısını yeniden kazanır.","higher":"","sourceText":"This spell bestows hope and vitality. Choose any number of creatures within range. For the duration, each target has advantage on wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing.","higherSource":""},{"id":"bestow-curse","name":"Bestow Curse","nameTr":"Lanet Ver","level":3,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bir yaratığa dokunduğunuzda, o yaratığın bir WIS saving throw üzerinde başarılı olması veya büyünün süresi boyunca lanetli hale gelmesi gerekir. Bu büyüyü yaptığınızda aşağıdaki seçenekler arasından lanetin doğasını seçin:\n- Bir yetenek puanı seçin. Lanetliyken hedefte ability check’ler üzerinde dezavantaj bulunur ve saving throw’lar bu yetenek puanıyla oluşturulur.\n- Lanetliyken, hedefin size karşı saldırı atışlarında dezavantaj vardır.\n- Hedef lanetliyken her turun başında bir WIS saving throw yapmalıdır. Başarısız olursa, hiçbir şey yapmadan dönen eylemini boşa harcar.\n- Hedef lanetliyken, saldırılarınız ve büyüleriniz hedefe fazladan 1d8 necrotic hasar verir.\nLaneti kaldırma büyüsü bu etkiyi sona erdirir. GM'nin tercihine göre alternatif bir lanet efekti seçebilirsiniz, ancak bu, yukarıda anlatılanlardan daha güçlü olmamalıdır. Böyle bir lanetin etkisi konusunda son söz GM'ye aittir.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaparsanız, süresi concentration olur, en fazla 10 dakika. 5. seviye veya üzeri spell slot kullanıyorsanız süre 8 saattir. 7. seviye veya daha yüksek bir spell slot kullanıyorsanız süre 24 saattir. 9. seviye spell slot kullanırsanız büyü, etkisiz hale getirilene kadar sürer. 5. seviye veya daha yüksek bir spell slot kullanmak, concentration gerektirmeyen bir süre sağlar.","sourceText":"You touch a creature, and that creature must succeed on a wisdom saving throw or become cursed for the duration of the spell. When you cast this spell, choose the nature of the curse from the following options:\n\n- Choose one ability score. While cursed, the target has disadvantage on ability checks and saving throws made with that ability score.\n\n- While cursed, the target has disadvantage on attack rolls against you.\n\n- While cursed, the target must make a wisdom saving throw at the start of each of its turns. If it fails, it wastes its action that turn doing nothing.\n\n- While the target is cursed, your attacks and spells deal an extra 1d8 necrotic damage to the target.\n\nA remove curse spell ends this effect. At the GM's option, you may choose an alternative curse effect, but it should be no more powerful than those described above. The GM has final say on such a curse's effect.","higherSource":"If you cast this spell using a spell slot of 4th level or higher, the duration is concentration, up to 10 minutes. If you use a spell slot of 5th level or higher, the duration is 8 hours. If you use a spell slot of 7th level or higher, the duration is 24 hours. If you use a 9th level spell slot, the spell lasts until it is dispelled. Using a spell slot of 5th level or higher grants a duration that doesn't require concentration."},{"id":"black-tentacles","name":"Black Tentacles","nameTr":"Siyah Dokunaçlar","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Dev bir ahtapot veya dev bir kalamarın dokunaç parçası","materialSource":"A piece of tentacle from a giant octopus or a giant squid","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":{"type":"cube","size":20},"description":"Kıvranan abanoz dokunaçlar, menzil içinde görebileceğiniz yerdeki 20 ft karesini dolduruyor. Bu süre boyunca bu dokunaçlar bölgedeki zemini zorlu arazilere dönüştürür.\nBir yaratık bir dönüşte etkilenen bölgeye ilk kez girdiğinde veya dönüşüne orada başladığında, yaratık bir DEX saving throw üzerinde başarılı olmalı veya 3d6 bludgeoning hasarı almalı ve restrained olmalıdır. büyü bitene kadar dokunaçlar. Bölgede sırasını başlatan ve zaten dokunaçlarıyla restrained olan bir yaratık, 3d6 bludgeoning hasarı alır.\nDokunaçların yanındaki restrained yaratık, hareketini kullanarak büyü kurtarma DC'nize karşı STR veya DEX kontrolü (kendi seçimi) yapabilir. Başarılı olduğunda kendini özgürleştirir.","higher":"","sourceText":"Squirming, ebony tentacles fill a 20-foot square on ground that you can see within range. For the duration, these tentacles turn the ground in the area into difficult terrain.\n\nWhen a creature enters the affected area for the first time on a turn or starts its turn there, the creature must succeed on a Dexterity saving throw or take 3d6 bludgeoning damage and be restrained by the tentacles until the spell ends. A creature that starts its turn in the area and is already restrained by the tentacles takes 3d6 bludgeoning damage.\n\nA creature restrained by the tentacles can use its action to make a Strength or Dexterity check (its choice) against your spell save DC. On a success, it frees itself.","higherSource":""},{"id":"blade-barrier","name":"Blade Barrier","nameTr":"Bıçak Bariyeri","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"90 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"line","size":100},"description":"Büyülü enerjiden yapılmış, dönen, jilet keskinliğinde bıçaklardan oluşan dikey bir duvar yaratırsınız. Duvar menzil içinde belirir ve bu süre boyunca varlığını sürdürür. 100 ft uzunluğa, 20 ft yüksekliğe ve 5 ft kalınlığa kadar düz bir duvar veya 60 ft çapa, 20 ft yüksekliğe kadar halkalı bir duvar oluşturabilirsiniz. 5 ft kalın. Duvar, arkasındaki yaratıklara dörtte üç koruma sağlıyor ve alanı zorlu bir arazi.\nBir yaratık ilk kez bir dönüşte duvar alanına girdiğinde veya orada dönüşüne başladığında, yaratık bir DEX saving throw yapmalıdır. Başarısız bir kaydetme durumunda yaratık, 6d10 slashing hasarı alır. Başarılı bir kurtarışta yaratık, yarısı kadar hasar alır.","higher":"","sourceText":"You create a vertical wall of whirling, razor-sharp blades made of magical energy. The wall appears within range and lasts for the duration. You can make a straight wall up to 100 feet long, 20 feet high, and 5 feet thick, or a ringed wall up to 60 feet in diameter, 20 feet high, and 5 feet thick. The wall provides three-quarters cover to creatures behind it, and its space is difficult terrain.\n\nWhen a creature enters the wall's area for the first time on a turn or starts its turn there, the creature must make a dexterity saving throw. On a failed save, the creature takes 6d10 slashing damage. On a successful save, the creature takes half as much damage.","higherSource":""},{"id":"bless","name":"Bless","nameTr":"korusun","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Cleric","Paladin"],"subclasses":["Life","Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam kutsal su.","materialSource":"A sprinkling of holy water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde seçtiğiniz en fazla üç yaratığı kutsarsınız. Bir hedef, büyü sona ermeden önce saldırı zarı veya saving throw yaptığında, hedef bir d4 atabilir ve zar sonucunu saldırı zarı veya saving throw'ye ekleyebilir.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her slot seviyesi için ilave bir yaratığı hedefleyebilirsiniz.","sourceText":"You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, the target can roll a d4 and add the number rolled to the attack roll or saving throw.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st."},{"id":"blight","name":"Blight","nameTr":"Yanıklık","level":4,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Druid","Sorcerer","Warlock","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":null,"description":"Nekromantik enerji, menzil içinde görebileceğiniz seçtiğiniz bir yaratığın üzerine akıp, onun nemini ve canlılığını emer. Hedefin bir CON saving throw yapması gerekir. Hedef, başarısız save’de 8d8 necrotic hasar alır veya başarılı save’de yarısı kadar hasar alır. Büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.\nBir bitki yaratığını veya sihirli bir bitkiyi hedef alırsanız, saving throw ile dezavantaj oluşturulur ve büyü ona maksimum hasar verir.\nAğaç veya çalı gibi yaratık olmayan, sihirli olmayan bir bitkiyi hedef alırsanız, bu saving throw oluşturmaz; sadece solar ve ölür.","higher":"Bu büyüyü 5. seviyeden daha yüksek bir spell slot kullanarak yaptığınızda, hasar 4. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"Necromantic energy washes over a creature of your choice that you can see within range, draining moisture and vitality from it. The target must make a constitution saving throw. The target takes 8d8 necrotic damage on a failed save, or half as much damage on a successful one. The spell has no effect on undead or constructs.\n\nIf you target a plant creature or a magical plant, it makes the saving throw with disadvantage, and the spell deals maximum damage to it.\n\nIf you target a nonmagical plant that isn't a creature, such as a tree or shrub, it doesn't make a saving throw; it simply withers and dies.","higherSource":"When you cast this spell using a spell slot of 5th level of higher, the damage increases by 1d8 for each slot level above 4th."},{"id":"blindness-deafness","name":"Blindness/Deafness","nameTr":"Körlük/Sağırlık","level":2,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Cleric","Sorcerer","Wizard"],"subclasses":["Fiend","Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"none","area":null,"description":"Bir düşmanı kör edebilir veya sağır edebilirsiniz. CON saving throw yapmak için menzil içinde görebileceğiniz bir yaratık seçin. Başarısız olursa, bu süre boyunca hedef ya blinded ya da deafened'dir (seçiminiz). Her turun sonunda hedef bir CON saving throw yapabilir. Başarılı olunduğunda büyü sona erer.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 2. seviyenin üzerindeki her yuva seviyesi için ilave bir yaratığı hedefleyebilirsiniz.","sourceText":"You can blind or deafen a foe. Choose one creature that you can see within range to make a constitution saving throw. If it fails, the target is either blinded or deafened (your choice) for the duration. At the end of each of its turns, the target can make a constitution saving throw. On a success, the spell ends.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},{"id":"blink","name":"Blink","nameTr":"Yanıp sönüyor","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü süresi boyunca her turun sonunda bir d20 yuvarlayın. 11 veya daha yüksek bir atışta, mevcut varoluş düzleminizden kaybolursunuz ve Ethereal Plande belirirsiniz (büyü başarısız olur ve eğer zaten o düzlemdeyseniz, büyü boşa gider). Bir sonraki turun başlangıcında ve Ethereal Plane'daysanız büyü sona erdiğinde, kaybolduğunuz alanın 10 ft içinde görebileceğiniz, seçtiğiniz boş bir alana geri dönersiniz. Bu aralıkta boş alan yoksa, en yakın boş alanda görünürsünüz (birden fazla alan eşit derecede yakınsa rastgele seçilir). Bu büyüyü bir eylem olarak reddedebilirsiniz.\nEthereal Plandeyken, geldiğiniz, gri tonlarında olan uçağı görebilir ve duyabilirsiniz ve orada 60 ft'den daha uzakta hiçbir şey göremezsiniz. Ethereal Plane'da yalnızca diğer canlıları etkileyebilir ve onlardan etkilenebilirsiniz. Orada olmayan canlılar, eğer öyle bir yeteneğe sahip değilse, sizi algılayamaz ve sizinle etkileşime giremezler.","higher":"","sourceText":"Roll a d20 at the end of each of your turns for the duration of the spell. On a roll of 11 or higher, you vanish from your current plane of existence and appear in the Ethereal Plane (the spell fails and the casting is wasted if you were already on that plane). At the start of your next turn, and when the spell ends if you are on the Ethereal Plane, you return to an unoccupied space of your choice that you can see within 10 feet of the space you vanished from. If no unoccupied space is available within that range, you appear in the nearest unoccupied space (chosen at random if more than one space is equally near). You can dismiss this spell as an action.\n\nWhile on the Ethereal Plane, you can see and hear the plane you originated from, which is cast in shades of gray, and you can't see anything there more than 60 feet away. You can only affect and be affected by other creatures on the Ethereal Plane. Creatures that aren't there can't perceive you or interact with you, unless they have the ability to do so.","higherSource":""},{"id":"blur","name":"Blur","nameTr":"Bulanıklaştırma","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Vücudunuz bulanıklaşıyor, kayıyor ve sizi görebilen herkes için sallanıyor. Bu süre boyunca herhangi bir yaratığın size karşı saldırı atışlarında dezavantaj vardır. Bir saldırgan, kör görüşte olduğu gibi görüşe güvenmiyorsa veya gerçek görüşte olduğu gibi illüzyonlar aracılığıyla görebiliyorsa bu etkiye karşı bağışıklıdır.","higher":"","sourceText":"Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn't rely on sight, as with blindsight, or can see through illusions, as with truesight.","higherSource":""},{"id":"branding-smite","name":"Branding Smite","nameTr":"Markalaşma Çarpması","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Paladin"],"subclasses":[],"castingTime":"1 bonus action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü sona ermeden silah saldırısı ile bir yaratığa bir daha vurduğunuzda, saldırırken silah astral ışıltıyla parlıyor. Saldırı, hedefe fazladan radiant invisible ise görünür hale gelen ekstra bir 2d6 radiant hasarı verir ve hedef, 5 ft yarıçapında loş bir ışık saçar ve büyü yapılana kadar invisible olamaz. biter.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, ekstra hasar 2. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it's invisible, and the target sheds dim light in a 5-foot radius and can't become invisible until the spell ends.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."},{"id":"burning-hands","name":"Burning Hands","nameTr":"Yanan Eller","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Fiend","Lore"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"cone","size":15},"description":"Ellerinizi başparmaklarınız dokunacak ve parmaklarınız açık olacak şekilde tuttuğunuzda, uzattığınız parmak uçlarınızdan ince bir alev tabakası fışkırır. Bir 15 ft konisindeki her yaratık bir DEX saving throw yapmalıdır. Bir yaratık, başarısız save’de 3d6 fire hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\nfire, alandaki giyilmeyen veya taşınmayan yanıcı nesneleri ateşler.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 1. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"As you hold your hands with thumbs touching and fingers spread, a thin sheet of flames shoots forth from your outstretched fingertips. Each creature in a 15-foot cone must make a dexterity saving throw. A creature takes 3d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire ignites any flammable objects in the area that aren't being worn or carried.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."},{"id":"call-lightning","name":"Call Lightning","nameTr":"Yıldırım'ı ara","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":{"type":"sphere","size":5},"description":"10 ft uzunluğunda ve 60 ft yarıçaplı bir silindir şeklinde, doğrudan üstünüzde 100 ft'yi görebileceğiniz bir noktaya ortalanmış bir fırtına bulutu belirir. Havada fırtına bulutunun görünebileceği bir nokta göremiyorsanız (örneğin bulutu barındıramayacak bir odadaysanız) büyü başarısız olur.\nBüyüyü yaparken menzil içinde görebileceğiniz bir nokta seçin. Bir lightning cıvatası buluttan o noktaya doğru parlıyor. Bu noktanın 5 ft içindeki her yaratık DEX saving throw atmalıdır. Bir yaratık, başarısız save’de 3d10 lightning hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Büyü sona erene kadar her turunuzda, aynı veya farklı bir noktayı hedefleyerek lightning'yi bu şekilde tekrar çağırmak için eyleminizi kullanabilirsiniz.\nBu büyüyü yaptığınızda dışarıda fırtınalı bir ortamda bulunuyorsanız, büyü size yeni bir fırtına yaratmak yerine mevcut fırtına üzerinde kontrol sahibi olmanızı sağlar. Bu koşullar altında büyünün hasarı 1d10 artar.","higher":"Bu büyüyü 4. veya daha yüksek seviyedeki bir spell slot kullanarak yaptığınızda, hasar 3. seviyenin üzerindeki her slot seviyesi için 1d10 artar.","sourceText":"A storm cloud appears in the shape of a cylinder that is 10 feet tall with a 60-foot radius, centered on a point you can see 100 feet directly above you. The spell fails if you can't see a point in the air where the storm cloud could appear (for example, if you are in a room that can't accommodate the cloud).\n\nWhen you cast the spell, choose a point you can see within range. A bolt of lightning flashes down from the cloud to that point. Each creature within 5 feet of that point must make a dexterity saving throw. A creature takes 3d10 lightning damage on a failed save, or half as much damage on a successful one. On each of your turns until the spell ends, you can use your action to call down lightning in this way again, targeting the same point or a different one.\n\nIf you are outdoors in stormy conditions when you cast this spell, the spell gives you control over the existing storm instead of creating a new one. Under such conditions, the spell's damage increases by 1d10.","higherSource":"When you cast this spell using a spell slot of 4th or higher level, the damage increases by 1d10 for each slot level above 3rd."},{"id":"calm-emotions","name":"Calm Emotions","nameTr":"Sakin Duygular","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":{"type":"sphere","size":20},"description":"Bir grup insandaki güçlü duyguları bastırmaya çalışıyorsunuz. Menzil içinde seçtiğiniz bir noktaya ortalanmış 20 ft yarıçaplı küredeki her insansı, CHA saving throw atmalıdır; bir yaratık isterse bu saving throw'de başarısız olmayı seçebilir. Bir yaratık saving throw'de başarısız olursa aşağıdaki iki efektten birini seçin. Hedefin charmed veya frightened olmasına neden olan her türlü etkiyi bastırabilirsiniz. Bu büyü sona erdiğinde, süresi dolmamış olması koşuluyla, bastırılmış herhangi bir etki devam eder.\nAlternatif olarak, hedefin düşmanca davrandığı seçtiğiniz yaratıklara karşı kayıtsız kalmasını sağlayabilirsiniz. Hedefin saldırıya uğraması, büyü ile zarar görmesi veya arkadaşlarından birinin zarar gördüğüne tanık olması durumunda bu kayıtsızlık sona erer. Büyü sona erdiğinde, GM aksi yönde bir karar vermediği sürece yaratık yeniden düşmanca davranır.","higher":"","sourceText":"You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot-radius sphere centered on a point you choose within range must make a charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects. You can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.\n\nAlternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise.","higherSource":""},{"id":"chain-lightning","name":"Chain Lightning","nameTr":"Zincir Yıldırım","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz kürk; bir parça kehribar, cam veya kristal çubuk; ve üç gümüş iğne.","materialSource":"A bit of fur; a piece of amber, glass, or a crystal rod; and three silver pins.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":null,"description":"Menzil içinde görebileceğiniz, seçtiğiniz bir hedefe doğru kavis çizen bir lightning oku oluşturursunuz. Daha sonra bu hedeften üç cıvata diğer üç hedefe sıçrar ve bunların her biri ilk hedefin 30 ft dahilinde olmalıdır. Hedef bir yaratık veya bir nesne olabilir ve cıvatalardan yalnızca biri tarafından hedef alınabilir.\nBir hedefin DEX saving throw yapması gerekir. Hedef, başarısız save’de 10d8 lightning hasar alır veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 6. seviyenin üzerindeki her yuva seviyesi için ilk hedeften başka bir hedefe ek bir ok atlar.","sourceText":"You create a bolt of lightning that arcs toward a target of your choice that you can see within range. Three bolts then leap from that target to as many as three other targets, each of which must be within 30 feet of the first target. A target can be a creature or an object and can be targeted by only one of the bolts.\n\nA target must make a dexterity saving throw. The target takes 10d8 lightning damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, one additional bolt leaps from the first target to another target for each slot level above 6th."},{"id":"charm-person","name":"Charm Person","nameTr":"Cazibe Kişisi","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Druid","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir insansıyı etkilemeye çalışırsınız. Bir WIS saving throw yapmalıdır ve siz veya arkadaşlarınız onunla savaşıyorsanız bunu avantaj ile yapar. saving throw başarısız olursa, büyü bitene kadar veya siz veya arkadaşlarınız ona zararlı bir şey yapana kadar sizin tarafınızdan charmed yapılır. charmed yaratığı sizi dost canlısı bir tanıdık olarak görüyor. Büyü sona erdiğinde yaratık onun sizin tarafınızdan charmed olduğunu anlar.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her slot seviyesi için ilave bir yaratığı hedefleyebilirsiniz. Yaratıkları hedeflediğinizde birbirlerine 30 ft mesafede olmalıdır.","sourceText":"You attempt to charm a humanoid you can see within range. It must make a wisdom saving throw, and does so with advantage if you or your companions are fighting it. If it fails the saving throw, it is charmed by you until the spell ends or until you or your companions do anything harmful to it. The charmed creature regards you as a friendly acquaintance. When the spell ends, the creature knows it was charmed by you.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."},{"id":"chill-touch","name":"Chill Touch","nameTr":"Sakin Dokunuş","level":0,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki bir yaratığın alanında hayaletimsi, iskelet gibi bir el yaratırsınız. Mezarın soğukluğuyla ona saldırmak için yaratığa karşı bir menzilli spell attack yapın. Hedef bir vuruşta 1d8 necrotic hasarı alır ve bir sonraki turunuzun başlangıcına kadar HP'yi geri kazanamaz. O zamana kadar el hedefe tutunur.\nBir ölümsüz hedefi vurursanız, bir sonraki turunuzun sonuna kadar size karşı saldırı atışlarında dezavantaj de bulunur.\nBu büyünün hasarı, 5. seviyeye (2d8), 11. seviyeye (3d8) ve 17. seviyeye (4d8) ulaştığınızda 1d8 artar.","higher":"","sourceText":"You create a ghostly, skeletal hand in the space of a creature within range. Make a ranged spell attack against the creature to assail it with the chill of the grave. On a hit, the target takes 1d8 necrotic damage, and it can't regain hit points until the start of your next turn. Until then, the hand clings to the target.\n\nIf you hit an undead target, it also has disadvantage on attack rolls against you until the end of your next turn.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","higherSource":""},{"id":"circle-of-death","name":"Circle of Death","nameTr":"Ölüm Çemberi","level":6,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"En az 500 gp değerinde ezilmiş siyah incinin tozu.","materialSource":"The powder of a crushed black pearl worth at least 500 gp.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"sphere","size":60},"description":"Menzil içindeki bir noktadan 60 ft yarıçaplı kürede bir negatif enerji küresi dalgalanıyor. O bölgedeki her canlı bir CON saving throw yapmalıdır. Hedef, başarısız save’de 8d6 necrotic hasar alır veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 6. seviyenin üzerindeki her yuva seviyesi için 2d6 artar.","sourceText":"A sphere of negative energy ripples out in a 60-foot radius sphere from a point within range. Each creature in that area must make a constitution saving throw. A target takes 8d6 necrotic damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the damage increases by 2d6 for each slot level above 6th."},{"id":"clairvoyance","name":"Clairvoyance","nameTr":"Basiret","level":3,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"10 minutes","range":"1 mile","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"En az 100gp değerinde bir odak noktası; işitmek için mücevherli bir boynuz veya görmek için cam bir göz.","materialSource":"A focus worth at least 100gp, either a jeweled horn for hearing or a glass eye for seeing.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil dahilinde, tanıdık bir konumda (daha önce ziyaret ettiğiniz veya gördüğünüz bir yer) veya size tanıdık gelmeyen bariz bir konumda (bir kapının arkası, bir köşenin arkası veya bir ağaç korusu gibi) bir invisible sensörü oluşturursunuz. Sensör bu süre boyunca yerinde kalır ve saldırıya uğrayamaz veya başka bir şekilde etkileşime geçilemez.\nBüyüyü yaptığınızda görmeyi veya duymayı seçersiniz. Seçtiğiniz duyuyu sensör aracılığıyla sanki onun alanındaymış gibi kullanabilirsiniz. Eyleminiz olarak görme ve duyma arasında geçiş yapabilirsiniz.\nSensörü görebilen bir yaratık (görünmezlik veya gerçek görüşten yararlanan bir yaratık gibi), yaklaşık yumruğunuz büyüklüğünde parlak, soyut bir küre görür.","higher":"","sourceText":"You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can't be attacked or otherwise interacted with.\n\nWhen you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing.\n\nA creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist.","higherSource":""},{"id":"clone","name":"Clone","nameTr":"Klon","level":8,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Wizard"],"subclasses":[],"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"En az 1.000 gp değerinde bir elmas ve klonlanacak yaratığın büyünün tüketeceği en az 1 inç küp eti ve kapatılabilir bir kapağı olan ve büyük bir vazo, tabut, yerdeki çamur dolu kist veya tuzlu suyla dolu kristal kap gibi bir Orta yaratığı tutacak kadar büyük olan en az 2.000 gp değerinde bir kap.","materialSource":"A diamond worth at least 1,000 gp and at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes, and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, ölüme karşı bir koruma olarak yaşayan bir yaratığın hareketsiz bir kopyasını büyütür. Bu klon, kapalı bir kap içinde oluşur ve 120 gün sonra tam boyuta ve olgunluğa ulaşır; Ayrıca klonun aynı yaratığın daha genç bir versiyonu olmasını da seçebilirsiniz. Kabı bozulmadan kaldığı sürece hareketsiz kalır ve süresiz olarak dayanır.\nKlon olgunlaştıktan sonra herhangi bir zamanda orijinal yaratık ölürse, ruhun özgür olması ve geri dönmeye istekli olması koşuluyla ruhu klona aktarılır. Klon, orijinaliyle fiziksel olarak aynıdır ve aynı kişiliğe, anılara ve yeteneklere sahiptir, ancak orijinalin hiçbir ekipmanına sahip değildir. Orijinal yaratığın fiziksel kalıntıları, eğer hala mevcutlarsa, hareketsiz hale gelir ve yaratığın ruhu başka bir yerde olduğundan daha sonra hayata döndürülemez.","higher":"","sourceText":"This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days; you can also choose to have the clone be a younger version of the same creature. It remains inert and endures indefinitely, as long as its vessel remains undisturbed.\n\nAt any time after the clone matures, if the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original's equipment. The original creature's physical remains, if they still exist, become inert and can't thereafter be restored to life, since the creature's soul is elsewhere.","higherSource":""},{"id":"cloudkill","name":"Cloudkill","nameTr":"Bulut Öldürme","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"sphere","size":20},"description":"Menzil içinde seçtiğiniz bir noktanın merkezinde, zehirli, sarı-yeşil sisten oluşan bir 20 ft yarıçap küresi yaratırsınız. Sis köşelere yayılıyor. Bu süre boyunca veya kuvvetli rüzgar sisi dağıtıp büyüyü sonlandırana kadar sürer. Alanı oldukça karanlıktır.\nBir yaratık bir turda ilk kez büyü alanına girdiğinde veya orada dönüşüne başladığında, o yaratık bir CON saving throw yapmalıdır. Yaratık, başarısız save’de 5d8 poison hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Canlılar nefeslerini tutsalar veya nefes almaya ihtiyaç duymasalar bile etkilenirler.\nSis, her dönüşünüzün başında 10 ft'yi zemin yüzeyi boyunca yuvarlanarak sizden uzaklaştırır. Havadan ağır olan buharlar toprağın en alt seviyesine kadar iner, hatta açıklıklardan aşağıya dökülür.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 5. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"You create a 20-foot-radius sphere of poisonous, yellow-green fog centered on a point you choose within range. The fog spreads around corners. It lasts for the duration or until strong wind disperses the fog, ending the spell. Its area is heavily obscured.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, that creature must make a constitution saving throw. The creature takes 5d8 poison damage on a failed save, or half as much damage on a successful one. Creatures are affected even if they hold their breath or don't need to breathe.\n\nThe fog moves 10 feet away from you at the start of each of your turns, rolling along the surface of the ground. The vapors, being heavier than air, sink to the lowest level of the land, even pouring down openings.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."},{"id":"color-spray","name":"Color Spray","nameTr":"Renk Spreyi","level":1,"school":"Illusion","schoolTr":"İllüzyon","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 round","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Kırmızı, sarı ve mavi renkli bir tutam toz veya kum.","materialSource":"A pinch of powder or sand that is colored red, yellow, and blue.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cone","size":15},"description":"Elinizden göz kamaştırıcı bir dizi yanıp sönen, renkli ışık yayılıyor. Rulo 6d10; toplam, bu büyünün kaç HP yaratığa etki edebileceğini gösterir. Sizden kaynaklanan bir 15 ft konisindeki yaratıklar, mevcut HP'lerine göre artan sırada etkilenir (unconscious yaratıkları ve göremeyen yaratıkları göz ardı ederek).\nEn düşük akım HP'ye sahip olan yaratıktan başlayarak, büyü bitene kadar bu büyüden etkilenen her yaratık blinded olur. Bir sonraki en düşük HP'ye sahip yaratığa geçmeden önce her yaratığın HP'sini toplamdan çıkarın. Bir yaratığın etkilenebilmesi için HP'nin kalan toplam değere eşit veya daha az olması gerekir.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her slot seviyesi için ek bir 2d10 yuvarlayın.","sourceText":"A dazzling array of flashing, colored light springs from your hand. Roll 6d10; the total is how many hit points of creatures this spell can effect. Creatures in a 15-foot cone originating from you are affected in ascending order of their current hit points (ignoring unconscious creatures and creatures that can't see).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell is blinded until the spell ends. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d10 for each slot level above 1st."},{"id":"command","name":"Command","nameTr":"Komut","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Cleric","Paladin"],"subclasses":["Fiend","Lore"],"castingTime":"1 action","range":"60 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir yaratığa tek kelimelik bir komut söylüyorsunuz. Hedef, WIS saving throw'de başarılı olmalı veya bir sonraki dönüşte komutu takip etmelidir. Hedef ölümsüzse, dilinizi anlamıyorsa veya komutunuz ona doğrudan zarar veriyorsa büyünün hiçbir etkisi yoktur.\nBazı tipik komutlar ve bunların etkileri aşağıdadır. Burada açıklananın dışında bir komut verebilirsiniz. Bunu yaparsanız, GM hedefin nasıl davranacağını belirler. Hedef emrinizi yerine getiremezse büyü sona erer.\n***Yaklaş.*** Hedef, en kısa ve en doğrudan rota üzerinden size doğru hareket eder ve 5 ft yakınınızda hareket ederse sırasını sona erdirir.\n***Bırak.*** Hedef elinde tuttuğu şeyi bırakır ve ardından sırasını bitirir.\n***Kaç.*** Hedef, sırasını en hızlı şekilde sizden uzaklaşarak geçirir.\n***Grovel.*** Hedef prone düşer ve ardından sırasını bitirir.\n***Dur.*** Hedef hareket etmiyor ve hiçbir eylemde bulunmuyor. Uçan bir canlı, gücü yettiği sürece havada kalır. Eğer havada kalmak için hareket etmesi gerekiyorsa, havada kalabilmek için gereken minimum mesafeyi kateder.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her slot seviyesi için ilave bir yaratığı etkileyebilirsiniz. Yaratıkları hedeflediğinizde birbirlerine 30 ft mesafede olmalıdır.","sourceText":"You speak a one-word command to a creature you can see within range. The target must succeed on a wisdom saving throw or follow the command on its next turn. The spell has no effect if the target is undead, if it doesn't understand your language, or if your command is directly harmful to it.\n\nSome typical commands and their effects follow. You might issue a command other than one described here. If you do so, the GM determines how the target behaves. If the target can't follow your command, the spell ends.\n\n***Approach.*** The target moves toward you by the shortest and most direct route, ending its turn if it moves within 5 feet of you.\n\n***Drop.*** The target drops whatever it is holding and then ends its turn.\n\n***Flee.*** The target spends its turn moving away from you by the fastest available means.\n\n***Grovel.*** The target falls prone and then ends its turn.\n\n***Halt.*** The target doesn't move and takes no actions. A flying creature stays aloft, provided that it is able to do so. If it must move to stay aloft, it flies the minimum distance needed to remain in the air.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you can affect one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."},{"id":"commune","name":"Commune","nameTr":"Komün","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric"],"subclasses":["Devotion"],"castingTime":"1 minute","range":"Self","duration":"1 minute","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Tütsü ve bir şişe kutsal veya kutsal olmayan su.","materialSource":"Incense and a vial of holy or unholy water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Tanrınız ya da ilahi bir vekil ile iletişime geçersiniz ve evet ya da hayır olarak cevaplanabilecek en fazla üç soru sorarsınız. Büyü bitmeden sorularınızı sormalısınız. Her soru için doğru cevabı alırsınız.\nİlahi varlıklar mutlaka her şeyi bilen değildir, dolayısıyla bir soru tanrının bilgisinin ötesinde yatan bir bilgiyle ilgiliyse cevap olarak \"belirsiz\" yanıtını alabilirsiniz. Tek kelimelik bir cevabın yanıltıcı olabileceği veya tanrının çıkarlarına aykırı olabileceği bir durumda, GM bunun yerine cevap olarak kısa bir cümle sunabilir.\nBir sonraki uzun dinlenmenizi tamamlamadan önce büyüyü iki veya daha fazla kez yaparsanız, ilkinden sonraki her kullanımda cevap alamama ihtimaliniz kümülatif yüzde 25'tir. GM bu atışı gizlice yapar.","higher":"","sourceText":"You contact your deity or a divine proxy and ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question.\n\nDivine beings aren't necessarily omniscient, so you might receive \"unclear\" as an answer if a question pertains to information that lies beyond the deity's knowledge. In a case where a one-word answer could be misleading or contrary to the deity's interests, the GM might offer a short phrase as an answer instead.\n\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get no answer. The GM makes this roll in secret.","higherSource":""},{"id":"commune-with-nature","name":"Commune With Nature","nameTr":"Doğayla İletişim Kurun","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Druid","Ranger"],"subclasses":["Land"],"castingTime":"1 minute","range":"Self","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kısaca doğayla bütünleşiyorsunuz ve çevredeki bölge hakkında bilgi ediniyorsunuz. Açık havada, büyü size 3 mil içindeki arazi hakkında bilgi verir. Mağaralarda ve diğer doğal yeraltı ortamlarında yarıçap 300 ft ile sınırlıdır. Büyü, zindanlar ve kasabalar gibi doğanın yerini inşaatın aldığı yerlerde çalışmaz.\nAlanla ilgili olarak aşağıdaki konulardan herhangi biri hakkında seçtiğiniz en fazla üç gerçek hakkında anında bilgi edinirsiniz:\n- arazi ve su kütleleri\n- yaygın bitkiler, mineraller, hayvanlar veya insanlar\n- güçlü gökseller, periler, şeytanlar, elementaller veya ölümsüzler\n- varoluşun diğer düzlemlerinin etkisi\n- binalar\nÖrneğin, bölgedeki güçlü ölümsüzlerin konumunu, başlıca güvenli içme suyu kaynaklarının konumunu ve yakınlardaki kasabaların konumunu belirleyebilirsiniz.","higher":"","sourceText":"You briefly become one with nature and gain knowledge of the surrounding territory. In the outdoors, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn't function where nature has been replaced by construction, such as in dungeons and towns.\n\nYou instantly gain knowledge of up to three facts of your choice about any of the following subjects as they relate to the area:\n\n- terrain and bodies of water\n\n- prevalent plants, minerals, animals, or peoples\n\n- powerful celestials, fey, fiends, elementals, or undead\n\n- influence from other planes of existence\n\n- buildings\n\nFor example, you could determine the location of powerful undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns.","higherSource":""},{"id":"comprehend-languages","name":"Comprehend Languages","nameTr":"Dilleri Anlayın","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir tutam kurum ve tuz.","materialSource":"A pinch of soot and salt.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca duyduğunuz herhangi bir konuşma dilinin gerçek anlamını anlarsınız. Ayrıca gördüğünüz herhangi bir yazılı dili de anlıyorsunuz, ancak kelimelerin yazıldığı yüzeye dokunuyor olmalısınız. Bir sayfalık metni okumak yaklaşık 1 dakika sürer.\nBu büyü, yazılı bir dilin parçası olmayan bir metin veya gizli mühür gibi bir glifteki gizli mesajların kodunu çözmez.","higher":"","sourceText":"For the duration, you understand the literal meaning of any spoken language that you hear. You also understand any written language that you see, but you must be touching the surface on which the words are written. It takes about 1 minute to read one page of text.\n\nThis spell doesn't decode secret messages in a text or a glyph, such as an arcane sigil, that isn't part of a written language.","higherSource":""},{"id":"compulsion","name":"Compulsion","nameTr":"Zorunluluk","level":4,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebileceğiniz ve duyabileceğiniz seçtiğiniz yaratıklardan bir WIS saving throw yapmalısınız. Bir hedef, charmed olamıyorsa bu saving throw üzerinde otomatik olarak başarılı olur. Başarısız bir kaydetme durumunda hedef bu büyüden etkilenir. Büyü sona erene kadar, her dönüşünüzde size yatay bir yön belirlemek için Bonus Action kullanabilirsiniz. Etkilenen her hedef, bir sonraki dönüşte o yönde hareket etmek için mümkün olduğu kadar hareket etmelidir. Harekete geçmeden önce her türlü eylemi gerçekleştirebilir. Bu şekilde hareket ettikten sonra başka bir WIS kaydı yaparak efekti sonlandırmaya çalışabilir.\nHedef, fire veya çukur gibi açıkça ölümcül bir tehlikeye doğru ilerlemek zorunda değildir, ancak belirlenen yönde hareket etmek için fırsat saldırılarını tetikleyecektir.","higher":"","sourceText":"Creatures of your choice that you can see within range and that can hear you must make a wisdom saving throw. A target automatically succeeds on this saving throw if it can't be charmed. On a failed save, a target is affected by this spell. Until the spell ends, you can use a bonus action on each of your turns to designate a direction that is horizontal to you. Each affected target must use as much of its movement as possible to move in that direction on its next turn. It can take any action before it moves. After moving in this way, it can make another Wisdom save to try to end the effect.\n\nA target isn't compelled to move into an obviously deadly hazard, such as a fire or a pit, but it will provoke opportunity attacks to move in the designated direction.","higherSource":""},{"id":"cone-of-cold","name":"Cone of Cold","nameTr":"Soğuk Konisi","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir kristal veya cam koni.","materialSource":"A small crystal or glass cone.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"cone","size":60},"description":"Ellerinizden bir cold hava patlaması çıkıyor. Bir 60 ft konisindeki her yaratık CON saving throw atmalıdır. Bir yaratık, başarısız save’de 8d8 cold hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\nBu büyüyle öldürülen yaratık, eriyene kadar donmuş bir heykele dönüşür.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 5. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a constitution saving throw. A creature takes 8d8 cold damage on a failed save, or half as much damage on a successful one.\n\nA creature killed by this spell becomes a frozen statue until it thaws.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."},{"id":"confusion","name":"Confusion","nameTr":"Karışıklık","level":4,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Üç ceviz kabuğu.","materialSource":"Three walnut shells.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":{"type":"sphere","size":10},"description":"Bu büyü, yaratıkların zihinlerine saldırır ve onları çarpıtır, yanılsamalar doğurur ve kontrolsüz eylemleri kışkırtır. Menzil içinde seçtiğiniz bir noktaya odaklanan 10 ft yarıçaplı küredeki her yaratık, bu büyüyü yaptığınızda veya bundan etkilendiğinde bir WIS saving throw üzerinde başarılı olmalıdır.\nEtkilenen hedef Reaction’lar'yi alamaz ve o turdaki davranışını belirlemek için her turun başında d10 atması gerekir.\n| d10 | Davranış |\n|---|---|\n| 1 | Yaratık tüm hareketini rastgele bir yönde hareket etmek için kullanır. Yönü belirlemek için d8 yuvarlayın ve her kalıp yüzüne bir yön atayın. Yaratık bu tur herhangi bir harekette bulunmaz. |\n| 2-6 | Yaratık bu tur hareket etmiyor veya herhangi bir eylemde bulunmuyor. |\n| 7-8 | Yaratık, menzilindeki rastgele belirlenen bir yaratığa karşı yakın dövüş saldırısı yapmak için eylemini kullanır. Ulaşabileceği bir yaratık yoksa yaratık bu turda hiçbir şey yapmaz. |\n| 9-10 | Yaratık normal şekilde hareket edebilir ve hareket edebilir. |\nHer turun sonunda, etkilenen hedef WIS saving throw yapabilir. Başarılı olursa o hedef için bu etki sona erer.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, kürenin yarıçapı 4. seviyenin üzerindeki her yuva seviyesi için 5 ft artar.","sourceText":"This spell assaults and twists creatures' minds, spawning delusions and provoking uncontrolled action. Each creature in a 10-foot-radius sphere centered on a point you choose within range must succeed on a Wisdom saving throw when you cast this spell or be affected by it.\n\nAn affected target can't take reactions and must roll a d10 at the start of each of its turns to determine its behavior for that turn.\n\n| d10 | Behavior |\n\n|---|---|\n\n| 1 | The creature uses all its movement to move in a random direction. To determine the direction, roll a d8 and assign a direction to each die face. The creature doesn't take an action this turn. |\n\n| 2-6 | The creature doesn't move or take actions this turn. |\n\n| 7-8 | The creature uses its action to make a melee attack against a randomly determined creature within its reach. If there is no creature within its reach, the creature does nothing this turn. |\n\n| 9-10 | The creature can act and move normally. |\n\nAt the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, the radius of the sphere increases by 5 feet for each slot level above 4th."},{"id":"conjure-animals","name":"Conjure Animals","nameTr":"Hayvanları Büyüle","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Canavar şeklini alan ve menzil içinde görebileceğiniz boş alanlarda ortaya çıkan peri ruhlarını çağırırsınız. Görünen şey için aşağıdaki seçeneklerden birini seçin:\n- Mücadele derecesi 2 veya daha düşük olan bir canavar\n- Mücadele derecesi 1 veya daha düşük olan iki canavar\n- 1/2 veya daha düşük zorluk derecesine sahip dört canavar\n- 1/4 veya daha düşük sekiz zorlu canavar canavarı\n- Her canavar da peri olarak kabul edilir ve 0 HP'ye düştüğünde veya büyü sona erdiğinde kaybolur.\nÇağrılan yaratıklar size ve arkadaşlarınıza karşı dost canlısıdır. Çağrılan yaratıklar için kendi sıraları olan bir grup olarak yuvarlanma girişimi. Onlara verdiğiniz sözlü emirlere itaat ederler (sizin hiçbir işlem yapmanıza gerek yoktur). Onlara herhangi bir komut vermezseniz, kendilerini düşman yaratıklara karşı savunurlar, ancak bunun dışında hiçbir eylemde bulunmazlar.\nGM'de yaratıkların istatistikleri var.","higher":"Bu büyüyü belirli bir yüksek seviye spell slot’ları kullanarak yaptığınızda, yukarıdaki çağırma seçeneklerinden birini seçersiniz ve daha fazla yaratık ortaya çıkar: 5. seviye yuvayla iki kat daha fazla, 7. seviye yuvayla üç kat daha fazla.","sourceText":"You summon fey spirits that take the form of beasts and appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One beast of challenge rating 2 or lower\n\n- Two beasts of challenge rating 1 or lower\n\n- Four beasts of challenge rating 1/2 or lower\n\n- Eight beasts of challenge rating 1/4 or lower\n\n- Each beast is also considered fey, and it disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","higherSource":"When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 5th-level slot, three times as many with a 7th-level."},{"id":"conjure-celestial","name":"Conjure Celestial","nameTr":"Göksel Büyü Yap","level":7,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz boş bir alanda görünen, meydan okuma derecesi 4 veya daha düşük olan bir göksel çağırırsınız. Göksel, 0 HP'ye düştüğünde veya büyü sona erdiğinde kaybolur.\nBu süre boyunca göksel size ve arkadaşlarınıza dost olacaktır. Kendi dönüşleri olan göksel için yuvarlanma girişimi. Uyumunu ihlal etmedikleri sürece, kendisine vereceğiniz her türlü sözlü emre itaat eder (sizin hiçbir işlem yapmanıza gerek yoktur). Eğer göksel varlığa herhangi bir komut vermezseniz, kendisini düşman yaratıklara karşı savunur ancak bunun dışında hiçbir eylemde bulunmaz.\nGM'de gökselin istatistikleri var.","higher":"Bu büyüyü 9. seviye spell slot kullanarak yaptığınızda, meydan okuma derecesi 5 veya daha düşük olan bir göksel meydan okuma çağırırsınız.","sourceText":"You summon a celestial of challenge rating 4 or lower, which appears in an unoccupied space that you can see within range. The celestial disappears when it drops to 0 hit points or when the spell ends.\n\nThe celestial is friendly to you and your companions for the duration. Roll initiative for the celestial, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the celestial, it defends itself from hostile creatures but otherwise takes no actions.\n\nThe GM has the celestial's statistics.","higherSource":"When you cast this spell using a 9th-level spell slot, you summon a celestial of challenge rating 5 or lower."},{"id":"conjure-elemental","name":"Conjure Elemental","nameTr":"Elemental'i Büyüle","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Wizard"],"subclasses":["Land"],"castingTime":"1 minute","range":"90 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Hava için tütsü yakmak, toprak için yumuşak kil, fire için kükürt ve fosfor veya su için su ve kum.","materialSource":"Burning incense for air, soft clay for earth, sulfur and phosphorus for fire, or water and sand for water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":10},"description":"Bir elemental hizmetkarı çağırıyorsunuz. Menzil içindeki bir 10 ft küpünü dolduracak bir hava, toprak, fire veya su alanı seçin. Seçtiğiniz alana uygun, meydan okuma derecesi 5 veya daha düşük olan bir elemental, onun 10 ft içindeki boş bir alanda görünür. Örneğin, bir fire elementali şenlik ateşinden çıkar ve bir toprak elementali yerden yükselir. Elemental, 0 HP'ye düştüğünde veya büyü sona erdiğinde kaybolur.\nBu süre boyunca elemental size ve arkadaşlarınıza dost olacaktır. Kendi dönüşleri olan elemental için yuvarlanma girişimi. Kendisine verdiğiniz her türlü sözlü emre itaat eder (sizin tarafınızdan herhangi bir işlem yapılması gerekmez). Eğer elementale herhangi bir komut vermezseniz, kendisini düşman yaratıklara karşı savunur ancak bunun dışında hiçbir eylemde bulunmaz.\nconcentration'niz bozulursa elemental kaybolmaz. Bunun yerine, elementalin kontrolünü kaybedersiniz, size ve arkadaşlarınıza karşı düşmanca davranır ve saldırabilir. Kontrolsüz bir elemental sizin tarafınızdan yok edilemez ve onu çağırdıktan 1 saat sonra kaybolur.\nGM'de elementalin istatistikleri var.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, meydan okuma puanı 5. seviyenin üzerindeki her yuva seviyesi için 1 artar.","sourceText":"You call forth an elemental servant. Choose an area of air, earth, fire, or water that fills a 10-foot cube within range. An elemental of challenge rating 5 or lower appropriate to the area you chose appears in an unoccupied space within 10 feet of it. For example, a fire elemental emerges from a bonfire, and an earth elemental rises up from the ground. The elemental disappears when it drops to 0 hit points or when the spell ends.\n\nThe elemental is friendly to you and your companions for the duration. Roll initiative for the elemental, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you). If you don't issue any commands to the elemental, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the elemental doesn't disappear. Instead, you lose control of the elemental, it becomes hostile toward you and your companions, and it might attack. An uncontrolled elemental can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the elemental's statistics.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th."},{"id":"conjure-fey","name":"Conjure Fey","nameTr":"Fey'i Büyüle","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Warlock"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Mücadele puanı 6 veya daha düşük olan bir fey yaratığını ya da meydan okuma derecesi 6 veya daha düşük olan bir canavar şeklini alan bir fey ruhunu çağırırsınız. Menzil içinde görebileceğiniz boş bir alanda görünür. Fey yaratık, 0 HP'ye düştüğünde veya büyü sona erdiğinde ortadan kaybolur.\nFey yaratık bu süre boyunca size ve arkadaşlarınıza karşı dost canlısıdır. Kendi dönüşleri olan yaratık için yuvarlanma girişimi. Uyumunu ihlal etmedikleri sürece, kendisine vereceğiniz her türlü sözlü emre itaat eder (sizin hiçbir işlem yapmanıza gerek yoktur). Peri yaratığa herhangi bir komut vermezseniz, kendisini düşman yaratıklara karşı savunur ancak bunun dışında hiçbir eylemde bulunmaz.\nconcentration'niz kırılırsa, bu peri yaratık ortadan kaybolmaz. Bunun yerine, peri yaratığın kontrolünü kaybedersiniz, size ve arkadaşlarınıza düşman olur ve saldırabilir. Kontrolsüz bir fey yaratığı sizin tarafınızdan kovılamaz ve onu çağırdıktan 1 saat sonra ortadan kaybolur.\nGM'de bu çılgın yaratığın istatistikleri var.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 6. seviyenin üzerindeki her slot seviyesi için meydan okuma puanı 1 artar.","sourceText":"You summon a fey creature of challenge rating 6 or lower, or a fey spirit that takes the form of a beast of challenge rating 6 or lower. It appears in an unoccupied space that you can see within range. The fey creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe fey creature is friendly to you and your companions for the duration. Roll initiative for the creature, which has its own turns. It obeys any verbal commands that you issue to it (no action required by you), as long as they don't violate its alignment. If you don't issue any commands to the fey creature, it defends itself from hostile creatures but otherwise takes no actions.\n\nIf your concentration is broken, the fey creature doesn't disappear. Instead, you lose control of the fey creature, it becomes hostile toward you and your companions, and it might attack. An uncontrolled fey creature can't be dismissed by you, and it disappears 1 hour after you summoned it.\n\nThe GM has the fey creature's statistics.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the challenge rating increases by 1 for each slot level above 6th."},{"id":"conjure-minor-elementals","name":"Conjure Minor Elementals","nameTr":"Minör Elementalleri Büyüle","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"90 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz boş alanlarda ortaya çıkan elementalleri çağırırsınız. Görünen şey için aşağıdaki seçeneklerden birini seçersiniz:\n- Zorluk derecesi 2 veya daha düşük olan bir elemental\n- Mücadele derecesi 1 veya daha düşük olan iki elemental\n- Zorluk derecesi 1/2 veya daha düşük olan dört elemental\n- Zorluk derecesi 1/4 veya daha düşük olan sekiz elemental.\nBu büyü tarafından çağrılan bir elemental, 0 HP'ye düştüğünde veya büyü sona erdiğinde kaybolur.\nÇağrılan yaratıklar size ve arkadaşlarınıza karşı dost canlısıdır. Çağrılan yaratıklar için kendi sıraları olan bir grup olarak yuvarlanma girişimi. Onlara verdiğiniz sözlü emirlere itaat ederler (sizin hiçbir işlem yapmanıza gerek yoktur). Onlara herhangi bir komut vermezseniz, kendilerini düşman yaratıklara karşı savunurlar, ancak bunun dışında hiçbir eylemde bulunmazlar.\nGM'de yaratıkların istatistikleri var.","higher":"Bu büyüyü belirli bir yüksek seviye spell slot’ları kullanarak yaptığınızda, yukarıdaki çağırma seçeneklerinden birini seçersiniz ve daha fazla yaratık ortaya çıkar: 6. seviye yuvayla iki kat daha fazla ve 8. seviye yuvayla üç kat daha fazla.","sourceText":"You summon elementals that appear in unoccupied spaces that you can see within range. You choose one the following options for what appears:\n\n- One elemental of challenge rating 2 or lower\n\n- Two elementals of challenge rating 1 or lower\n\n- Four elementals of challenge rating 1/2 or lower\n\n- Eight elementals of challenge rating 1/4 or lower.\n\nAn elemental summoned by this spell disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which has its own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","higherSource":"When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."},{"id":"conjure-woodland-beings","name":"Conjure Woodland Beings","nameTr":"Orman Varlıklarını Çağır","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Ranger"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Çağrılan yaratık başına bir kutsal meyve.","materialSource":"One holly berry per creature summoned.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz boş alanlarda ortaya çıkan fey yaratıkları çağırırsınız. Görünen şey için aşağıdaki seçeneklerden birini seçin:\n- Mücadele puanı 2 veya daha düşük olan bir çılgın yaratık\n- Mücadele puanı 1 veya daha düşük olan iki çılgın yaratık\n- Mücadele puanı 1/2 veya daha düşük olan dört çılgın yaratık\n- Mücadele puanı 1/4 veya daha düşük olan sekiz fey yaratık\nÇağrılan bir yaratık, 0 HP'ye düştüğünde veya büyü sona erdiğinde kaybolur.\nÇağrılan yaratıklar size ve arkadaşlarınıza karşı dost canlısıdır. Çağrılan yaratıklar için kendi sıraları olan bir grup olarak inisiyatifi yuvarlayın. Onlara verdiğiniz sözlü emirlere itaat ederler (sizin hiçbir işlem yapmanıza gerek yoktur). Onlara herhangi bir komut vermezseniz, kendilerini düşman yaratıklara karşı savunurlar, ancak bunun dışında hiçbir eylemde bulunmazlar.\nGM'de yaratıkların istatistikleri var.","higher":"Bu büyüyü belirli bir yüksek seviye spell slot’ları kullanarak yaptığınızda, yukarıdaki çağırma seçeneklerinden birini seçersiniz ve daha fazla yaratık ortaya çıkar: 6. seviye yuvayla iki kat daha fazla ve 8. seviye yuvayla üç kat daha fazla.","sourceText":"You summon fey creatures that appear in unoccupied spaces that you can see within range. Choose one of the following options for what appears:\n\n- One fey creature of challenge rating 2 or lower\n\n- Two fey creatures of challenge rating 1 or lower\n\n- Four fey creatures of challenge rating 1/2 or lower\n\n- Eight fey creatures of challenge rating 1/4 or lower\n\nA summoned creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe summoned creatures are friendly to you and your companions. Roll initiative for the summoned creatures as a group, which have their own turns. They obey any verbal commands that you issue to them (no action required by you). If you don't issue any commands to them, they defend themselves from hostile creatures, but otherwise take no actions.\n\nThe GM has the creatures' statistics.","higherSource":"When you cast this spell using certain higher-level spell slots, you choose one of the summoning options above, and more creatures appear: twice as many with a 6th-level slot and three times as many with an 8th-level slot."},{"id":"contact-other-plane","name":"Contact Other Plane","nameTr":"Diğer Uçakla İletişime Geçin","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Warlock","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"Self","duration":"1 minute","concentration":false,"ritual":true,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"INT","saves":["INT"],"saveSuccess":"other","area":null,"description":"Zihinsel olarak bir yarı tanrıyla, çoktan ölmüş bir bilgenin ruhuyla ya da başka bir boyuttaki başka bir gizemli varlıkla temasa geçersiniz. Bu ekstraplanar INT ile temasa geçmek zihninizi zorlayabilir, hatta bozabilir. Bu büyüyü yaptığınızda, bir DC 15 INT saving throw yapın. Başarısızlık durumunda, 6d6 psychic hasarı alırsınız ve uzun bir dinlenmeyi bitirene kadar delirirsiniz. Deli olduğunuzda harekete geçemezsiniz, diğer canlıların ne dediğini anlayamazsınız, okuyamazsınız ve sadece anlamsız konuşamazsınız. Size yapılan daha büyük bir yenileme büyüsü bu etkiyi sona erdirir.\nBaşarılı bir kaydetme sonrasında varlığa en fazla beş soru sorabilirsiniz. Büyü bitmeden sorularınızı sormalısınız. GM her soruyu \"evet\", \"hayır\", \"belki\", \"asla\", \"ilgisiz\" veya \"belirsiz\" (varlık sorunun cevabını bilmiyorsa) gibi tek bir kelimeyle yanıtlar. Tek kelimelik bir cevap yanıltıcı olacaksa, GM bunun yerine cevap olarak kısa bir cümle sunabilir.","higher":"","sourceText":"You mentally contact a demigod, the spirit of a long-dead sage, or some other mysterious entity from another plane. Contacting this extraplanar intelligence can strain or even break your mind. When you cast this spell, make a DC 15 intelligence saving throw. On a failure, you take 6d6 psychic damage and are insane until you finish a long rest. While insane, you can't take actions, can't understand what other creatures say, can't read, and speak only in gibberish. A greater restoration spell cast on you ends this effect.\n\nOn a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as \"yes,\" \"no,\" \"maybe,\" \"never,\" \"irrelevant,\" or \"unclear\" (if the entity doesn't know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer.","higherSource":""},{"id":"contagion","name":"Contagion","nameTr":"Bulaşma","level":5,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Druid"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"7 days","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"melee","save":"CON","saves":["CON","WIS","STR","INT","DEX"],"saveSuccess":"other","area":null,"description":"Dokunuşun hastalığa neden olur. Ulaşabileceğiniz bir yaratığa karşı yakın spell attack yapın. Bir vuruşta, yaratığa aşağıda açıklananlardan herhangi birini seçtiğiniz bir hastalıkla saldırırsınız.\nHedefin her turunun sonunda bir CON saving throw yapması gerekir. Bu saving throw’lar'den üçü başarısız olduktan sonra hastalığın etkileri bu süre boyunca devam eder ve yaratık bu kurtarmaları yapmayı bırakır. Bu saving throw’lar'den üçünü başarıyla tamamladıktan sonra yaratık hastalıktan kurtulur ve büyü sona erer.\nBu büyü hedefinde doğal bir hastalık tetiklediği için, bir hastalığı ortadan kaldıran veya hastalığın etkilerini başka şekilde iyileştiren herhangi bir etki, kendisine uygulanır.\n***Kör Edici Hastalık.*** Acı, yaratığın zihnini ele geçirir ve gözleri süt beyazına döner. Yaratığın WIS kontrollerinde dezavantaj ve WIS saving throw’lar vardır ve blinded'dir.\n***Pislik Ateşi*** Azgın bir ateş yaratığın vücudunu sarıyor. Yaratığın dezavantaj kontrollerinde dezavantaj, STR saving throw’lar ve STR kullanan saldırı atışları var.\n***Et Çürümesi.*** Yaratığın eti çürür. Yaratığın dezavantaj üzerinde CHA kontrolleri ve her türlü hasara karşı savunmasızlığı bulunuyor.\n***Akıl ateşi.*** Yaratığın zihni hararetli hale gelir. Yaratığın INT kontrollerinde ve INT saving throw’lar üzerinde dezavantaj bulunuyor ve yaratık, dövüş sırasında kafa karışıklığı büyüsünün etkisi altındaymış gibi davranıyor.\n***Nöbet.*** Yaratık titremeye yenik düşer. Yaratığın dezavantaj kontrollerinde dezavantaj, DEX saving throw’lar ve DEX kullanan saldırı atışları var.\n***Sümüksü Kıyamet*** Yaratık kontrolsüz bir şekilde kanamaya başlar. Yaratığın CON çeklerinde dezavantaj ve CON saving throw’lar var. Ayrıca yaratık hasar aldığında bir sonraki turun sonuna kadar stunned olur.","higher":"","sourceText":"Your touch inflicts disease. Make a melee spell attack against a creature within your reach. On a hit, you afflict the creature with a disease of your choice from any of the ones described below.\n\nAt the end of each of the target's turns, it must make a constitution saving throw. After failing three of these saving throws, the disease's effects last for the duration, and the creature stops making these saves. After succeeding on three of these saving throws, the creature recovers from the disease, and the spell ends.\n\nSince this spell induces a natural disease in its target, any effect that removes a disease or otherwise ameliorates a disease's effects apply to it.\n\n***Blinding Sickness.*** Pain grips the creature's mind, and its eyes turn milky white. The creature has disadvantage on wisdom checks and wisdom saving throws and is blinded.\n\n***Filth Fever.*** A raging fever sweeps through the creature's body. The creature has disadvantage on strength checks, strength saving throws, and attack rolls that use Strength.\n\n***Flesh Rot.*** The creature's flesh decays. The creature has disadvantage on Charisma checks and vulnerability to all damage.\n\n***Mindfire.*** The creature's mind becomes feverish. The creature has disadvantage on intelligence checks and intelligence saving throws, and the creature behaves as if under the effects of the confusion spell during combat.\n\n***Seizure.*** The creature is overcome with shaking. The creature has disadvantage on dexterity checks, dexterity saving throws, and attack rolls that use Dexterity.\n\n***Slimy Doom.*** The creature begins to bleed uncontrollably. The creature has disadvantage on constitution checks and constitution saving throws. In addition, whenever the creature takes damage, it is stunned until the end of its next turn.","higherSource":""},{"id":"contingency","name":"Contingency","nameTr":"beklenmedik durum","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Self","duration":"10 days","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Fildişinden oyulmuş ve en az 1.500 GP değerinde mücevherlerle süslenmiş bir heykelcik.","materialSource":"A statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Yapabileceğiniz, kullanım süresi 1 eylem olan ve sizi hedef alabilecek 5. seviye veya daha düşük bir büyü seçin. Olasılık büyüsü olarak adlandırılan bu büyüyü, olasılığın bir parçası olarak, her ikisi için de spell slot’ları harcayarak kullanırsınız, ancak koşullu büyü yürürlüğe girmez. Bunun yerine belirli bir durum meydana geldiğinde etkili olur. İki büyüyü yaptığınızda bu durumu anlatırsınız. Örneğin, su ile nefes alma ile ilgili bir acil durum alçısı, su veya benzeri bir sıvıya maruz kaldığınızda su ile nefes almanın devreye gireceğini şart koşabilir.\nKoşullu büyü, siz isteseniz de istemeseniz de, durumla ilk kez karşılaşıldığında hemen etkili olur. ve sonra beklenmedik durum sona erer.\nKoşullu büyü normalde başkalarını hedef alsa bile yalnızca sizin üzerinizde etkili olur. Aynı anda yalnızca bir acil durum büyüsü kullanabilirsiniz. Bu büyüyü tekrar yaparsanız, başka bir acil durum büyüsünün üzerinizdeki etkisi sona erer. Ayrıca, eğer maddi unsuru sizin üzerinizde değilse, beklenmedik durum sizin aleyhinize sona erer.","higher":"","sourceText":"Choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell--called the contingent spell--as part of casting contingency, expending spell slots for both, but the contingent spell doesn't come into effect. Instead, it takes effect when a certain circumstance occurs. You describe that circumstance when you cast the two spells. For example, a contingency cast with water breathing might stipulate that water breathing comes into effect when you are engulfed in water or a similar liquid.\n\nThe contingent spell takes effect immediately after the circumstance is met for the first time, whether or not you want it to. and then contingency ends.\n\nThe contingent spell takes effect only on you, even if it can normally target others. You can use only one contingency spell at a time. If you cast this spell again, the effect of another contingency spell on you ends. Also, contingency ends on you if its material component is ever not on your person.","higherSource":""},{"id":"continual-flame","name":"Continual Flame","nameTr":"Sürekli Alev","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği 50 gp değerindeki yakut tozu.","materialSource":"Ruby dust worth 50 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz bir nesneden parlaklık bakımından meşale eşdeğerinde bir alev fışkırır. Etki normal bir aleve benziyor ancak ısı yaratmıyor ve oksijen kullanmıyor. Sürekli bir alev kapatılabilir veya gizlenebilir ancak bastırılamaz veya söndürülemez.","higher":"","sourceText":"A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered or hidden but not smothered or quenched.","higherSource":""},{"id":"control-water","name":"Control Water","nameTr":"Kontrol Suyu","level":4,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid","Wizard"],"subclasses":[],"castingTime":"1 action","range":"300 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla su ve bir tutam toz.","materialSource":"A drop of water and a pinch of dust.","attackType":"","save":"STR","saves":["STR"],"saveSuccess":"half","area":{"type":"cube","size":100},"description":"Büyü sona erene kadar, bir tarafta 100 ft'ye kadar küp olan, seçtiğiniz bir alandaki bağımsız suyu kontrol edersiniz. Bu büyüyü yaptığınızda aşağıdaki efektlerden herhangi birini seçebilirsiniz. Sıra size geldiğinde, aynı efekti tekrarlayabilir veya farklı bir efekt seçebilirsiniz.\n***Sel.*** Bölgedeki tüm durgun suların su seviyesinin 20 ft kadar yükselmesine neden olursunuz. Alanın kıyısı varsa, sular kuru araziye taşar.\nBüyük bir su kütlesi içindeki bir alanı seçerseniz, bunun yerine bölgenin bir tarafından diğerine ilerleyen ve ardından aşağıya çarpan 20 ft uzun bir dalga yaratırsınız. Dalganın yolu üzerindeki herhangi bir büyük veya daha küçük araç, dalganın diğer tarafına taşınır. Dalganın çarptığı büyük veya daha küçük araçların alabora olma şansı yüzde 25'tir.\nBüyü bitene veya siz farklı bir efekt seçene kadar su seviyesi yüksek kalır. Bu etki bir dalga yarattıysa, taşma etkisi devam ederken dalga bir sonraki dönüşün başlangıcında tekrarlanır.\n***Kısmi Su.*** Bölgedeki suyun birbirinden ayrılarak hendek oluşturmasına neden olursunuz. Hendek büyü alanı boyunca uzanıyor ve ayrılan su her iki tarafta da bir duvar oluşturuyor. Siper, büyü bitene veya siz farklı bir efekt seçene kadar kalır. Daha sonra su, normal su seviyesi yeniden sağlanana kadar bir sonraki tur boyunca hendeği yavaşça doldurur.\n***Akışı Yönlendirin.*** Su engellerin üzerinden, duvarların yukarısına veya diğer beklenmedik yönlere doğru akmak zorunda kalsa bile, bölgedeki akan suyun seçtiğiniz bir yönde hareket etmesini sağlarsınız. Bölgedeki su siz yönlendirdikçe hareket eder, ancak büyü alanının dışına çıktığında arazi koşullarına bağlı olarak akışına devam eder. Büyü bitene veya siz farklı bir efekt seçene kadar su seçtiğiniz yönde hareket etmeye devam eder.\n***Whirlpool.*** Bu etki, en az 50 ft kare ve 25 ft derinliğinde bir su kütlesi gerektirir. Alanın ortasında bir girdap oluşmasına neden olursunuz. Girdap, tabanda 5 ft genişliğinde, üstte 50 ft genişliğe kadar ve 25 ft yüksekliğinde bir girdap oluşturur. Sudaki ve girdabın 25 ft içindeki herhangi bir yaratık veya nesne, 10 ft'yi kendisine doğru çeker. Bir yaratık, DC'yi kurtaran büyünüze karşı STR (Atletizm) kontrolü yaparak girdaptan yüzerek uzaklaşabilir.\nBir yaratık bir dönüşte girdaba ilk kez girdiğinde veya dönüşüne burada başladığında STR saving throw yapmalıdır. Başarısız bir kurtarma durumunda yaratık 2d8 bludgeoning hasarı alır ve büyü bitene kadar girdapta kalır. Başarılı bir kurtarışta yaratık yarı hasar alır ve girdaba yakalanmaz. Girdaba yakalanan bir yaratık, yukarıda açıklandığı gibi girdaptan yüzerek uzaklaşmayı denemek için hareketini kullanabilir, ancak bunu yapmak için dezavantaj (Atletizm) kontrolüne sahiptir.\nBir nesnenin girdaba girdiği her dönüşte, nesne 2d8 bludgeoning hasarı alır; bu hasar girdapta kaldığı her turda meydana gelir.","higher":"","sourceText":"Until the spell ends, you control any freestanding water inside an area you choose that is a cube up to 100 feet on a side. You can choose from any of the following effects when you cast this spell. As an action on your turn, you can repeat the same effect or choose a different one.\n\n***Flood.*** You cause the water level of all standing water in the area to rise by as much as 20 feet. If the area includes a shore, the flooding water spills over onto dry land.\n\nIf you choose an area in a large body of water, you instead create a 20-foot tall wave that travels from one side of the area to the other and then crashes down. Any Huge or smaller vehicles in the wave's path are carried with it to the other side. Any Huge or smaller vehicles struck by the wave have a 25 percent chance of capsizing.\n\nThe water level remains elevated until the spell ends or you choose a different effect. If this effect produced a wave, the wave repeats on the start of your next turn while the flood effect lasts.\n\n***Part Water.*** You cause water in the area to move apart and create a trench. The trench extends across the spell's area, and the separated water forms a wall to either side. The trench remains until the spell ends or you choose a different effect. The water then slowly fills in the trench over the course of the next round until the normal water level is restored.\n\n***Redirect Flow.*** You cause flowing water in the area to move in a direction you choose, even if the water has to flow over obstacles, up walls, or in other unlikely directions. The water in the area moves as you direct it, but once it moves beyond the spell's area, it resumes its flow based on the terrain conditions. The water continues to move in the direction you chose until the spell ends or you choose a different effect.\n\n***Whirlpool.*** This effect requires a body of water at least 50 feet square and 25 feet deep. You cause a whirlpool to form in the center of the area. The whirlpool forms a vortex that is 5 feet wide at the base, up to 50 feet wide at the top, and 25 feet tall. Any creature or object in the water and within 25 feet of the vortex is pulled 10 feet toward it. A creature can swim away from the vortex by making a Strength (Athletics) check against your spell save DC.\n\nWhen a creature enters the vortex for the first time on a turn or starts its turn there, it must make a strength saving throw. On a failed save, the creature takes 2d8 bludgeoning damage and is caught in the vortex until the spell ends. On a successful save, the creature takes half damage, and isn't caught in the vortex. A creature caught in the vortex can use its action to try to swim away from the vortex as described above, but has disadvantage on the Strength (Athletics) check to do so.\n\nThe first time each turn that an object enters the vortex, the object takes 2d8 bludgeoning damage; this damage occurs each round it remains in the vortex.","higherSource":""},{"id":"control-weather","name":"Control Weather","nameTr":"Hava Durumunun Kontrolü","level":8,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid","Wizard"],"subclasses":["Land"],"castingTime":"10 minutes","range":"Self","duration":"Up to 8 hours","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Suya karıştırılmış tütsü ve toprak ve odun parçalarının yakılması.","materialSource":"Burning incense and bits of earth and wood mixed in water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca 5 mil dahilindeki hava durumunun kontrolünü elinize alırsınız. Bu büyüyü yapabilmek için dışarıda olmanız gerekir. Gökyüzüne giden net bir yolun olmadığı bir yere taşınmak büyüyü erken bitirir.\nBüyüyü yaptığınızda, GM'nin iklim ve mevsime göre belirlediği mevcut hava koşullarını değiştirirsiniz. Yağışı, sıcaklığı ve rüzgarı değiştirebilirsiniz. Yeni koşulların yürürlüğe girmesi 1d4 x 10 dakika sürer. Bunu yaptıktan sonra koşulları tekrar değiştirebilirsiniz. Büyü sona erdiğinde hava yavaş yavaş normale döner.\nHava koşullarını değiştirdiğinizde aşağıdaki tablolardan mevcut durumu bulun ve kademesini birer birer yukarı veya aşağı değiştirin. Rüzgarı değiştirirken yönünü de değiştirebilirsiniz.\n##### Yağış\n| Sahne | Durum |\n|---|---|\n| 1 | Temizle |\n| 2 | Hafif bulutlar |\n| 3 | Bulutlu veya sisli |\n| 4 | Yağmur, dolu veya kar |\n| 5 | Sağanak yağmur, şiddetli dolu veya kar fırtınası |\n##### Sıcaklık\n| Sahne | Durum |\n|---|---|\n| 1 | Dayanılmaz ısı |\n| 2 | Sıcak |\n| 3 | Sıcak |\n| 4 | Harika |\n| 5 | cold |\n| 6 | Arktik cold |\n##### Rüzgar\n| Sahne | Durum |\n|---|---|\n| 1 | Sakin |\n| 2 | Orta rüzgar |\n| 3 | Kuvvetli rüzgar |\n| 4 | Fırtına |\n| 5 | Fırtına |","higher":"","sourceText":"You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don't have a clear path to the sky ends the spell early.\n\nWhen you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 x 10 minutes for the new conditions to take effect. Once they do so, you can change the conditions again. When the spell ends, the weather gradually returns to normal.\n\nWhen you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction.\n\n##### Precipitation\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Clear |\n\n| 2 | Light clouds |\n\n| 3 | Overcast or ground fog |\n\n| 4 | Rain, hail, or snow |\n\n| 5 | Torrential rain, driving hail, or blizzard |\n\n##### Temperature\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Unbearable heat |\n\n| 2 | Hot |\n\n| 3 | Warm |\n\n| 4 | Cool |\n\n| 5 | Cold |\n\n| 6 | Arctic cold |\n\n##### Wind\n\n| Stage | Condition |\n\n|---|---|\n\n| 1 | Calm |\n\n| 2 | Moderate wind |\n\n| 3 | Strong wind |\n\n| 4 | Gale |\n\n| 5 | Storm |","higherSource":""},{"id":"counterspell","name":"Counterspell","nameTr":"Karşı büyü","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 reaction","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü yapma sürecindeki bir yaratığın sözünü kesmeye çalışıyorsunuz. Yaratık 3. seviye veya daha düşük bir büyü yapıyorsa büyüsü başarısız olur ve hiçbir etkisi olmaz. 4. seviye veya daha yüksek bir büyü yapıyorsa, büyü yapma yeteneğinizi kullanarak bir ability check yapın. DC, 10 + büyünün seviyesine eşittir. Başarılı olunduğunda yaratığın büyüsü başarısız olur ve hiçbir etkisi olmaz.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, seviyesi kullandığınız spell slot seviyesinden düşük veya ona eşitse, kesintiye uğrayan büyünün hiçbir etkisi olmaz.","sourceText":"You attempt to interrupt a creature in the process of casting a spell. If the creature is casting a spell of 3rd level or lower, its spell fails and has no effect. If it is casting a spell of 4th level or higher, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a success, the creature's spell fails and has no effect.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the interrupted spell has no effect if its level is less than or equal to the level of the spell slot you used."},{"id":"create-food-and-water","name":"Create Food and Water","nameTr":"Yiyecek ve Su Oluşturun","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Druid","Paladin"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Yerde veya menzil içindeki kaplarda 45 lb yiyecek ve 30 galon su yaratırsınız; bu, on beşe kadar insansı hayvanı veya beş atı 24 saat boyunca beslemeye yetecektir. Yiyecekler yumuşak ama besleyicidir ve 24 saat sonra yenilmezse bozulur. Su temizdir ve bozulmaz.","higher":"","sourceText":"You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing, and spoils if uneaten after 24 hours. The water is clean and doesn't go bad.","higherSource":""},{"id":"create-undead","name":"Create Undead","nameTr":"Ölümsüz Yarat","level":6,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Warlock","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Her ceset için bir adet mezar toprağıyla doldurulmuş toprak kap, bir adet acı su ile doldurulmuş toprak kap ve bir adet 150 gp siyah oniks taşı.","materialSource":"One clay pot filled with grave dirt, one clay pot filled with brackish water, and one 150 gp black onyx stone for each corpse.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyüyü sadece geceleri yapabilirsiniz. Menzildeki en fazla üç Orta veya Küçük insansı cesedi seçin. Her ceset kontrolünüz altında bir gulyabani haline gelir. (GM'nin bu yaratıklar için oyun istatistikleri vardır.)\nHer sıranızda bir Bonus Action olarak, eğer yaratık 120 ft yakınınızdaysa, bu büyüyle canlandırdığınız herhangi bir yaratığa zihinsel olarak komut verebilirsiniz (birden fazla yaratığı kontrol ediyorsanız, bunlardan herhangi birine veya hepsine aynı anda komut verebilirsiniz, her birine aynı komutu verebilirsiniz). Yaratığın bir sonraki dönüşte hangi eylemi gerçekleştireceğine ve nereye hareket edeceğine siz karar verirsiniz veya belirli bir odayı veya koridoru korumak gibi genel bir komut verebilirsiniz. Hiçbir komut vermezseniz yaratık yalnızca kendisini düşman yaratıklara karşı savunur. Bir emir verildiğinde yaratık, görevi tamamlanana kadar onu takip etmeye devam eder.\nYaratık 24 saat boyunca sizin kontrolünüz altındadır ve sonrasında ona verdiğiniz hiçbir komuta uymayı bırakır. Yaratığın kontrolünü 24 saat daha sürdürmek için, bu büyüyü mevcut 24 saatlik süre sona ermeden yaratığa yapmalısınız. Büyünün bu kullanımı, yeni yaratıkları canlandırmak yerine, bu büyüyle canlandırdığınız en fazla üç yaratık üzerinde kontrolünüzü yeniden sağlar.","higher":"Bu büyüyü 7. seviye spell slot kullanarak yaptığınızda, dört gulyabaniyi canlandırabilir veya kontrolünü yeniden sağlayabilirsiniz. Bu büyüyü 8. seviye spell slot kullanarak yaptığınızda, beş gulyabani veya iki ghast veya wight'ı canlandırabilir veya kontrolünü yeniden sağlayabilirsiniz. Bu büyüyü 9. seviye spell slot kullanarak yaptığınızda, altı gulyabani, üç hayalet veya wight veya iki mumyayı canlandırabilir veya kontrolünüzü yeniden sağlayabilirsiniz.","sourceText":"You can cast this spell only at night. Choose up to three corpses of Medium or Small humanoids within range. Each corpse becomes a ghoul under your control. (The GM has game statistics for these creatures.)\n\nAs a bonus action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete.\n\nThe creature is under your control for 24 hours, after which it stops obeying any command you have given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell, rather than animating new ones.","higherSource":"When you cast this spell using a 7th-level spell slot, you can animate or reassert control over four ghouls. When you cast this spell using an 8th-level spell slot, you can animate or reassert control over five ghouls or two ghasts or wights. When you cast this spell using a 9th-level spell slot, you can animate or reassert control over six ghouls, three ghasts or wights, or two mummies."},{"id":"create-or-destroy-water","name":"Create or Destroy Water","nameTr":"Su Yaratın veya Yok Edin","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Su yaratıyorsa bir damla su, yok ediyorsa birkaç kum tanesi.","materialSource":"A drop of water if creating water, or a few grains of sand if destroying it.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":30},"description":"Suyu ya yaratırsınız ya da yok edersiniz.\n***Su Oluşturun.*** Açık bir kapta menzil dahilinde 10 galona kadar temiz su oluşturursunuz. Alternatif olarak su, menzil içindeki bir 30 ft küpünde yağmur olarak düşer.\n***Suyu Yok Edin.*** Menzil içindeki açık bir kapta 10 galona kadar suyu yok edersiniz. Alternatif olarak menzil içindeki bir 30 ft küpündeki sisi yok edebilirsiniz.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, ilave 10 galon su yaratır veya yok edersiniz veya 1. seviyenin üzerindeki her yuva seviyesi için küpün boyutu 5 ft artar.","sourceText":"You either create or destroy water.\n\n***Create Water.*** You create up to 10 gallons of clean water within range in an open container. Alternatively, the water falls as rain in a 30-foot cube within range.\n\n***Destroy Water.*** You destroy up to 10 gallons of water in an open container within range. Alternatively, you destroy fog in a 30-foot cube within range.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you create or destroy 10 additional gallons of water, or the size of the cube increases by 5 feet, for each slot level above 1st."},{"id":"creation","name":"Creation","nameTr":"Yaratılış","level":5,"school":"Illusion","schoolTr":"İllüzyon","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","duration":"Special","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Yaratmayı planladığınız öğenin aynı türünden küçük bir madde parçası.","materialSource":"A tiny piece of matter of the same type of the item you plan to create.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":5},"description":"Menzil içinde bitkisel maddelerden oluşan cansız bir nesne oluşturmak için Gölgeyarı'ndan gölge malzemesi tutamları çekersiniz: yumuşak ürünler, ip, tahta veya benzeri bir şey. Bu büyüyü taş, kristal veya metal gibi mineral nesneler oluşturmak için de kullanabilirsiniz. Oluşturulan nesnenin 5 ft küpten büyük olmaması ve nesnenin daha önce gördüğünüz form ve malzemeden olması gerekmektedir.\nSüre nesnenin malzemesine bağlıdır. Nesne birden fazla malzemeden oluşuyorsa en kısa süreyi kullanın.\n| Malzeme | Süre |\n|---|---|\n| Bitkisel madde | 1 gün |\n| Taş veya kristal | 12 saat |\n| Değerli metaller | 1 saat |\n| Mücevher | 10 dakika |\n| Adamantin veya mitral | 1 dakika |\nBu büyünün yarattığı herhangi bir materyali başka bir büyünün materyal bileşeni olarak kullanmak o büyünün başarısız olmasına neden olur.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, küp 5. seviyenin üzerindeki her yuva seviyesi için 5 ft artar.","sourceText":"You pull wisps of shadow material from the Shadowfell to create a nonliving object of vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before.\n\nThe duration depends on the object's material. If the object is composed of multiple materials, use the shortest duration.\n\n| Material | Duration |\n\n|---|---|\n\n| Vegetable matter | 1 day |\n\n| Stone or crystal | 12 hours |\n\n| Precious metals | 1 hour |\n\n| Gems | 10 minutes |\n\n| Adamantine or mithral | 1 minute |\n\nUsing any material created by this spell as another spell's material component causes that spell to fail.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the cube increases by 5 feet for each slot level above 5th."},{"id":"cure-wounds","name":"Cure Wounds","nameTr":"Yaraları İyileştirmek","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Cleric","Druid","Paladin","Ranger"],"subclasses":["Life","Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz bir yaratık, 1d8 + büyü yapma yeteneği değiştiricinize eşit sayıda HP sayısını yeniden kazanır. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, iyileştirme 1. seviyenin üzerindeki her slot seviyesi için 1d8 artar.","sourceText":"A creature you touch regains a number of hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d8 for each slot level above 1st."},{"id":"dancing-lights","name":"Dancing Lights","nameTr":"Dans Eden Işıklar","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz fosfor, wychwood ya da ateş böceği.","materialSource":"A bit of phosphorus or wychwood, or a glowworm.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde dört adede kadar meşale boyutunda ışık yaratarak bunların meşaleler, fenerler veya havada asılı kalan parlayan küreler gibi görünmesini sağlarsınız. Ayrıca dört ışığı Orta büyüklükte, belli belirsiz parlayan tek bir insansı formda birleştirebilirsiniz. Hangi biçimi seçerseniz seçin, her ışık 10 ft yarıçapında loş ışık tutar.\nSıra size geldiğinde Bonus Action olarak ışıkları 60 ft'ye kadar menzil içindeki yeni bir noktaya taşıyabilirsiniz. Bir ışık, bu büyü tarafından oluşturulan başka bir ışığın 20 ft yakınında olmalıdır ve büyünün menzilini aşarsa bir ışık yanıp söner.","higher":"","sourceText":"You create up to four torch-sized lights within range, making them appear as torches, lanterns, or glowing orbs that hover in the air for the duration. You can also combine the four lights into one glowing vaguely humanoid form of Medium size. Whichever form you choose, each light sheds dim light in a 10-foot radius.\n\nAs a bonus action on your turn, you can move the lights up to 60 feet to a new spot within range. A light must be within 20 feet of another light created by this spell, and a light winks out if it exceeds the spell's range.","higherSource":""},{"id":"darkness","name":"Darkness","nameTr":"Karanlık","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","M"],"materialTr":"Yarasa kürkü ve bir damla zift veya bir parça kömür.","materialSource":"Bat fur and a drop of pitch or piece of coal.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":15},"description":"Büyülü karanlık, menzil içinde seçtiğiniz bir noktadan yayılarak bir 15 ft yarıçap küresini bu süre boyunca doldurur. Karanlık köşelere yayılıyor. Karanlık görüşe sahip bir yaratık bu karanlığın arkasını göremez ve büyülü olmayan ışık onu aydınlatamaz.\nSeçtiğiniz nokta, tuttuğunuz veya giyilmeyen veya taşınmayan bir nesnenin üzerindeyse, karanlık nesneden yayılır ve onunla birlikte hareket eder. Karanlığın kaynağını kase veya miğfer gibi opak bir cisimle tamamen kapatmak karanlığı engeller.\nBu büyünün alanlarından herhangi biri, 2. seviye veya daha düşük bir büyü tarafından oluşturulan bir ışık alanıyla örtüşürse, ışığı yaratan büyü bozulur.","higher":"","sourceText":"Magical darkness spreads from a point you choose within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and nonmagical light can't illuminate it.\n\nIf the point you choose is on an object you are holding or one that isn't being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.\n\nIf any of this spell's area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled.","higherSource":""},{"id":"darkvision","name":"Darkvision","nameTr":"Karanlık görüş","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam kurutulmuş havuç veya akik.","materialSource":"Either a pinch of dried carrot or an agate.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Karanlıkta görme yeteneği kazandırmak için istekli bir yaratığa dokunuyorsunuz. Bu süre boyunca, bu yaratığın 60 ft aralığına kadar karanlık görüşü vardır.","higher":"","sourceText":"You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet.","higherSource":""},{"id":"daylight","name":"Daylight","nameTr":"Gün ışığı","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric","Druid","Paladin","Ranger","Sorcerer"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"60 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":60},"description":"60 ft yarıçap ışık küresi, menzil içinde seçtiğiniz bir noktadan yayılır. Küre parlak ışıktır ve ek bir 60 ft için loş ışık yayar.\nTuttuğunuz veya giyilmeyen veya taşınmayan bir nesnenin üzerinde bir nokta seçerseniz, ışık nesneden parlar ve onunla birlikte hareket eder. Etkilenen nesnenin kase veya dümen gibi opak bir nesneyle tamamen kapatılması ışığı engeller.\nBu büyünün alanlarından herhangi biri, 3. seviye veya daha düşük bir büyü tarafından oluşturulan karanlık bir alanla örtüşürse, karanlığı yaratan büyü ortadan kalkar.","higher":"","sourceText":"A 60-foot-radius sphere of light spreads out from a point you choose within range. The sphere is bright light and sheds dim light for an additional 60 feet.\n\nIf you chose a point on an object you are holding or one that isn't being worn or carried, the light shines from the object and moves with it. Completely covering the affected object with an opaque object, such as a bowl or a helm, blocks the light.\n\nIf any of this spell's area overlaps with an area of darkness created by a spell of 3rd level or lower, the spell that created the darkness is dispelled.","higherSource":""},{"id":"death-ward","name":"Death Ward","nameTr":"Ölüm Koğuşu","level":4,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin"],"subclasses":["Life"],"castingTime":"1 action","range":"Touch","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsunuz ve ona ölümden bir miktar koruma sağlıyorsunuz.\nHasar almanın bir sonucu olarak hedef ilk kez 0 HP'ye düştüğünde, bunun yerine hedef 1 vuruş puanına düşer ve büyü sona erer.\nHedef, onu hasar vermeden anında öldürecek bir etkiye maruz kaldığında büyü hala etkiliyse, bu etki hedefte engellenir ve büyü sona erer.","higher":"","sourceText":"You touch a creature and grant it a measure of protection from death.\n\nThe first time the target would drop to 0 hit points as a result of taking damage, the target instead drops to 1 hit point, and the spell ends.\n\nIf the spell is still in effect when the target is subjected to an effect that would kill it instantaneously without dealing damage, that effect is instead negated against the target, and the spell ends.","higherSource":""},{"id":"delayed-blast-fireball","name":"Delayed Blast Fireball","nameTr":"Gecikmeli Patlama Ateş Topu","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir yarasa gübresi ve kükürt topu.","materialSource":"A tiny ball of bat guano and sulfur.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"sphere","size":20},"description":"İşaret parmağınızdan bir sarı ışık huzmesi yanıp söner, ardından yoğunlaşarak menzil içinde seçilen bir noktada parlayan bir boncuk olarak oyalanır. concentration'niz bozulduğu için ya da siz onu bitirmeye karar verdiğiniz için büyü sona erdiğinde, boncuk hafif bir kükremeyle çiçek açarak köşelere yayılan bir alev patlamasına dönüşür. Bu noktaya odaklanan 20 ft yarıçaplı küredeki her yaratık, bir DEX saving throw yapmalıdır. Bir yaratık, başarısız save’de toplam birikmiş hasara eşit veya başarılı save’de yarısı kadar fire hasar alır.\nBüyünün temel hasarı 12d6'dir. Turunuzun sonunda boncuk henüz patlamamışsa hasar 1d6 artar.\nParlayan boncuğa aralık dolmadan dokunulursa, ona dokunan yaratığın bir DEX saving throw yapması gerekir. Başarısız bir kurtarma durumunda büyü hemen sona erer ve boncuğun alevler içinde patlamasına neden olur. Başarılı bir kurtarmanın ardından yaratık, boncuğu 40 ft'ye kadar fırlatabilir. Bir yaratığa veya katı bir nesneye çarptığında büyü sona erer ve boncuk patlar.\nfire, bölgedeki nesnelere zarar verir ve giyilmeyen veya taşınmayan yanıcı nesneleri ateşler.","higher":"Bu büyüyü 8. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 7. seviyenin üzerindeki her yuva seviyesi için taban hasar 1d6 artar.","sourceText":"A beam of yellow light flashes from your pointing finger, then condenses to linger at a chosen point within range as a glowing bead for the duration. When the spell ends, either because your concentration is broken or because you decide to end it, the bead blossoms with a low roar into an explosion of flame that spreads around corners. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A creature takes fire damage equal to the total accumulated damage on a failed save, or half as much damage on a successful one.\n\nThe spell's base damage is 12d6. If at the end of your turn the bead has not yet detonated, the damage increases by 1d6.\n\nIf the glowing bead is touched before the interval has expired, the creature touching it must make a dexterity saving throw. On a failed save, the spell ends immediately, causing the bead to erupt in flame. On a successful save, the creature can throw the bead up to 40 feet. When it strikes a creature or a solid object, the spell ends, and the bead explodes.\n\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried.","higherSource":"When you cast this spell using a spell slot of 8th level or higher, the base damage increases by 1d6 for each slot level above 7th."},{"id":"demiplane","name":"Demiplane","nameTr":"Yarım düzlem","level":8,"school":"Conjuration","schoolTr":"Çağırma","classes":["Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz düz ve sağlam bir yüzey üzerinde gölgeli bir kapı yaratırsınız. Kapı Orta boy yaratıkların engellenmeden geçmesine izin verecek kadar büyüktür. Kapı açıldığında, her boyutta ahşap veya taştan yapılmış boş bir oda 30 ft gibi görünen bir yarım düzleme açılıyor. Büyü sona erdiğinde kapı kaybolur ve yarı düzlemin içindeki yaratıklar veya nesneler orada sıkışıp kalır, çünkü kapı diğer taraftan da kaybolur.\nBu büyüyü her yaptığınızda, yeni bir yarı düzlem oluşturabilir veya gölgeli kapının, bu büyüyü daha önce yaptığınızda oluşturduğunuz bir yarı düzleme bağlanmasını sağlayabilirsiniz. Ek olarak, başka bir yaratık tarafından bu büyünün yapılmasıyla oluşturulan yarı düzlemin doğasını ve içeriğini biliyorsanız, bunun yerine gölgeli kapının yarı düzleme bağlanmasını sağlayabilirsiniz.","higher":"","sourceText":"You create a shadowy door on a flat solid surface that you can see within range. The door is large enough to allow Medium creatures to pass through unhindered. When opened, the door leads to a demiplane that appears to be an empty room 30 feet in each dimension, made of wood or stone. When the spell ends, the door disappears, and any creatures or objects inside the demiplane remain trapped there, as the door also disappears from the other side.\n\nEach time you cast this spell, you can create a new demiplane, or have the shadowy door connect to a demiplane you created with a previous casting of this spell. Additionally, if you know the nature and contents of a demiplane created by a casting of this spell by another creature, you can have the shadowy door connect to its demiplane instead.","higherSource":""},{"id":"detect-evil-and-good","name":"Detect Evil and Good","nameTr":"Kötüyü ve İyiyi Algıla","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric","Paladin"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Bu süre boyunca 30 ft'nizde bir sapkınlık, göksel, elemental, peri, iblis veya ölümsüz olup olmadığının yanı sıra yaratığın nerede bulunduğunu da bilirsiniz. Benzer şekilde, 30 ft'nizde sihirli bir şekilde kutsanan veya kutsallaştırılan bir yer veya nesnenin olup olmadığını bilirsiniz.\nBüyü çoğu engeli aşabilir ancak 1 ft taş, 1 inçlik adi metal, ince bir kurşun levha veya 3 ft tahta veya toprak tarafından engellenir.","higher":"","sourceText":"For the duration, you know if there is an aberration, celestial, elemental, fey, fiend, or undead within 30 feet of you, as well as where the creature is located. Similarly, you know if there is a place or object within 30 feet of you that has been magically consecrated or desecrated.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","higherSource":""},{"id":"detect-magic","name":"Detect Magic","nameTr":"Büyüyü Algıla","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Druid","Paladin","Ranger","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Bu süre boyunca 30 ft içinizde büyünün varlığını hissedeceksiniz. Bu şekilde büyü hissederseniz, eyleminizi kullanarak bölgedeki büyü taşıyan herhangi bir canlının veya nesnenin etrafında hafif bir aura görebilir ve varsa büyü okulunu öğrenebilirsiniz.\nBüyü çoğu engeli aşabilir ancak 1 ft taş, 1 inçlik adi metal, ince bir kurşun levha veya 3 ft ahşap veya toprak tarafından engellenir.","higher":"","sourceText":"For the duration, you sense the presence of magic within 30 feet of you. If you sense magic in this way, you can use your action to see a faint aura around any visible creature or object in the area that bears magic, and you learn its school of magic, if any.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","higherSource":""},{"id":"detect-poison-and-disease","name":"Detect Poison and Disease","nameTr":"Zehir ve Hastalığı Tespit Et","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric","Druid","Paladin","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":true,"components":["V","S","M"],"materialTr":"Bir porsuk yaprağı.","materialSource":"A yew leaf.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Bu süre boyunca 30 ft içinizdeki zehirlerin, zehirli yaratıkların ve hastalıkların varlığını ve konumunu hissedebilirsiniz. Ayrıca her durumda poison'nin türünü, zehirli yaratığı veya hastalığı da tanımlarsınız.\nBüyü çoğu engeli aşabilir ancak 1 ft taş, 1 inçlik adi metal, ince bir kurşun levha veya 3 ft ahşap veya toprak tarafından engellenir.","higher":"","sourceText":"For the duration, you can sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet of you. You also identify the kind of poison, poisonous creature, or disease in each case.\n\nThe spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt.","higherSource":""},{"id":"detect-thoughts","name":"Detect Thoughts","nameTr":"Düşünceleri Algıla","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir bakır para.","materialSource":"A copper coin.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Bu süre boyunca belirli yaratıkların düşüncelerini okuyabilirsiniz. Büyüyü yaptığınızda ve büyü bitene kadar her turda eyleminizi sürdürürken, zihninizi 30 ft içinde görebileceğiniz herhangi bir yaratığa odaklayabilirsiniz. Seçtiğiniz yaratığın INT değeri 3 veya daha düşükse veya herhangi bir dil konuşmuyorsa yaratık etkilenmez.\nBaşlangıçta yaratığın yüzeysel düşüncelerini, o anda aklında en çok ne olduğunu öğrenirsiniz. Bir eylem olarak dikkatinizi başka bir yaratığın düşüncelerine kaydırabilir veya aynı yaratığın zihnini daha derinlemesine incelemeye çalışabilirsiniz. Daha derine inerseniz hedefin bir WIS saving throw yapması gerekir. Başarısız olursa, (varsa) mantığı, duygusal durumu ve zihninde önemli görünen bir şey (endişelendiği, sevdiği veya nefret ettiği bir şey gibi) hakkında fikir sahibi olursunuz. Başarılı olursa büyü sona erer. Her iki durumda da hedef, onun zihnini araştırdığınızı bilir ve dikkatinizi başka bir yaratığın düşüncelerine kaydırmadığınız sürece, yaratık sırası geldiğinde eylemini kullanarak sizin INT çekinize itiraz eden bir INT çekini yapabilir; başarılı olursa büyü sona erer.\nHedef yaratığa sözlü olarak yöneltilen sorular doğal olarak onun düşüncelerinin gidişatını şekillendirir, dolayısıyla bu büyü özellikle sorgulamanın bir parçası olarak etkilidir.\nBu büyüyü aynı zamanda göremediğiniz düşünen yaratıkların varlığını tespit etmek için de kullanabilirsiniz. Büyüyü yaptığınızda veya bu süre içindeki eyleminiz olarak, 30 ft içindeki düşünceleri arayabilirsiniz. Büyü engelleri aşabilir, ancak 2 ft kayadan, 2 inç kurşun dışında herhangi bir metalden veya ince bir kurşun tabakası sizi engeller. INT değeri 3 veya daha düşük olan ya da herhangi bir dil konuşmayan bir canlıyı tespit edemezsiniz.\nBir yaratığın varlığını bu şekilde tespit ettiğinizde, onu göremeseniz bile, yukarıda anlatıldığı gibi geri kalan süre boyunca düşüncelerini okuyabilirsiniz, ancak yine de menzil içinde olması gerekir.","higher":"","sourceText":"For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn't speak any language, the creature is unaffected.\n\nYou initially learn the surface thoughts of the creature - what is most on its mind in that moment. As an action, you can either shift your attention to another creature's thoughts or attempt to probe deeper into the same creature's mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature's thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.\n\nQuestions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.\n\nYou can also use this spell to detect the presence of thinking creatures you can't see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can't detect a creature with an Intelligence of 3 or lower or one that doesn't speak any language.\n\nOnce you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can't see it, but it must still be within range.","higherSource":""},{"id":"dimension-door","name":"Dimension Door","nameTr":"Boyut Kapısı","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"500 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kendinizi mevcut konumunuzdan menzil içindeki herhangi bir noktaya ışınlarsınız. Tam istediğiniz noktaya varırsınız. Görebileceğiniz, görselleştirebileceğiniz veya \"200 ft düz aşağı\" veya \"45 derecelik açıyla kuzeybatıya doğru 300 ft\" gibi mesafeyi ve yönü belirterek tanımlayabileceğiniz bir yer olabilir.\nAğırlığı taşıyabileceğiniz ağırlığı aşmadığı sürece eşyaları yanınızda getirebilirsiniz. Ayrıca, sizin bedeninizde veya daha küçük, taşıma kapasitesine kadar teçhizat taşıyan istekli bir yaratığı da getirebilirsiniz. Bu büyüyü yaptığınızda yaratık 5 ft yakınınızda olmalıdır.\nZaten bir nesnenin veya yaratığın bulunduğu bir yere varırsanız, siz ve sizinle seyahat eden herhangi bir yaratık 4d6 force hasarı alırsınız ve büyü sizi ışınlamada başarısız olur.","higher":"","sourceText":"You teleport yourself from your current location to any other spot within range. You arrive at exactly the spot desired. It can be a place you can see, one you can visualize, or one you can describe by stating distance and direction, such as \"200 feet straight downward\" or \"upward to the northwest at a 45-degree angle, 300 feet.\"\n\nYou can bring along objects as long as their weight doesn't exceed what you can carry. You can also bring one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell.\n\nIf you would arrive in a place already occupied by an object or a creature, you and any creature traveling with you each take 4d6 force damage, and the spell fails to teleport you.","higherSource":""},{"id":"disguise-self","name":"Disguise Self","nameTr":"Kendini Gizle","level":1,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü sona erene veya büyüyü ortadan kaldırmak için eyleminizi kullanana kadar kendinizi (kıyafetleriniz, zırhınız, silahlarınız ve üzerinizdeki diğer eşyalar dahil) farklı gösterirsiniz. 1 ft daha kısa veya daha uzun görünebilirsiniz ve zayıf, şişman veya arada görünebilirsiniz. Vücut tipinizi değiştiremezsiniz, bu nedenle aynı temel uzuv düzenine sahip bir form benimsemelisiniz. Aksi takdirde illüzyonun boyutu size bağlıdır.\nBu büyünün yarattığı değişiklikler fiziksel incelemeye dayanamaz. Örneğin, bu büyüyü kıyafetinize bir şapka eklemek için kullanırsanız, nesneler şapkanın içinden geçer ve ona dokunan kişi hiçbir şey hissetmez veya başınızı ve saçınızı hisseder. Bu büyüyü olduğunuzdan daha zayıf görünmek için kullanırsanız, size dokunmak için uzanan birinin eli, sanki hala havadayken size çarpacaktır.\nBir yaratık, kılık değiştirdiğinizi anlamak için eylemini kullanarak görünümünüzü inceleyebilir ve DC'ye karşı büyü kaydetmenize karşı INT (Soruşturma) kontrolünde başarılı olmalıdır.","higher":"","sourceText":"You make yourself--including your clothing, armor, weapons, and other belongings on your person--look different until the spell ends or until you use your action to dismiss it. You can seem 1 foot shorter or taller and can appear thin, fat, or in between. You can't change your body type, so you must adopt a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to your outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel your head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nTo discern that you are disguised, a creature can use its action to inspect your appearance and must succeed on an Intelligence (Investigation) check against your spell save DC.","higherSource":""},{"id":"disintegrate","name":"Disintegrate","nameTr":"Parçalanmak","level":6,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir mıknatıs taşı ve bir tutam toz.","materialSource":"A lodestone and a pinch of dust.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":{"type":"cube","size":10},"description":"İşaret parmağınızdan menzil içinde görebileceğiniz bir hedefe doğru ince yeşil bir ışın yayılıyor. Hedef bir yaratık, bir nesne veya force'nin sihirli bir eseri olabilir; örneğin force duvarının oluşturduğu duvar.\nBu büyünün hedef aldığı yaratık DEX saving throw atmalıdır. Başarısız bir kaydetme durumunda hedef 10d6+40 force hasarı alır. Bu hasar hedefi 0 HP'ye düşürürse parçalanır.\nParçalanmış bir yaratık ve büyülü eşyalar dışında giydiği ve taşıdığı her şey, ince gri bir toz yığınına dönüştü. Yaratık ancak gerçek bir diriliş veya dilek büyüsü ile hayata döndürülebilir.\nBu büyü, Büyük veya daha küçük, büyülü olmayan bir nesneyi veya sihirli bir force yaratımını otomatik olarak parçalara ayırır. Hedef çok büyük veya daha büyük bir nesneyse ya da force'nin yaratımıysa, bu büyü onun 10 ft küp şeklindeki kısmını parçalar. Büyülü bir eşya bu büyüden etkilenmez.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 6. seviyenin üzerindeki her yuva seviyesi için 3d6 artar.","sourceText":"A thin green ray springs from your pointing finger to a target that you can see within range. The target can be a creature, an object, or a creation of magical force, such as the wall created by wall of force.\n\nA creature targeted by this spell must make a dexterity saving throw. On a failed save, the target takes 10d6 + 40 force damage. If this damage reduces the target to 0 hit points, it is disintegrated.\n\nA disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust. The creature can be restored to life only by means of a true resurrection or a wish spell.\n\nThis spell automatically disintegrates a Large or smaller nonmagical object or a creation of magical force. If the target is a Huge or larger object or creation of force, this spell disintegrates a 10-foot-cube portion of it. A magic item is unaffected by this spell.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the damage increases by 3d6 for each slot level above 6th."},{"id":"dispel-evil-and-good","name":"Dispel Evil and Good","nameTr":"Kötülüğü ve İyiliği Defet","level":5,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Kutsal su veya toz gümüş ve demir.","materialSource":"Holy water or powdered silver and iron.","attackType":"melee","save":"CHA","saves":["CHA"],"saveSuccess":"other","area":null,"description":"Parıldayan enerji sizi çevreler ve perilerden, ölümsüzlerden ve Maddi Düzlemin ötesinden gelen yaratıklardan korur. Bu süre boyunca gökseller, elementaller, periler, iblisler ve ölümsüzler size karşı saldırı atışlarında dezavantaj'ye sahip.\nAşağıdaki özel işlevlerden birini kullanarak büyüyü erken sonlandırabilirsiniz.\n***Büyüyü Kırın.*** Eyleminiz olarak, ulaşabileceğiniz charmed, frightened veya bir göksel, bir elemental, bir fey, bir iblis veya bir ölümsüz tarafından ele geçirilen bir yaratığa dokunursunuz. Dokunduğunuz yaratık artık charmed, frightened veya bu tür yaratıkların elinde değil.\n***İşten çıkarma.*** Eyleminiz olarak, ulaşabileceğiniz bir göksel, bir elemental, bir peri, bir iblis veya bir ölümsüze karşı yakın spell attack yapın. Bir vuruşta yaratığı ana uçağına geri götürmeye çalışırsınız. Yaratığın bir CHA saving throw üzerinde başarılı olması veya ana uçağına geri gönderilmesi gerekir (eğer zaten orada değilse). Kendi uçaklarında değillerse ölümsüzler Gölgeyarı'na, periler ise Feywild'e gönderilir.","higher":"","sourceText":"Shimmering energy surrounds and protects you from fey, undead, and creatures originating from beyond the Material Plane. For the duration, celestials, elementals, fey, fiends, and undead have disadvantage on attack rolls against you.\n\nYou can end the spell early by using either of the following special functions.\n\n***Break Enchantment.*** As your action, you touch a creature you can reach that is charmed, frightened, or possessed by a celestial, an elemental, a fey, a fiend, or an undead. The creature you touch is no longer charmed, frightened, or possessed by such creatures.\n\n***Dismissal.*** As your action, make a melee spell attack against a celestial, an elemental, a fey, a fiend, or an undead you can reach. On a hit, you attempt to drive the creature back to its home plane. The creature must succeed on a charisma saving throw or be sent back to its home plane (if it isn't there already). If they aren't on their home plane, undead are sent to the Shadowfell, and fey are sent to the Feywild.","higherSource":""},{"id":"dispel-magic","name":"Dispel Magic","nameTr":"Büyüyü Gider","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Druid","Paladin","Sorcerer","Warlock","Wizard"],"subclasses":["Devotion","Lore"],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki bir yaratık, nesne veya büyülü efekti seçin. Hedefteki 3. seviye veya daha düşük herhangi bir büyü sona erer. Hedefteki 4. seviye veya daha yüksek her büyü için, büyü yapma yeteneğinizi kullanarak bir ability check yapın. DC, 10 + büyünün seviyesine eşittir. Başarılı bir kontrolde büyü sona erer.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, büyünün seviyesi kullandığınız spell slot'nin seviyesine eşit veya bundan daha düşükse, bir büyünün hedef üzerindeki etkilerini otomatik olarak sona erdirirsiniz.","sourceText":"Choose one creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher on the target, make an ability check using your spellcasting ability. The DC equals 10 + the spell's level. On a successful check, the spell ends.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, you automatically end the effects of a spell on the target if the spell's level is equal to or less than the level of the spell slot you used."},{"id":"divination","name":"Divination","nameTr":"Kehanet","level":4,"school":"Divination","schoolTr":"Kehanet","classes":["Druid"],"subclasses":["Land"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 25gp değerindeki tütsü ve dininize uygun bir kurban.","materialSource":"Incense and a sacrificial offering appropriate to your religion, together worth at least 25gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Sihriniz ve bir adak sizi bir tanrıyla ya da tanrının hizmetkarlarıyla temasa geçirir. 7 gün içinde gerçekleşecek belirli bir hedef, olay veya faaliyetle ilgili tek bir soru sorarsınız. GM gerçekçi bir cevap sunuyor. Cevap kısa bir cümle, şifreli bir kafiye veya bir kehanet olabilir.\nBüyü, ek büyü yapılması veya bir yoldaşın kaybedilmesi veya kazanılması gibi sonucu değiştirebilecek olası koşulları hesaba katmaz.\nBir sonraki uzun dinlenmenizi tamamlamadan önce büyüyü iki veya daha fazla kez yaparsanız, ilkinden sonraki her kullanım için rastgele bir okuma alma şansınız kümülatif yüzde 25'tir. GM bu atışı gizlice yapar.","higher":"","sourceText":"Your magic and an offering put you in contact with a god or a god's servants. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen.\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret.","higherSource":""},{"id":"divine-favor","name":"Divine Favor","nameTr":"İlahi Lütuf","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Paladin"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Duanız sizi ilahi ışıltıyla güçlendirir. Büyü bitene kadar silah saldırılarınız, bir vuruşta fazladan 1d4 radiant hasar verir.","higher":"","sourceText":"Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit.","higherSource":""},{"id":"divine-word","name":"Divine Word","nameTr":"İlahi Kelime","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":[],"castingTime":"1 bonus action","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":null,"description":"Yaradılışın şafağında dünyayı şekillendiren güçle dolu ilahi bir söz söylüyorsunuz. Menzil içinde görebileceğiniz herhangi bir sayıda yaratığı seçin. Sizi duyabilen her yaratık bir CHA saving throw yapmalıdır. Başarısız bir kaydetme işleminde yaratık, mevcut HP'sine bağlı olarak bir etkiye maruz kalır:\n- 50 HP veya daha az: 1 dakika boyunca deafened\n- 40 HP veya daha az: 10 dakika boyunca deafened ve blinded\n- 30 HP veya daha az: 1 saat boyunca blinded, deafened ve stunned\n- 20 HP veya daha az: anında öldürülür\nMevcut HP'sine bakılmaksızın, kurtarılamayan bir göksel, bir elemental, bir peri veya bir iblis, menşe düzlemine geri dönmeye zorlanır (eğer zaten orada değilse) ve bir dilek büyüsü dışında hiçbir şekilde 24 saat boyunca mevcut düzleminize dönemez.","higher":"","sourceText":"You utter a divine word, imbued with the power that shaped the world at the dawn of creation. Choose any number of creatures you can see within range. Each creature that can hear you must make a Charisma saving throw. On a failed save, a creature suffers an effect based on its current hit points:\n\n- 50 hit points or fewer: deafened for 1 minute\n\n- 40 hit points or fewer: deafened and blinded for 10 minutes\n\n- 30 hit points or fewer: blinded, deafened, and stunned for 1 hour\n\n- 20 hit points or fewer: killed instantly\n\nRegardless of its current hit points, a celestial, an elemental, a fey, or a fiend that fails its save is forced back to its plane of origin (if it isn't there already) and can't return to your current plane for 24 hours by any means short of a wish spell.","higherSource":""},{"id":"dominate-beast","name":"Dominate Beast","nameTr":"Canavara Hakim Ol","level":4,"school":"Enchantment","schoolTr":"Etkileme","classes":["Druid","Sorcerer"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir yaratığı kandırmaya çalışıyorsunuz. Bu süre boyunca bir WIS saving throw üzerinde başarılı olmalı veya sizin tarafınızdan charmed olmalıdır. Siz veya size dost yaratıklar onunla savaşıyorsa, avantaj saving throw'de bulunur.\nYaratık charmed olsa da, ikiniz aynı varoluş düzleminde olduğunuz sürece onunla telepatik bir bağlantınız var. Bu telepatik bağlantıyı, siz bilinçliyken yaratığa komutlar vermek için kullanabilirsiniz (hiçbir eylem gerekmez), o da buna uymak için elinden geleni yapar. \"O yaratığa saldır\", \"Oraya koş\" veya \"O nesneyi getir\" gibi basit ve genel bir eylem planı belirleyebilirsiniz. Eğer yaratık emri yerine getirir ve sizden başka bir talimat almazsa, elinden geldiğince kendini savunur ve muhafaza eder.\nHedefin tam ve kesin kontrolünü ele geçirmek için eyleminizi kullanabilirsiniz. Bir sonraki turunuzun sonuna kadar yaratık yalnızca sizin seçtiğiniz eylemleri gerçekleştirir ve yapmasına izin vermediğiniz hiçbir şeyi yapmaz. Bu süre zarfında yaratığın bir Reaction kullanmasını da sağlayabilirsiniz, ancak bu aynı zamanda kendi Reaction'nizi de kullanmanızı gerektirir. Hedef her hasar aldığında, büyüye karşı yeni bir WIS saving throw oluşturur. saving throw başarılı olursa büyü sona erer.","higher":"Bu büyüyü 9. seviye spell slot ile yaptığınızda, süresi concentration olup, 8 saate kadardır.","sourceText":"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well. Each time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","higherSource":"When you cast this spell with a 9th level spell slot, the duration is concentration, up to 8 hours."},{"id":"dominate-monster","name":"Dominate Monster","nameTr":"Canavara Hakim Ol","level":8,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir yaratığı kandırmaya çalışıyorsunuz. Bir WIS saving throw üzerinde başarılı olmalı veya bu süre boyunca sizin tarafınızdan charmed olmalıdır. Siz veya size dost olan yaratıklar onunla savaşıyorsa, saving throw üzerinde avantaj vardır.\nYaratık charmed olsa da, ikiniz aynı varoluş düzleminde olduğunuz sürece onunla telepatik bir bağlantınız var. Bu telepatik bağlantıyı, siz bilinçliyken yaratığa komutlar vermek için kullanabilirsiniz (hiçbir eylem gerekmez), o da buna uymak için elinden geleni yapar. \"O yaratığa saldır\", \"Oraya koş\" veya \"O nesneyi getir\" gibi basit ve genel bir eylem planı belirleyebilirsiniz. Eğer yaratık emri yerine getirir ve sizden başka bir talimat almazsa, elinden geldiğince kendini savunur ve muhafaza eder.\nHedefin tam ve kesin kontrolünü ele geçirmek için eyleminizi kullanabilirsiniz. Bir sonraki turunuzun sonuna kadar yaratık yalnızca sizin seçtiğiniz eylemleri gerçekleştirir ve yapmasına izin vermediğiniz hiçbir şeyi yapmaz. Bu süre zarfında yaratığın bir Reaction kullanmasını da sağlayabilirsiniz, ancak bu aynı zamanda kendi Reaction'nizi de kullanmanızı gerektirir.\nHedef her hasar aldığında, büyüye karşı yeni bir WIS saving throw oluşturur. saving throw başarılı olursa büyü sona erer.","higher":"Bu büyüyü 9. seviye spell slot ile yaptığınızda, süresi concentration olup, 8 saate kadardır.","sourceText":"You attempt to beguile a creature that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the creature is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time, you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","higherSource":"When you cast this spell with a 9th-level spell slot, the duration is concentration, up to 8 hours."},{"id":"dominate-person","name":"Dominate Person","nameTr":"Hakim Kişi","level":5,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"other","area":null,"description":"Menzilde görebileceğiniz bir insansıyı kandırmaya çalışıyorsunuz. Bu süre boyunca bir WIS saving throw üzerinde başarılı olmalı veya sizin tarafınızdan charmed olmalıdır. Siz veya size dost yaratıklar onunla savaşıyorsa, saving throw üzerinde avantaj vardır.\nHedef charmed olsa da, ikiniz aynı varoluş düzleminde olduğunuz sürece onunla telepatik bir bağlantınız var. Bu telepatik bağlantıyı, siz bilinçliyken yaratığa komutlar vermek için kullanabilirsiniz (hiçbir eylem gerekmez), o da buna uymak için elinden geleni yapar. \"O yaratığa saldır\", \"Oraya koş\" veya \"O nesneyi getir\" gibi basit ve genel bir eylem planı belirleyebilirsiniz. Eğer yaratık emri yerine getirir ve sizden başka bir talimat almazsa, elinden geldiğince kendini savunur ve muhafaza eder.\nHedefin tam ve kesin kontrolünü ele geçirmek için eyleminizi kullanabilirsiniz. Bir sonraki turunuzun sonuna kadar yaratık yalnızca sizin seçtiğiniz eylemleri gerçekleştirir ve yapmasına izin vermediğiniz hiçbir şeyi yapmaz. Bu süre zarfında yaratığın bir Reaction kullanmasını da sağlayabilirsiniz, ancak bu aynı zamanda kendi Reaction'nizi de kullanmanızı gerektirir.\nHedef her hasar aldığında, büyüye karşı yeni bir WIS saving throw oluşturur. saving throw başarılı olursa büyü sona erer.","higher":"Bu büyüyü 6. seviye spell slot kullanarak yaptığınızda, süresi concentration olup, en fazla 10 dakikadır. 7. düzey spell slot kullandığınızda süre concentration olup, en fazla 1 saattir. 8. seviye veya daha yüksek bir spell slot kullandığınızda, süre concentration olup 8 saate kadardır.","sourceText":"You attempt to beguile a humanoid that you can see within range. It must succeed on a wisdom saving throw or be charmed by you for the duration. If you or creatures that are friendly to you are fighting it, it has advantage on the saving throw.\n\nWhile the target is charmed, you have a telepathic link with it as long as the two of you are on the same plane of existence. You can use this telepathic link to issue commands to the creature while you are conscious (no action required), which it does its best to obey. You can specify a simple and general course of action, such as \"Attack that creature,\" \"Run over there,\" or \"Fetch that object.\" If the creature completes the order and doesn't receive further direction from you, it defends and preserves itself to the best of its ability.\n\nYou can use your action to take total and precise control of the target. Until the end of your next turn, the creature takes only the actions you choose, and doesn't do anything that you don't allow it to do. During this time you can also cause the creature to use a reaction, but this requires you to use your own reaction as well.\n\nEach time the target takes damage, it makes a new wisdom saving throw against the spell. If the saving throw succeeds, the spell ends.","higherSource":"When you cast this spell using a 6th-level spell slot, the duration is concentration, up to 10 minutes. When you use a 7th-level spell slot, the duration is concentration, up to 1 hour. When you use a spell slot of 8th level or higher, the duration is concentration, up to 8 hours."},{"id":"dream","name":"Dream","nameTr":"Rüya","level":5,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Warlock","Wizard"],"subclasses":["Land"],"castingTime":"1 minute","range":"Special","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir avuç kum, bir damla mürekkep ve uyuyan bir kuştan koparılmış bir yazı tüyü.","materialSource":"A handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bu büyü bir yaratığın rüyalarını şekillendirir. Bu büyünün hedefi olarak bildiğiniz bir yaratığı seçin. Hedef sizinle aynı varoluş düzleminde olmalıdır. Elfler gibi uyumayan yaratıklarla bu büyüyle iletişime geçilemez. Siz veya dokunduğunuz istekli bir yaratık, bir elçi gibi hareket ederek trans durumuna girer.\nTrans halindeyken haberci çevresinin farkındadır ancak harekete geçemez veya hareket edemez.\nHedef uyuyorsa, haberci hedefin rüyalarında belirir ve büyü süresi boyunca uykuda kaldığı sürece hedefle konuşabilir. Haberci ayrıca manzaralar, nesneler ve diğer görüntüler yaratarak rüyanın ortamını da şekillendirebilir. Haberci istediği zaman transtan çıkabilir ve büyünün etkisini erken sonlandırabilir. Hedef uyandığında rüyayı mükemmel bir şekilde hatırlıyor. Büyüyü yaptığınızda hedef uyanıksa, haberci bunu bilir ve ya transı (ve büyüyü) sona erdirebilir ya da hedefin uykuya dalmasını bekleyebilir, bu noktada haberci hedefin rüyasında görünür.\nHabercinin hedefe canavarca ve korkutucu görünmesini sağlayabilirsiniz. Bunu yaparsanız, haberci en fazla on kelimeden oluşan bir mesaj iletebilir ve ardından hedefin bir WIS saving throw yapması gerekir. Başarısız bir kurtarma durumunda, hayalet canavarın yankıları, hedefin uyku süresi boyunca devam eden ve hedefin bu dinlenmeden herhangi bir fayda elde etmesini engelleyen bir kabus yaratır. Ayrıca hedef uyandığında 3d6 psychic hasarı alır.\nHedefin vücudunda bir kısım, bir tutam saç, bir tırnak kırpıntısı veya benzer bir vücut kısmı varsa, hedef dezavantaj ile saving throw'sini oluşturur.","higher":"","sourceText":"This spell shapes a creature's dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don't sleep, such as elves, can't be contacted by this spell. You, or a willing creature you touch, enters a trance state, acting as a messenger.\n\nWhile in the trance, the messenger is aware of his or her surroundings, but can't take actions or move.\n\nIf the target is asleep, the messenger appears in the target's dreams and can converse with the target as long as it remains asleep, through the duration of the spell. The messenger can also shape the environment of the dream, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the effect of the spell early. The target recalls the dream perfectly upon waking. If the target is awake when you cast the spell, the messenger knows it, and can either end the trance (and the spell) or wait for the target to fall asleep, at which point the messenger appears in the target's dreams.\n\nYou can make the messenger appear monstrous and terrifying to the target. If you do, the messenger can deliver a message of no more than ten words and then the target must make a wisdom saving throw. On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target's sleep and prevents the target from gaining any benefit from that rest. In addition, when the target wakes up, it takes 3d6 psychic damage.\n\nIf you have a body part, lock of hair, clipping from a nail, or similar portion of the target's body, the target makes its saving throw with disadvantage.","higherSource":""},{"id":"druidcraft","name":"Druidcraft","nameTr":"Druidcraft","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Doğanın ruhlarına fısıldayarak 'menzil' dahilinde aşağıdaki etkilerden birini yaratırsınız:\n- Bulunduğunuz yerde önümüzdeki 24 saat boyunca havanın nasıl olacağını tahmin eden küçük, zararsız bir duyusal etki yaratırsınız. Etki, açık gökyüzü için altın bir küre, yağmur için bir bulut, kar için düşen kar taneleri vb. şeklinde ortaya çıkabilir. Bu etki 1 tur boyunca devam eder.\n- Anında bir çiçeğin açmasını, bir tohum kabuğunun açılmasını veya bir yaprak tomurcuğunun açmasını sağlarsınız.\n- Düşen yapraklar, rüzgarın esintisi, küçük bir hayvanın sesi veya hafif bir kokarca sesi gibi anlık, zararsız bir duyusal etki yaratırsınız. Efekt bir 5 ft küpüne sığmalıdır.\n- Bir mumu, meşaleyi ya da küçük bir kamp ateşini anında yakarsınız ya da söndürürsünüz.","higher":"","sourceText":"Whispering to the spirits of nature, you create one of the following effects within 'range':\n\n- You create a tiny, harmless sensory effect that predicts what the weather will be at your location for the next 24 hours. The effect might manifest as a golden orb for clear skies, a cloud for rain, falling snowflakes for snow, and so on. This effect persists for 1 round.\n\n- You instantly make a flower bloom, a seed pod open, or a leaf bud bloom.\n\n- You create an instantaneous, harmless sensory effect, such as falling leaves, a puff of wind, the sound of a small animal, or the faint order of skunk. The effect must fit in a 5-foot cube.\n\n- You instantly light or snuff out a candle, a torch, or a small campfire.","higherSource":""},{"id":"earthquake","name":"Earthquake","nameTr":"Deprem","level":8,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric","Druid","Sorcerer"],"subclasses":[],"castingTime":"1 action","range":"500 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam toprak, bir parça kaya ve bir parça kil.","materialSource":"A pinch of dirt, a piece of rock, and a lump of clay.","attackType":"","save":"CON","saves":["CON","DEX"],"saveSuccess":"","area":{"type":"sphere","size":100},"description":"Yerde, menzil içerisinde görebileceğiniz bir noktada sismik bir rahatsızlık yaratırsınız. Bu süre boyunca şiddetli bir sarsıntı, o noktayı merkez alan 100 ft yarıçap daire şeklinde zemini delip geçiyor ve o bölgedeki zeminle temas halinde olan canlıları ve yapıları sarsıyor.\nBölgedeki zemin zorlu arazi haline geliyor. Yerde yoğunlaşan her canlı CON saving throw atmalıdır. Başarısız bir kaydetme durumunda yaratığın concentration'si bozulur.\nBu büyüyü yaptığınızda ve ona odaklanarak harcadığınız her turun sonunda, alanda yerde bulunan her canlının bir DEX saving throw yapması gerekir. Başarısız bir kaydetme durumunda yaratık prone'yi devirir.\nBu büyünün, GM tarafından belirlendiği şekilde, bölgedeki araziye bağlı olarak ek etkileri olabilir.\nÇatlaklar. Büyüyü yaptıktan sonraki bir sonraki turun başlangıcında büyü alanı boyunca çatlaklar açılır. GM tarafından seçilen konumlarda toplam 1d6 bu tür çatlaklar açılıyor. Her biri 1d10 x 10 ft derin, 10 ft genişliğindedir ve büyü alanının bir kenarından karşı tarafa kadar uzanır. Bir çatlağın açıldığı noktada duran bir yaratık, bir DEX saving throw üzerinde başarılı olmalı veya içeri düşmelidir. Başarılı bir şekilde kurtaran bir yaratık, çatlağın kenarı açılırken hamle yapar.\nBir yapının altında açılan bir çatlak, yapının otomatik olarak çökmesine neden olur (aşağıya bakınız).\nYapılar. Büyüyü yaptığınızda ve büyü bitene kadar her turun başlangıcında, sarsıntı bölgedeki zeminle temas eden herhangi bir yapıya 50 bludgeoning hasar verir. Bir yapı 0 HP'ye düşerse çöker ve muhtemelen yakındaki canlılara zarar verir. Bir yapının yüksekliğinin yarısı kadar mesafedeki bir yaratığın DEX saving throw yapması gerekir. Başarısız bir kurtarma durumunda yaratık, 5d6 bludgeoning hasarı alır, prone'ye devrilir ve enkazın altına gömülür, kaçmak için bir DC 20 STR (Atletizm) kontrolü gerektirir. GM, molozun niteliğine bağlı olarak DC'yi daha yüksek veya daha düşük ayarlayabilir. Başarılı bir kurtarışta yaratık, yarısı kadar hasar alır ve prone düşmez veya gömülmez.","higher":"","sourceText":"You create a seismic disturbance at a point on the ground that you can see within range. For the duration, an intense tremor rips through the ground in a 100-foot-radius circle centered on that point and shakes creatures and structures in contact with the ground in that area.\n\nThe ground in the area becomes difficult terrain. Each creature on the ground that is concentrating must make a constitution saving throw. On a failed save, the creature's concentration is broken.\n\nWhen you cast this spell and at the end of each turn you spend concentrating on it, each creature on the ground in the area must make a dexterity saving throw. On a failed save, the creature is knocked prone.\n\nThis spell can have additional effects depending on the terrain in the area, as determined by the GM.\n\nFissures. Fissures open throughout the spell's area at the start of your next turn after you cast the spell. A total of 1d6 such fissures open in locations chosen by the GM. Each is 1d10 x 10 feet deep, 10 feet wide, and extends from one edge of the spell's area to the opposite side. A creature standing on a spot where a fissure opens must succeed on a dexterity saving throw or fall in. A creature that successfully saves moves with the fissure's edge as it opens.\n\nA fissure that opens beneath a structure causes it to automatically collapse (see below).\n\nStructures. The tremor deals 50 bludgeoning damage to any structure in contact with the ground in the area when you cast the spell and at the start of each of your turns until the spell ends. If a structure drops to 0 hit points, it collapses and potentially damages nearby creatures. A creature within half the distance of a structure's height must make a dexterity saving throw. On a failed save, the creature takes 5d6 bludgeoning damage, is knocked prone, and is buried in the rubble, requiring a DC 20 Strength (Athletics) check as an action to escape. The GM can adjust the DC higher or lower, depending on the nature of the rubble. On a successful save, the creature takes half as much damage and doesn't fall prone or become buried.","higherSource":""},{"id":"eldritch-blast","name":"Eldritch Blast","nameTr":"Tekinsiz Patlama","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Warlock"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Çatırdayan bir enerji ışını menzil içindeki bir yaratığa doğru ilerliyor. Hedefe karşı bir menzilli spell attack yapın. Bir vuruşta hedef 1d10 force hasarı alır. Büyü, daha yüksek seviyelere ulaştığınızda birden fazla ışın yaratır: 5. seviyede iki ışın, 11. seviyede üç ışın ve 17. seviyede dört ışın. Işınları aynı hedefe veya farklı hedeflere yönlendirebilirsiniz. Her ışın için ayrı bir saldırı zarı yapın.","higher":"","sourceText":"A beam of crackling energy streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 force damage. The spell creates more than one beam when you reach higher levels: two beams at 5th level, three beams at 11th level, and four beams at 17th level. You can direct the beams at the same target or at different ones. Make a separate attack roll for each beam.","higherSource":""},{"id":"enhance-ability","name":"Enhance Ability","nameTr":"Yeteneği Geliştirin","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Cleric","Druid","Sorcerer"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir canavarın kürkü veya tüyü.","materialSource":"Fur or a feather from a beast.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsunuz ve ona büyülü bir güç veriyorsunuz. Aşağıdaki efektlerden birini seçin; Hedef, büyü bitene kadar bu etkiyi kazanır.\n***Ayı'nın Dayanıklılığı.*** Hedefin CON kontrollerinde avantaj var. Ayrıca büyü sona erdiğinde kaybedilen 2d6 geçici HP'yi de kazanır.\n***Bull'un STR.*** Hedefin STR çeklerinde avantaj var ve taşıma kapasitesi iki katına çıkıyor.\n***Cat's Grace.*** Hedefin DEX kontrollerinde avantaj var. Ayrıca 20 ft veya incapacitated değilse düşmekten de hasar almaz.\n***Kartalın Görkemi.*** Hedefin CHA kontrollerinde avantaj var.\n***Fox'un Kurnazlığı.*** Hedefin INT kontrollerinde avantaj var.\n***Baykuşun WIS'si.*** Hedefin WIS kontrollerinde avantaj var.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 2. seviyenin üzerindeki her yuva seviyesi için bir ek yaratığı hedefleyebilirsiniz.","sourceText":"You touch a creature and bestow upon it a magical enhancement. Choose one of the following effects; the target gains that effect until the spell ends.\n\n***Bear's Endurance.*** The target has advantage on constitution checks. It also gains 2d6 temporary hit points, which are lost when the spell ends.\n\n***Bull's Strength.*** The target has advantage on strength checks, and his or her carrying capacity doubles.\n\n***Cat's Grace.*** The target has advantage on dexterity checks. It also doesn't take damage from falling 20 feet or less if it isn't incapacitated.\n\n***Eagle's Splendor.*** The target has advantage on Charisma checks.\n\n***Fox's Cunning.*** The target has advantage on intelligence checks.\n\n***Owl's Wisdom.*** The target has advantage on wisdom checks.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},{"id":"enlarge-reduce","name":"Enlarge/Reduce","nameTr":"Büyüt/Küçült","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam demir tozu.","materialSource":"A pinch iron powder.","attackType":"","save":"CON","saves":["CON","STR"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebileceğiniz bir yaratığın veya nesnenin bu süre boyunca büyüyüp küçülmesine neden olursunuz. Bir yaratık ya da giyilmeyen ya da taşınmayan bir nesneyi seçin. Hedef isteksizse CON saving throw yapabilir. Başarı durumunda büyünün hiçbir etkisi yoktur.\nHedef bir yaratıksa, giydiği ve taşıdığı her şey onunla birlikte boyut değiştirir. Etkilenen bir yaratığın düşürdüğü herhangi bir eşya anında normal boyutuna döner.\n***Büyüt.*** Hedefin boyutu tüm boyutlarda iki katına çıkar ve ağırlığı sekizle çarpılır. Bu büyüme, boyutunu bir kategori artırıyor; örneğin Orta'dan Büyük'e. Hedefin boyutunu iki katına çıkarması için yeterli alan yoksa, yaratık veya nesne mevcut alanda mümkün olan maksimum boyuta ulaşır. Büyü bitene kadar hedefte STR kontrollerinde ve STR saving throw’lar'de avantaj bulunur. Hedefin silahları da yeni boyutuna uyacak şekilde büyür. Bu silahlar büyütülürken hedefin bunlarla yaptığı saldırılar 1d4 ekstra hasar verir.\n***Küçült.*** Hedefin boyutu tüm boyutlarda yarıya indirilir ve ağırlığı normalin sekizde birine düşürülür. Bu küçültme, boyutunu bir kategori kadar azaltır; örneğin Orta'dan Küçük'e. Büyü sona erene kadar hedefin ayrıca STR kontrollerinde dezavantaj ve STR saving throw’lar vardır. Hedefin silahları da yeni boyutuna uyacak şekilde küçülür. Bu silahlar azaltılırken, hedefin bunlarla yaptığı saldırılar 1d4 daha az hasar verir (bu, hasarı 1'in altına indiremez).","higher":"","sourceText":"You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.\n\nIf the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.\n\n***Enlarge.*** The target's size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category-from Medium to Large, for example. If there isn't enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target's weapons also grow to match its new size. While these weapons are enlarged, the target's attacks with them deal 1d4 extra damage.\n\n***Reduce.*** The target's size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target's weapons also shrink to match its new size. While these weapons are reduced, the target's attacks with them deal 1d4 less damage (this can't reduce the damage below 1).","higherSource":""},{"id":"entangle","name":"Entangle","nameTr":"dolaşıklık","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"90 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"STR","saves":["STR"],"saveSuccess":"none","area":{"type":"cube","size":20},"description":"Yerden 20 ft kare şeklinde filizlenen yabani otları ve asmaları kavrayarak menzil içindeki bir noktayı oluşturun. Bu süre zarfında bu bitkiler bölgedeki zemini zorlu arazilere dönüştürür.\nBüyüyü yaptığınızda bölgedeki bir yaratık, büyü bitene kadar bir STR saving throw üzerinde başarılı olmalı veya dolandırıcı bitkiler tarafından restrained olmalıdır. Bitkiler tarafından yaratılan restrained yaratık, eylemini kullanarak DC'yi kurtaran büyünüze karşı bir STR kontrolü yapabilir. Başarılı olduğunda kendini özgürleştirir.\nBüyü sona erdiğinde, yaratılan bitkiler solar.","higher":"","sourceText":"Grasping weeds and vines sprout from the ground in a 20-foot square starting form a point within range. For the duration, these plants turn the ground in the area into difficult terrain.\n\nA creature in the area when you cast the spell must succeed on a strength saving throw or be restrained by the entangling plants until the spell ends. A creature restrained by the plants can use its action to make a Strength check against your spell save DC. On a success, it frees itself.\n\nWhen the spell ends, the conjured plants wilt away.","higherSource":""},{"id":"enthrall","name":"Enthrall","nameTr":"büyülemek","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Warlock"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Dikkatinizi dağıtan bir dizi kelime örüyorsunuz ve menzil içinde görebileceğiniz ve sizi duyabilen seçtiğiniz yaratıkların bir WIS saving throw oluşturmasına neden oluyorsunuz. charmed olamayan herhangi bir yaratık, bu saving throw'de otomatik olarak başarılı olur ve siz veya arkadaşlarınız bir yaratıkla savaşıyorsanız, onun tasarrufunda avantaj bulunur. Başarısız bir kaydetme durumunda, hedef, büyü bitene veya hedef artık sizi duyamayana kadar sizden başka herhangi bir yaratığı algılamak için WIS (Algı) kontrollerinde dezavantaj'ye sahiptir. incapacitated iseniz veya artık konuşamıyorsanız büyü sona erer.","higher":"","sourceText":"You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak.","higherSource":""},{"id":"etherealness","name":"Etherealness","nameTr":"ruhanilik","level":7,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Eterik Düzlem'in mevcut düzleminizle örtüştüğü sınır bölgelerine adım atarsınız. Bu süre boyunca veya büyüyü ortadan kaldırmak için eyleminizi kullanana kadar Border Ethereal'de kalırsınız. Bu süre zarfında herhangi bir yöne hareket edebilirsiniz. Yukarı veya aşağı hareket ederseniz, hareketin her ayağı ekstra bir ayağa mal olur. Geldiğiniz uçağı görebilir ve duyabilirsiniz, ancak oradaki her şey gri görünüyor ve uzaktaki 60 ft'den başka bir şey göremiyorsunuz.\nEthereal Plandeyken yalnızca o plandaki diğer canlıları etkileyebilir ve onlardan etkilenebilirsiniz. Eterik Planda olmayan yaratıklar, özel bir yetenek veya sihir onlara bu yeteneği vermedikçe sizi algılayamaz ve sizinle etkileşime giremezler.\nEterik Düzlemde olmayan tüm nesneleri ve efektleri göz ardı ederek, geldiğiniz düzlemde algıladığınız nesneler arasında hareket etmenize olanak tanırsınız.\nBüyü sona erdiğinde, derhal bulunduğunuz uçağa, bulunduğunuz noktaya geri dönersiniz. Bu gerçekleştiğinde katı bir nesne veya yaratıkla aynı noktada bulunuyorsanız, hemen işgal edebileceğiniz en yakın boş alana yönlendirilirsiniz ve hareket ettiğiniz ft sayısının iki katına eşit force hasar alırsınız.\nBu büyüyü, Ethereal Plane'da veya onu çevreleyen bir düzlemde, örneğin Dış Düzlemlerden birindeyken yaparsanız, hiçbir etkisi olmaz.","higher":"Bu büyüyü 8. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 7. seviyenin üzerindeki her yuva seviyesi için en fazla üç istekli yaratığı (siz dahil) hedefleyebilirsiniz. Büyüyü yaptığınızda yaratıkların 10 ft yakınınızda olması gerekir.","sourceText":"You step into the border regions of the Ethereal Plane, in the area where it overlaps with your current plane. You remain in the Border Ethereal for the duration or until you use your action to dismiss the spell. During this time, you can move in any direction. If you move up or down, every foot of movement costs an extra foot. You can see and hear the plane you originated from, but everything there looks gray, and you can't see anything more than 60 feet away.\n\nWhile on the Ethereal Plane, you can only affect and be affected by other creatures on that plane. Creatures that aren't on the Ethereal Plane can't perceive you and can't interact with you, unless a special ability or magic has given them the ability to do so.\n\nYou ignore all objects and effects that aren't on the Ethereal Plane, allowing you to move through objects you perceive on the plane you originated from.\n\nWhen the spell ends, you immediately return to the plane you originated from in the spot you currently occupy. If you occupy the same spot as a solid object or creature when this happens, you are immediately shunted to the nearest unoccupied space that you can occupy and take force damage equal to twice the number of feet you are moved.\n\nThis spell has no effect if you cast it while you are on the Ethereal Plane or a plane that doesn't border it, such as one of the Outer Planes.","higherSource":"When you cast this spell using a spell slot of 8th level or higher, you can target up to three willing creatures (including you) for each slot level above 7th. The creatures must be within 10 feet of you when you cast the spell."},{"id":"expeditious-retreat","name":"Expeditious Retreat","nameTr":"Hızlı Geri Çekilme","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü inanılmaz bir hızda hareket etmenizi sağlar. Bu büyüyü yaptığınızda ve ardından büyü bitene kadar her sıranızda Bonus Action olarak Atılma eylemini gerçekleştirebilirsiniz.","higher":"","sourceText":"This spell allows you to move at an incredible pace. When you cast this spell, and then as a bonus action on each of your turns until the spell ends, you can take the Dash action.","higherSource":""},{"id":"eyebite","name":"Eyebite","nameTr":"göz ısırığı","level":6,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Büyünün süresi boyunca gözleriniz dehşet verici bir güçle dolu, mürekkep rengi bir boşluğa dönüşür. 60 ft içinde görebildiğiniz seçtiğiniz bir yaratık, bir WIS saving throw üzerinde başarılı olmalı veya bu süre boyunca seçtiğiniz aşağıdaki etkilerden birinden etkilenmelidir. Büyü sona erene kadar her turunuzda, eyleminizi başka bir yaratığı hedeflemek için kullanabilirsiniz ancak bu göz ısırmasına karşı saving throw ile başarılı olmuşsa bir yaratığı tekrar hedef alamazsınız.\n***Uykuda.*** Hedef unconscious düşüyor. Herhangi bir hasar alırsa veya başka bir yaratık, uyuyan kişiyi sarsmak için hareketini kullanırsa uyanır.\n***Panikledim.*** Hedef siz frightened'siniz. frightened yaratığı her dönüşünde Dash eylemini gerçekleştirmeli ve hareket edecek bir yer olmadığı sürece mümkün olan en güvenli ve en kısa rotayı kullanarak sizden uzaklaşmalıdır. Hedef sizden en az 60 ft uzakta sizi göremeyeceği bir yere hareket ederse bu etki sona erer.\n***Hastalanmış.*** Hedefin saldırı atışlarında dezavantaj ve ability check’ler var. Her dönüşünün sonunda başka bir WIS saving throw yapabilir. Başarılı olursa etki sona erer.","higher":"","sourceText":"For the spell's duration, your eyes become an inky void imbued with dread power. One creature of your choice within 60 feet of you that you can see must succeed on a wisdom saving throw or be affected by one of the following effects of your choice for the duration. On each of your turns until the spell ends, you can use your action to target another creature but can't target a creature again if it has succeeded on a saving throw against this casting of eyebite.\n\n***Asleep.*** The target falls unconscious. It wakes up if it takes any damage or if another creature uses its action to shake the sleeper awake.\n\n***Panicked.*** The target is frightened of you. On each of its turns, the frightened creature must take the Dash action and move away from you by the safest and shortest available route, unless there is nowhere to move. If the target moves to a place at least 60 feet away from you where it can no longer see you, this effect ends.\n\n***Sickened.*** The target has disadvantage on attack rolls and ability checks. At the end of each of its turns, it can make another wisdom saving throw. If it succeeds, the effect ends.","higherSource":""},{"id":"fabricate","name":"Fabricate","nameTr":"Fabrikasyon","level":4,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Ham maddeleri aynı malzemeden ürünlere dönüştürürsünüz. Örneğin, bir grup ağaçtan ahşap bir köprü, bir parça kenevirden bir ip, keten veya yünden giysiler yapabilirsiniz.\nMenzil dahilinde görebileceğiniz ham maddeleri seçin. Yeterli miktarda hammadde verildiğinde, Büyük veya daha küçük bir nesne (bir 10 ft küpünde veya sekiz bağlantılı 5 ft küpünde bulunur) üretebilirsiniz. Ancak metal, taş veya başka bir mineral maddeyle çalışıyorsanız, üretilen nesne Medium'dan (tek bir 5 ft küp içinde yer alan) daha büyük olamaz. Büyüyle yapılan nesnelerin kalitesi, hammaddelerin kalitesiyle orantılıdır.\nBu büyüyle yaratıklar veya sihirli eşyalar yaratılamaz veya dönüştürülemez. Ayrıca, mücevher, silah, cam veya zırh gibi normalde yüksek derecede işçilik gerektiren öğeler yaratmak için de, bu tür nesneleri yapmak için kullanılan zanaatkar aletlerinin türü konusunda yeterliliğiniz olmadığı sürece, bunu kullanamazsınız.","higher":"","sourceText":"You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool.\n\nChoose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given a sufficient quantity of raw material. If you are working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a single 5-foot cube). The quality of objects made by the spell is commensurate with the quality of the raw materials.\n\nCreatures or magic items can't be created or transmuted by this spell. You also can't use it to create items that ordinarily require a high degree of craftsmanship, such as jewelry, weapons, glass, or armor, unless you have proficiency with the type of artisan's tools used to craft such objects.","higherSource":""},{"id":"faerie-fire","name":"Faerie Fire","nameTr":"Peri Ateşi","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":{"type":"cube","size":20},"description":"20 ft küpündeki menzil içindeki her nesnenin ana hatları mavi, yeşil veya mor ışıkla (seçiminiz) belirtilir. Büyü yapıldığında bölgedeki herhangi bir yaratık, DEX saving throw başarısız olursa, ışıkla çerçevelenir. Bu süre boyunca nesneler ve etkilenen yaratıklar 10 ft yarıçapında loş ışık saçar.\nEtkilenen bir yaratığa veya nesneye karşı herhangi bir saldırı zarı, saldırganın görebilmesi durumunda avantaj'ye sahiptir ve etkilenen yaratık veya nesne invisible olmaktan yararlanamaz.","higher":"","sourceText":"Each object in a 20-foot cube within range is outlined in blue, green, or violet light (your choice). Any creature in the area when the spell is cast is also outlined in light if it fails a dexterity saving throw. For the duration, objects and affected creatures shed dim light in a 10-foot radius.\n\nAny attack roll against an affected creature or object has advantage if the attacker can see it, and the affected creature or object can't benefit from being invisible.","higherSource":""},{"id":"faithful-hound","name":"Faithful Hound","nameTr":"Sadık Tazı","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Minik gümüş bir düdük, bir parça kemik ve bir iplik","materialSource":"A tiny silver whistle, a piece of bone, and a thread","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz, boş bir alanda, siz onu bir eylem olarak reddedene veya ondan 100 ft'den daha fazlasını uzaklaştırıncaya kadar, süre boyunca orada kalacağı hayalet bir bekçi köpeği yaratırsınız.\nTazı, sizin dışınızdaki tüm canlılar için invisible'dir ve zarar verilemez. Bu büyüyü yaparken belirlediğiniz şifreyi söylemeden 30 ft yakınına Küçük veya daha büyük bir yaratık geldiğinde, tazı yüksek sesle havlamaya başlar. Tazı, invisible yaratıklarını görür ve Ethereal Plane'ın içini görebilir. İllüzyonları görmezden gelir.\nHer turunuzun başında tazı, 5 ft içindeki size düşman olan bir yaratığı ısırmaya çalışır. Tazı'nın saldırı bonusu, büyü yapma yeteneği değiştiriciniz + yeterlilik bonusunuza eşittir. Bir vuruşta 4d8 piercing hasarı verir.","higher":"","sourceText":"You conjure a phantom watchdog in an unoccupied space that you can see within range, where it remains for the duration, until you dismiss it as an action, or until you move more than 100 feet away from it.\n\nThe hound is invisible to all creatures except you and can't be harmed. When a Small or larger creature comes within 30 feet of it without first speaking the password that you specify when you cast this spell, the hound starts barking loudly. The hound sees invisible creatures and can see into the Ethereal Plane. It ignores illusions.\n\nAt the start of each of your turns, the hound attempts to bite one creature within 5 feet of it that is hostile to you. The hound's attack bonus is equal to your spellcasting ability modifier + your proficiency bonus. On a hit, it deals 4d8 piercing damage.","higherSource":""},{"id":"false-life","name":"False Life","nameTr":"Yanlış Yaşam","level":1,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Az miktarda alkol veya damıtılmış alkollü içki.","materialSource":"A small amount of alcohol or distilled spirits.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kendinizi yaşamın büyücü benzeri bir kopyasıyla güçlendirerek, bu süre boyunca 1d4+4 geçici HP kazanırsınız.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her yuva seviyesi için 5 ek geçici HP kazanırsınız.","sourceText":"Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you gain 5 additional temporary hit points for each slot level above 1st."},{"id":"fear","name":"Fear","nameTr":"Korku","level":3,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Beyaz bir tüy veya bir tavuğun kalbi.","materialSource":"A white feather or the heart of a hen.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":{"type":"cone","size":30},"description":"Bir yaratığın en büyük korkularının hayali bir görüntüsünü yansıtırsınız. Bir 30 ft konisindeki her yaratık, bir WIS saving throw üzerinde başarılı olmalı veya elindeki her şeyi bırakıp bu süre boyunca frightened haline gelmelidir.\nBu büyü frightened iken, hareket edecek bir yer olmadığı sürece, bir yaratığın Atılma eylemini gerçekleştirmesi ve her dönüşünde mümkün olan en güvenli rotayı kullanarak sizden uzaklaşması gerekir. Yaratık, sırasını sizi göremeyeceği bir yerde bitirirse, yaratık bir WIS saving throw yapabilir. Başarılı bir kurtarmanın ardından o yaratığın büyüsü sona erer.","higher":"","sourceText":"You project a phantasmal image of a creature's worst fears. Each creature in a 30-foot cone must succeed on a wisdom saving throw or drop whatever it is holding and become frightened for the duration.\n\nWhile frightened by this spell, a creature must take the Dash action and move away from you by the safest available route on each of its turns, unless there is nowhere to move. If the creature ends its turn in a location where it doesn't have line of sight to you, the creature can make a wisdom saving throw. On a successful save, the spell ends for that creature.","higherSource":""},{"id":"feather-fall","name":"Feather Fall","nameTr":"Tüy Güz","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 reaction","range":"60 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","M"],"materialTr":"Küçük bir tüy veya kuş tüyü parçası.","materialSource":"A small feather or a piece of down.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki en fazla beş düşen yaratığı seçin. Düşen yaratığın iniş hızı, büyü bitene kadar tur başına 60 ft'ye yavaşlar. Yaratık, büyü bitmeden yere inerse, düşme hasarı almaz ve ayakları üzerine inebilir ve o yaratık için büyü sona erer.","higher":"","sourceText":"Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before the spell ends, it takes no falling damage and can land on its feet, and the spell ends for that creature.","higherSource":""},{"id":"feeblemind","name":"Feeblemind","nameTr":"Zayıf akıl","level":8,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Druid","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir avuç kil, kristal, cam veya mineral küre.","materialSource":"A handful of clay, crystal, glass, or mineral spheres.","attackType":"","save":"INT","saves":["INT"],"saveSuccess":"other","area":null,"description":"Menzilde görebileceğiniz bir yaratığın zihnini patlatır, zekasını ve kişiliğini parçalamaya çalışırsınız. Hedef 4d6 psychic hasarı alır ve INT saving throw yapması gerekir.\nBaşarısız bir kaydetme durumunda yaratığın INT ve CHA puanları 1 olur. Yaratık büyü yapamaz, sihirli öğeleri etkinleştiremez, dili anlayamaz veya anlaşılır bir şekilde iletişim kuramaz. Ancak yaratık, arkadaşlarını tanıyabiliyor, takip edebiliyor, hatta koruyabiliyor.\nHer 30 günün sonunda yaratık bu büyüye karşı saving throw büyüsünü tekrarlayabilir. saving throw'de başarılı olursa büyü sona erer.\nBüyü ayrıca daha büyük bir iyileşme, iyileşme veya dilek ile de sona erdirilebilir.","higher":"","sourceText":"You blast the mind of a creature that you can see within range, attempting to shatter its intellect and personality. The target takes 4d6 psychic damage and must make an intelligence saving throw.\n\nOn a failed save, the creature's Intelligence and Charisma scores become 1. The creature can't cast spells, activate magic items, understand language, or communicate in any intelligible way. The creature can, however, identify its friends, follow them, and even protect them.\n\nAt the end of every 30 days, the creature can repeat its saving throw against this spell. If it succeeds on its saving throw, the spell ends.\n\nThe spell can also be ended by greater restoration, heal, or wish.","higherSource":""},{"id":"find-familiar","name":"Find Familiar","nameTr":"Tanıdık Bul","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 hour","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"fire tarafından pirinç mangalda tüketilmesi gereken 10gp değerinde kömür, tütsü ve şifalı bitkiler.","materialSource":"10gp worth of charcoal, incense, and herbs that must be consumed by fire in a brass brazier.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Seçtiğiniz bir hayvan formunu alan tanıdık bir ruhun hizmetini alırsınız: yarasa, kedi, yengeç, kurbağa (kurbağa), şahin, kertenkele, ahtapot, baykuş, zehirli yılan, balık (quipper), sıçan, kuzgun, deniz atı, örümcek veya gelincik. Menzil dahilinde boş bir alanda görünen tanıdık, bir canavar yerine göksel, peri veya şeytan (seçiminiz) olmasına rağmen seçilen formun istatistiklerine sahiptir.\nTanıdığınız sizden bağımsız hareket eder ama her zaman komutlarınıza uyar. Savaşta kendi inisiyatifini kullanır ve sırası geldiğinde hareket eder. Bir tanıdık saldıramaz, ancak normal olarak başka eylemlerde bulunabilir.\nTanıdık olan 0 HP'ye düştüğünde, arkasında hiçbir fiziksel form bırakmadan kaybolur. Bu büyüyü tekrar yaptığınızda yeniden ortaya çıkar.\nTanıdığınız 100 ft yakınınızdayken, onunla telepatik olarak iletişim kurabilirsiniz. Ek olarak, bir aksiyon olarak, bir sonraki sıranızın başlangıcına kadar tanıdıklarınızın gözlerinden görebilir ve duyduklarını duyabilir, tanıdıklarınızın sahip olduğu özel duyuların avantajlarından yararlanabilirsiniz. Bu süre zarfında kendi duyularınız açısından sağır ve körsünüz.\nBir eylem olarak tanıdıklarınızı geçici olarak kovabilirsiniz. Çağrınızı beklediği cep boyutunda kaybolur. Alternatif olarak, onu sonsuza kadar reddedebilirsiniz. Geçici olarak kapatıldığında bir eylem olarak, 30 ft içindeki boş herhangi bir alanda yeniden görünmesini sağlayabilirsiniz.\nAynı anda birden fazla tanıdık olamaz. Zaten bir tanıdık varken bu büyüyü yaparsanız, bunun yerine yeni bir biçim almasına neden olursunuz. Yukarıdaki listeden formlardan birini seçin. Tanıdığınız, seçilen yaratığa dönüşür.\nSon olarak, çeşitli dokunuşlarla bir büyü yaptığınızda, tanıdıklarınız büyüyü sanki büyü yapmış gibi yapabilir. Tanıdığınız kişi 100 ft yakınınızda olmalı ve büyüyü yaptığınızda büyüyü iletmek için Reaction'sini kullanmalıdır. Büyü bir saldırı zarı gerektiriyorsa, rulo için eylem değiştiricinizi kullanırsınız.","higher":"","sourceText":"You gain the service of a familiar, a spirit that takes an animal form you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, sea horse, spider, or weasel. Appearing in an unoccupied space within range, the familiar has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of a beast.\n\nYour familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can't attack, but it can take other actions as normal.\n\nWhen the familiar drops to 0 hit points, it disappears, leaving behind no physical form. It reappears after you cast this spell again.\n\nWhile your familiar is within 100 feet of you, you can communicate with it telepathically. Additionally, as an action, you can see through your familiar's eyes and hear what it hears until the start of your next turn, gaining the benefits of any special senses that the familiar has. During this time, you are deaf and blind with regard to your own senses.\n\nAs an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. Alternatively, you can dismiss it forever. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you.\n\nYou can't have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose one of the forms from the above list. Your familiar transforms into the chosen creature.\n\nFinally, when you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your action modifier for the roll.","higherSource":""},{"id":"find-steed","name":"Find Steed","nameTr":"Steed'i Bul","level":2,"school":"Conjuration","schoolTr":"Çağırma","classes":["Paladin"],"subclasses":["Lore"],"castingTime":"10 minutes","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Alışılmadık derecede zeki, güçlü ve sadık bir at biçimine bürünen bir ruhu çağırırsınız ve onunla uzun süreli bir bağ kurarsınız. Menzil dahilindeki boş bir alanda görünen küheylan, savaş atı, midilli, deve, Kanada geyiği veya mastif gibi seçtiğiniz bir biçimi alır. (GM'niz diğer hayvanların at olarak çağrılmasına izin verebilir.) At, normal türü yerine göksel, peri veya şeytan (seçiminiz) olmasına rağmen, seçilen formun istatistiklerine sahiptir. Ek olarak, atınızın INT puanı 5 veya daha azsa INT değeri 6 olur ve konuştuğunuz dillerden birini anlama becerisi kazanır.\nAtınız size hem savaşta hem de dışarıda bir binek görevi görür ve onunla kusursuz bir birim olarak savaşmanızı sağlayan içgüdüsel bir bağınız vardır. Atınızın üzerindeyken, yalnızca sizi hedef alan herhangi bir büyüyü atınızı da hedef alarak yapabilirsiniz.\nAt 0 HP'ye düştüğünde, arkasında hiçbir fiziksel form bırakmadan ortadan kaybolur. Ayrıca atınızı istediğiniz zaman bir eylem olarak ortadan kaldırabilir ve kaybolmasına neden olabilirsiniz. Her iki durumda da, bu büyüyü tekrar kullanmak aynı atı çağırır ve maksimum can puanına geri döner.\nAtınız 1 mil yakınınızdayken onunla telepatik olarak iletişim kurabilirsiniz.\nBu büyüyle aynı anda birden fazla küheylan bağlayamazsınız. Bir eylem olarak, istediğiniz zaman atı bağından kurtarabilir ve yok olmasını sağlayabilirsiniz.","higher":"","sourceText":"You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes on a form that you choose, such as a warhorse, a pony, a camel, an elk, or a mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of the chosen form, though it is a celestial, fey, or fiend (your choice) instead of its normal type. Additionally, if your steed has an Intelligence of 5 or less, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\n\nYour steed serves you as a mount, both in combat and out, and you have an instinctive bond with it that allows you to fight as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed.\n\nWhen the steed drops to 0 hit points, it disappears, leaving behind no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum.\n\nWhile your steed is within 1 mile of you, you can communicate with it telepathically.\n\nYou can't have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear.","higherSource":""},{"id":"find-traps","name":"Find Traps","nameTr":"Tuzakları Bul","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric","Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Görüş alanınızda bulunan herhangi bir tuzağın varlığını hissedersiniz. Bu büyünün amacına uygun olarak bir tuzak, yaratıcısı tarafından özel olarak amaçlanan, zararlı veya istenmeyen olduğunu düşündüğünüz ani veya beklenmedik bir etki yaratacak her şeyi içerir. Böylece büyü, alarm büyüsünden, bir koruma glifinden veya mekanik bir çukur tuzağından etkilenen bir alanı algılayacak, ancak zemindeki doğal bir zayıflığı, dengesiz bir tavanı veya gizli bir çukuru ortaya çıkarmayacaktır.\nBu büyü yalnızca bir tuzağın var olduğunu ortaya çıkarır. Her bir tuzağın yerini öğrenemezsiniz, ancak hissettiğiniz bir tuzağın yarattığı tehlikenin genel doğasını öğrenirsiniz.","higher":"","sourceText":"You sense the presence of any trap within range that is within line of sight. A trap, for the purpose of this spell, includes anything that would inflict a sudden or unexpected effect you consider harmful or undesirable, which was specifically intended as such by its creator. Thus, the spell would sense an area affected by the alarm spell, a glyph of warding, or a mechanical pit trap, but it would not reveal a natural weakness in the floor, an unstable ceiling, or a hidden sinkhole.\n\nThis spell merely reveals that a trap is present. You don't learn the location of each trap, but you do learn the general nature of the danger posed by a trap you sense.","higherSource":""},{"id":"find-the-path","name":"Find the Path","nameTr":"Yolu Bul","level":6,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Druid"],"subclasses":[],"castingTime":"1 minute","range":"Self","duration":"Up to 24 hours","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"100gp değerinde bir dizi kehanet aracı (kemikler, fildişi çubuklar, kartlar, dişler veya oyulmuş rünler gibi) ve bulmak istediğiniz yerden bir nesne.","materialSource":"A set of divinatory tools--such as bones, ivory sticks, cards, teeth, or carved runes--worth 100gp and an object from the location you wish to find.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, aynı varoluş düzleminde aşina olduğunuz belirli bir sabit konuma giden en kısa, en doğrudan fiziksel rotayı bulmanızı sağlar. Başka bir varoluş düzlemindeki bir hedefi, hareket eden bir hedefi (örneğin mobil bir kale) veya spesifik olmayan bir hedefi (\"yeşil bir ejderhanın ini\" gibi) adlandırırsanız, büyü başarısız olur.\nBu süre zarfında, varış noktasıyla aynı varoluş düzleminde olduğunuz sürece, onun ne kadar uzakta olduğunu ve hangi yönde olduğunu bilirsiniz. Oraya seyahat ederken, yol boyunca size çeşitli yol seçenekleri sunulduğunda, hangi yolun hedefe giden en kısa ve en doğrudan rota (ancak en güvenli rota olması gerekmez) olduğunu otomatik olarak belirlersiniz.","higher":"","sourceText":"This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn't specific (such as \"a green dragon's lair\"), the spell fails.\n\nFor the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in what direction it lies. While you are traveling there, whenever you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination.","higherSource":""},{"id":"finger-of-death","name":"Finger of Death","nameTr":"Ölüm Parmağı","level":7,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":null,"description":"Menzil içinde görebildiğiniz bir yaratığın içinden akan negatif enerjiyi gönderiyorsunuz, bu da onun yakıcı bir acıya neden olmasına neden oluyor. Hedefin bir CON saving throw yapması gerekir. Başarısız bir kaydetmede 7d8+30 necrotic hasar alır veya başarılı bir kaydetmede bunun yarısı kadar hasar alır.\nBu büyü tarafından öldürülen bir insansı, bir sonraki turunuzun başlangıcında, kalıcı olarak emriniz altında olan ve sözlü emirlerinizi elinden gelen en iyi şekilde yerine getiren bir zombi olarak yükselir.","higher":"","sourceText":"You send negative energy coursing through a creature that you can see within range, causing it searing pain. The target must make a constitution saving throw. It takes 7d8 + 30 necrotic damage on a failed save, or half as much damage on a successful one.\n\nA humanoid killed by this spell rises at the start of your next turn as a zombie that is permanently under your command, following your verbal orders to the best of its ability.","higherSource":""},{"id":"fire-bolt","name":"Fire Bolt","nameTr":"Ateş Oku","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki bir yaratığa veya nesneye bir fire zerresi fırlatırsınız. Hedefe karşı bir menzilli spell attack yapın. Bir vuruşta hedef 1d10 fire hasarı alır. Bu büyünün çarptığı yanıcı bir nesne, eğer giyilmiyor veya taşınmıyorsa tutuşur.\nBu büyünün hasarı, 5. seviyeye (2d10), 11. seviyeye (3d10) ve 17. seviyeye (4d10) ulaştığınızda 1d10 artar.","higher":"","sourceText":"You hurl a mote of fire at a creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried.\n\nThis spell's damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10).","higherSource":""},{"id":"fire-shield","name":"Fire Shield","nameTr":"Yangın Kalkanı","level":4,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":["Fiend"],"castingTime":"1 action","range":"Self","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz fosfor ya da ateş böceği.","materialSource":"A little phosphorus or a firefly.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":5},"description":"İnce ve buharlı alev, büyü süresi boyunca vücudunuzu çevreler, 10 ft yarıçapında parlak bir ışık ve ek bir 10 ft için loş bir ışık yayar. Büyüyü ortadan kaldıracak bir eylem kullanarak sonlandırabilirsiniz.\nAlevler etrafınızda bir ısı kalkanı veya cold, sizin seçiminiz. Isı kalkanı size cold hasar direnci ve cold fire hasarına karşı direnç sağlar.\nAyrıca 5 ft içindeki bir yaratık size yakın dövüş saldırısıyla vurduğunda, kalkandan alevler fışkırır. Saldırgan daha sonra modele bağlı olarak 2d8 puan fire veya cold hasarına maruz kalır.","higher":"","sourceText":"Thin and vaporous flame surround your body for the duration of the spell, radiating a bright light bright light in a 10-foot radius and dim light for an additional 10 feet. You can end the spell using an action to make it disappear.\n\nThe flames are around you a heat shield or cold, your choice. The heat shield gives you cold damage resistance and the cold resistance to fire damage.\n\nIn addition, whenever a creature within 5 feet of you hits you with a melee attack, flames spring from the shield. The attacker then suffers 2d8 points of fire damage or cold, depending on the model.","higherSource":""},{"id":"fire-storm","name":"Fire Storm","nameTr":"Ateş Fırtınası","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric","Druid","Sorcerer"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"cube","size":100},"description":"Menzil içinde seçtiğiniz bir yerde kükreyen alevlerden oluşan bir fırtına beliriyor. Fırtınanın alanı, dilediğiniz gibi düzenleyebileceğiniz on adede kadar 10 ft küpten oluşur. Her küpün, başka bir küpün yüzüne bitişik en az bir yüzü olmalıdır. Bölgedeki her canlı bir DEX saving throw yapmalıdır. başarısız save’de 7d10 fire hasar alır veya başarılı save’de yarısı kadar hasar alır.\nfire, bölgedeki nesnelere zarar verir ve giyilmeyen veya taşınmayan yanıcı nesneleri ateşler. İsterseniz bölgedeki bitki yaşamı bu büyüden etkilenmez.","higher":"","sourceText":"A storm made up of sheets of roaring flame appears in a location you choose within range. The area of the storm consists of up to ten 10-foot cubes, which you can arrange as you wish. Each cube must have at least one face adjacent to the face of another cube. Each creature in the area must make a dexterity saving throw. It takes 7d10 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire damages objects in the area and ignites flammable objects that aren't being worn or carried. If you choose, plant life in the area is unaffected by this spell.","higherSource":""},{"id":"fireball","name":"Fireball","nameTr":"Ateş topu","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Fiend","Lore"],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir yarasa gübresi ve kükürt topu.","materialSource":"A tiny ball of bat guano and sulfur.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"sphere","size":20},"description":"İşaret parmağınızdan menzil içinde seçtiğiniz bir noktaya kadar parlak bir çizgi yanıp söner ve ardından alçak bir kükreme ile bir alev patlamasına dönüşür. Bu noktaya odaklanan 20 ft yarıçaplı küredeki her yaratık, DEX saving throw atmalıdır. Bir hedef, başarısız save’de 8d6 fire hasar alır veya başarılı save’de yarısı kadar hasar alır.\nfire köşelere yayılır. Ortamdaki giyilmeyen veya taşınmayan yanıcı nesneleri tutuşturur.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 3. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"A bright streak flashes from your pointing finger to a point you choose within range and then blossoms with a low roar into an explosion of flame. Each creature in a 20-foot-radius sphere centered on that point must make a dexterity saving throw. A target takes 8d6 fire damage on a failed save, or half as much damage on a successful one.\n\nThe fire spreads around corners. It ignites flammable objects in the area that aren't being worn or carried.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},{"id":"flame-blade","name":"Flame Blade","nameTr":"Alev Kılıcı","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Sumak yaprağı.","materialSource":"Leaf of sumac.","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Serbest elinizde ateşli bir bıçağı çağrıştırıyorsunuz. Bıçağın boyutu ve şekli palaya benzer ve bu süre boyunca dayanır. Bıçağı bırakırsanız kaybolur ancak bıçağı tekrar Bonus Action olarak çağırabilirsiniz.\nAteşli bıçakla bir yakın spell attack yapmak için eyleminizi kullanabilirsiniz. Bir vuruşta hedef 3d6 fire hasarı alır.\nAlevli bıçak, 10 ft yarıçapında parlak ışık saçar ve ek bir 10 ft için loş ışık yayar.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 2. seviyenin üzerindeki her iki slot seviyesi için 1d6 artar.","sourceText":"You evoke a fiery blade in your free hand. The blade is similar in size and shape to a scimitar, and it lasts for the duration. If you let go of the blade, it disappears, but you can evoke the blade again as a bonus action.\n\nYou can use your action to make a melee spell attack with the fiery blade. On a hit, the target takes 3d6 fire damage.\n\nThe flaming blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for every two slot levels above 2nd."},{"id":"flame-strike","name":"Flame Strike","nameTr":"Alev Saldırısı","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Devotion","Fiend"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam kükürt.","materialSource":"Pinch of sulfur.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"cylinder","size":40},"description":"İlahi fire'nin dikey bir sütunu, belirttiğiniz bir konumda göklerden gürleyerek iniyor. Menzil içindeki bir noktaya merkezlenen 10 ft yarıçap, 40 ft yükseklik silindirindeki her yaratık, bir DEX saving throw yapmalıdır. Bir yaratık, başarısız save’de 4d6 fire hasarı ve 4d6 radiant hasarı veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, fire hasarı veya radiant hasarı (seçiminiz), 5. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"A vertical column of divine fire roars down from the heavens in a location you specify. Each creature in a 10-foot-radius, 40-foot-high cylinder centered on a point within range must make a dexterity saving throw. A creature takes 4d6 fire damage and 4d6 radiant damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the fire damage or the radiant damage (your choice) increases by 1d6 for each slot level above 5th."},{"id":"flaming-sphere","name":"Flaming Sphere","nameTr":"Alevli Küre","level":2,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz donyağı, bir tutam kükürt ve bir tutam demir tozu.","materialSource":"A bit of tallow, a pinch of brimstone, and a dusting of powdered iron.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":null,"description":"5 ft çapında bir fire küresi, menzil dahilinde seçtiğiniz boş bir alanda belirir ve bu süre boyunca varlığını sürdürür. Kürenin 5 ft içinde sırasını bitiren herhangi bir yaratık, bir DEX saving throw yapmalıdır. Yaratık, başarısız save’de 2d6 fire hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\nBonus Action olarak küreyi 30 ft'ye kadar hareket ettirebilirsiniz. Küreyi bir yaratığa çarparsanız, o yaratığın kürenin hasarına karşı saving throw yapması gerekir ve küre bu dönüşte hareket etmeyi bırakır.\nKüreyi hareket ettirdiğinizde, onu 5 ft yüksekliğe kadar olan bariyerlerin üzerinden yönlendirebilir ve 10 ft genişliğe kadar olan çukurların üzerinden atlayabilirsiniz. Küre, giyilmemiş veya taşınmamış yanıcı nesneleri ateşler ve 20 ft yarıçapında parlak ışık ve ek bir 20 ft için loş ışık saçar.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 2. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"A 5-foot-diameter sphere of fire appears in an unoccupied space of your choice within range and lasts for the duration. Any creature that ends its turn within 5 feet of the sphere must make a dexterity saving throw. The creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\n\nAs a bonus action, you can move the sphere up to 30 feet. If you ram the sphere into a creature, that creature must make the saving throw against the sphere's damage, and the sphere stops moving this turn.\n\nWhen you move the sphere, you can direct it over barriers up to 5 feet tall and jump it across pits up to 10 feet wide. The sphere ignites flammable objects not being worn or carried, and it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."},{"id":"flesh-to-stone","name":"Flesh to Stone","nameTr":"Etten Taşa","level":6,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam kireç, su ve toprak.","materialSource":"A pinch of lime, water, and earth.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"none","area":null,"description":"Yakın mesafede görebileceğiniz bir yaratığı taşa çevirmeye çalışıyorsunuz. Hedefin vücudu etten yapılmışsa yaratığın bir CON saving throw yapması gerekir. Başarısız bir kaydetme işleminde eti sertleşmeye başladığında restrained olur. Başarılı bir kaydetme işleminde yaratık etkilenmez.\nBu büyüyle restrained yaratık, her turun sonunda başka bir CON saving throw yapmalıdır. Bu büyüye karşı üç kez başarıyla kurtarılırsa büyü sona erer. Üç kez kurtarmada başarısız olursa taşa döner ve bu süre boyunca petrified koşuluna tabi tutulur. Başarıların ve başarısızlıkların ardışık olması gerekmez; Hedef aynı türden üç tane toplayana kadar her ikisini de takip edin.\nEğer yaratık petrified iken fiziksel olarak kırılırsa, orijinal durumuna dönmesi durumunda da benzer deformasyonlara maruz kalıyor.\nconcentration'nizi mümkün olan tüm süre boyunca bu büyüde tutarsanız, yaratık, etki kaldırılıncaya kadar taşa dönüşür.","higher":"","sourceText":"You attempt to turn one creature that you can see within range into stone. If the target's body is made of flesh, the creature must make a constitution saving throw. On a failed save, it is restrained as its flesh begins to harden. On a successful save, the creature isn't affected.\n\nA creature restrained by this spell must make another constitution saving throw at the end of each of its turns. If it successfully saves against this spell three times, the spell ends. If it fails its saves three times, it is turned to stone and subjected to the petrified condition for the duration. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\n\nIf the creature is physically broken while petrified, it suffers from similar deformities if it reverts to its original state.\n\nIf you maintain your concentration on this spell for the entire possible duration, the creature is turned to stone until the effect is removed.","higherSource":""},{"id":"floating-disk","name":"Floating Disk","nameTr":"Yüzen Disk","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir damla cıva.","materialSource":"A drop of mercury.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, 3 ft'yi menzil içinde görebileceğiniz seçtiğiniz boş bir alanda yerin üzerinde yüzen force, 3 ft'den oluşan, çapı ve 1 inç kalınlığında dairesel, yatay bir düzlem oluşturur. Disk bu süre boyunca kalır ve 500 lb'ye kadar tutabilir. Üzerine daha fazla ağırlık konulursa büyü sona erer ve diskteki her şey yere düşer.\nSiz diskin 20 ft yakınındayken disk hareketsizdir. Ondan 20 ft'den daha fazlasını uzaklaştırırsanız disk sizi takip edecek ve böylece 20 ft yakınınızda kalacaktır. Engebeli arazide, merdivenlerden yukarı veya aşağı, eğimlerde ve benzerlerinde hareket edebilir, ancak 10 ft veya daha fazla yükseklik değişikliğini geçemez. Örneğin disk bir 10 ft derinlik çukuru boyunca hareket edemez veya altta oluşturulmuşsa böyle bir çukurdan çıkamaz.\nDiskten 100 ft değerinden daha fazla uzaklaşırsanız (genellikle sizi takip etmek için bir engelin etrafından dolaşamadığı için), büyü sona erer.","higher":"","sourceText":"This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\n\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. If can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot-deep pit, nor could it leave such a pit if it was created at the bottom.\n\nIf you move more than 100 feet away from the disk (typically because it can't move around an obstacle to follow you), the spell ends.","higherSource":""},{"id":"fly","name":"Fly","nameTr":"Uçmak","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Herhangi bir kuşun kanat tüyü.","materialSource":"A wing feather from any bird.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunuyorsun. Hedef bu süre boyunca 60 ft uçuş hızı kazanır. Büyü sona erdiğinde hedef, düşüşü durduramadığı sürece hâlâ havadaysa düşer.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 3. seviyenin üzerindeki her yuva seviyesi için ilave bir yaratığı hedefleyebilirsiniz.","sourceText":"You touch a willing creature. The target gains a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft, unless it can stop the fall.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."},{"id":"fog-cloud","name":"Fog Cloud","nameTr":"Sis Bulutu","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":20},"description":"Menzil içindeki bir noktayı merkezleyen bir 20 ft yarıçap sis küresi yaratırsınız. Küre köşelere yayılıyor ve alanı oldukça karanlık. Bu süre boyunca veya orta veya daha yüksek hızdaki bir rüzgar (en azından saatte 10 mil) onu dağıtana kadar sürer.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, sisin yarıçapı 1. seviyenin üzerindeki her yuva seviyesi için 20 ft artar.","sourceText":"You create a 20-foot-radius sphere of fog centered on a point within range. The sphere spreads around corners, and its area is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the radius of the fog increases by 20 feet for each slot level above 1st."},{"id":"forbiddance","name":"Forbiddance","nameTr":"Yasak","level":6,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric"],"subclasses":[],"castingTime":"10 minutes","range":"Touch","duration":"24 hours","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"En az 1000 gp değerinde kutsal su, nadir tütsü ve toz haline getirilmiş yakut serpintisi.","materialSource":"A sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":40000},"description":"40.000 ft²ye kadar zemin alanını yerden 30 ft yüksekliğe kadar koruyan, büyülü yolculuğa karşı bir koruma oluşturursunuz. Bu süre boyunca yaratıklar bölgeye ışınlanamaz veya alana girmek için kapı büyüsü tarafından oluşturulanlar gibi portalları kullanamaz. Büyü, bölgeyi düzlemsel yolculuğa karşı korur ve bu nedenle yaratıkların Astral Düzlem, Ethereal Düzlem, Feywild, Shadowfell veya düzlem değiştirme büyüsü yoluyla bölgeye erişmesini engeller.\nAyrıca büyü, yaptığınızda seçtiğiniz yaratık türlerine de zarar verir. Şunlardan birini veya birkaçını seçin: gökseller, elementaller, periler, şeytanlar ve ölümsüzler. Seçilen bir yaratık bir turda büyü alanına ilk kez girdiğinde veya turuna orada başladığında, yaratık 5d10 radiant veya necrotic hasarı alır (bu büyüyü yaptığınızda seçiminiz).\nBu büyüyü yaparken kendinize bir şifre belirleyebilirsiniz. Alana girerken şifreyi söyleyen yaratık, büyüden zarar görmez.\nBüyünün alanı başka bir yasaklama büyüsünün alanıyla örtüşemez. 30 gün boyunca her gün aynı yerde yasaklama yaparsanız, büyü bozuluncaya kadar devam eder ve malzeme bileşenleri son kullanımda tüketilir.","higher":"","sourceText":"You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can't teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel, and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, Feywild, Shadowfell, or the plane shift spell.\n\nIn addition, the spell damages types of creatures that you choose when you cast it. Choose one or more of the following: celestials, elementals, fey, fiends, and undead. When a chosen creature enters the spell's area for the first time on a turn or starts its turn there, the creature takes 5d10 radiant or necrotic damage (your choice when you cast this spell).\n\nWhen you cast this spell, you can designate a password. A creature that speaks the password as it enters the area takes no damage from the spell.\n\nThe spell's area can't overlap with the area of another forbiddance spell. If you cast forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the material components are consumed on the last casting.","higherSource":""},{"id":"forcecage","name":"Forcecage","nameTr":"Zorla Kafes","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"100 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"1.500 gp değerinde yakut tozu.","materialSource":"Ruby dust worth 1,500 gp.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"","area":{"type":"cube","size":20},"description":"Büyülü force'den oluşan küp şeklindeki hareketsiz invisible hapishane, menzil içinde seçtiğiniz bir alanın etrafında ortaya çıkıyor. Hapishane seçiminize göre bir kafes veya sağlam bir kutu olabilir.\nKafes şeklindeki bir hapishanenin bir tarafı 20 ft'ye kadar olabilir ve 1/2 inç aralıklı 1/2 inç çapındaki çubuklardan yapılır.\nKutu şeklindeki bir hapishanenin bir tarafı 10 ft'ye kadar olabilir, bu da içinden herhangi bir maddenin geçmesini önleyen ve bölgeye giren veya bölgeden çıkan büyüleri engelleyen sağlam bir bariyer oluşturur.\nBüyüyü yaptığınızda, tamamen kafesin alanı içinde olan herhangi bir yaratık tuzağa düşürülür. Alanın yalnızca bir kısmı içinde bulunan veya alana sığmayacak kadar büyük olan canlılar, alanın merkezinden tamamen alanın dışına çıkana kadar itilir.\nKafesin içindeki bir yaratık, büyü dışı yöntemlerle kafesten ayrılamaz. Yaratık kafesten çıkmak için ışınlanmayı veya düzlemler arası yolculuğu kullanmaya çalışırsa, önce bir CHA saving throw yapması gerekir. Başarılı olması durumunda yaratık bu büyüyü kullanarak kafesten çıkabilir. Başarısızlık durumunda yaratık kafesten çıkamaz ve büyü veya etki kullanımını boşa harcar. Kafes aynı zamanda Eterik Düzlem'e kadar uzanarak ruhani yolculuğu engeller.\nBu büyü, yok etme büyüsüyle ortadan kaldırılamaz.","higher":"","sourceText":"An immobile, invisible, cube-shaped prison composed of magical force springs into existence around an area you choose within range. The prison can be a cage or a solid box, as you choose.\n\nA prison in the shape of a cage can be up to 20 feet on a side and is made from 1/2-inch diameter bars spaced 1/2 inch apart.\n\nA prison in the shape of a box can be up to 10 feet on a side, creating a solid barrier that prevents any matter from passing through it and blocking any spells cast into or out from the area.\n\nWhen you cast the spell, any creature that is completely inside the cage's area is trapped. Creatures only partially within the area, or those too large to fit inside the area, are pushed away from the center of the area until they are completely outside the area.\n\nA creature inside the cage can't leave it by nonmagical means. If the creature tries to use teleportation or interplanar travel to leave the cage, it must first make a charisma saving throw. On a success, the creature can use that magic to exit the cage. On a failure, the creature can't exit the cage and wastes the use of the spell or effect. The cage also extends into the Ethereal Plane, blocking ethereal travel.\n\nThis spell can't be dispelled by dispel magic.","higherSource":""},{"id":"foresight","name":"Foresight","nameTr":"Öngörü","level":9,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Druid","Warlock","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir sinek kuşu tüyü.","materialSource":"A hummingbird feather.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunursunuz ve yakın geleceği görme konusunda sınırlı bir yetenek bahşedersiniz. Bu süre boyunca hedef şaşıramaz ve saldırı atışlarında ability check’ler ve saving throw’lar avantaj'ye sahiptir. Ek olarak, diğer yaratıklar bu süre boyunca hedefe karşı saldırı atışlarında dezavantaj'ye sahiptir.\nBu büyüyü, süresi sona ermeden tekrar kullanırsanız hemen sona erer.","higher":"","sourceText":"You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against the target for the duration.\n\nThis spell immediately ends if you cast it again before its duration ends.","higherSource":""},{"id":"freedom-of-movement","name":"Freedom of Movement","nameTr":"Hareket Özgürlüğü","level":4,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Druid","Ranger"],"subclasses":["Devotion","Land"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Kolun etrafına veya benzer bir eklentiye bağlanan deri kayış.","materialSource":"A leather strap, bound around the arm or a similar appendage.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunuyorsun. Bu süre boyunca hedefin hareketi zorlu arazi koşullarından etkilenmez ve büyüler ve diğer büyülü etkiler ne hedefin hızını azaltabilir ne de hedefin paralyzed veya restrained olmasına neden olabilir.\nHedef ayrıca kelepçeler veya grappled'ye sahip bir yaratık gibi sihirli olmayan sınırlamalardan otomatik olarak kaçmak için 5 ft hareket harcayabilir. Son olarak, su altında olmak hedefin hareketine veya saldırılarına herhangi bir zarar vermez.","higher":"","sourceText":"You touch a willing creature. For the duration, the target's movement is unaffected by difficult terrain, and spells and other magical effects can neither reduce the target's speed nor cause the target to be paralyzed or restrained.\n\nThe target can also spend 5 feet of movement to automatically escape from nonmagical restraints, such as manacles or a creature that has it grappled. Finally, being underwater imposes no penalties on the target's movement or attacks.","higherSource":""},{"id":"freezing-sphere","name":"Freezing Sphere","nameTr":"Donma Küresi","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"300 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir kristal küre.","materialSource":"A small crystal sphere.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"sphere","size":60},"description":"Soğuk bir cold enerji küresi, parmak uçlarınızdan menzil içinde seçtiğiniz bir noktaya doğru akar ve burada bir 60 ft yarıçap küresi şeklinde patlar. Bölgedeki her yaratık CON saving throw atmalıdır. Başarısız bir kaydetme durumunda yaratık, 10d6 cold hasarı alır. başarılı save’de yarısı kadar hasar alır.\nKüre bir su kütlesine veya esas olarak su olan bir sıvıya (su bazlı canlılar hariç) çarparsa, sıvıyı 30 ft kare alanı üzerinde 6 inç derinliğe kadar dondurur. Bu buz 1 dakika kadar sürer. Donmuş suyun yüzeyinde yüzen canlılar buzun içinde mahsur kaldı. Kapana kısılmış bir yaratık, serbest kalmak için STR büyü kurtarma DC'nizi kontrol etmek için bir eylemi kullanabilir.\nİsterseniz büyüyü tamamladıktan sonra küreyi ateşlemekten kaçınabilirsiniz. Elinizde, sapan taşı büyüklüğünde, dokunulabilecek kadar soğuk küçük bir küre beliriyor. İstediğiniz zaman siz veya küreyi verdiğiniz bir yaratık, küreyi fırlatabilir (40 ft aralığına) veya bir askıyla (sapanın normal menziline) fırlatabilir. Çarpma anında paramparça olur ve normal büyü kullanımıyla aynı etkiyi gösterir. Ayrıca küreyi kırmadan yere koyabilirsiniz. 1 dakika sonra eğer küre henüz parçalanmamışsa patlar.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 6. seviyenin üzerindeki her slot seviyesi için 1d6 artar.","sourceText":"A frigid globe of cold energy streaks from your fingertips to a point of your choice within range, where it explodes in a 60-foot-radius sphere. Each creature within the area must make a constitution saving throw. On a failed save, a creature takes 10d6 cold damage. On a successful save, it takes half as much damage.\n\nIf the globe strikes a body of water or a liquid that is principally water (not including water-based creatures), it freezes the liquid to a depth of 6 inches over an area 30 feet square. This ice lasts for 1 minute. Creatures that were swimming on the surface of frozen water are trapped in the ice. A trapped creature can use an action to make a Strength check against your spell save DC to break free.\n\nYou can refrain from firing the globe after completing the spell, if you wish. A small globe about the size of a sling stone, cool to the touch, appears in your hand. At any time, you or a creature you give the globe to can throw the globe (to a range of 40 feet) or hurl it with a sling (to the sling's normal range). It shatters on impact, with the same effect as the normal casting of the spell. You can also set the globe down without shattering it. After 1 minute, if the globe hasn't already shattered, it explodes.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d6 for each slot level above 6th."},{"id":"gaseous-form","name":"Gaseous Form","nameTr":"Gaz Halinde","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz gazlı bez ve bir tutam duman.","materialSource":"A bit of gauze and a wisp of smoke.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"","area":null,"description":"Dokunduğunuz istekli bir yaratığı, giydiği ve taşıdığı her şeyle birlikte bu süre boyunca sisli bir buluta dönüştürürsünüz. Yaratık 0 HP'ye düşerse büyü sona erer. Bedensiz bir yaratık etkilenmez.\nBu formdayken hedefin tek hareket yöntemi 10 ft uçuş hızıdır. Hedef başka bir yaratığın alanına girip işgal edebilir. Hedefin büyüsel olmayan hasara karşı direnci vardır ve STR, DEX ve CON saving throw’lar üzerinde avantaj'ye sahiptir. Hedef, sıvılara katı yüzeylermiş gibi davransa da küçük deliklerden, dar açıklıklardan ve hatta basit çatlaklardan geçebilir. Hedef düşemez ve stunned veya incapacitated durumunda bile havada asılı kalır.\nPuslu bir bulut formundayken hedef konuşamaz veya nesneleri kullanamaz ve taşıdığı veya tuttuğu nesneler düşürülemez, kullanılamaz veya başka şekilde etkileşime geçilemez. Hedef saldıramaz veya büyü yapamaz.","higher":"","sourceText":"You transform a willing creature you touch, along with everything it's wearing and carrying, into a misty cloud for the duration. The spell ends if the creature drops to 0 hit points. An incorporeal creature isn't affected.\n\nWhile in this form, the target's only method of movement is a flying speed of 10 feet. The target can enter and occupy the space of another creature. The target has resistance to nonmagical damage, and it has advantage on Strength, Dexterity, and constitution saving throws. The target can pass through small holes, narrow openings, and even mere cracks, though it treats liquids as though they were solid surfaces. The target can't fall and remains hovering in the air even when stunned or otherwise incapacitated.\n\nWhile in the form of a misty cloud, the target can't talk or manipulate objects, and any objects it was carrying or holding can't be dropped, used, or otherwise interacted with. The target can't attack or cast spells.","higherSource":""},{"id":"gate","name":"Gate","nameTr":"Kapı","level":9,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"En az 5.000gp değerinde bir elmas.","materialSource":"A diamond worth at least 5,000gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz boş bir alanı farklı bir varoluş düzlemindeki kesin bir konuma bağlayan bir portal yaratırsınız. Portal, 5 ila 20 ft çapında yapabileceğiniz dairesel bir açıklıktır. Portalı seçtiğiniz herhangi bir yöne yönlendirebilirsiniz. Portal bu süre boyunca devam eder.\nPortalın göründüğü her düzlemde bir ön ve arka kısmı vardır. Portalda seyahat etmek ancak önünden geçerek mümkündür. Bunu yapan her şey anında diğer düzleme aktarılır ve portala en yakın boş alanda görünür.\nTanrılar ve diğer düzlemsel yöneticiler, bu büyü tarafından oluşturulan portalların, onların varlığında veya etki alanlarının herhangi bir yerinde açılmasını engelleyebilir.\nBu büyüyü yaptığınızda, belirli bir yaratığın adını söyleyebilirsiniz (takma ad, unvan veya takma ad işe yaramaz). Eğer o yaratık sizin bulunduğunuz uçaktan farklı bir düzlemdeyse, adı geçen yaratığın hemen yakınında portal açılır ve yaratığı onun içinden portalın sizin tarafınızdaki en yakın boş alana çeker. Yaratık üzerinde özel bir güç kazanmazsınız ve GM'nin uygun gördüğü şekilde hareket etmekte özgürdür. Gidebilir, size saldırabilir veya size yardım edebilir.","higher":"","sourceText":"You conjure a portal linking an unoccupied space you can see within range to a precise location on a different plane of existence. The portal is a circular opening, which you can make 5 to 20 feet in diameter. You can orient the portal in any direction you choose. The portal lasts for the duration.\n\nThe portal has a front and a back on each plane where it appears. Travel through the portal is possible only by moving through its front. Anything that does so is instantly transported to the other plane, appearing in the unoccupied space nearest to the portal.\n\nDeities and other planar rulers can prevent portals created by this spell from opening in their presence or anywhere within their domains.\n\nWhen you cast this spell, you can speak the name of a specific creature (a pseudonym, title, or nickname doesn't work). If that creature is on a plane other than the one you are on, the portal opens in the named creature's immediate vicinity and draws the creature through it to the nearest unoccupied space on your side of the portal. You gain no special power over the creature, and it is free to act as the GM deems appropriate. It might leave, attack you, or help you.","higherSource":""},{"id":"geas","name":"Geas","nameTr":"Geas","level":5,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Cleric","Druid","Paladin","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"60 feet","duration":"30 days","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebileceğiniz bir yaratığa sihirli bir komut vererek onu bazı hizmetleri yerine getirmeye veya karar verdiğiniz bir eylemden veya faaliyet akışından kaçınmaya zorlarsınız. Yaratık sizi anlayabiliyorsa, WIS saving throw üzerinde başarılı olmalı veya bu süre boyunca sizin tarafınızdan charmed olmalıdır. Yaratık sizin tarafınızdan charmed olsa da, talimatlarınıza doğrudan aykırı bir şekilde hareket ettiği her seferde 5d10 psychic hasar alır, ancak günde bir kereden fazla olamaz. Seni anlayamayan bir yaratık büyüden etkilenmez.\nKesin ölümle sonuçlanacak bir faaliyet dışında, seçtiğiniz herhangi bir komutu verebilirsiniz. İntihar emri verirseniz büyü sona erer.\nBüyüyü iptal etme eylemini kullanarak büyüyü erken sonlandırabilirsiniz. Laneti kaldırmak, daha büyük bir iyileşme veya dilek büyüsü de onu sona erdirir.","higher":"Bu büyüyü 7. veya 8. seviyedeki spell slot kullanarak yaptığınızda, süresi 1 yıldır. Bu büyüyü 9. seviye spell slot kullanarak yaptığınızda, büyü yukarıda bahsedilen büyülerden biri tarafından sonlandırılana kadar devam eder.","sourceText":"You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a wisdom saving throw or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can't understand you is unaffected by the spell.\n\nYou can issue any command you choose, short of an activity that would result in certain death. Should you issue a suicidal command, the spell ends.\n\nYou can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it.","higherSource":"When you cast this spell using a spell slot of 7th or 8th level, the duration is 1 year. When you cast this spell using a spell slot of 9th level, the spell lasts until it is ended by one of the spells mentioned above."},{"id":"gentle-repose","name":"Gentle Repose","nameTr":"Nazik Duruş","level":2,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"10 days","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Cesedin gözlerinin her birine bir tutam tuz ve bir bakır parçası yerleştirilir ve bu gözlerin o süre boyunca orada kalması gerekir.","materialSource":"A pinch of salt and one copper piece placed on each of the corpse's eyes, which must remain there for the duration.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir cesede veya başka kalıntılara dokunuyorsunuz. Bu süre boyunca hedef çürümeye karşı korunur ve ölümsüz olamaz.\nBüyü aynı zamanda hedefi ölümden diriltme zaman sınırını da etkili bir şekilde uzatır, çünkü bu büyünün etkisi altında geçirilen günler, ölü diriltme gibi büyülerin zaman sınırına dahil edilmez.","higher":"","sourceText":"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead.\n\nThe spell also effectively extends the time limit on raising the target from the dead, since days spent under the influence of this spell don't count against the time limit of spells such as raise dead.","higherSource":""},{"id":"giant-insect","name":"Giant Insect","nameTr":"Dev Böcek","level":4,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki en fazla on kırkayağı, üç örümceği, beş yaban arısını veya bir akrebi, bu süre boyunca doğal formlarının dev versiyonlarına dönüştürürsünüz. Bir çıyan dev bir kırkayağa, bir örümcek dev bir örümceğe, bir yaban arısı dev bir yaban arısına ve bir akrep dev bir akrebe dönüşür.\nHer yaratık sözlü komutlarınıza itaat eder ve savaşta her turda sıra size göre hareket eder. GM bu yaratıkların istatistiklerine sahiptir ve onların eylemlerini ve hareketlerini çözer.\nBir yaratık, 0 HP'ye düşene kadar veya siz onun üzerindeki etkiyi ortadan kaldırmak için bir eylem kullanana kadar dev boyutunda kalır.\nGM farklı hedefler seçmenize izin verebilir. Örneğin, bir arıyı dönüştürürseniz, onun dev versiyonu, dev bir eşekarısı ile aynı istatistiklere sahip olabilir.","higher":"","sourceText":"You transform up to ten centipedes, three spiders, five wasps, or one scorpion within range into giant versions of their natural forms for the duration. A centipede becomes a giant centipede, a spider becomes a giant spider, a wasp becomes a giant wasp, and a scorpion becomes a giant scorpion.\n\nEach creature obeys your verbal commands, and in combat, they act on your turn each round. The GM has the statistics for these creatures and resolves their actions and movement.\n\nA creature remains in its giant size for the duration, until it drops to 0 hit points, or until you use an action to dismiss the effect on it.\n\nThe GM might allow you to choose different targets. For example, if you transform a bee, its giant version might have the same statistics as a giant wasp.","higherSource":""},{"id":"glibness","name":"Glibness","nameTr":"Kolaylık","level":8,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Warlock"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"1 hour","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü bitene kadar CHA kontrolü yaptığınızda attığınız sayıyı 15 ile değiştirebilirsiniz. Ayrıca ne söylerseniz söyleyin doğruyu söyleyip söylemediğinizi belirleyecek sihir, dürüst olduğunuzu gösterir.","higher":"","sourceText":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful.","higherSource":""},{"id":"globe-of-invulnerability","name":"Globe of Invulnerability","nameTr":"Hasar Göremezlik Küresi","level":6,"school":"Abjuration","schoolTr":"Koruma","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Büyü sona erdiğinde parçalanan cam veya kristal boncuk.","materialSource":"A glass or crystal bead that shatters when the spell ends.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":10},"description":"Etrafınızdaki 10 ft yarıçapında hareketsiz, hafifçe parıldayan bir bariyer ortaya çıkıyor ve bu süre boyunca orada kalıyor.\nBariyerin dışından yapılan 5. seviye veya daha düşük herhangi bir büyü, büyü daha yüksek seviyeli bir spell slot kullanılarak yapılsa bile, içindeki yaratıkları veya nesneleri etkileyemez. Böyle bir büyü, bariyerin içindeki yaratıkları ve nesneleri hedef alabilir ancak büyünün onlar üzerinde hiçbir etkisi yoktur. Benzer şekilde bariyerin içindeki alan da bu tür büyülerden etkilenen alanların dışında bırakılır.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, bariyer 6. seviyenin üzerindeki her yuva seviyesi için bir seviye daha yüksek olan büyüleri engeller.","sourceText":"An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you and remains for the duration.\n\nAny spell of 5th level or lower cast from outside the barrier can't affect creatures or objects within it, even if the spell is cast using a higher level spell slot. Such a spell can target creatures and objects within the barrier, but the spell has no effect on them. Similarly, the area within the barrier is excluded from the areas affected by such spells.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the barrier blocks spells of one level higher for each slot level above 6th."},{"id":"glyph-of-warding","name":"Glyph of Warding","nameTr":"Koruma Glifi","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 hour","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 200 gp değerindeki tütsü ve elmas tozu.","materialSource":"Incense and powdered diamond worth at least 200 gp, which the spell consumes.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":null,"description":"Bu büyüyü yaptığınızda, diğer yaratıklara zarar veren bir glifi ya bir yüzeye (masa ya da yer ya da duvarın bir bölümü gibi) ya da glifi gizlemek için kapatılabilen bir nesnenin (kitap, parşömen ya da hazine sandığı gibi) içine yazarsınız. Bir yüzey seçerseniz glif, yüzeyin çapı 10 ft'den büyük olmayan bir alanı kapsayabilir. Bir nesneyi seçerseniz o nesnenin yerinde kalması gerekir; nesne bu büyüyü yaptığınız yerden 10 ft'den daha fazla hareket ettirilirse glif bozulur ve büyü tetiklenmeden sona erer.\nGlif neredeyse invisible'dir ve bulunması için DC yazım kaydınıza karşı başarılı bir INT (Soruşturma) kontrolü gerektirir.\nBüyüyü yaptığınızda glifi neyin tetikleyeceğine siz karar verirsiniz. Bir yüzeye yazılan glifler için en tipik tetikleyiciler arasında glifa dokunmak veya üzerinde durmak, glifi kaplayan başka bir nesneyi kaldırmak, glifin belirli bir mesafesine yaklaşmak veya üzerine glifin yazıldığı nesneyi değiştirmek yer alır. Bir nesnenin içine yazılan glifler için en yaygın tetikleyiciler arasında o nesnenin açılması, nesneye belirli bir mesafeye yaklaşmak veya glifi görmek veya okumak yer alır. Bir glif tetiklendiğinde bu büyü sona erer.\nBüyünün yalnızca belirli koşullar altında veya fiziksel özelliklere (boy veya kilo gibi), yaratık türüne (örneğin, totem sapmaları veya drowu etkileyecek şekilde ayarlanabilir) veya hizalamaya göre etkinleşeceği şekilde tetiği daha da hassaslaştırabilirsiniz. Belirli bir şifreyi söyleyenler gibi glifi tetiklemeyen yaratıklar için de koşullar ayarlayabilirsiniz.\nGlifi yazarken *patlayıcı rünleri* veya *büyü glifini* seçin.\n***Patlayıcı Rünler.*** Tetiklendiğinde, glif, glifin merkezinde bulunan bir 20 ft yarıçap küresinde sihirli enerjiyle patlar. Küre köşelere yayılıyor. Bölgedeki her canlı bir DEX saving throw yapmalıdır. Bir yaratık 5d8 acid, cold, fire, lightning veya thunder hasarı alır. başarısız bir saving throw (glifi oluştururken seçiminiz) veya başarılı olanın yarısı kadar hasar.\n***Heceleme Glifi.*** Glifi oluşturmanın bir parçası olarak hazırladığınız 3. seviye veya daha düşük bir büyüyü, onu kullanarak glifte saklayabilirsiniz. Büyü tek bir yaratığı veya bir alanı hedef almalıdır. Saklanan büyünün bu şekilde yapıldığında anında etkisi olmaz. Glif tetiklendiğinde depolanan büyü kullanılır. Büyünün bir hedefi varsa, glifi tetikleyen yaratığı hedef alır. Büyü bir bölgeyi etkiliyorsa, alan o yaratığın üzerine odaklanır. Büyü, düşman yaratıkları çağırırsa veya zararlı nesneler veya tuzaklar oluşturursa, davetsiz misafire mümkün olduğu kadar yakın görünerek ona saldırırlar. Büyü concentration gerektiriyorsa, tam süresinin sonuna kadar sürer.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, patlayıcı rün glifinin hasarı 3. seviyenin üzerindeki her yuva seviyesi için 1d8 artar. Bir büyü glifi oluşturursanız, totem glifi için kullandığınız yuvayla aynı seviyeye kadar herhangi bir büyüyü saklayabilirsiniz.","sourceText":"When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible and requires a successful Intelligence (Investigation) check against your spell save DC to be found.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends.\n\nYou can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight), creature kind (for example, the ward could be set to affect aberrations or drow), or alignment. You can also set conditions for creatures that don't trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose *explosive runes* or a *spell glyph*.\n\n***Explosive Runes.*** When triggered, the glyph erupts with magical energy in a 20-foot-radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a Dexterity saving throw. A creature takes 5d8 acid, cold, fire, lightning, or thunder damage on a failed saving throw (your choice when you create the glyph), or half as much damage on a successful one.\n\n***Spell Glyph.*** You can store a prepared spell of 3rd level or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage of an explosive runes glyph increases by 1d8 for each slot level above 3rd. If you create a spell glyph, you can store any spell of up to the same level as the slot you use for the glyph of warding."},{"id":"goodberry","name":"Goodberry","nameTr":"Çilek","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam ökse otu.","materialSource":"A sprig of mistletoe.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Elinizde en fazla on tane meyve belirir ve bu süre boyunca büyüyle aşılanır. Bir yaratık, hareketini bir meyveyi yemek için kullanabilir. Bir meyve yemek 1 can puanını yeniler ve meyve bir yaratığın bir gün boyunca ayakta kalmasına yetecek kadar besin sağlar.\nMeyveler, bu büyünün yapılmasından sonraki 24 saat içinde tüketilmezlerse etkilerini kaybederler.","higher":"","sourceText":"Up to ten berries appear in your hand and are infused with magic for the duration. A creature can use its action to eat one berry. Eating a berry restores 1 hit point, and the berry provides enough nourishment to sustain a creature for a day.\n\nThe berries lose their potency if they have not been consumed within 24 hours of the casting of this spell.","higherSource":""},{"id":"grease","name":"Grease","nameTr":"Gres","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz domuz kabuğu veya tereyağı.","materialSource":"A bit of pork rind or butter.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":{"type":"cube","size":10},"description":"Kaygan gres, menzil içindeki bir noktaya ortalanmış bir 10 ft kare şeklindeki zemini kaplar ve bu süre boyunca burayı zorlu bir araziye dönüştürür.\nYağ ortaya çıktığında, kendi bölgesinde duran her yaratığın DEX saving throw ile başarılı olması veya prone düşmesi gerekir. Bölgeye giren veya sırasını orada bitiren bir yaratığın aynı zamanda DEX saving throw ile başarılı olması veya prone düşmesi gerekir.","higher":"","sourceText":"Slick grease covers the ground in a 10-foot square centered on a point within range and turns it into difficult terrain for the duration.\n\nWhen the grease appears, each creature standing in its area must succeed on a dexterity saving throw or fall prone. A creature that enters the area or ends its turn there must also succeed on a dexterity saving throw or fall prone.","higherSource":""},{"id":"greater-invisibility","name":"Greater Invisibility","nameTr":"Daha Fazla Görünmezlik","level":4,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Siz veya dokunduğunuz bir yaratık, büyü bitene kadar invisible olur. Hedefin giydiği veya taşıdığı her şey, hedefin üzerinde olduğu sürece invisible'dir.","higher":"","sourceText":"You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person.","higherSource":""},{"id":"greater-restoration","name":"Greater Restoration","nameTr":"Daha Büyük Restorasyon","level":5,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Druid"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 100gp değerindeki elmas tozu.","materialSource":"Diamond dust worth at least 100gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Zayıflatıcı bir etkiyi ortadan kaldırmak için dokunduğunuz bir yaratığa pozitif enerji aşılarsınız. Hedefin exhaustion seviyesini bir birim azaltabilir veya hedef üzerinde aşağıdaki etkilerden birini sonlandırabilirsiniz:\n- Hedefin charmed veya petrified olmasını sağlayan bir efekt\n- Hedefin lanetli bir büyülü eşyaya uyumlanması da dahil olmak üzere bir lanet\n- Hedefin yetenek puanlarından birinde herhangi bir azalma\n- Hedefin maksimum can puanını azaltan bir etki","higher":"","sourceText":"You imbue a creature you touch with positive energy to undo a debilitating effect. You can reduce the target's exhaustion level by one, or end one of the following effects on the target:\n\n- One effect that charmed or petrified the target\n\n- One curse, including the target's attunement to a cursed magic item\n\n- Any reduction to one of the target's ability scores\n\n- One effect reducing the target's hit point maximum","higherSource":""},{"id":"guardian-of-faith","name":"Guardian of Faith","nameTr":"İnancın Koruyucusu","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"8 hours","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"cylinder","size":10},"description":"Büyük bir spektral koruyucu belirir ve menzil içinde görebileceğiniz, seçtiğiniz boş bir alanda bir süre boyunca havada asılı kalır. Koruyucu bu alanı işgal eder ve tanrınızın sembolüyle süslenmiş parlak bir kılıç ve kalkan dışında belirsizdir.\nBir turda ilk kez koruyucunun 10 ft içindeki bir alana hareket eden, size düşman olan herhangi bir yaratık, DEX saving throw'de başarılı olmalıdır. Yaratık, başarısız save’de 20 radiant hasar alır, başarılı save’de ise bunun yarısı kadar hasar alır. Muhafız toplam 60 hasar verdiğinde ortadan kaybolur.","higher":"","sourceText":"A Large spectral guardian appears and hovers for the duration in an unoccupied space of your choice that you can see within range. The guardian occupies that space and is indistinct except for a gleaming sword and shield emblazoned with the symbol of your deity.\n\nAny creature hostile to you that moves to a space within 10 feet of the guardian for the first time on a turn must succeed on a dexterity saving throw. The creature takes 20 radiant damage on a failed save, or half as much damage on a successful one. The guardian vanishes when it has dealt a total of 60 damage.","higherSource":""},{"id":"guards-and-wards","name":"Guards and Wards","nameTr":"Muhafızlar ve Koğuşlar","level":6,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Touch","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Yanan tütsü, az miktarda kükürt ve yağ, düğümlü bir ip, az miktarda koyu renkli hulk kanı ve en az 10 gp değerinde küçük bir gümüş çubuk.","materialSource":"Burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":2500},"description":"2.500 ft²ye kadar taban alanını (bir 50 ft karesi veya yüz 5 ft karesi veya yirmi beş 10 ft karesi) koruyan bir koğuş oluşturursunuz. Korumalı alan 20 ft uzunluğa kadar olabilir ve istediğiniz şekilde şekillendirilebilir. Büyüyü yaparken bitişik alanların her birine girebildiğiniz sürece, alanı aralarında bölerek bir kalenin birkaç katını koruyabilirsiniz.\nBu büyüyü yaptığınızda, seçtiğiniz efektlerin herhangi birinden veya tümünden etkilenmeyen kişileri belirleyebilirsiniz. Ayrıca, yüksek sesle söylendiğinde konuşmacının bu etkilere karşı bağışık olmasını sağlayacak bir parola da belirleyebilirsiniz.\nMuhafızlar ve koğuşlar, totem alanı içerisinde aşağıdaki etkileri yaratır.\n***Koridorlar.*** Sis, muhafazalı koridorların tamamını dolduruyor ve onları büyük oranda karartıyor. Ayrıca yön seçeneği sunan her kesişme veya dallanma geçişinde, sizin dışınızda bir canlının, seçtiği yönün tersi yönde gittiğine inanma ihtimali yüzde 50'dir.\n***Kapılar.*** Korunan bölgedeki tüm kapılar sanki gizemli bir kilitleme büyüsüyle mühürlenmiş gibi sihirli bir şekilde kilitlenir. Ek olarak, on adede kadar kapıyı bir illüzyonla (küçük illüzyon büyüsünün yanıltıcı nesne işlevine eşdeğer) kaplayarak bunların duvarın düz bölümleri gibi görünmesini sağlayabilirsiniz.\n***Merdivenler.*** Ağlar, ağın büyüsü gibi, muhafazalı alandaki tüm merdivenleri yukarıdan aşağıya doğru dolduruyor. Bu teller, korumalar ve muhafazalar devam ederken yakılırsa veya koparılırsa 10 dakika içinde yeniden büyür.\n***Diğer Büyü Etkileri.*** Aşağıdaki büyülü efektlerden birini kalenin korunan alanına yerleştirebilirsiniz.\n- Dört koridora dans ışıkları yerleştirin. Güvenlik görevlileri ve koğuşlar devam ettiği sürece ışıkların tekrar edeceği basit bir program belirleyebilirsiniz.\n- Sihirli ağzı iki yere yerleştirin.\n- Kokuşmuş bulutu iki yere yerleştirin. Belirlediğiniz yerlerde buharlar çıkıyor; Muhafızlar ve koğuşlar devam ederken rüzgarla dağılırlarsa 10 dakika içinde geri dönerler.\n- Bir koridora veya odaya sürekli kuvvetli rüzgar verin.\n- Bir öneriyi tek bir yere yerleştirin. 5 ft kareye kadar bir alan seçersiniz ve bu alana giren veya bu alandan geçen her canlı bu öneriyi zihinsel olarak alır.\nMuhafaza edilen alanın tamamı büyü yayıyor. Belirli bir efekt üzerinde yapılan etkisizleştirme büyüsü başarılı olursa yalnızca o etkiyi ortadan kaldırır.\nBu büyüyü bir yıl boyunca her gün orada yaparak kalıcı olarak korunan ve korunan bir yapı oluşturabilirsiniz.","higher":"","sourceText":"You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell.\n\nWhen you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects.\n\nGuards and wards creates the following effects within the warded area.\n\n***Corridors.*** Fog fills all the warded corridors, making them heavily obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you will believe it is going in the opposite direction from the one it chooses.\n\n***Doors.*** All doors in the warded area are magically locked, as if sealed by an arcane lock spell. In addition, you can cover up to ten doors with an illusion (equivalent to the illusory object function of the minor illusion spell) to make them appear as plain sections of wall.\n\n***Stairs.*** Webs fill all stairs in the warded area from top to bottom, as the web spell. These strands regrow in 10 minutes if they are burned or torn away while guards and wards lasts.\n\n***Other Spell Effect.*** You can place your choice of one of the following magical effects within the warded area of the stronghold.\n\n- Place dancing lights in four corridors. You can designate a simple program that the lights repeat as long as guards and wards lasts.\n\n- Place magic mouth in two locations.\n\n- Place stinking cloud in two locations. The vapors appear in the places you designate; they return within 10 minutes if dispersed by wind while guards and wards lasts.\n\n- Place a constant gust of wind in one corridor or room.\n\n- Place a suggestion in one location. You select an area of up to 5 feet square, and any creature that enters or passes through the area receives the suggestion mentally.\n\nThe whole warded area radiates magic. A dispel magic cast on a specific effect, if successful, removes only that effect.\n\nYou can create a permanently guarded and warded structure by casting this spell there every day for one year.","higherSource":""},{"id":"guidance","name":"Guidance","nameTr":"Rehberlik","level":0,"school":"Divination","schoolTr":"Kehanet","classes":["Cleric","Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunuyorsun. Büyü sona ermeden önce, hedef bir d4 atabilir ve atılan sayıyı kendi seçtiği bir ability check'ye ekleyebilir. ability check'yi yapmadan önce veya sonra kalıbı yuvarlayabilir. Büyü daha sonra sona erer.","higher":"","sourceText":"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one ability check of its choice. It can roll the die before or after making the ability check. The spell then ends.","higherSource":""},{"id":"guiding-bolt","name":"Guiding Bolt","nameTr":"Kılavuz Cıvata","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki seçtiğiniz bir yaratığa doğru bir ışık parıltısı parlıyor. Hedefe karşı bir menzilli spell attack yapın. Bir vuruşta hedef 4d6 radiant hasarı alır ve bir sonraki turunuzun bitiminden önce bu hedefe karşı yapılan bir sonraki saldırı zarı, o zamana kadar hedefin üzerinde parıldayan mistik loş ışık sayesinde avantaj'ye sahip olur.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 1. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"A flash of light streaks toward a creature of your choice within range. Make a ranged spell attack against the target. On a hit, the target takes 4d6 radiant damage, and the next attack roll made against this target before the end of your next turn has advantage, thanks to the mystical dim light glittering on the target until then.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."},{"id":"gust-of-wind","name":"Gust of Wind","nameTr":"Rüzgarın esintisi","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir baklagil tohumu.","materialSource":"A legume seed.","attackType":"","save":"STR","saves":["STR"],"saveSuccess":"none","area":{"type":"line","size":60},"description":"60 ft uzunluğunda ve 10 ft genişliğinde güçlü bir rüzgar çizgisi, büyünün süresi boyunca seçtiğiniz bir yöne doğru sizden esiyor. Sırada sırasına başlayan her yaratık bir STR saving throw üzerinde başarılı olmalı veya 15 ft çizgiyi takip eden bir yönde sizden uzağa itilmelidir.\nSıradaki herhangi bir yaratık, size yaklaşırken hareket ettiği her 1 ft için 2 ft hareket harcamalıdır.\nRüzgar gaz veya buharı dağıtarak bölgedeki mumları, meşaleleri ve benzeri korunmasız alevleri söndürür. Fenerler gibi korunan alevlerin çılgınca dans etmesine neden olur ve onları söndürme şansı yüzde 50'dir.\nBonus Action olarak, büyü sona ermeden her turunuzda, hattın sizden fırladığı yönü değiştirebilirsiniz.","higher":"","sourceText":"A line of strong wind 60 feet long and 10 feet wide blasts from you in a direction you choose for the spell's duration. Each creature that starts its turn in the line must succeed on a strength saving throw or be pushed 15 feet away from you in a direction following the line.\n\nAny creature in the line must spend 2 feet of movement for every 1 foot it moves when moving closer to you.\n\nThe gust disperses gas or vapor, and it extinguishes candles, torches, and similar unprotected flames in the area. It causes protected flames, such as those of lanterns, to dance wildly and has a 50 percent chance to extinguish them.\n\nAs a bonus action on each of your turns before the spell ends, you can change the direction in which the line blasts from you.","higherSource":""},{"id":"hallow","name":"Hallow","nameTr":"kutsal","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Fiend"],"castingTime":"24 hours","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 1.000 gp değerindeki otlar, yağlar ve tütsü.","materialSource":"Herbs, oils, and incense worth at least 1,000 gp, which the spell consumes.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":{"type":"sphere","size":60},"description":"Bir noktaya dokunursunuz ve etrafındaki alana kutsal (veya kutsal olmayan) güç aşılarsınız. Alanın yarıçapı 60 ft'ye kadar olabilir ve eğer yarıçap halihazırda bir kutsal büyünün etkisi altındaki bir alanı içeriyorsa büyü başarısız olur. Etkilenen bölge aşağıdaki etkilere maruz kalır.\nBirincisi, göksel varlıklar, elementaller, periler, iblisler ve ölümsüzler bölgeye giremez ve bu tür yaratıklar, içindeki yaratıkları büyüleyemez, korkutamaz veya ele geçiremez. charmed, frightened veya böyle bir yaratığın ele geçirdiği yaratıklar artık charmed, frightened veya bölgeye girildiğinde ele geçirilmiyor. Bu tür yaratıklardan bir veya daha fazlasını bu etkinin dışında bırakabilirsiniz.\nİkinci olarak bölgeye ekstra bir efekt bağlayabilirsiniz. Aşağıdaki listeden efekti seçin veya GM tarafından sunulan bir efekti seçin. Bu etkilerin bazıları bölgedeki canlılar için geçerlidir; Efektin tüm canlılar, belirli bir tanrıyı veya lideri takip eden yaratıklar veya cevherler veya troller gibi belirli bir türdeki yaratıklar için geçerli olup olmayacağını belirleyebilirsiniz. Etkilenecek bir yaratık bir turda büyü alanına ilk kez girdiğinde veya dönüşüne orada başladığında, CHA saving throw yapabilir. Başarılı olunduğunda yaratık, bölgeyi terk edene kadar ekstra etkiyi görmezden gelir.\n***Cesaret.*** Etkilenen yaratıklar bölgedeyken frightened olamaz.\n***Karanlık.*** Karanlık alanı dolduruyor. Normal ışık ve bu büyüyü yapmak için kullandığınız yuvadan daha düşük seviyedeki büyülerin yarattığı büyülü ışık, alanı aydınlatamaz.\n***Gün ışığı.*** Alanı parlak ışık dolduruyor. Bu büyüyü yapmak için kullandığınız yuvadan daha düşük seviyedeki büyülerin yarattığı büyülü karanlık, ışığı söndüremez.\n***Enerji Koruması.*** Bölgedeki etkilenen yaratıklar, bludgeoning, piercing veya slashing hariç, seçtiğiniz bir hasar türüne karşı dirence sahiptir.\n***Enerji Güvenlik Açığı.*** Bölgedeki etkilenen yaratıklar, bludgeoning, piercing veya slashing hariç, seçtiğiniz bir hasar türüne karşı güvenlik açığına sahiptir.\n***Sonsuz Dinlenme.*** Bölgeye defnedilen cesetler ölümsüz hale getirilemez.\n***Boyut Dışı Müdahale.*** Etkilenen yaratıklar ışınlanma veya boyut dışı ya da düzlemler arası yollarla hareket edemez veya seyahat edemez.\n***Korku.*** Bölgedeyken etkilenen yaratıklar frightened'dir.\n***Sessizlik.*** Alanın içinden hiçbir ses çıkamaz ve hiçbir ses oraya ulaşamaz.\n***Diller.*** Etkilenen canlılar, ortak bir dili paylaşmasalar bile bölgedeki diğer canlılarla iletişim kurabilir.","higher":"","sourceText":"You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect a hallow spell. The affected area is subject to the following effects.\n\nFirst, celestials, elementals, fey, fiends, and undead can't enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect.\n\nSecond, you can bind an extra effect to the area. Choose the effect from the following list, or choose an effect offered by the GM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as ores or trolls. When a creature that would be affected enters the spell's area for the first time on a turn or starts its turn there, it can make a charisma saving throw. On a success, the creature ignores the extra effect until it leaves the area.\n\n***Courage.*** Affected creatures can't be frightened while in the area.\n\n***Darkness.*** Darkness fills the area. Normal light, as well as magical light created by spells of a lower level than the slot you used to cast this spell, can't illuminate the area.\n\n***Daylight.*** Bright light fills the area. Magical darkness created by spells of a lower level than the slot you used to cast this spell can't extinguish the light.\n\n***Energy Protection.*** Affected creatures in the area have resistance to one damage type of your choice, except for bludgeoning, piercing, or slashing.\n\n***Energy Vulnerability.*** Affected creatures in the area have vulnerability to one damage type of your choice, except for bludgeoning, piercing, or slashing.\n\n***Everlasting Rest.*** Dead bodies interred in the area can't be turned into undead.\n\n***Extradimensional Interference.*** Affected creatures can't move or travel using teleportation or by extradimensional or interplanar means.\n\n***Fear.*** Affected creatures are frightened while in the area.\n\n***Silence.*** No sound can emanate from within the area, and no sound can reach into it.\n\n***Tongues.*** Affected creatures can communicate with any other creature in the area, even if they don't share a common language.","higherSource":""},{"id":"hallucinatory-terrain","name":"Hallucinatory Terrain","nameTr":"Halüsinasyonlu Arazi","level":4,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Druid","Warlock","Wizard"],"subclasses":["Land"],"castingTime":"10 minutes","range":"300 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir taş, bir dal ve bir parça yeşil bitki.","materialSource":"A stone, a twig, and a bit of green plant.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":150},"description":"150 ft küpte doğal araziyi, başka türdeki doğal araziler gibi menzilli görünüm, ses ve kokuya sahip hale getirirsiniz. Böylece, açık alanlar veya bir yol, bir bataklığa, tepeye, yarığa veya başka zor veya geçilmez araziye benzeyecek şekilde yapılabilir. Bir gölet çimenli bir çayır gibi, bir uçurum hafif bir eğim gibi veya kayalarla kaplı bir oluk geniş ve pürüzsüz bir yol gibi görünebilir. Bölgedeki üretilen yapıların, ekipmanların ve yaratıkların görünümü değişmedi.\nArazinin dokunsal özellikleri değişmediğinden, bölgeye giren yaratıkların illüzyonun arkasını görmesi muhtemeldir. Fark dokunarak açıkça görülemiyorsa, illüzyonu dikkatlice inceleyen bir yaratık, buna inanmamak için DC'yi kurtaran büyünüze karşı INT (Soruşturma) kontrolü yapmaya çalışabilir. Yanılsamanın ne olduğunu fark eden bir yaratık, onu araziye yerleştirilmiş belirsiz bir görüntü olarak görür.","higher":"","sourceText":"You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren't changed in appearance.\n\nThe tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn't obvious by touch, a creature carefully examining the illusion can attempt an Intelligence (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is, sees it as a vague image superimposed on the terrain.","higherSource":""},{"id":"harm","name":"Harm","nameTr":"zarar","level":6,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":null,"description":"Menzil içinde görebileceğiniz bir yaratığın üzerine öldürücü bir hastalık salıyorsunuz. Hedefin bir CON saving throw yapması gerekir. Başarısız bir kaydetmede 14d6 necrotic hasar alır veya başarılı bir kaydetmenin yarısı kadar hasar alır. Hasar, hedefin HP'sini 1'in altına düşüremez. Hedef saving throw'yi geçemezse, maksimum can puanı, aldığı necrotic hasarına eşit miktarda 1 saat boyunca azaltılır. Bir hastalığı ortadan kaldıran herhangi bir etki, yaratığın maksimum can puanının bu süre geçmeden normale dönmesine olanak tanır.","higher":"","sourceText":"You unleash a virulent disease on a creature that you can see within range. The target must make a constitution saving throw. On a failed save, it takes 14d6 necrotic damage, or half as much damage on a successful save. The damage can't reduce the target's hit points below 1. If the target fails the saving throw, its hit point maximum is reduced for 1 hour by an amount equal to the necrotic damage it took. Any effect that removes a disease allows a creature's hit point maximum to return to normal before that time passes.","higherSource":""},{"id":"haste","name":"Haste","nameTr":"Acele et","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Meyan kökü tıraşı.","materialSource":"A shaving of licorice root.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz istekli bir yaratık seçin. Büyü bitene kadar hedefin hızı iki katına çıkar, AC'ye +2 bonus kazanır, DEX saving throw’lar üzerinde avantaj'ye sahiptir ve her turunda ek bir eylem kazanır. Bu eylem yalnızca Saldırı (yalnızca bir silah saldırısı), Atılma, Devre Dışı Bırakma, Gizleme veya Bir Nesne Kullanma eylemini gerçekleştirmek için kullanılabilir.\nBüyü sona erdiğinde, hedef bir uyuşukluk dalgasının üzerinden geçtiği için bir sonraki turuna kadar hareket edemez veya harekete geçemez.","higher":"","sourceText":"Choose a willing creature that you can see within range. Until the spell ends, the target's speed is doubled, it gains a +2 bonus to AC, it has advantage on dexterity saving throws, and it gains an additional action on each of its turns. That action can be used only to take the Attack (one weapon attack only), Dash, Disengage, Hide, or Use an Object action.\n\nWhen the spell ends, the target can't move or take actions until after its next turn, as a wave of lethargy sweeps over it.","higherSource":""},{"id":"heal","name":"Heal","nameTr":"İyileşmek","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric","Druid"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir yaratık seçin. Yaratığın içinden bir pozitif enerji dalgası yayılır ve yaratığın 70 HP geri kazanmasına neden olur. Bu büyü aynı zamanda körlüğü, sağırlığı ve hedefi etkileyen hastalıkları da ortadan kaldırır. Bu büyünün yapılar veya ölümsüzler üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, iyileştirme miktarı 6. seviyenin üzerindeki her yuva seviyesi için 10 artar.","sourceText":"Choose a creature that you can see within range. A surge of positive energy washes through the creature, causing it to regain 70 hit points. This spell also ends blindness, deafness, and any diseases affecting the target. This spell has no effect on constructs or undead.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the amount of healing increases by 10 for each slot level above 6th."},{"id":"healing-word","name":"Healing Word","nameTr":"Şifalı Kelime","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Cleric","Druid"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz seçtiğiniz bir yaratık, 1d4 + büyü yapma yeteneği değiştiricinize eşit HP'yi yeniden kazanır. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, iyileştirme 1. seviyenin üzerindeki her slot seviyesi için 1d4 artar.","sourceText":"A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the healing increases by 1d4 for each slot level above 1st."},{"id":"heat-metal","name":"Heat Metal","nameTr":"Isı Metali","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir parça demir ve bir alev.","materialSource":"A piece of iron and a flame.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"other","area":null,"description":"Menzil içinde görebileceğiniz, metal bir silah veya ağır veya orta metal zırh gibi üretilmiş bir metal nesne seçin. Nesnenin kırmızı-sıcak bir şekilde parlamasına neden olursunuz. Büyüyü yaptığınızda, nesneyle fiziksel temas halinde olan herhangi bir yaratık 2d8 fire hasarı alır. Büyü sona erene kadar sonraki turlarınızın her birinde Bonus Action kullanarak bu hasarı tekrar verebilirsiniz.\nBir yaratık nesneyi tutuyor veya taşıyorsa ve ondan hasar alıyorsa, yaratık bir CON saving throw üzerinde başarılı olmalı veya yapabiliyorsa nesneyi bırakmalıdır. Nesneyi düşürmezse, saldırı atışlarında dezavantaj ve bir sonraki turunuzun başlangıcına kadar ability check’ler olur.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 2. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"Choose a manufactured metal object, such as a metal weapon or a suit of heavy or medium metal armor, that you can see within range. You cause the object to glow red-hot. Any creature in physical contact with the object takes 2d8 fire damage when you cast the spell. Until the spell ends, you can use a bonus action on each of your subsequent turns to cause this damage again.\n\nIf a creature is holding or wearing the object and takes the damage from it, the creature must succeed on a constitution saving throw or drop the object if it can. If it doesn't drop the object, it has disadvantage on attack rolls and ability checks until the start of your next turn.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."},{"id":"hellish-rebuke","name":"Hellish Rebuke","nameTr":"Cehennem Azarlaması","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Warlock"],"subclasses":[],"castingTime":"1 reaction","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":null,"description":"Parmağınızı işaret ediyorsunuz ve size zarar veren yaratık bir an için cehennem alevleriyle çevreleniyor. Yaratığın bir DEX saving throw yapması gerekir. başarısız save’de 2d10 fire hasar alır veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 1. seviyenin üzerindeki her yuva seviyesi için 1d10 artar.","sourceText":"You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."},{"id":"heroes-feast","name":"Heroes' Feast","nameTr":"Kahramanların Bayramı","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Druid"],"subclasses":[],"castingTime":"10 minutes","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 1.000 gp değerinde mücevherlerle kaplı bir kase.","materialSource":"A gem-encrusted bowl worth at least 1,000gp, which the spell consumes.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Muhteşem yiyecek ve içeceklerin de dahil olduğu harika bir ziyafet sunuyorsunuz. Ziyafetin tüketilmesi 1 saat sürer ve bu sürenin sonunda kaybolur ve bu saat bitene kadar faydalı etkileri ortaya çıkmaz. Ziyafete en fazla on iki canlı daha katılabilir.\nZiyafete katılan canlı, pek çok fayda elde eder. Yaratık tüm hastalıklardan iyileşir ve poison, poison'ye karşı bağışıklık kazanır ve frightened olur ve tüm WIS saving throw’lar'yi yapar. avantaj. Maksimum can puanı da 2d10 kadar artar ve aynı sayıda HP kazanır. Bu avantajlar 24 saat sürer.","higher":"","sourceText":"You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don't set in until this hour is over. Up to twelve other creatures can partake of the feast.\n\nA creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all wisdom saving throws with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours.","higherSource":""},{"id":"heroism","name":"Heroism","nameTr":"Kahramanlık","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Paladin"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz istekli bir yaratık cesaretle doludur. Büyü sona erene kadar yaratık, frightened olmaya karşı bağışıklıdır ve her turun başında büyü yapma yeteneği değiştiricinize eşit geçici HP kazanır. Büyü sona erdiğinde hedef, bu büyüden kalan geçici HP'yi kaybeder.","higher":"","sourceText":"A willing creature you touch is imbued with bravery. Until the spell ends, the creature is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. When the spell ends, the target loses any remaining temporary hit points from this spell.","higherSource":""},{"id":"hideous-laughter","name":"Hideous Laughter","nameTr":"İğrenç Kahkaha","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Minik turtalar ve havada sallanan bir tüy.","materialSource":"Tiny tarts and a feather that is waved in the air.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz seçeceğiniz bir yaratık, her şeyi çok komik algılar ve bu büyü onu etkilediğinde gülme krizine girer. Hedef, WIS saving throw ile başarılı olmalı veya prone düşerek incapacitated haline gelmeli ve bu süre boyunca ayağa kalkamaz. INT puanı 4 veya daha az olan bir yaratık etkilenmez.\nHer turun sonunda ve her hasar aldığında, hedef başka bir WIS saving throw yapabilir. Hedefin hasarla tetiklenmesi durumunda saving throw üzerinde avantaj vardı. Başarılı olunduğunda büyü sona erer.","higher":"","sourceText":"A creature of your choice that you can see within range perceives everything as hilariously funny and falls into fits of laughter if this spell affects it. The target must succeed on a wisdom saving throw or fall prone, becoming incapacitated and unable to stand up for the duration. A creature with an Intelligence score of 4 or less isn't affected.\n\nAt the end of each of its turns, and each time it takes damage, the target can make another wisdom saving throw. The target had advantage on the saving throw if it's triggered by damage. On a success, the spell ends.","higherSource":""},{"id":"hold-monster","name":"Hold Monster","nameTr":"Canavarı Tut","level":5,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"90 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir demir parçası.","materialSource":"A small piece of iron.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Görebileceğiniz ve ulaşabileceğiniz bir canlı seçin. Hedef, büyü süresi boyunca saving throw veya WIS yapmalı veya paralyzed olmalıdır. Bu büyünün ölümsüzlere karşı hiçbir etkisi yoktur. Her turun sonunda hedef, WIS'den yeni bir saving throw yapabilir. Başarılı olursa büyü yaratık için sona erer.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir konumu kullanarak yaptığınızda, beşinci seviyenin ötesindeki her seviye için ek bir yaratığı hedefleyebilirsiniz. Yaratıkları hedeflediğinizde birbirlerinin 30 ft yakınında olmalıdır.","sourceText":"Choose a creature you can see and reach. The target must make a saving throw of Wisdom or be paralyzed for the duration of the spell. This spell has no effect against the undead. At the end of each round, the target can make a new saving throw of Wisdom. If successful, the spell ends for the creature.","higherSource":"When you cast this spell using a level 6 or higher location, you can target an additional creature for each level of location beyond the fifth. The creatures must be within 30 feet o f each other when you target them."},{"id":"hold-person","name":"Hold Person","nameTr":"Kişiyi Tut","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük, düz bir demir parçası.","materialSource":"A small, straight piece of iron.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebileceğiniz bir insansı seçin. Hedef, bu süre boyunca bir WIS saving throw üzerinde başarılı olmalı veya paralyzed olmalıdır. Her turun sonunda hedef başka bir WIS saving throw yapabilir. Başarı durumunda büyü hedefte sona erer.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 2. seviyenin üzerindeki her yuva seviyesi için ek bir insansı hedefleyebilirsiniz. İnsansıları hedeflediğinizde birbirlerinden 30 ft uzaklıkta olmalıdır.","sourceText":"Choose a humanoid that you can see within range. The target must succeed on a wisdom saving throw or be paralyzed for the duration. At the end of each of its turns, the target can make another wisdom saving throw. On a success, the spell ends on the target.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional humanoid for each slot level above 2nd. The humanoids must be within 30 feet of each other when you target them."},{"id":"holy-aura","name":"Holy Aura","nameTr":"Kutsal Aura","level":8,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir azizin cübbesinden bir kumaş parçası veya dini bir metinden bir parşömen parçası gibi kutsal bir emanet içeren, en az 1.000 gp değerinde küçük bir kutsal emanet.","materialSource":"A tiny reliquary worth at least 1,000gp containing a sacred relic, such as a scrap of cloth from a saint's robe or a piece of parchment from a religious text.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"İlahi ışık sizden akıp gidiyor ve etrafınızdaki 30 ft yarıçapında yumuşak bir ışıltı halinde birleşiyor. Bu büyüyü yaptığınızda o yarıçaptaki seçtiğiniz yaratıklar, 5 ft yarıçapında loş bir ışık saçarlar ve tüm saving throw’lar'de avantaj'ye sahiptirler ve diğer yaratıklar, büyü bitene kadar onlara karşı saldırı atışlarında dezavantaj'ye sahiptir. Buna ek olarak, bir iblis ya da ölümsüz, etkilenen bir yaratığa yakın dövüş saldırısıyla vurduğunda, aura parlak bir ışıkla yanıp söner. Saldırganın, büyü bitene kadar CON saving throw üzerinde başarılı olması veya blinded olması gerekir.","higher":"","sourceText":"Divine light washes out from you and coalesces in a soft radiance in a 30-foot radius around you. Creatures of your choice in that radius when you cast this spell shed dim light in a 5-foot radius and have advantage on all saving throws, and other creatures have disadvantage on attack rolls against them until the spell ends. In addition, when a fiend or an undead hits an affected creature with a melee attack, the aura flashes with brilliant light. The attacker must succeed on a constitution saving throw or be blinded until the spell ends.","higherSource":""},{"id":"hunters-mark","name":"Hunter's Mark","nameTr":"Avcı İşareti","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Ranger"],"subclasses":[],"castingTime":"1 bonus action","range":"90 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir yaratığı seçersiniz ve onu mistik bir şekilde avınız olarak işaretlersiniz. Büyü sona erene kadar, hedefe silah saldırısı ile vurduğunuzda ekstra 1d6 hasarı verirsiniz ve herhangi bir WIS (Algı) veya WIS üzerinde avantaj'ye sahip olursunuz. (Hayatta kalma) onu bulmak için yaptığınız kontrolü yapın. Bu büyü sona ermeden hedef 0 HP'ye düşerse, sonraki turunuzda yeni bir yaratığı işaretlemek için Bonus Action kullanabilirsiniz.","higher":"Bu büyüyü 3. veya 4. seviyedeki spell slot kullanarak yaptığınızda, concentration'nizi 8 saate kadar büyünün üzerinde tutabilirsiniz. 5. seviye veya daha yüksek bir spell slot kullandığınızda, concentration'nizi 24 saate kadar büyüde tutabilirsiniz.","sourceText":"You choose a creature you can see within range and mystically mark it as your quarry. Until the spell ends, you deal an extra 1d6 damage to the target whenever you hit it with a weapon attack, and you have advantage on any Wisdom (Perception) or Wisdom (Survival) check you make to find it. If the target drops to 0 hit points before this spell ends, you can use a bonus action on a subsequent turn of yours to mark a new creature.","higherSource":"When you cast this spell using a spell slot of 3rd or 4th level, you can maintain your concentration on the spell for up to 8 hours. When you use a spell slot of 5th level or higher, you can maintain your concentration on the spell for up to 24 hours."},{"id":"hypnotic-pattern","name":"Hypnotic Pattern","nameTr":"Hipnotik Desen","level":3,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["S","M"],"materialTr":"Parlayan bir tütsü çubuğu veya fosforlu malzemeyle dolu kristal bir şişe.","materialSource":"A glowing stick of incense or a crystal vial filled with phosphorescent material.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzil içindeki 30 ft küpün içindeki havada dolaşan renklerden oluşan bükümlü bir desen yaratırsınız. Desen bir anlığına beliriyor ve kayboluyor. Bölgedeki deseni gören her canlının bir WIS saving throw yapması gerekir. Başarısız bir kaydetme durumunda yaratık, bu süre boyunca charmed olur. Bu büyü ile charmed iken yaratık incapacitated olup hızı 0'dır.\nBüyü, etkilenen yaratık için herhangi bir hasar alırsa veya başka biri yaratığı sersemliğinden kurtarmak için bir hareket kullanırsa sona erer.","higher":"","sourceText":"You create a twisting pattern of colors that weaves through the air inside a 30-foot cube within range. The pattern appears for a moment and vanishes. Each creature in the area who sees the pattern must make a wisdom saving throw. On a failed save, the creature becomes charmed for the duration. While charmed by this spell, the creature is incapacitated and has a speed of 0.\n\nThe spell ends for an affected creature if it takes any damage or if someone else uses an action to shake the creature out of its stupor.","higherSource":""},{"id":"ice-storm","name":"Ice Storm","nameTr":"Buz Fırtınası","level":4,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"300 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam toz ve birkaç damla su.","materialSource":"A pinch of dust and a few drops of water.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"cylinder","size":20},"description":"Menzil dahilindeki bir noktaya ortalanmış bir 20 ft yarıçap, 40 ft yükseklik silindirinde kaya gibi sert buz kütlelerinden oluşan bir dolu. Silindirdeki her yaratık bir DEX saving throw yapmalıdır. Bir yaratık, başarısız save’de 2d8 bludgeoning hasarı ve 4d6 cold hasarı veya başarılı save’de yarısı kadar hasar alır.\nDolu taşları, fırtınanın etki alanını bir sonraki turunuzun sonuna kadar zorlu bir araziye dönüştürür.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, bludgeoning hasarı 4. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"A hail of rock-hard ice pounds to the ground in a 20-foot-radius, 40-foot-high cylinder centered on a point within range. Each creature in the cylinder must make a dexterity saving throw. A creature takes 2d8 bludgeoning damage and 4d6 cold damage on a failed save, or half as much damage on a successful one.\n\nHailstones turn the storm's area of effect into difficult terrain until the end of your next turn.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, the bludgeoning damage increases by 1d8 for each slot level above 4th."},{"id":"identify","name":"Identify","nameTr":"Tanımla","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"En az 100gp değerinde bir inci ve bir baykuş tüyü.","materialSource":"A pearl worth at least 100gp and an owl feather.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyüyü yaparken dokunmanız gereken bir nesneyi seçersiniz. Eğer bu sihirli bir eşya ya da sihirle dolu başka bir nesne ise, onun özelliklerini ve nasıl kullanılacağını, kullanmak için uyum gerektirip gerektirmediğini ve varsa kaç şarja sahip olduğunu öğrenirsiniz. Herhangi bir büyünün eşyayı etkileyip etkilemediğini ve bunların ne olduğunu öğrenirsiniz. Öğe bir büyü tarafından yaratıldıysa, onu hangi büyünün yarattığını öğrenirsiniz.\nBunun yerine, oyuncu seçimi sırasında bir yaratığa dokunursanız, o anda onu hangi büyülerin (varsa) etkilediğini öğrenirsiniz.","higher":"","sourceText":"You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it.\n\nIf you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it.","higherSource":""},{"id":"illusory-script","name":"Illusory Script","nameTr":"Hayali Senaryo","level":1,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"Touch","duration":"10 days","concentration":false,"ritual":true,"components":["S","M"],"materialTr":"Bu büyünün tükettiği, en az 10gp değerinde kurşun bazlı mürekkep.","materialSource":"A lead-based ink worth at least 10gp, which this spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Parşömen, kağıt veya başka uygun bir yazı malzemesi üzerine yazarsınız ve onu, süre boyunca süren güçlü bir yanılsama ile doldurursunuz.\nBüyüyü yaparken size ve belirlediğiniz yaratıklara, yazı normal görünür, elinizde yazılmış ve metni yazarken amaçladığınız anlamı taşır. Diğerlerine göre yazı sanki bilinmeyen ya da anlaşılmaz sihirli bir yazıyla yazılmış gibi görünüyor. Alternatif olarak, yazının tamamen farklı bir mesaj gibi görünmesini, farklı bir el ve dilde yazılmış gibi görünmesini de sağlayabilirsiniz; ancak bu dilin bildiğiniz bir dil olması gerekir.\nBüyü bozulursa hem orijinal senaryo hem de illüzyon ortadan kalkar.\nGerçek görüşe sahip bir yaratık gizli mesajı okuyabilir.","higher":"","sourceText":"You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.\n\nTo you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.\n\nShould the spell be dispelled, the original script and the illusion both disappear.\n\nA creature with truesight can read the hidden message.","higherSource":""},{"id":"imprisonment","name":"Imprisonment","nameTr":"hapis","level":9,"school":"Abjuration","schoolTr":"Koruma","classes":["Warlock","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Hedefe benzeyen bir parşömen tasviri veya oyulmuş bir heykelcik ve hedefin Hit Die başına en az 500gp değerinde, seçtiğiniz büyünün versiyonuna göre değişen özel bir bileşen.","materialSource":"A vellum depiction or a carved statuette in the likeness of the target, and a special component that varies according to the version of the spell you choose, worth at least 500gp per Hit Die of the target.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzil içinde görebildiğiniz bir yaratığı tutmak için sihirli bir sınırlama yaratırsınız. Hedef bir WIS saving throw üzerinde başarılı olmalı veya büyüye bağlı olmalıdır; Başarılı olursa, tekrar yaptığınızda bu büyüye karşı bağışıklı olur. Bu büyüden etkilenen canlının nefes almasına, yemek yemesine, içmesine gerek kalmaz ve yaşlanmaz. Kehanet büyüleri hedefin yerini tespit edemez veya algılayamaz.\nBüyüyü yaptığınızda aşağıdaki hapis şekillerinden birini seçersiniz.\n***Gömülme.*** Hedef, yerin çok altında, hedefi içine alacak kadar büyük, büyülü bir force küresinin içine gömülür. Hiçbir şey kürenin içinden geçemez, hiçbir yaratık ışınlanamaz veya oraya girip çıkmak için düzlemsel yolculuğu kullanamaz.\nBüyünün bu versiyonunun özel bileşeni küçük bir mitral küredir.\n***Zincirleme.*** Yere sıkı bir şekilde kök salmış ağır zincirler hedefi yerinde tutar. Hedef, büyü bitene kadar restrained'dir ve o zamana kadar hiçbir şekilde hareket edemez veya hareket ettirilemez.\nBüyünün bu versiyonunun özel bileşeni, değerli metalden yapılmış ince bir zincirdir.\n***Korunan Hapishane.*** Büyü, hedefi ışınlanmaya ve düzlemsel yolculuğa karşı korunan küçük bir yarı-uçağa taşır. Yarı düzlem bir labirent, bir kafes, bir kule veya sizin seçtiğiniz herhangi bir benzer kapalı yapı veya alan olabilir.\nBüyünün bu versiyonunun özel bileşeni, hapishanenin yeşim taşından yapılmış minyatür bir temsilidir.\n***Minimus Sınırlama.*** Hedef 1 inç yüksekliğe kadar küçülür ve değerli bir taş veya benzeri bir nesnenin içine hapsedilir. Işık normal olarak değerli taşın içinden geçebilir (hedefin dışarıyı ve diğer canlıların içeriyi görmesine izin verir), ancak ışınlanma veya düzlemsel yolculuk yoluyla bile başka hiçbir şey geçemez. Büyünün etkisi devam ettiği sürece değerli taş kesilemez veya kırılamaz.\nBüyünün bu versiyonunun özel bileşeni korindon, elmas veya yakut gibi büyük, şeffaf bir değerli taştır.\n***Uyku.*** Hedef uykuya dalar ve uyandırılamaz.\nBüyünün bu versiyonunun özel bileşeni nadir uyutucu bitkilerden oluşur.\n***Büyü Sonlandırma.*** Büyünün herhangi bir versiyonunda, yapılması sırasında, büyünün sona ermesine ve hedefin serbest kalmasına neden olacak bir koşul belirleyebilirsiniz. Koşul, seçtiğiniz kadar spesifik veya ayrıntılı olabilir, ancak GM, koşulun makul olduğunu ve gerçekleşme ihtimalinin bulunduğunu kabul etmelidir. Koşullar bir yaratığın ismine, kimliğine veya tanrısına dayanabilir ancak aksi takdirde gözlemlenebilir eylemlere veya niteliklere dayanmalı ve seviye, sınıf veya HP gibi soyut unsurlara dayanmamalıdır.\nBir yok etme büyüsü, büyüyü yalnızca hapishaneyi veya onu oluşturmak için kullanılan özel bileşeni hedef alan 9. seviye bir büyü olarak kullanıldığında sona erdirebilir.\nAynı anda yalnızca bir hapishane oluşturmak için belirli bir özel bileşeni kullanabilirsiniz. Eğer büyüyü aynı bileşeni kullanarak tekrar yaparsanız, ilk yaptığınız büyünün hedefi büyünün bağlayıcılığından hemen kurtulur.","higher":"","sourceText":"You create a magical restraint to hold a creature that you can see within range. The target must succeed on a wisdom saving throw or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again. While affected by this spell, the creature doesn't need to breathe, eat, or drink, and it doesn't age. Divination spells can't locate or perceive the target.\n\nWhen you cast the spell, you choose one of the following forms of imprisonment.\n\n***Burial.*** The target is entombed far beneath the earth in a sphere of magical force that is just large enough to contain the target. Nothing can pass through the sphere, nor can any creature teleport or use planar travel to get into or out of it.\n\nThe special component for this version of the spell is a small mithral orb.\n\n***Chaining.*** Heavy chains, firmly rooted in the ground, hold the target in place. The target is restrained until the spell ends, and it can't move or be moved by any means until then.\n\nThe special component for this version of the spell is a fine chain of precious metal.\n\n***Hedged Prison.*** The spell transports the target into a tiny demiplane that is warded against teleportation and planar travel. The demiplane can be a labyrinth, a cage, a tower, or any similar confined structure or area of your choice.\n\nThe special component for this version of the spell is a miniature representation of the prison made from jade.\n\n***Minimus Containment.*** The target shrinks to a height of 1 inch and is imprisoned inside a gemstone or similar object. Light can pass through the gemstone normally (allowing the target to see out and other creatures to see in), but nothing else can pass through, even by means of teleportation or planar travel. The gemstone can't be cut or broken while the spell remains in effect.\n\nThe special component for this version of the spell is a large, transparent gemstone, such as a corundum, diamond, or ruby.\n\n***Slumber.*** The target falls asleep and can't be awoken.\n\nThe special component for this version of the spell consists of rare soporific herbs.\n\n***Ending the Spell.*** During the casting of the spell, in any of its versions, you can specify a condition that will cause the spell to end and release the target. The condition can be as specific or as elaborate as you choose, but the GM must agree that the condition is reasonable and has a likelihood of coming to pass. The conditions can be based on a creature's name, identity, or deity but otherwise must be based on observable actions or qualities and not based on intangibles such as level, class, or hit points.\n\nA dispel magic spell can end the spell only if it is cast as a 9th-level spell, targeting either the prison or the special component used to create it.\n\nYou can use a particular special component to create only one prison at a time. If you cast the spell again using the same component, the target of the first casting is immediately freed from its binding.","higherSource":""},{"id":"incendiary-cloud","name":"Incendiary Cloud","nameTr":"Yangın Çıkarıcı Bulut","level":8,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"sphere","size":20},"description":"Menzil içindeki bir noktaya odaklanan bir 20 ft yarıçap küresinde, beyaz-sıcak közlerin arasından fırlayan dönen bir duman bulutu görünüyor. Bulut köşelere yayılıyor ve büyük ölçüde gizleniyor. Bu süre boyunca veya orta veya daha yüksek hızdaki bir rüzgar (en azından saatte 10 mil) onu dağıtıncaya kadar sürer.\nBulut ortaya çıktığında, içindeki her canlının bir DEX saving throw yapması gerekir. Bir yaratık, başarısız save’de 10d8 fire hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Bir yaratık aynı zamanda bu saving throw'yi bir turda büyü alanına ilk kez girdiğinde veya turunu burada bitirdiğinde de yapmalıdır.\nBulut, 10 ft'yi her dönüşünüzün başında seçtiğiniz bir yöne doğru doğrudan sizden uzaklaştırır.","higher":"","sourceText":"A swirling cloud of smoke shot through with white-hot embers appears in a 20-foot-radius sphere centered on a point within range. The cloud spreads around corners and is heavily obscured. It lasts for the duration or until a wind of moderate or greater speed (at least 10 miles per hour) disperses it.\n\nWhen the cloud appears, each creature in it must make a dexterity saving throw. A creature takes 10d8 fire damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.\n\nThe cloud moves 10 feet directly away from you in a direction that you choose at the start of each of your turns.","higherSource":""},{"id":"inflict-wounds","name":"Inflict Wounds","nameTr":"Yara Vermek","level":1,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Ulaşabildiğin bir yaratığa karşı yakın spell attack yap. Bir vuruşta hedef 3d10 necrotic hasarı alır.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 1. seviyenin üzerindeki her yuva seviyesi için 1d10 artar.","sourceText":"Make a melee spell attack against a creature you can reach. On a hit, the target takes 3d10 necrotic damage.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."},{"id":"insect-plague","name":"Insect Plague","nameTr":"Böcek Vebası","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Druid","Sorcerer"],"subclasses":["Land"],"castingTime":"1 action","range":"300 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Birkaç tane şeker, biraz tahıl tanesi ve bir parça yağ.","materialSource":"A few grains of sugar, some kernels of grain, and a smear of fat.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"sphere","size":20},"description":"Kaynaşan, ısıran çekirgeler, menzil içinde seçtiğiniz bir noktanın ortasında bulunan bir 20 ft yarıçap küresini dolduruyor. Küre köşelere yayılıyor. Küre bu süre boyunca kalır ve alanı hafifçe gizlenir. Kürenin alanı zorlu bir arazidir.\nAlan göründüğünde, içindeki her canlının bir CON saving throw yapması gerekir. Bir yaratık, başarısız save’de 4d10 piercing hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Bir yaratık aynı zamanda bu saving throw'yi bir turda büyü alanına ilk kez girdiğinde veya turunu burada bitirdiğinde de yapmalıdır.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 5. seviyenin üzerindeki her yuva seviyesi için 1d10 artar.","sourceText":"Swarming, biting locusts fill a 20-foot-radius sphere centered on a point you choose within range. The sphere spreads around corners. The sphere remains for the duration, and its area is lightly obscured. The sphere's area is difficult terrain.\n\nWhen the area appears, each creature in it must make a constitution saving throw. A creature takes 4d10 piercing damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw when it enters the spell's area for the first time on a turn or ends its turn there.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d10 for each slot level above 5th."},{"id":"instant-summons","name":"Instant Summons","nameTr":"Anında Çağrı","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"1000 GP değerinde bir safir.","materialSource":"A sapphire worth 1,000 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"En uzun boyutu 6 ft veya daha az olan 10 lb veya daha hafif bir nesneye dokunursunuz. Büyü, yüzeyinde bir invisible işareti bırakır ve malzeme bileşeni olarak kullandığınız safir üzerine eşyanın adını görünmez bir şekilde yazar. Bu büyüyü her yaptığınızda farklı bir safir kullanmalısınız.\nBundan sonra istediğiniz zaman öğenin adını söyleyerek safiri ezmek için eyleminizi kullanabilirsiniz. Öğe, fiziksel veya düzlemsel mesafelere bakılmaksızın anında elinizde belirir ve büyü sona erer.\nEğer eşyayı başka bir canlı tutuyor veya taşıyorsa, safiri ezmek eşyayı size ulaştırmaz, bunun yerine nesneye sahip olan yaratığın kim olduğunu ve o yaratığın o anda kabaca nerede bulunduğunu öğrenirsiniz.\nSafire başarıyla uygulanan etkisizleştirme büyüsü veya benzer bir etki, bu büyünün etkisini sona erdirir.","higher":"","sourceText":"You touch an object weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire.\n\nAt any time thereafter, you can use your action to speak the item's name and crush the sapphire. The item instantly appears in your hand regardless of physical or planar distances, and the spell ends.\n\nIf another creature is holding or carrying the item, crushing the sapphire doesn't transport the item to you, but instead you learn who the creature possessing the object is and roughly where that creature is located at that moment.\n\nDispel magic or a similar effect successfully applied to the sapphire ends this spell's effect.","higherSource":""},{"id":"invisibility","name":"Invisibility","nameTr":"Görünmezlik","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Arap zamkı ile kaplanmış bir kirpik.","materialSource":"An eyelash encased in gum arabic.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz yaratık, büyü bitene kadar invisible olur. Hedefin giydiği veya taşıdığı her şey, hedefin üzerinde olduğu sürece invisible'dir. Büyü, saldıran veya büyü yapan hedef için sona erer.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 2. seviyenin üzerindeki her yuva seviyesi için bir ek yaratık hedefleyebilirsiniz.","sourceText":"A creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. The spell ends for a target that attacks or casts a spell.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."},{"id":"irresistible-dance","name":"Irresistible Dance","nameTr":"Dayanılmaz Dans","level":6,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX","WIS"],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir yaratık seçin. Hedef yerinde komik bir dansa başlar: bu süre boyunca ayaklarını sürüyerek, ayaklarını yere vurarak ve zıplayarak dans eder. charmed olamayacak yaratıklar bu büyüye karşı bağışıklıdır.\nDans eden bir yaratık, alanını terk etmeden dans etmek için tüm hareketini kullanmalıdır ve DEX saving throw’lar üzerinde dezavantaj ve saldırı atışlarına sahip olmalıdır. Hedef bu büyüden etkilenirken, diğer yaratıkların ona karşı saldırı atışlarında avantaj vardır. Bir aksiyon olarak dans eden bir yaratık, kendi kontrolünü yeniden kazanmak için bir WIS saving throw yapar. Başarılı bir kaydetmeyle büyü sona erer.","higher":"","sourceText":"Choose one creature that you can see within range. The target begins a comic dance in place: shuffling, tapping its feet, and capering for the duration. Creatures that can't be charmed are immune to this spell.\n\nA dancing creature must use all its movement to dance without leaving its space and has disadvantage on dexterity saving throws and attack rolls. While the target is affected by this spell, other creatures have advantage on attack rolls against it. As an action, a dancing creature makes a wisdom saving throw to regain control of itself. On a successful save, the spell ends.","higherSource":""},{"id":"jump","name":"Jump","nameTr":"Atla","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir çekirgenin arka ayağı.","materialSource":"A grasshopper's hind leg.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsun. Büyü bitene kadar yaratığın atlama mesafesi üç katına çıkar.","higher":"","sourceText":"You touch a creature. The creature's jump distance is tripled until the spell ends.","higherSource":""},{"id":"knock","name":"Knock","nameTr":"Vuruş","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir nesne seçin. Nesne bir kapı, bir kutu, bir sandık, bir dizi kelepçe, bir asma kilit veya erişimi engelleyen sıradan veya büyülü bir araç içeren başka bir nesne olabilir.\nSıradan bir kilitle kapalı tutulan veya sıkışmış veya çubuklu bir hedefin kilidi açılır, çözülür veya çubuk kaldırılır. Nesnenin birden fazla kilidi varsa yalnızca birinin kilidi açılır.\nGizli kilitle kapalı tutulan bir hedef seçerseniz, bu büyü 10 dakika süreyle bastırılır ve bu süre zarfında hedef normal şekilde açılıp kapatılabilir.\nBüyüyü yaptığınızda, hedef nesneden 300 ft kadar uzaktan duyulabilen yüksek bir vuruş duyulur.","higher":"","sourceText":"Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\n\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\n\nIf you choose a target that is held shut with arcane lock, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.\n\nWhen you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object.","higherSource":""},{"id":"legend-lore","name":"Legend Lore","nameTr":"Efsane Bilgisi","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği en az 250 gp değerindeki tütsü ve her biri en az 50 gp değerinde dört fildişi şerit.","materialSource":"Incense worth at least 250 gp, which the spell consumes, and four ivory strips worth at least 50 gp each.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir kişiyi, yeri veya nesneyi adlandırın veya tanımlayın. Büyü, adını verdiğiniz şeyle ilgili önemli bilgilerin kısa bir özetini aklınıza getirir. Bilgi güncel hikayelerden, unutulmuş hikayelerden ve hatta hiçbir zaman geniş çapta bilinmeyen gizli bilgilerden oluşabilir. Adını söylediğiniz şey efsanevi bir öneme sahip değilse hiçbir bilgi elde edemezsiniz. Bir şey hakkında ne kadar çok bilgiye sahipseniz, aldığınız bilgi de o kadar kesin ve ayrıntılı olur.\nÖğrendiğiniz bilgiler doğrudur ancak mecazi bir dille ifade edilmiş olabilir. Örneğin, elinizde gizemli bir sihirli balta varsa, büyü şu bilgiyi verebilir: \"Vay be eli baltaya dokunan kötü adama, çünkü sapı bile kötü olanın elini keser. Yalnızca gerçek bir Taş Çocuk, Moradin'in sevgilisi ve sevgilisi, baltanın gerçek güçlerini uyandırabilir ve yalnızca dudaklarındaki kutsal *Rudnogg* sözcüğüyle uyandırabilir.\"","higher":"","sourceText":"Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about the thing you named. The lore might consist of current tales, forgotten stories, or even secret lore that has never been widely known. If the thing you named isn't of legendary importance, you gain no information. The more information you already have about the thing, the more precise and detailed the information you receive is.\n\nThe information you learn is accurate but might be couched in figurative language. For example, if you have a mysterious magic axe on hand the spell might yield this information: \"Woe to the evildoer whose hand touches the axe, for even the haft slices the hand of the evil ones. Only a true Child of Stone, lover and beloved of Moradin, may awaken the true powers of the axe, and only with the sacred word *Rudnogg* on the lips.\"","higherSource":""},{"id":"lesser-restoration","name":"Lesser Restoration","nameTr":"Küçük Restorasyon","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Druid","Paladin","Ranger"],"subclasses":["Devotion","Life","Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunduğunuzda, onu etkileyen bir hastalığı ya da rahatsızlığı ortadan kaldırabilirsiniz. Koşul blinded, deafened, paralyzed veya poisoned olabilir.","higher":"","sourceText":"You touch a creature and can end either one disease or one condition afflicting it. The condition can be blinded, deafened, paralyzed, or poisoned.","higherSource":""},{"id":"levitate","name":"Levitate","nameTr":"Havaya yükselme","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Ya küçük bir deri halka ya da bir ucunda uzun bir sap bulunan, fincan şeklinde bükülmüş bir parça altın tel.","materialSource":"Either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on one end.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz seçtiğiniz bir yaratık veya nesne 20 ft'ye kadar dikey olarak yükselir ve bu süre boyunca orada asılı kalır. Büyü, ağırlığı 500 lb'ye kadar olan bir hedefi havaya kaldırabilir. CON saving throw üzerinde başarılı olan isteksiz bir yaratık etkilenmez.\nHedef, yalnızca erişilebilen sabit bir nesneyi veya yüzeyi (duvar veya tavan gibi) iterek veya çekerek hareket edebilir, bu da sanki tırmanıyormuş gibi hareket etmesine olanak tanır. Sıra size geldiğinde hedefin yüksekliğini 20 ft'ye kadar her iki yönde değiştirebilirsiniz. Hedef sizseniz, hareketinizin bir parçası olarak yukarı veya aşağı hareket edebilirsiniz. Aksi takdirde, büyünün menzili içinde kalması gereken hedefi hareket ettirmek için eyleminizi kullanabilirsiniz.\nBüyü sona erdiğinde hedef hâlâ havadaysa yavaşça yere doğru süzülür.","higher":"","sourceText":"One creature or object of your choice that you can see within range rises vertically, up to 20 feet, and remains suspended there for the duration. The spell can levitate a target that weighs up to 500 pounds. An unwilling creature that succeeds on a constitution saving throw is unaffected.\n\nThe target can move only by pushing or pulling against a fixed object or surface within reach (such as a wall or a ceiling), which allows it to move as if it were climbing. You can change the target's altitude by up to 20 feet in either direction on your turn. If you are the target, you can move up or down as part of your move. Otherwise, you can use your action to move the target, which must remain within the spell's range.\n\nWhen the spell ends, the target floats gently to the ground if it is still aloft.","higherSource":""},{"id":"light","name":"Light","nameTr":"Işık","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Cleric","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","M"],"materialTr":"Ateş böceği veya fosforlu yosun.","materialSource":"A firefly or phosphorescent moss.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":null,"description":"Herhangi bir boyutta 10 ft'den daha büyük olmayan bir nesneye dokunuyorsunuz. Büyü bitene kadar nesne, 20 ft yarıçapında parlak ışık tutar ve ek bir 20 ft için loş ışık tutar. Işık istediğiniz gibi renklendirilebilir. Nesnenin tamamen opak bir şeyle kaplanması ışığı engeller. Büyüyü tekrar yaparsanız veya bir eylem olarak reddederseniz büyü sona erer.\nDüşman bir yaratık tarafından tutulan veya giyilen bir nesneyi hedef alırsanız, büyüyü önlemek için o yaratığın DEX saving throw üzerinde başarılı olması gerekir.","higher":"","sourceText":"You touch one object that is no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. The light can be colored as you like. Completely covering the object with something opaque blocks the light. The spell ends if you cast it again or dismiss it as an action.\n\nIf you target an object held or worn by a hostile creature, that creature must succeed on a dexterity saving throw to avoid the spell.","higherSource":""},{"id":"lightning-bolt","name":"Lightning Bolt","nameTr":"Şimşek","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir parça kürk ve bir kehribar, kristal veya cam çubuk.","materialSource":"A bit of fur and a rod of amber, crystal, or glass.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"line","size":100},"description":"lightning uzun ve 5 ft genişliğinde bir çizgi oluşturan lightning vuruşu, seçtiğiniz bir yönde sizden dışarı fırlar. Sıradaki her yaratık bir DEX saving throw yapmalıdır. Bir yaratık, başarısız save’de 8d6 lightning hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\nlightning, alandaki giyilmeyen veya taşınmayan yanıcı nesneleri ateşler.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 3. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you in a direction you choose. Each creature in the line must make a dexterity saving throw. A creature takes 8d6 lightning damage on a failed save, or half as much damage on a successful one.\n\nThe lightning ignites flammable objects in the area that aren't being worn or carried.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},{"id":"locate-animals-or-plants","name":"Locate Animals or Plants","nameTr":"Hayvanların veya Bitkilerin Yerini Belirleyin","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir tazıdan bir parça kürk.","materialSource":"A bit of fur from a bloodhound.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Belirli bir hayvan veya bitki türünü tanımlayın veya adlandırın. Çevrenizdeki doğanın sesine odaklanarak, 5 mil içerisinde varsa o türden en yakın canlı veya bitkinin yönünü ve mesafesini öğrenirsiniz.","higher":"","sourceText":"Describe or name a specific kind of beast or plant. Concentrating on the voice of nature in your surroundings, you learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present.","higherSource":""},{"id":"locate-creature","name":"Locate Creature","nameTr":"Yaratığı Bul","level":4,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tazıdan bir parça kürk.","materialSource":"A bit of fur from a bloodhound.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Tanıdığınız bir yaratığı tanımlayın veya adlandırın. Yaratık 1,000 ft yakınınızda olduğu sürece, yaratığın konumunun yönünü hissedersiniz. Yaratık hareket ediyorsa hareketinin yönünü bilirsiniz.\nBüyü, sizin tarafınızdan bilinen belirli bir yaratığın veya belirli türden en yakın yaratığın (insan veya tek boynuzlu at gibi) yerini, böyle bir yaratığı 30 ft içinde en az bir kez yakından gördüğünüz sürece bulabilir. Tanımladığınız veya adını verdiğiniz yaratık farklı bir formdaysa, örneğin polimorf büyüsünün etkisi altındaysa bu büyü, yaratığın yerini tespit edemez.\nEn azından 10 ft genişliğinde akan su sizinle yaratık arasındaki doğrudan yolu kapatıyorsa, bu büyü bir yaratığın yerini tespit edemez.","higher":"","sourceText":"Describe or name a creature that is familiar to you. You sense the direction to the creature's location, as long as that creature is within 1,000 feet of you. If the creature is moving, you know the direction of its movement.\n\nThe spell can locate a specific creature known to you, or the nearest creature of a specific kind (such as a human or a unicorn), so long as you have seen such a creature up close--within 30 feet--at least once. If the creature you described or named is in a different form, such as being under the effects of a polymorph spell, this spell doesn't locate the creature.\n\nThis spell can't locate a creature if running water at least 10 feet wide blocks a direct path between you and the creature.","higherSource":""},{"id":"locate-object","name":"Locate Object","nameTr":"Nesneyi Bul","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Çatallı bir dal.","materialSource":"A forked twig.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Size tanıdık gelen bir nesneyi tanımlayın veya adlandırın. Nesne 1,000 ft yakınınızda olduğu sürece nesnenin konumunun yönünü hissedersiniz. Nesne hareket halindeyse hareketinin yönünü bilirsiniz.\nBüyü, sizin tarafınızdan bilinen belirli bir nesneyi, onu en az bir kez yakından (30 ft içinde) gördüğünüz sürece bulabilir. Alternatif olarak büyü, belirli bir tür giysi, mücevher, mobilya, alet veya silah gibi belirli türden en yakın nesnenin yerini belirleyebilir.\nHerhangi bir kalınlıktaki kurşun, hatta ince bir tabaka bile sizinle nesne arasındaki doğrudan yolu kapatıyorsa, bu büyü bir nesnenin yerini tespit edemez.","higher":"","sourceText":"Describe or name an object that is familiar to you. You sense the direction to the object's location, as long as that object is within 1,000 feet of you. If the object is in motion, you know the direction of its movement.\n\nThe spell can locate a specific object known to you, as long as you have seen it up close--within 30 feet--at least once. Alternatively, the spell can locate the nearest object of a particular kind, such as a certain kind of apparel, jewelry, furniture, tool, or weapon.\n\nThis spell can't locate an object if any thickness of lead, even a thin sheet, blocks a direct path between you and the object.","higherSource":""},{"id":"longstrider","name":"Longstrider","nameTr":"Uzunyolcu","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid","Ranger","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam kir.","materialSource":"A pinch of dirt.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsun. Büyü bitene kadar hedefin hızı 10 ft artar.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her spell slot için ek bir yaratık hedefleyebilirsiniz.","sourceText":"You touch a creature. The target's speed increases by 10 feet until the spell ends.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each spell slot above 1st."},{"id":"mage-armor","name":"Mage Armor","nameTr":"Büyücü Zırhı","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir parça sertleştirilmiş deri.","materialSource":"A piece of cured leather.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Zırh giymeyen istekli bir yaratığa dokunduğunuzda, büyü sona erene kadar koruyucu, büyülü bir force onu çevreler. Hedefin temel AC'si 13 + onun DEX değiştiricisi olur. Hedef zırh kuşandığında ya da büyüyü bir eylem olarak iptal ettiğinizde büyü sona erer.","higher":"","sourceText":"You touch a willing creature who isn't wearing armor, and a protective magical force surrounds it until the spell ends. The target's base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or if you dismiss the spell as an action.","higherSource":""},{"id":"mage-hand","name":"Mage Hand","nameTr":"Büyücü Eli","level":0,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde seçtiğiniz bir noktada spektral, havada süzülen bir el belirir. El, süre boyunca veya siz onu bir eylem olarak reddedinceye kadar sürer. El, sizden 30 ft değerinden daha fazla uzaktaysa veya bu büyüyü tekrar yaparsanız kaybolur.\nElinizi kontrol etmek için eyleminizi kullanabilirsiniz. Elinizi bir nesneyi hareket ettirmek, kilitli olmayan bir kapıyı veya kabı açmak, açık bir kaptan bir öğeyi yerleştirmek veya almak veya bir şişenin içeriğini boşaltmak için kullanabilirsiniz. Her kullandığınızda ibreyi 30 ft konumuna getirebilirsiniz.\nEl, 10 lb'den fazlasını saldıramaz, sihirli eşyaları etkinleştiremez veya taşıyamaz.","higher":"","sourceText":"A spectral, floating hand appears at a point you choose within range. The hand lasts for the duration or until you dismiss it as an action. The hand vanishes if it is ever more than 30 feet away from you or if you cast this spell again.\n\nYou can use your action to control the hand. You can use the hand to manipulate an object, open an unlocked door or container, stow or retrieve an item from an open container, or pour the contents out of a vial. You can move the hand up to 30 feet each time you use it.\n\nThe hand can't attack, activate magic items, or carry more than 10 pounds.","higherSource":""},{"id":"magic-circle","name":"Magic Circle","nameTr":"Sihirli Çember","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"10 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 100 gp değerinde kutsal su veya toz gümüş ve demir.","materialSource":"Holy water or powdered silver and iron worth at least 100 gp, which the spell consumes.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"other","area":{"type":"cylinder","size":10},"description":"Yerde menzil içinde görebileceğiniz bir noktaya odaklanan bir 10 ft yarıçapı, 20 ft yükseklik büyülü enerji silindiri yaratırsınız. Silindir zeminle veya başka bir yüzeyle kesiştiğinde parlayan runeler belirir.\nAşağıdaki yaratık türlerinden bir veya daha fazlasını seçin: gökseller, elementaller, periler, şeytanlar veya ölümsüzler. Daire, seçilen türdeki bir yaratığı aşağıdaki şekillerde etkiler:\n- Yaratık, sihirli olmayan yollarla silindire isteyerek giremez. Yaratık bunu yapmak için ışınlanmayı veya düzlemler arası seyahati kullanmaya çalışırsa, öncelikle CHA saving throw üzerinde başarılı olması gerekir.\n- Yaratığın silindir içindeki hedeflere karşı saldırı atışlarında dezavantaj var.\n- Silindir içindeki hedefler charmed, frightened olamaz veya yaratığın eline geçemez.\nBu büyüyü yaptığınızda, büyüsünün ters yönde çalışmasını sağlayarak belirtilen türden bir yaratığın silindirden çıkmasını ve silindirin dışındaki hedefleri korumasını önleyebilirsiniz.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, süre 3. seviyenin üzerindeki her yuva seviyesi için 1 saat artar.","sourceText":"You create a 10-foot radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear whenever the cylinder intersects with the floor or other surface.\n\nChoose one or more of the following types of creatures: celestials, elementals, fey, fiends, or undead. The circle affects a creature of the chosen type in the following ways:\n\n- The creature can't willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a charisma saving throw.\n\n- The creature has disadvantage on attack rolls against targets within the cylinder.\n\n- Targets within the cylinder can't be charmed, frightened, or possessed by the creature.\n\nWhen you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the duration increases by 1 hour for each slot level above 3rd."},{"id":"magic-jar","name":"Magic Jar","nameTr":"Sihirli Kavanoz","level":6,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Wizard"],"subclasses":[],"castingTime":"1 minute","range":"Self","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"En az 500 GP değerinde bir mücevher, kristal, kutsal emanet veya başka bir süs kabı.","materialSource":"A gem, crystal, reliquary, or some other ornamental container worth at least 500 gp.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"other","area":null,"description":"Ruhunuz onu terk edip büyünün maddi bileşeni için kullandığınız kaba girdiğinde bedeniniz katatonik bir duruma düşer. Ruhunuz kabın içinde yaşarken, sanki kabın içindeymiş gibi çevrenizin farkında olursunuz. Reaction’lar'yi taşıyamaz veya kullanamazsınız. Yapabileceğiniz tek eylem, ruhunuzu kabın dışına 100 ft'ye kadar yansıtmak, ya canlı bedeninize geri dönmek (ve büyüyü bitirmek) ya da insansı bir bedene sahip olmaya çalışmaktır.\n100 ft içinde görebileceğiniz herhangi bir insansıyı ele geçirmeye çalışabilirsiniz (kötülüğe ve iyiliğe karşı korumayla korunan yaratıklara veya büyü çemberi büyüsüne sahip olamazsınız). Hedef bir CHA saving throw yapmalıdır. Başarısızlık durumunda ruhunuz hedefin bedenine girer ve hedefin ruhu kabın içinde sıkışıp kalır. Başarılı olduğunuzda hedef, onu ele geçirme çabalarınıza direnir ve siz onu 24 saat boyunca tekrar ele geçirmeye çalışamazsınız.\nBir yaratığın bedenine sahip olduğunuzda onu kontrol edersiniz. Oyun istatistiklerinizin yerini yaratığın istatistikleri alır, ancak hizanızı ve WIS ve CHA puanlarınızı korursunuz. Kendi sınıf özelliklerinizin avantajlarından yararlanmaya devam edersiniz. Hedefin herhangi bir sınıf düzeyi varsa sınıf özelliklerinden hiçbirini kullanamazsınız.\nBu arada ele geçirilen yaratığın ruhu, kendi duyularını kullanarak kaptan algılayabilir ancak hiçbir şekilde hareket edemez ve hareket edemez.\nBir bedene sahip olduğunuzda, eğer 100 ft yakınınızdaysa, ev sahibi vücuttan konteynere geri dönmek ve ev sahibi yaratığın ruhunu bedenine geri döndürmek için eyleminizi kullanabilirsiniz. Konakçının gövdesi siz onun içindeyken ölürse, yaratık da ölür ve kendi büyü yapan DC'nize karşı bir CHA saving throw yapmalısınız. Başarılı olduğunuzda, 100 ft yakınınızdaysa konteynere geri dönersiniz. Aksi takdirde ölürsünüz.\nKap yok edilirse veya büyü sona ererse ruhunuz hemen bedeninize geri döner. Vücudunuz sizden 100 ft'den daha uzaktaysa veya ona geri dönmeye çalıştığınızda bedeniniz ölüyse ölürsünüz. Yok edildiğinde başka bir yaratığın ruhu kabın içindeyse, canlının ruhu, eğer beden canlıysa ve 100 ft içindeyse bedenine geri döner. Aksi takdirde o yaratık ölür.\nBüyü sona erdiğinde kutu yok edilir.","higher":"","sourceText":"Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell's material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container's space. You can't move or use reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a humanoids body.\n\nYou can attempt to possess any humanoid within 100 feet of you that you can see (creatures warded by a protection from evil and good or magic circle spell can't be possessed). The target must make a charisma saving throw. On a failure, your soul moves into the target's body, and the target's soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can't attempt to possess it again for 24 hours.\n\nOnce you possess a creature's body, you control it. Your game statistics are replaced by the statistics of the creature, though you retain your alignment and your Intelligence, Wisdom, and Charisma scores. You retain the benefit of your own class features. If the target has any class levels, you can't use any of its class features.\n\nMeanwhile, the possessed creature's soul can perceive from the container using its own senses, but it can't move or take actions at all.\n\nWhile possessing a body, you can use your action to return from the host body to the container if it is within 100 feet of you, returning the host creature's soul to its body. If the host body dies while you're in it, the creature dies, and you must make a charisma saving throw against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die.\n\nIf the container is destroyed or the spell ends, your soul immediately returns to your body. If your body is more than 100 feet away from you or if your body is dead when you attempt to return to it, you die. If another creature's soul is in the container when it is destroyed, the creature's soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies.\n\nWhen the spell ends, the container is destroyed.","higherSource":""},{"id":"magic-missile","name":"Magic Missile","nameTr":"Sihirli Füze","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyülü force'den üç parlak dart yaratırsınız. Her dart, menzil içinde görebileceğiniz, seçtiğiniz bir yaratığa çarpar. Bir dart hedefine 1d4+1 force hasar verir. Dartların hepsi aynı anda vuruyor ve onları bir veya daha fazla yaratığa vurmaya yönlendirebiliyorsunuz.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, büyü 1. seviyenin üzerindeki her yuva seviyesi için bir dart daha oluşturur.","sourceText":"You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range. A dart deals 1d4 + 1 force damage to its target. The darts all strike simultaneously, and you can direct them to hit one creature or several.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart for each slot level above 1st."},{"id":"magic-mouth","name":"Magic Mouth","nameTr":"Sihirli Ağız","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"30 feet","duration":"Until dispelled","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Büyü, en az 10 inç değerinde bal peteği ve yeşim tozu tüketir.","materialSource":"A honeycomb and jade dust of at least 10 inches, the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyünün menzilindeki bir nesneye bir mesaj yerleştirirsiniz. Tetikleyici koşullar karşılandığında mesaj sözlü olarak ifade edilir. Gördüğünüz ve başka bir canlı tarafından giyilmeyen veya taşınmayan bir nesneyi seçin. Daha sonra 25 kelimeyi geçmemesi gereken ancak dinleme süresi 10 dakikayı bulabilecek mesajı söyleyin. Son olarak, mesajınızı iletmek için büyüyü tetikleyen koşulları belirleyin.\nBu koşullar sağlandığında, nesnenin üzerinde sihirli bir ağız belirir ve mesajın yerleştirilmesi sırasında kullanılan tonun aynısını, sizin sesinizi taklit ederek mesajı ifade eder. Seçilen nesnenin bir ağzı veya heykel ağzı gibi yaklaşan bir şey varsa, sihirli ağız bu noktada canlanır ve kelimelerin nesnenin ağzından geldiği yanılsamasını verir.\nBu büyüyü yaptığınızda, mesaj iletildiğinde büyünün sona ermesine veya büyünün devam etmesine ve koşullar oluştuğunda mesajı tekrarlamasına karar verebilirsiniz.\nTetikleyici durum istediğiniz kadar genel veya ayrıntılı olabilir, ancak nesnenin 30 ft içinde meydana gelen görsel veya işitsel koşullara dayanması gerekir. Örneğin, nesnenin 30 ft yakınında herhangi bir yaratık hareket ettiğinde veya 30 ft içinde gümüş bir zil çaldığında ağza konuşma talimatı verebilirsiniz.","higher":"","sourceText":"You plant a message to an object in the range of the spell. The message is verbalized when the trigger conditions are met. Choose an object that you see, and that is not worn or carried by another creature. Then say the message, which should not exceed 25 words but listening can take up to 10 minutes. Finally, establish the circumstances that trigger the spell to deliver your message.\n\nWhen these conditions are satisfied, a magical mouth appears on the object and it articulates the message imitating your voice, the same tone used during implantation of the message. If the selected object has a mouth or something that approaches such as the mouth of a statue, the magic mouth come alive at this point, giving the illusion that the words come from the mouth of the object.\n\nWhen you cast this spell, you may decide that the spell ends when the message is delivered or it can persist and repeat the message whenever circumstances occur.\n\nThe triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it.","higherSource":""},{"id":"magic-weapon","name":"Magic Weapon","nameTr":"Sihirli Silah","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Paladin","Wizard"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyülü olmayan bir silaha dokunuyorsun. Büyü bitene kadar bu silah, saldırı zarlarına ve hasar atışlarına +1 bonus veren sihirli bir silaha dönüşür.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda bonus +2'ye yükselir. 6. seviye veya daha yüksek bir spell slot kullandığınızda bonus +3'e çıkar.","sourceText":"You touch a nonmagical weapon. Until the spell ends, that weapon becomes a magic weapon with a +1 bonus to attack rolls and damage rolls.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the bonus increases to +2. When you use a spell slot of 6th level or higher, the bonus increases to +3."},{"id":"magnificent-mansion","name":"Magnificent Mansion","nameTr":"Muhteşem Konak","level":7,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"300 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Fildişinden oyulmuş minyatür bir portal, küçük bir cilalı mermer parçası ve minik bir gümüş kaşık; her biri en az 5 gp değerinde.","materialSource":"A miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":5},"description":"Süre boyunca süren, ekstra boyutlu bir mesken yaratırsınız. Bir girişinin nerede olacağını siz seçersiniz. Giriş hafifçe parlıyor ve 5 ft genişliğinde ve 10 ft yüksekliğinde. Siz ve büyüyü yaparken belirlediğiniz herhangi bir yaratık, portal açık kaldığı sürece ekstra boyutlu meskene girebilirsiniz. 30 ft içerisindeyseniz portalı açabilir veya kapatabilirsiniz. Kapalıyken portal invisible'dir.\nPortalın ötesinde, arkasında çok sayıda odanın bulunduğu muhteşem bir fuaye var. Atmosfer temiz, taze ve sıcak.\nİstediğiniz kat planını oluşturabilirsiniz ancak alan 50 küpü aşamaz; her küpün her iki tarafı da 10 ft'dir. Mekan sizin tercihinize göre döşenir ve dekore edilir. İçinde 100 kişiye kadar dokuz servisli bir ziyafete yetecek kadar yiyecek var. İçeri giren herkese 100'e yakın şeffaf hizmetçiden oluşan bir personel katılıyor. Bu hizmetlilerin görselliğine ve kıyafetlerine siz karar veriyorsunuz. Emirlerinize tamamen itaat ediyorlar. Her hizmetçi, normal bir insan hizmetçinin yapabileceği her görevi yerine getirebilir ancak başka bir canlıya saldıramaz veya doğrudan zarar verecek bir eylemde bulunamaz. Böylece hizmetçiler bir şeyler getirebilir, temizleyebilir, onarabilir, kıyafetleri katlayabilir, ateş yakabilir, yemek servisi yapabilir, şarap dökebilir vb. Hizmetçiler konağın herhangi bir yerine gidebilirler ama oradan ayrılamazlar. Bu büyünün yarattığı mobilyalar ve diğer nesneler, malikaneden çıkarıldığında duman olarak dağılır. Büyü sona erdiğinde, boyut dışı uzayın içindeki tüm yaratıklar, girişe en yakın açık alanlara atılır.","higher":"","sourceText":"You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible.\n\nBeyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.\n\nYou can create any floor plan you like, but the space can't exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine course banquet for up to 100 people. A staff of 100 near-transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can't attack or take any action that would directly harm another creature. Thus the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can't leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures inside the extradimensional space are expelled into the open spaces nearest to the entrance.","higherSource":""},{"id":"major-image","name":"Major Image","nameTr":"Ana Resim","level":3,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz yün.","materialSource":"A bit of fleece.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir 20 ft küpünden daha büyük olmayan bir nesnenin, bir yaratığın veya başka bir görünür olgunun görüntüsünü yaratırsınız. Görüntü, menzil içerisinde görebileceğiniz bir noktada belirir ve bu süre boyunca devam eder. Tasvir edilen şeye uygun sesler, kokular ve sıcaklık da dahil olmak üzere tamamen gerçek görünüyor. Hasara neden olacak yeterli ısıyı veya cold'yi, thunder'ye hasar verecek veya bir yaratığa sağırlık kazandıracak kadar yüksek bir ses veya bir yaratığı hasta edebilecek bir koku (bir ilkel insanın kokusu gibi) oluşturamazsınız.\nYanılsamanın menzili içinde olduğunuz sürece, eyleminizi kullanarak görüntünün menzil içindeki herhangi bir noktaya hareket etmesini sağlayabilirsiniz. Görüntünün konumu değiştikçe, hareketlerinin görüntü için doğal görünmesini sağlayacak şekilde görünümünü değiştirebilirsiniz. Örneğin, bir yaratığın görüntüsünü oluşturup onu hareket ettirirseniz, görüntüyü yürüyormuş gibi görünecek şekilde değiştirebilirsiniz. Benzer şekilde, illüzyonun farklı zamanlarda farklı sesler çıkarmasını, hatta örneğin bir sohbeti sürdürmesini bile sağlayabilirsiniz.\nGörüntüyle fiziksel etkileşim onun bir yanılsama olduğunu ortaya koyuyor çünkü nesneler onun içinden geçebiliyor. Görüntüyü incelemek için eylemini kullanan bir yaratık, DC'yi kaydetme büyünüze karşı başarılı bir INT (Soruşturma) kontrolü ile bunun bir illüzyon olduğunu belirleyebilir. Bir yaratık illüzyonun ne olduğunu anlarsa, yaratık görüntünün arkasını görebilir ve diğer duyusal nitelikleri yaratık için zayıf hale gelir.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, büyü concentration'nize ihtiyaç duymadan etkisiz hale getirilene kadar sürer.","sourceText":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 20-foot cube. The image appears at a spot that you can see within range and lasts for the duration. It seems completely real, including sounds, smells, and temperature appropriate to the thing depicted. You can't create sufficient heat or cold to cause damage, a sound loud enough to deal thunder damage or deafen a creature, or a smell that might sicken a creature (like a troglodyte's stench).\n\nAs long as you are within range of the illusion, you can use your action to cause the image to move to any other spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking. Similarly, you can cause the illusion to make different sounds at different times, even making it carry on a conversation, for example.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and its other sensory qualities become faint to the creature.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled, without requiring your concentration."},{"id":"mass-cure-wounds","name":"Mass Cure Wounds","nameTr":"Yaraları Toplu İyileştirme","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Cleric","Druid"],"subclasses":["Life"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Menzil içinde seçtiğiniz bir noktadan bir şifa enerjisi dalgası yıkanır. Bu noktanın merkezinde bulunan 30 ft yarıçaplı küredeki altıya kadar yaratık seçin. Her hedef, 3d8 + büyü yapma yeteneği değiştiricinize eşit HP'yi yeniden kazanır. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, iyileştirme 5. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"A wave of healing energy washes out from a point of your choice within range. Choose up to six creatures in a 30-foot-radius sphere centered on that point. Each target regains hit points equal to 3d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","higherSource":"When you cast this spell using a spell slot of 6th level or higher, the healing increases by 1d8 for each slot level above 5th."},{"id":"mass-heal","name":"Mass Heal","nameTr":"Toplu İyileşme","level":9,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Sizden etrafınızdaki yaralı yaratıklara bir şifa enerjisi akışı akıyor. Menzil içinde görebileceğiniz herhangi bir sayıdaki yaratık arasından seçtiğiniz sayıda bölüştürerek 700'e kadar HP'yi geri yüklersiniz. Bu büyüyle iyileştirilen yaratıklar aynı zamanda tüm hastalıklardan ve onları blinded veya deafened yapan tüm etkilerden de iyileşir. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"","sourceText":"A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures that you can see within range. Creatures healed by this spell are also cured of all diseases and any effect making them blinded or deafened. This spell has no effect on undead or constructs.","higherSource":""},{"id":"mass-healing-word","name":"Mass Healing Word","nameTr":"Toplu Şifa Kelimesi","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Siz restorasyon sözlerini haykırırken, menzil içinde görebileceğiniz seçtiğiniz en fazla altı yaratık, 1d4 + büyü yapma yeteneği değiştiricinize eşit olan HP'yi yeniden kazanır. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 3. seviyenin üzerindeki her yuva seviyesi için iyileştirme 1d4 artar.","sourceText":"As you call out words of restoration, up to six creatures of your choice that you can see within range regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the healing increases by 1d4 for each slot level above 3rd."},{"id":"mass-suggestion","name":"Mass Suggestion","nameTr":"Toplu Öneri","level":6,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","M"],"materialTr":"Bir yılanın dili ve ya bir parça bal peteği ya da bir damla tatlı yağ.","materialSource":"A snake's tongue and either a bit of honeycomb or a drop of sweet oil.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bir faaliyet planı önerirsiniz (bir veya iki cümleyle sınırlı) ve menzil içinde görebileceğiniz ve sizi duyabilen ve anlayabilen seçtiğiniz on iki canlıya kadar sihirli bir şekilde etkileyebilirsiniz. charmed olamayacak yaratıklar bu etkiye karşı bağışıklıdır. Öneri, eylem planının makul görünmesini sağlayacak şekilde ifade edilmelidir. Yaratığın kendisini bıçaklamasını, bir mızrağa atmasını, kendisini yakmasını veya açıkça zararlı başka bir eylem yapmasını istemek, büyünün etkisini otomatik olarak ortadan kaldırır.\nHer hedefin bir WIS saving throw yapması gerekir. Başarısız bir kaydetme durumunda, tanımladığınız eylem planını elinden gelen en iyi şekilde takip eder. Önerilen eylem planı tüm süre boyunca devam edebilir. Önerilen aktivite daha kısa sürede tamamlanabiliyorsa, deneğin kendisinden isteneni tamamlamasıyla büyü sona erer.\nSüre boyunca özel bir etkinliği tetikleyecek koşulları da belirtebilirsiniz. Örneğin bir grup askere, karşılaştıkları ilk dilenciye tüm paralarını vermelerini önerebilirsiniz. Büyü sona ermeden koşul karşılanmazsa etkinlik gerçekleştirilmez.\nSiz veya arkadaşlarınızdan herhangi biri bu büyüden etkilenen bir yaratığa zarar verirse, o canlının büyüsü sona erer.","higher":"Bu büyüyü 7. seviye spell slot kullanarak yaptığınızda, süresi 10 gündür. 8. seviye spell slot kullandığınızda süre 30 gündür. 9. seviye spell slot kullandığınızda süre bir yıl bir gündür.","sourceText":"You suggest a course of activity (limited to a sentence or two) and magically influence up to twelve creatures of your choice that you can see within range and that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act automatically negates the effect of the spell.\n\nEach target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a group of soldiers give all their money to the first beggar they meet. If the condition isn't met before the spell ends, the activity isn't performed.\n\nIf you or any of your companions damage a creature affected by this spell, the spell ends for that creature.","higherSource":"When you cast this spell using a 7th-level spell slot, the duration is 10 days. When you use an 8th-level spell slot, the duration is 30 days. When you use a 9th-level spell slot, the duration is a year and a day."},{"id":"maze","name":"Maze","nameTr":"Labirent","level":8,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir yaratığı labirent benzeri bir yarı düzleme sürgün edersiniz. Hedef, labirentten çıkana kadar veya labirentten çıkana kadar orada kalır.\nHedef, kaçmaya çalışmak için eylemini kullanabilir. Bunu yaptığında DC 20 INT kontrolü yapar. Başarılı olursa kaçar ve büyü sona erer (bir minotaur veya goristro iblisi otomatik olarak başarılı olur).\nBüyü sona erdiğinde hedef, bıraktığı alanda veya o alan doluysa en yakın boş alanda yeniden belirir.","higher":"","sourceText":"You banish a creature that you can see within range into a labyrinthine demiplane. The target remains there for the duration or until it escapes the maze.\n\nThe target can use its action to attempt to escape. When it does so, it makes a DC 20 Intelligence check. If it succeeds, it escapes, and the spell ends (a minotaur or goristro demon automatically succeeds).\n\nWhen the spell ends, the target reappears in the space it left or, if that space is occupied, in the nearest unoccupied space.","higherSource":""},{"id":"meld-into-stone","name":"Meld Into Stone","nameTr":"Taşa Erimek","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"8 hours","concentration":false,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Vücudunuzu tamamen kaplayacak kadar geniş bir taş nesneye veya yüzeye adım atıyorsunuz, kendinizi ve taşıdığınız tüm ekipmanı bu süre boyunca taşla birleştiriyorsunuz. Hareketinizi kullanarak dokunabileceğiniz bir noktada taşın üzerine basıyorsunuz. Varlığınızın hiçbir şeyi görünür kalmaz veya büyülü olmayan duyular tarafından başka bir şekilde algılanamaz.\nTaşla birleştiğinde dışında ne olduğunu göremezsiniz ve onun dışındaki sesleri duymak için yaptığınız her türlü WIS (Algı) kontrolleri dezavantaj ile yapılır. Zamanın geçtiğinin farkında olursunuz ve taşa karışmışken kendinize büyü yapabilirsiniz. Taşı girdiğiniz yerde bırakmak için hareketinizi kullanabilirsiniz, bu da büyüyü sona erdirir. Aksi takdirde hareket edemezsiniz.\nTaşa verilen küçük fiziksel hasar size zarar vermez, ancak kısmen yok olması veya şeklindeki bir değişiklik (artık içine sığamayacağınız ölçüde) sizi dışarı atar ve bludgeoning size bludgeoning hasarı verir. Taşın tamamen yok olması (ya da farklı bir maddeye dönüşmesi) sizi dışarı atar ve 50 bludgeoning hasar verir. Eğer atılırsanız, prone ilk girdiğiniz yere en yakın boş alana düşersiniz.","higher":"","sourceText":"You step into a stone object or surface large enough to fully contain your body, melding yourself and all the equipment you carry with the stone for the duration. Using your movement, you step into the stone at a point you can touch. Nothing of your presence remains visible or otherwise detectable by nonmagical senses.\n\nWhile merged with the stone, you can't see what occurs outside it, and any Wisdom (Perception) checks you make to hear sounds outside it are made with disadvantage. You remain aware of the passage of time and can cast spells on yourself while merged in the stone. You can use your movement to leave the stone where you entered it, which ends the spell. You otherwise can't move.\n\nMinor physical damage to the stone doesn't harm you, but its partial destruction or a change in its shape (to the extent that you no longer fit within it) expels you and deals 6d6 bludgeoning damage to you. The stone's complete destruction (or transmutation into a different substance) expels you and deals 50 bludgeoning damage to you. If expelled, you fall prone in an unoccupied space closest to where you first entered.","higherSource":""},{"id":"mending","name":"Mending","nameTr":"Tamir","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Cleric","Druid","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"İki mıknatıs taşı.","materialSource":"Two lodestones.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, dokunduğunuz bir nesnedeki (kırık bir anahtar, yırtık bir pelerin veya sızdıran bir şarap tulumu gibi) tek bir kırılmayı veya yırtığı onarır. Kırılma veya yırtılma herhangi bir boyutta 1 ft'den uzun olmadığı sürece, eski hasardan hiçbir iz bırakmadan onarırsınız.\nBu büyü, sihirli bir öğeyi veya yapıyı fiziksel olarak onarabilir, ancak büyü, böyle bir nesnenin büyüsünü geri getiremez.","higher":"","sourceText":"This spell repairs a single break or tear in an object you touch, such as a broken key, a torn cloak, or a leaking wineskin. As long as the break or tear is no longer than 1 foot in any dimension, you mend it, leaving no trace of the former damage.\n\nThis spell can physically repair a magic item or construct, but the spell can't restore magic to such an object.","higherSource":""},{"id":"message","name":"Message","nameTr":"Mesaj","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Kısa bir bakır tel parçası.","materialSource":"A short piece of copper wire.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Parmağınızı menzil içindeki bir yaratığa doğrultup bir mesaj fısıldarsınız. Hedef (ve yalnızca hedef) mesajı duyar ve yalnızca sizin duyabileceğiniz bir fısıltıyla yanıt verebilir.\nHedefi tanıyorsanız ve onun bariyerin ötesinde olduğunu biliyorsanız, bu büyüyü katı nesneler aracılığıyla yapabilirsiniz. Büyülü sessizlik, 1 ft taş, 1 inçlik sıradan metal, ince bir kurşun levha veya 3 ft ahşap büyüyü engeller. Büyünün düz bir çizgi izlemesi gerekmez ve köşelerden veya açıklıklardan serbestçe geçebilir.","higher":"","sourceText":"You point your finger toward a creature within range and whisper a message. The target (and only the target) hears the message and can reply in a whisper that only you can hear.\n\nYou can cast this spell through solid objects if you are familiar with the target and know it is beyond the barrier. Magical silence, 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood blocks the spell. The spell doesn't have to follow a straight line and can travel freely around corners or through openings.","higherSource":""},{"id":"meteor-swarm","name":"Meteor Swarm","nameTr":"Meteor Sürüsü","level":9,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"1 mile","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"sphere","size":40},"description":"fire'nin yanan küreleri menzil içinde görebileceğiniz dört farklı noktada yere düşüyor. Seçtiğiniz her noktanın merkezinde yer alan 40 ft yarıçaplı küredeki her yaratık, bir DEX saving throw yapmalıdır. Küre köşelere yayılıyor. Bir yaratık, başarısız save’de 20d6 fire hasarı ve 20d6 bludgeoning hasarı veya başarılı save’de yarısı kadar hasar alır. Birden fazla ateşli patlamanın olduğu bölgedeki bir yaratık yalnızca bir kez etkilenir.\nBüyü, bölgedeki nesnelere zarar verir ve giyilmeyen veya taşınmayan yanıcı nesneleri ateşler.","higher":"","sourceText":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere centered on each point you choose must make a dexterity saving throw. The sphere spreads around corners. A creature takes 20d6 fire damage and 20d6 bludgeoning damage on a failed save, or half as much damage on a successful one. A creature in the area of more than one fiery burst is affected only once.\n\nThe spell damages objects in the area and ignites flammable objects that aren't being worn or carried.","higherSource":""},{"id":"mind-blank","name":"Mind Blank","nameTr":"Zihin Boş","level":8,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü bitene kadar, dokunduğunuz istekli bir yaratık, psychic hasarına, onun duygularını algılayacak veya düşüncelerini okuyacak herhangi bir etkiye, kehanet büyülerine ve charmed durumuna karşı bağışıklıdır. Hatta büyü, hedefin zihnini etkilemek veya hedef hakkında bilgi edinmek için kullanılan dilek büyülerini, büyüleri veya benzer güçteki etkileri bile engeller.","higher":"","sourceText":"Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and spells or effects of similar power used to affect the target's mind or to gain information about the target.","higherSource":""},{"id":"minor-illusion","name":"Minor Illusion","nameTr":"Küçük Yanılsama","level":0,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["S","M"],"materialTr":"Biraz yün.","materialSource":"A bit of fleece.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki bir nesnenin, süre boyunca süren bir sesini veya görüntüsünü yaratırsınız. İllüzyon, bunu bir eylem olarak görmezden gelirseniz veya bu büyüyü tekrar yaparsanız da sona erer.\nBir ses yaratırsanız, ses düzeyi fısıltıdan çığlığa kadar değişebilir. Bu sizin sesiniz, bir başkasının sesi, bir aslanın kükremesi, davul sesi veya seçtiğiniz herhangi bir ses olabilir. Ses, bu süre boyunca azalmadan devam eder veya büyü sona ermeden farklı zamanlarda ayrı ayrı sesler çıkartabilirsiniz.\nBir sandalye, çamurlu ayak izleri veya küçük bir sandık gibi bir nesnenin görüntüsünü oluşturursanız, bunun 5 ft küpten daha büyük olmaması gerekir. Görüntü ses, ışık, koku veya başka herhangi bir duyusal etki yaratamaz. Görüntüyle fiziksel etkileşim onun bir yanılsama olduğunu ortaya koyuyor çünkü nesneler onun içinden geçebiliyor.\nBir yaratık, sesi veya görüntüyü incelemek için eylemini kullanırsa yaratık, DC'yi kurtaran büyünüze karşı başarılı bir INT (Soruşturma) kontrolüyle bunun bir illüzyon olduğunu belirleyebilir. Eğer bir yaratık illüzyonun ne olduğunu anlarsa, illüzyon yaratık için sönükleşir.","higher":"","sourceText":"You create a sound or an image of an object within range that lasts for the duration. The illusion also ends if you dismiss it as an action or cast this spell again.\n\nIf you create a sound, its volume can range from a whisper to a scream. It can be your voice, someone else's voice, a lion's roar, a beating of drums, or any other sound you choose. The sound continues unabated throughout the duration, or you can make discrete sounds at different times before the spell ends.\n\nIf you create an image of an object--such as a chair, muddy footprints, or a small chest--it must be no larger than a 5-foot cube. The image can't create sound, light, smell, or any other sensory effect. Physical interaction with the image reveals it to be an illusion, because things can pass through it.\n\nIf a creature uses its action to examine the sound or image, the creature can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the illusion becomes faint to the creature.","higherSource":""},{"id":"mirage-arcane","name":"Mirage Arcane","nameTr":"Mirage Gizemli","level":7,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Druid","Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"Sight","duration":"10 days","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":5280},"description":"1 mil'ye kadar bir alandaki araziyi kare görünüm, ses, koku haline getirir ve hatta başka tür bir arazi gibi hissedersiniz. Ancak arazinin genel şekli aynı kalıyor. Açık alanlar veya bir yol, bir bataklığa, tepeye, yarığa veya başka zor veya geçilmez araziye benzeyecek şekilde yapılabilir. Bir gölet çimenli bir çayır gibi, bir uçurum hafif bir eğim gibi veya kayalarla kaplı bir oluk geniş ve pürüzsüz bir yol gibi görünebilir.\nBenzer şekilde yapıların görünümünü değiştirebilir veya mevcut olmayan yerlere bunları ekleyebilirsiniz. Büyü yaratıkları gizlemez, gizlemez veya eklemez.\nİllüzyon işitsel, görsel, dokunsal ve koku alma unsurlarını içerir, böylece açık zemini zorlu araziye dönüştürebilir (veya tam tersi) veya alandaki hareketi başka şekilde engelleyebilir. Büyü alanından kaldırılan hayali arazinin herhangi bir parçası (kaya veya sopa gibi) anında kaybolur.\nGerçek görüşe sahip yaratıklar, yanılsamanın içinden arazinin gerçek biçimini görebilirler; ancak yanılsamanın diğer tüm unsurları kalır, dolayısıyla yaratık yanılsamanın varlığının farkında olsa da yaratık yine de yanılsamayla fiziksel olarak etkileşime girebilir.","higher":"","sourceText":"You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain's general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road.\n\nSimilarly, you can alter the appearance of structures, or add them where none are present. The spell doesn't disguise, conceal, or add creatures.\n\nThe illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell's area disappears immediately.\n\nCreatures with truesight can see through the illusion to the terrain's true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion's presence, the creature can still physically interact with the illusion.","higherSource":""},{"id":"mirror-image","name":"Mirror Image","nameTr":"Ayna Görüntüsü","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Self","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Alanınızda kendinizin üç hayali kopyası beliriyor. Büyü sona erene kadar kopyalar sizinle birlikte hareket eder ve hareketlerinizi taklit ederek konum değiştirir, böylece hangi görüntünün gerçek olduğunu takip etmek imkansızdır. Hayali kopyaları ortadan kaldırmak için eyleminizi kullanabilirsiniz.\nBüyünün süresi boyunca bir yaratığın sizi bir saldırı ile hedeflediği her defasında, saldırının kopyalarınızdan birini hedef alıp almadığını belirlemek için bir d20 yuvarlayın.\nÜç kopyanız varsa, saldırının hedefini kopya olarak değiştirmek için 6 veya daha yüksek bir sayı atmanız gerekir. İki kopya durumunda 8 veya daha yüksek bir sayı atmalısınız. Bir kopya ile 11 veya daha yüksek bir sayı atmalısınız.\nBir kopyanın AC'si 10 + DEX değiştiricinize eşittir. Bir saldırı kopyaya isabet ederse kopya yok edilir. Bir kopya yalnızca ona çarpan bir saldırıyla yok edilebilir. Diğer tüm hasar ve etkileri göz ardı eder. Büyü, üç kopyanın tümü yok edildiğinde sona erer.\nBir canlı göremiyorsa, görme dışında kör görüş gibi duyulara güveniyorsa veya gerçek görüşte olduğu gibi illüzyonları sahte olarak algılayabiliyorsa bu büyüden etkilenmez.","higher":"","sourceText":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates.\n\nEach time a creature targets you with an attack during the spell's duration, roll a d20 to determine whether the attack instead targets one of your duplicates.\n\nIf you have three duplicates, you must roll a 6 or higher to change the attack's target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.\n\nA duplicate's AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.\n\nA creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight.","higherSource":""},{"id":"mislead","name":"Mislead","nameTr":"yanıltıcı","level":5,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Durduğunuz yerde hayali bir ikiziniz belirdiği anda invisible olursunuz. Çifte bu süre boyunca sürer, ancak saldırırsanız veya büyü yaparsanız görünmezlik sona erer.\nEyleminizi, hayali çiftinizi hızınızın iki katına kadar hareket ettirmek ve onun seçtiğiniz şekilde hareket etmesini, konuşmasını ve davranmasını sağlamak için kullanabilirsiniz.\nSanki bulunduğu yerdeymişsiniz gibi onun gözleriyle görebilir, kulaklarıyla duyabilirsiniz. Bir Bonus Action olarak her turunuzda, duyularınızı kullanmaktan kendi duyularınızı kullanmaya veya tekrar duyularınızı kullanmaya geçiş yapabilirsiniz. Onun duyularını kullanırken, kendi çevrenize göre blinded ve deafened olursunuz.","higher":"","sourceText":"You become invisible at the same time that an illusory double of you appears where you are standing. The double lasts for the duration, but the invisibility ends if you attack or cast a spell.\n\nYou can use your action to move your illusory double up to twice your speed and make it gesture, speak, and behave in whatever way you choose.\n\nYou can see through its eyes and hear through its ears as if you were located where it is. On each of your turns as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.","higherSource":""},{"id":"misty-step","name":"Misty Step","nameTr":"Sisli Adım","level":2,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 bonus action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kısa bir süre gümüşi sisle çevrelenmiş olarak 30 ft'ye görebildiğiniz boş bir alana ışınlanırsınız.","higher":"","sourceText":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see.","higherSource":""},{"id":"modify-memory","name":"Modify Memory","nameTr":"Belleği Değiştir","level":5,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Başka bir yaratığın anılarını yeniden şekillendirmeye çalışırsınız. Görebileceğiniz bir yaratık WIS saving throw yapmalıdır. Yaratıkla savaşıyorsanız, saving throw üzerinde avantaj vardır. Başarısız bir kaydetme durumunda hedef, bu süre boyunca sizin tarafınızdan charmed olur. charmed hedefi incapacitated'dir ve çevresinden habersiz olmasına rağmen sizi hâlâ duyabilmektedir. Herhangi bir hasar alırsa veya başka bir büyü tarafından hedef alınırsa, bu büyü sona erer ve hedefin hiçbir hafızası değişmez.\nBu büyü devam ederken, hedefin son 24 saat içinde yaşadığı ve 10 dakikadan fazla sürmeyen bir olaya ilişkin hafızasını etkileyebilirsiniz. Olayın tüm hafızasını kalıcı olarak ortadan kaldırabilir, hedefin olayı mükemmel bir netlik ve titiz ayrıntılarla hatırlamasına izin verebilir, olayın ayrıntılarına ilişkin hafızasını değiştirebilir veya başka bir olayın hafızasını yaratabilirsiniz.\nAnılarının nasıl etkilendiğini anlatmak için hedefle konuşmalısınız ve değiştirilmiş anıların kök salması için hedefin dilinizi anlayabilmesi gerekir. Onun zihni, açıklamanızın ayrıntılarındaki tüm boşlukları doldurur. Eğer büyü, değiştirilen anıları tanımlamayı tamamlamadan sona ererse, yaratığın hafızası değişmeyecektir. Aksi takdirde, büyü sona erdiğinde değiştirilen anılar hafızaya alınır.\nDeğiştirilmiş bir hafıza, özellikle hafıza yaratığın doğal eğilimleri, yönelimi veya inançlarıyla çelişiyorsa, bir yaratığın nasıl davrandığını mutlaka etkilemez. Yaratığın acid'ye dalmaktan ne kadar keyif aldığına dair bir anıyı yerleştirmek gibi mantıksız şekilde değiştirilmiş bir anı, belki de kötü bir rüya olarak değerlendirilerek göz ardı edilir. GM, değiştirilmiş bir hafızanın bir yaratığı önemli bir şekilde etkilemeyecek kadar saçma olduğunu düşünebilir.\nHedefe yapılan bir laneti kaldırma veya daha büyük bir yenileme büyüsü, yaratığın gerçek hafızasını geri yükler.","higher":"Bu büyüyü 6. seviye veya daha yüksek bir spell slot kullanarak yaparsanız, hedefin 7 gün öncesine kadar (6. seviye), 30 gün öncesine kadar (7. seviye), 1 yıl öncesine kadar (8. seviye) veya yaratığın geçmişinde herhangi bir zamanda (9. seviye) meydana gelen bir olaya ilişkin anılarını değiştirebilirsiniz.","sourceText":"You attempt to reshape another creature's memories. One creature that you can see must make a wisdom saving throw. If you are fighting the creature, it has advantage on the saving throw. On a failed save, the target becomes charmed by you for the duration. The charmed target is incapacitated and unaware of its surroundings, though it can still hear you. If it takes any damage or is targeted by another spell, this spell ends, and none of the target's memories are modified.\n\nWhile this charm lasts, you can affect the target's memory of an event that it experienced within the last 24 hours and that lasted no more than 10 minutes. You can permanently eliminate all memory of the event, allow the target to recall the event with perfect clarity and exacting detail, change its memory of the details of the event, or create a memory of some other event.\n\nYou must speak to the target to describe how its memories are affected, and it must be able to understand your language for the modified memories to take root. Its mind fills in any gaps in the details of your description. If the spell ends before you have finished describing the modified memories, the creature's memory isn't altered. Otherwise, the modified memories take hold when the spell ends.\n\nA modified memory doesn't necessarily affect how a creature behaves, particularly if the memory contradicts the creature's natural inclinations, alignment, or beliefs. An illogical modified memory, such as implanting a memory of how much the creature enjoyed dousing itself in acid, is dismissed, perhaps as a bad dream. The GM might deem a modified memory too nonsensical to affect a creature in a significant manner.\n\nA remove curse or greater restoration spell cast on the target restores the creature's true memory.","higherSource":"If you cast this spell using a spell slot of 6th level or higher, you can alter the target's memories of an event that took place up to 7 days ago (6th level), 30 days ago (7th level), 1 year ago (8th level), or any time in the creature's past (9th level)."},{"id":"moonbeam","name":"Moonbeam","nameTr":"Ay ışığı","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Herhangi bir ay tohumu bitkisinin birkaç tohumu ve bir parça yanardöner feldispat.","materialSource":"Several seeds of any moonseed plant and a piece of opalescent feldspar.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"cylinder","size":5},"description":"Gümüş rengi soluk bir ışık huzmesi 5 ft yarıçapında parlıyor, 40 ft yükseklik silindiri menzil içindeki bir noktaya odaklanıyor. Büyü bitene kadar loş ışık silindiri doldurur.\nBir yaratık büyü alanına ilk kez bir dönüşte girdiğinde veya dönüşüne orada başladığında, yakıcı acıya neden olan hayaletimsi alevler tarafından yutulur ve bir CON saving throw yapması gerekir. başarısız save’de 2d10 radiant hasar alır veya başarılı save’de yarısı kadar hasar alır.\nBir şekil değiştirici, saving throw'yi dezavantaj ile yapar. Başarısız olması durumunda anında orijinal formuna geri döner ve büyünün ışığından çıkana kadar farklı bir forma bürünemez.\nBu büyüyü yaptıktan sonraki her dönüşünüzde, 60 ft ışını herhangi bir yöne hareket ettirmek için bir eylem kullanabilirsiniz.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 2. seviyenin üzerindeki her slot seviyesi için 1dl0 artar.","sourceText":"A silvery beam of pale light shines down in a 5-foot radius, 40-foot-high cylinder centered on a point within range. Until the spell ends, dim light fills the cylinder.\n\nWhen a creature enters the spell's area for the first time on a turn or starts its turn there, it is engulfed in ghostly flames that cause searing pain, and it must make a constitution saving throw. It takes 2d10 radiant damage on a failed save, or half as much damage on a successful one.\n\nA shapechanger makes its saving throw with disadvantage. If it fails, it also instantly reverts to its original form and can't assume a different form until it leaves the spell's light.\n\nOn each of your turns after you cast this spell, you can use an action to move the beam 60 feet in any direction.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1dl0 for each slot level above 2nd."},{"id":"move-earth","name":"Move Earth","nameTr":"Dünyayı Taşı","level":6,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 2 hours","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Demir bir bıçak ve toprak, kil, balçık ve kum karışımı içeren küçük bir torba.","materialSource":"An iron blade and a small bag containing a mixture of soils--clay, loam, and sand.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cone","size":40},"description":"Menzil içindeki bir tarafta 40 ft'den daha büyük olmayan bir arazi alanı seçin. Süre boyunca bölgedeki kiri, kumu veya kili istediğiniz şekilde yeniden şekillendirebilirsiniz. Alanın yüksekliğini yükseltebilir veya alçaltabilirsiniz, bir hendek oluşturabilir veya doldurabilirsiniz, bir duvarı dikebilir veya düzleştirebilirsiniz ya da bir sütun oluşturabilirsiniz. Bu tür değişikliklerin kapsamı alanın en büyük boyutunun yarısını aşamaz. Dolayısıyla, bir 40 ft karesini etkilerseniz, 20 ft yüksekliğe kadar bir sütun oluşturabilir, karenin yüksekliğini 20 ft'ye kadar yükseltebilir veya alçaltabilir, 20 ft derinliğe kadar bir hendek kazabilirsiniz vb. Bu değişikliklerin tamamlanması 10 dakika sürer.\nBüyüye konsantre olarak harcadığınız her 10 dakikanın sonunda etkilenecek yeni bir arazi alanı seçebilirsiniz.\nArazinin dönüşümü yavaş gerçekleştiğinden, bölgedeki canlılar genellikle yerin hareketinden dolayı tuzağa düşürülemez veya yaralanamaz.\nBu büyü doğal taşı veya taş yapıyı değiştiremez. Kayalar ve yapılar yeni araziye uyum sağlamak için değişiyor. Eğer araziyi şekillendirme şekliniz bir yapıyı dengesiz hale getirecekse, yapı çökebilir.\nBenzer şekilde bu büyü bitki büyümesini doğrudan etkilemez. Taşınan toprak, her türlü bitkiyi de beraberinde taşır.","higher":"","sourceText":"Choose an area of terrain no larger than 40 feet on a side within range. You can reshape dirt, sand, or clay in the area in any manner you choose for the duration. You can raise or lower the area's elevation, create or fill in a trench, erect or flatten a wall, or form a pillar. The extent of any such changes can't exceed half the area's largest dimension. So, if you affect a 40-foot square, you can create a pillar up to 20 feet high, raise or lower the square's elevation by up to 20 feet, dig a trench up to 20 feet deep, and so on. It takes 10 minutes for these changes to complete.\n\nAt the end of every 10 minutes you spend concentrating on the spell, you can choose a new area of terrain to affect.\n\nBecause the terrain's transformation occurs slowly, creatures in the area can't usually be trapped or injured by the ground's movement.\n\nThis spell can't manipulate natural stone or stone construction. Rocks and structures shift to accommodate the new terrain. If the way you shape the terrain would make a structure unstable, it might collapse.\n\nSimilarly, this spell doesn't directly affect plant growth. The moved earth carries any plants along with it.","higherSource":""},{"id":"nondetection","name":"Nondetection","nameTr":"Tespit edilmeme","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Ranger","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği hedefin üzerine 25 gp değerinde bir tutam elmas tozu serpilir.","materialSource":"A pinch of diamond dust worth 25 gp sprinkled over the target, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca dokunduğunuz hedefi kehanet büyüsünden gizlersiniz. Hedef istekli bir yaratık veya herhangi bir boyutta 10 ft'den daha büyük olmayan bir yer veya nesne olabilir. Hedef, herhangi bir kehanet büyüsü ile hedef alınamaz veya büyülü tarama sensörleri aracılığıyla algılanamaz.","higher":"","sourceText":"For the duration, you hide a target that you touch from divination magic. The target can be a willing creature or a place or an object no larger than 10 feet in any dimension. The target can't be targeted by any divination magic or perceived through magical scrying sensors.","higherSource":""},{"id":"pass-without-trace","name":"Pass Without Trace","nameTr":"İzsiz Geçiş","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Druid","Ranger"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Yanmış bir ökse otu yaprağının ve bir ladin dalının külleri.","materialSource":"Ashes from a burned leaf of mistletoe and a sprig of spruce.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Sizden bir gölge ve sessizlik perdesi yayılıyor, sizi ve arkadaşlarınızı tespit edilmekten maskeliyor. Bu süre boyunca, 30 ft içinde seçtiğiniz her yaratık (siz de dahil), DEX (Gizlilik) kontrollerine yönelik +10 bonusa sahiptir ve sihirli yöntemler dışında takip edilemez. Bu bonusu alan yaratık, arkasında hiçbir iz veya geçişine dair başka bir iz bırakmaz.","higher":"","sourceText":"A veil of shadows and silence radiates from you, masking you and your companions from detection. For the duration, each creature you choose within 30 feet of you (including you) has a +10 bonus to Dexterity (Stealth) checks and can't be tracked except by magical means. A creature that receives this bonus leaves behind no tracks or other traces of its passage.","higherSource":""},{"id":"passwall","name":"Passwall","nameTr":"Geçiş duvarı","level":5,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"30 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam susam.","materialSource":"A pinch of sesame seeds.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil dahilindeki ahşap, alçı veya taş yüzeyde (duvar, tavan, zemin gibi) görebileceğiniz, seçtiğiniz bir noktada bir geçit belirir ve bu süre boyunca devam eder. Açıklığın boyutlarını siz seçersiniz: 5 ft genişliğe, 8 ft uzunluğa ve 20 ft derinliğe kadar. Geçit, onu çevreleyen yapıda herhangi bir istikrarsızlık yaratmaz.\nAçıklık kaybolduğunda, hala büyünün yarattığı geçitte bulunan yaratıklar veya nesneler, büyüyü yaptığınız yüzeye en yakın boş alana güvenli bir şekilde fırlatılır.","higher":"","sourceText":"A passage appears at a point of your choice that you can see on a wooden, plaster, or stone surface (such as a wall, a ceiling, or a floor) within range, and lasts for the duration. You choose the opening's dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in a structure surrounding it.\n\nWhen the opening disappears, any creatures or objects still in the passage created by the spell are safely ejected to an unoccupied space nearest to the surface on which you cast the spell.","higherSource":""},{"id":"phantasmal-killer","name":"Phantasmal Killer","nameTr":"Hayalet Katil","level":4,"school":"Illusion","schoolTr":"İllüzyon","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir yaratığın kabuslarından yararlanırsınız ve onun en derin korkularının yalnızca o yaratığın görebileceği yanıltıcı bir tezahürünü yaratırsınız. Hedefin bir WIS saving throw yapması gerekir. Başarısız bir kaydetme durumunda hedef, süre boyunca frightened olur. Hedefin her turunun başlangıcında, büyü sona ermeden önce, hedefin bir WIS saving throw üzerinde başarılı olması veya 4d10 psychic hasarı alması gerekir. Başarılı bir kaydetmeyle büyü sona erer.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 4. seviyenin üzerindeki her yuva seviyesi için 1d10 artar.","sourceText":"You tap into the nightmares of a creature you can see within range and create an illusory manifestation of its deepest fears, visible only to that creature. The target must make a wisdom saving throw. On a failed save, the target becomes frightened for the duration. At the start of each of the target's turns before the spell ends, the target must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d10 for each slot level above 4th."},{"id":"phantom-steed","name":"Phantom Steed","nameTr":"Hayalet Küheylan","level":3,"school":"Illusion","schoolTr":"İllüzyon","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"30 feet","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil dahilinde seçtiğiniz boş bir alanda yerde büyük, yarı gerçek, ata benzer bir yaratık belirir. Yaratığın görünümüne siz karar verirsiniz ancak bir eyer, kantarma ve dizginle donatılmıştır. Büyü tarafından oluşturulan herhangi bir ekipman, eğer attan 10 ft'den daha uzağa taşınırsa, bir duman bulutu içinde yok olur.\nBu süre boyunca siz veya seçtiğiniz bir yaratık ata binebilir. Yaratık, 100 ft hızına sahip olması ve 10 mil'yi bir saatte veya 13 mil'yi hızlı bir şekilde kat edebilmesi dışında, bir binicilik atı için istatistikleri kullanıyor. Büyü sona erdiğinde at yavaş yavaş kaybolur ve biniciye atından inmesi için 1 dakika süre tanınır. Büyüyü yok etmek için bir eylem kullandığınızda veya küheylan herhangi bir hasar aldığında büyü sona erer.","higher":"","sourceText":"A Large quasi-real, horselike creature appears on the ground in an unoccupied space of your choice within range. You decide the creature's appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is carried more than 10 feet away from the steed.\n\nFor the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it or if the steed takes any damage.","higherSource":""},{"id":"planar-ally","name":"Planar Ally","nameTr":"Düzlemsel Müttefik","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":[],"castingTime":"10 minutes","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Yardım için dünya dışı bir varlığa yalvarıyorsunuz. Varlık sizin tarafınızdan bilinmelidir: bir tanrı, bir ilkel, bir şeytan prens veya kozmik güce sahip başka bir varlık. Bu varlık size yardım etmek için bir göksel, bir elemental veya kendisine sadık bir iblis göndererek yaratığın menzil içindeki boş bir alanda görünmesini sağlar. Belirli bir yaratığın adını biliyorsanız, o yaratığı istemek için bu büyüyü yaptığınızda bu adı söyleyebilirsiniz, ancak yine de farklı bir yaratık elde edebilirsiniz (GM'nin seçimi).\nYaratık ortaya çıktığında, herhangi bir şekilde davranma zorunluluğu yoktur. Yaratıktan ödeme karşılığında bir hizmet yapmasını isteyebilirsiniz, ancak yaratık bunu yapmak zorunda değildir. İstenen görev basitten (bizi uçurumun üzerinden uçurmak veya savaşta savaşmamıza yardım etmek) kadar karmaşık (düşmanlarımızı gözetlemek veya zindana baskın sırasında bizi korumak) arasında değişebilir. Hizmetleri için pazarlık yapabilmek için yaratıkla iletişim kurabilmeniz gerekir.\nÖdeme çeşitli şekillerde olabilir. Bir göksel, müttefik bir tapınağa büyük miktarda altın veya büyülü eşya bağışına ihtiyaç duyabilirken, bir iblis canlı bir kurban veya bir hazine hediyesi talep edebilir. Bazı yaratıklar, sizin tarafınızdan üstlenilen bir görev karşılığında hizmetlerini değiştirebilirler.\nGenel bir kural olarak, dakikalarla ölçülebilen bir görev, dakikada 100 gp değerinde bir ödeme gerektirir. Saat cinsinden ölçülen bir görev, saatte 1.000 gp gerektirir. Günlerle ölçülen bir görev (10 güne kadar) günde 10.000 gp gerektirir. GM, büyüyü yaptığınız koşullara bağlı olarak bu ödemeleri ayarlayabilir. Görev yaratığın ahlakına uygunsa ödeme yarıya indirilebilir, hatta feragat edilebilir. Tehlikeli olmayan görevler genellikle önerilen ödemenin yalnızca yarısını gerektirirken, özellikle tehlikeli görevler daha büyük bir hediye gerektirebilir. Yaratıklar nadiren intihar gibi görünen görevleri kabul ederler.\nYaratık, görevi tamamladıktan sonra veya kararlaştırılan hizmet süresi dolduğunda, yaratık, eğer göreve uygunsa ve mümkünse size rapor vererek ana uçağına geri döner. Yaratığın hizmeti için bir fiyatta anlaşamazsanız, yaratık hemen ana uçağına geri döner.\nGrubunuza katılmak üzere kaydedilen bir yaratık, grubun bir üyesi olarak sayılır ve verilen deneyim puanlarının tam payını alır.","higher":"","sourceText":"You beseech an otherworldly entity for aid. The being must be known to you: a god, a primordial, a demon prince, or some other being of cosmic power. That entity sends a celestial, an elemental, or a fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature's name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM's choice).\n\nWhen the creature appears, it is under no compulsion to behave in any particular way. You can ask the creature to perform a service in exchange for payment, but it isn't obliged to do so. The requested task could range from simple (fly us across the chasm, or help us fight a battle) to complex (spy on our enemies, or protect us during our foray into the dungeon). You must be able to communicate with the creature to bargain for its services.\n\nPayment can take a variety of forms. A celestial might require a sizable donation of gold or magic items to an allied temple, while a fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you.\n\nAs a rule of thumb, a task that can be measured in minutes requires a payment worth 100 gp per minute. A task measured in hours requires 1,000 gp per hour. And a task measured in days (up to 10 days) requires 10,000 gp per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature's ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that seem suicidal.\n\nAfter the creature completes the task, or when the agreed-upon duration of service expires, the creature returns to its home plane after reporting back to you, if appropriate to the task and if possible. If you are unable to agree on a price for the creature's service, the creature immediately returns to its home plane.\n\nA creature enlisted to join your group counts as a member of it, receiving a full share of experience points awarded.","higherSource":""},{"id":"planar-binding","name":"Planar Binding","nameTr":"Düzlemsel Bağlama","level":5,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Druid","Wizard"],"subclasses":[],"castingTime":"1 hour","range":"60 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 1.000 GP değerinde bir mücevher.","materialSource":"A jewel worth at least 1,000 gp, which the spell consumes.","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":null,"description":"Bu büyüyle, bir gökseli, bir elementali, bir periyi veya bir iblisi hizmetinize bağlamaya çalışırsınız. Yaratığın büyünün tamamı boyunca menzil içinde olması gerekir. (Genellikle yaratık, bu büyü yapılırken tuzağa düşürülmesi için önce ters çevrilmiş bir sihirli dairenin merkezine çağrılır.) Yapılması tamamlandığında, hedefin bir CHA saving throw yapması gerekir. Başarısız bir kaydetme durumunda, bu süre boyunca size hizmet vermesi zorunludur. Yaratık başka bir büyü tarafından çağrıldıysa veya yaratıldıysa, o büyünün süresi, bu büyünün süresine uyacak şekilde uzatılır.\nBağlı bir yaratık, talimatlarınıza elinden geldiğince uymalıdır. Yaratığa bir macerada size eşlik etmesini, bir yeri korumasını veya bir mesaj iletmesini emredebilirsiniz. Yaratık, talimatlarınızın lafzına uyar, ancak eğer yaratık size düşman ise, kendi amaçlarına ulaşmak için sözlerinizi çarpıtmaya çalışır. Eğer yaratık, büyü bitmeden talimatlarınızı eksiksiz yerine getirirse, aynı varoluş düzlemindeyseniz bu gerçeği bildirmek için size doğru gelir. Eğer farklı bir varoluş düzlemindeyseniz, onu sınırladığınız yere geri döner ve büyü bitene kadar orada kalır.","higher":"Bu büyüyü daha yüksek seviyedeki bir spell slot kullanarak yaptığınızda, süre 6. seviye yuvayla 10 güne, 7. seviye yuvayla 30 güne, 8. seviye yuvayla 180 güne ve 9. seviye spell slot ile bir yıl ve bir güne çıkar.","sourceText":"With this spell, you attempt to bind a celestial, an elemental, a fey, or a fiend to your service. The creature must be within range for the entire casting of the spell. (Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast.) At the completion of the casting, the target must make a charisma saving throw. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell's duration is extended to match the duration of this spell.\n\nA bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends.","higherSource":"When you cast this spell using a spell slot of a higher level, the duration increases to 10 days with a 6th-level slot, to 30 days with a 7th-level slot, to 180 days with an 8th-level slot, and to a year and a day with a 9th-level spell slot."},{"id":"plane-shift","name":"Plane Shift","nameTr":"Düzlem Kayması","level":7,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Druid","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Belirli bir varoluş düzlemine uyum sağlayan, en az 250 gp değerinde çatallı, metal bir çubuk.","materialSource":"A forked, metal rod worth at least 250 gp, attuned to a particular plane of existence.","attackType":"melee","save":"CHA","saves":["CHA"],"saveSuccess":"none","area":null,"description":"Siz ve bir daire şeklinde el ele tutuşan en fazla sekiz istekli yaratık, farklı bir varoluş düzlemine taşınırsınız. fire Elemental Düzlemindeki Brass Şehri veya Dokuz Cehennemin ikinci seviyesindeki Dispater sarayı gibi genel anlamda bir hedef varış yeri belirtebilirsiniz ve bu varış yerinin içinde veya yakınında görünürsünüz. Örneğin Pirinç Şehri'ne ulaşmaya çalışıyorsanız, GM'nin takdirine bağlı olarak, Kül Kapısı'ndan önce Çelik Sokağı'na varabilir veya şehre fire Denizi'nin karşı tarafından bakabilirsiniz.\nAlternatif olarak, başka bir varoluş düzlemindeki ışınlanma çemberinin mühür dizisini biliyorsanız, bu büyü sizi o çembere götürebilir. Işınlanma çemberi, taşıdığınız tüm yaratıkları barındıramayacak kadar küçükse, bunlar çemberin yanındaki en yakın boş alanlarda görünürler.\nBu büyüyü isteksiz bir yaratığı başka bir uçağa sürmek için kullanabilirsiniz. Ulaşabileceğiniz bir yaratık seçin ve ona karşı bir yakın spell attack yapın. Vuruşta yaratığın bir CHA saving throw yapması gerekir. Yaratık bu kurtarmayı başaramazsa, belirttiğiniz varoluş düzleminde rastgele bir konuma nakledilir. Bu şekilde taşınan bir yaratık, mevcut varoluş düzeyinize geri dönüş yolunu bulmalıdır.","higher":"","sourceText":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. You can specify a target destination in general terms, such as the City of Brass on the Elemental Plane of Fire or the palace of Dispater on the second level of the Nine Hells, and you appear in or near that destination. If you are trying to reach the City of Brass, for example, you might arrive in its Street of Steel, before its Gate of Ashes, or looking at the city from across the Sea of Fire, at the GM's discretion.\n\nAlternatively, if you know the sigil sequence of a teleportation circle on another plane of existence, this spell can take you to that circle. If the teleportation circle is too small to hold all the creatures you transported, they appear in the closest unoccupied spaces next to the circle.\n\nYou can use this spell to banish an unwilling creature to another plane. Choose a creature within your reach and make a melee spell attack against it. On a hit, the creature must make a charisma saving throw. If the creature fails this save, it is transported to a random location on the plane of existence you specify. A creature so transported must find its own way back to your current plane of existence.","higherSource":""},{"id":"plant-growth","name":"Plant Growth","nameTr":"Bitki Büyümesi","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid","Ranger"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, canlılığı belirli bir bölgedeki bitkilere kanalize eder. Büyünün, anında veya uzun vadeli faydalar sağlayan iki olası kullanımı vardır.\nBu büyüyü 1 eylem kullanarak yaparsanız menzil içinde bir nokta seçin. Bu noktayı merkez alan 100 ft yarıçapındaki tüm normal bitkiler kalınlaşır ve aşırı büyümüş olur. Bölgede hareket eden bir yaratığın, hareket ettiği her 1 ft için 4 ft hareket harcaması gerekir.\nBüyünün alanı içindeki herhangi bir boyuttaki bir veya daha fazla alanı etkilenmekten hariç tutabilirsiniz.\nBu büyüyü 8 saatten fazla yaparsanız toprağı zenginleştirirsiniz. Menzil içindeki bir noktaya odaklanan yarım mil yarıçapındaki tüm bitkiler 1 yıl boyunca zenginleşir. Bitkiler hasat edildiğinde normalin iki katı miktarda yiyecek verir.","higher":"","sourceText":"This spell channels vitality into plants within a specific area. There are two possible uses for the spell, granting either immediate or long-term benefits.\n\nIf you cast this spell using 1 action, choose a point within range. All normal plants in a 100-foot radius centered on that point become thick and overgrown. A creature moving through the area must spend 4 feet of movement for every 1 foot it moves.\n\nYou can exclude one or more areas of any size within the spell's area from being affected.\n\nIf you cast this spell over 8 hours, you enrich the land. All plants in a half-mile radius centered on a point within range become enriched for 1 year. The plants yield twice the normal amount of food when harvested.","higherSource":""},{"id":"poison-spray","name":"Poison Spray","nameTr":"Zehirli Sprey","level":0,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"none","area":null,"description":"Elinizi menzil içinde görebileceğiniz bir yaratığa doğru uzatırsınız ve avucunuzdan zehirli bir gaz püskürtürsünüz. Yaratığın CON saving throw ile başarılı olması veya 1d12 poison hasarı alması gerekir.\nBu büyünün hasarı, 5. seviyeye (2d12), 11. seviyeye (3d12) ve 17. seviyeye (4d12) ulaştığınızda 1d12 artar.","higher":"","sourceText":"You extend your hand toward a creature you can see within range and project a puff of noxious gas from your palm. The creature must succeed on a constitution saving throw or take 1d12 poison damage.\n\nThis spell's damage increases by 1d12 when you reach 5th level (2d12), 11th level (3d12), and 17th level (4d12).","higherSource":""},{"id":"polymorph","name":"Polymorph","nameTr":"Polimorf","level":4,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tırtıl kozası.","materialSource":"A caterpillar cocoon.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bu büyü, menzil içinde görebileceğiniz bir yaratığı yeni bir forma dönüştürür. Bu etkiyi önlemek için isteksiz bir yaratığın WIS saving throw yapması gerekir. Bir şekil değiştirici bu saving throw'de otomatik olarak başarılı olur.\nDönüşüm, süre boyunca veya hedef 0 HP'ye düşene veya ölene kadar sürer. Yeni form, meydan okuma derecesi hedefinkine (veya meydan okuma derecesi yoksa hedefin seviyesine) eşit veya ondan daha az olan herhangi bir canavar olabilir. Zihinsel yetenek puanları da dahil olmak üzere hedefin oyun istatistikleri, seçilen canavarın istatistikleriyle değiştirilir. Uyumluluğunu ve kişiliğini korur.\nHedef, HP'nin yeni formunu alır. Yaratık normal formuna döndüğünde, dönüşmeden önceki HP sayısına geri döner. 0 HP'ye düşme sonucunda geri dönerse, fazla hasar normal formuna taşınır. Aşırı hasar yaratığın normal formunu 0 HP'ye düşürmediği sürece, unconscious devrilmez.\nCanlı, yeni formunun doğası gereği yapabileceği eylemlerde sınırlıdır ve konuşamaz, büyü yapamaz, el veya konuşma gerektiren herhangi bir eylemde bulunamaz.\nHedefin donanımı yeni forma dönüşür. Yaratık, ekipmanlarından herhangi birini etkinleştiremez, kullanamaz, kullanamaz veya başka bir şekilde yararlanamaz.","higher":"","sourceText":"This spell transforms a creature that you can see within range into a new form. An unwilling creature must make a wisdom saving throw to avoid the effect. A shapechanger automatically succeeds on this saving throw.\n\nThe transformation lasts for the duration, or until the target drops to 0 hit points or dies. The new form can be any beast whose challenge rating is equal to or less than the target's (or the target's level, if it doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the chosen beast. It retains its alignment and personality.\n\nThe target assumes the hit points of its new form. When it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\n\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech.\n\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment.","higherSource":""},{"id":"power-word-kill","name":"Power Word Kill","nameTr":"Güç Kelimesi Öldürme","level":9,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzilde görebileceğiniz bir yaratığı anında ölmeye zorlayabilecek bir güç sözü söylüyorsunuz. Seçtiğiniz yaratık 100 HP veya daha azına sahipse ölür. Aksi takdirde büyünün hiçbir etkisi olmaz.","higher":"","sourceText":"You utter a word of power that can compel one creature you can see within range to die instantly. If the creature you choose has 100 hit points or fewer, it dies. Otherwise, the spell has no effect.","higherSource":""},{"id":"power-word-stun","name":"Power Word Stun","nameTr":"Güç Kelimesi Sersemletme","level":8,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"","area":null,"description":"Menzilde görebileceğiniz bir yaratığın zihnini alt edebilecek ve onu şaşkına çevirebilecek güçlü bir söz söylüyorsunuz. Hedefte 150 HP veya daha az varsa stunned olur. Aksi takdirde büyünün hiçbir etkisi olmaz.\nstunned hedefi, her turunun sonunda bir CON saving throw yapmalıdır. Başarılı bir kaydetmeyle bu çarpıcı etki sona erer.","higher":"","sourceText":"You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned. Otherwise, the spell has no effect.\n\nThe stunned target must make a constitution saving throw at the end of each of its turns. On a successful save, this stunning effect ends.","higherSource":""},{"id":"prayer-of-healing","name":"Prayer of Healing","nameTr":"Şifa Duası","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"10 minutes","range":"30 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz, seçtiğiniz en fazla altı yaratığın her biri, 2d8 + büyü yapma yeteneği değiştiricinize eşit HP kazanır. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, iyileştirme 2. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d8 for each slot level above 2nd."},{"id":"prestidigitation","name":"Prestidigitation","nameTr":"Prestijitasyon","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"10 feet","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, acemi büyücülerin pratik yapmak için kullandıkları küçük bir sihir numarasıdır. 'Menzil' dahilinde aşağıdaki sihirli efektlerden birini yaratırsınız:\nKıvılcım yağmuru, rüzgar esintisi, hafif müzik notaları veya tuhaf bir koku gibi anlık, zararsız bir duyusal etki yaratırsınız.\nBir mumu, meşaleyi ya da küçük bir kamp ateşini anında yakarsınız ya da söndürürsünüz.\n1 fit küpten büyük olmayan bir nesneyi anında temizler veya kirletirsiniz.\n1 ft³'e kadar cansız malzemeyi 1 saat boyunca soğutur, ısıtır veya tatlandırırsınız.\n1 saat boyunca bir nesnenin veya yüzeyin üzerinde bir renk, küçük bir işaret veya bir simgenin görünmesini sağlarsınız.\nElinize sığabilecek ve bir sonraki turunuzun sonuna kadar sürecek, sihirli olmayan bir biblo veya yanıltıcı bir görüntü yaratırsınız.\nBu büyüyü birden çok kez yaparsanız, aynı anda en fazla üç anlık olmayan etkisini aktif hale getirebilirsiniz ve böyle bir etkiyi bir eylem olarak göz ardı edebilirsiniz.","higher":"","sourceText":"This spell is a minor magical trick that novice spellcasters use for practice. You create one of the following magical effects within 'range':\n\nYou create an instantaneous, harmless sensory effect, such as a shower of sparks, a puff of wind, faint musical notes, or an odd odor.\n\nYou instantaneously light or snuff out a candle, a torch, or a small campfire.\n\nYou instantaneously clean or soil an object no larger than 1 cubic foot.\n\nYou chill, warm, or flavor up to 1 cubic foot of nonliving material for 1 hour.\n\nYou make a color, a small mark, or a symbol appear on an object or a surface for 1 hour.\n\nYou create a nonmagical trinket or an illusory image that can fit in your hand and that lasts until the end of your next turn.\n\nIf you cast this spell multiple times, you can have up to three of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.","higherSource":""},{"id":"prismatic-spray","name":"Prismatic Spray","nameTr":"Prizmatik Sprey","level":7,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX","CON","WIS"],"saveSuccess":"other","area":{"type":"cone","size":60},"description":"Elinizden sekiz adet çok renkli ışık ışını parlıyor. Her ışın farklı bir renktedir ve farklı bir güce ve amaca sahiptir. Bir 60 ft konisindeki her yaratık DEX saving throw atmalıdır. Her hedef için, hangi renk ışınının onu etkilediğini belirlemek için bir d8 yuvarlayın.\n***1. Kırmızı.*** Hedef, başarısız save’de 10d6 fire hasar alır veya başarılı save’de yarısı kadar hasar alır.\n***2. Turuncu.*** Hedef, başarısız save’de 10d6 acid hasar alır veya başarılı save’de yarısı kadar hasar alır.\n***3. Sarı.*** Hedef, başarısız save’de 10d6 lightning hasar alır veya başarılı save’de yarısı kadar hasar alır.\n***4. Yeşil.*** Hedef, başarısız save’de 10d6 poison hasar alır veya başarılı save’de yarısı kadar hasar alır.\n***5. Mavi.*** Hedef, başarısız save’de 10d6 cold hasar alır veya başarılı save’de yarısı kadar hasar alır.\n***6. Indigo.*** Başarısız bir kaydetme durumunda hedef restrained'dir. Daha sonra her turun sonunda bir CON saving throw yapması gerekir. Üç kez başarılı bir şekilde kurtarırsa büyü sona erer. Üç kez kurtarmayı başaramazsa kalıcı olarak taşa döner ve petrified koşuluna tabi tutulur. Başarıların ve başarısızlıkların ardışık olması gerekmez; Hedef aynı türden üç tane toplayana kadar her ikisini de takip edin.\n***7. Menekşe.*** Başarısız bir kaydetme işleminde hedef blinded'dir. Daha sonra bir sonraki turunuzun başlangıcında WIS saving throw yapmalıdır. Başarılı bir kurtarma körlüğe son verir. Bu kurtarma başarısız olursa, yaratık GM'nin seçeceği başka bir varoluş düzlemine nakledilir ve artık blinded olmaz. (Genellikle, ana düzlemi olmayan bir düzlemde bulunan bir yaratık eve sürgün edilirken, diğer yaratıklar genellikle Astral veya Eterik düzlemlere atılır.)\n***8. Özel.*** Hedefe iki ışın çarpıyor. Herhangi bir 8'i yeniden atarak iki kez daha yuvarlayın.","higher":"","sourceText":"Eight multicolored rays of light flash from your hand. Each ray is a different color and has a different power and purpose. Each creature in a 60-foot cone must make a dexterity saving throw. For each target, roll a d8 to determine which color ray affects it.\n\n***1. Red.*** The target takes 10d6 fire damage on a failed save, or half as much damage on a successful one.\n\n***2. Orange.*** The target takes 10d6 acid damage on a failed save, or half as much damage on a successful one.\n\n***3. Yellow.*** The target takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\n\n***4. Green.*** The target takes 10d6 poison damage on a failed save, or half as much damage on a successful one.\n\n***5. Blue.*** The target takes 10d6 cold damage on a failed save, or half as much damage on a successful one.\n\n***6. Indigo.*** On a failed save, the target is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the target collects three of a kind.\n\n***7. Violet.*** On a failed save, the target is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of existence of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.)\n\n***8. Special.*** The target is struck by two rays. Roll twice more, rerolling any 8.","higherSource":""},{"id":"prismatic-wall","name":"Prismatic Wall","nameTr":"Prizmatik Duvar","level":9,"school":"Abjuration","schoolTr":"Koruma","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON","DEX","WIS"],"saveSuccess":"","area":{"type":"line","size":90},"description":"Parıldayan, çok renkli bir ışık düzlemi, menzil içinde görebileceğiniz bir noktada ortalanmış, 90 ft uzunluğa, 30 ft yüksekliğe ve 1 inç kalınlığa kadar dikey opak bir duvar oluşturur. Alternatif olarak duvarı, aralık içinde seçtiğiniz bir noktanın merkezinde 30 ft çapına kadar bir küre şeklinde şekillendirebilirsiniz. Duvar bu süre boyunca yerinde kalır. Duvarı bir yaratığın bulunduğu alandan geçecek şekilde konumlandırırsanız büyü başarısız olur ve eyleminiz ve spell slot boşa gider.\nDuvar, bir dizi 100 ft'ye parlak ışık, ek bir 100 ft'ye ise loş ışık tutuyor. Siz ve büyüyü yaptığınızda belirlediğiniz yaratıklar duvardan zarar görmeden geçebilir ve yakınında kalabilirsiniz. Duvarı görebilen başka bir yaratık onun 20 ft yakınına doğru hareket ederse veya dönüşüne orada başlarsa, yaratığın bir CON saving throw üzerinde başarılı olması veya 1 dakika boyunca blinded olması gerekir.\nDuvar, her biri farklı renkte olan yedi katmandan oluşuyor. Bir yaratık duvara ulaşmaya veya duvarın içinden geçmeye çalıştığında, bunu duvarın tüm katmanlarını tek tek katmanlar halinde gerçekleştirir. Yaratığın her katmandan geçerken veya ulaşırken bir DEX saving throw yapması veya aşağıda anlatıldığı gibi o katmanın özelliklerinden etkilenmesi gerekir.\nDuvar, her katmana özel yöntemlerle, kırmızıdan mora doğru sırayla tek katman halinde yok edilebiliyor. Bir katman yok edildiğinde büyünün süresi boyunca öyle kalır. Bir iptal çubuğu prizmatik bir duvarı yok eder, ancak anti-sihirli alanın bunun üzerinde hiçbir etkisi yoktur.\n***1. Kırmızı.*** Yaratık, başarısız save’de 10d6 fire hasar alır veya başarılı save’de yarısı kadar hasar alır. Bu katman yerindeyken, büyüsel olmayan menzilli saldırılar duvarı geçemez. Katman, en az 25 cold hasar verilerek yok edilebilir.\n***2. Turuncu.*** Yaratık, başarısız save’de 10d6 acid hasar alır veya başarılı save’de yarısı kadar hasar alır. Bu katman yerindeyken büyülü menzilli saldırılar duvardan geçemez. Katman kuvvetli bir rüzgarla yok edilir.\n***3. Sarı.*** Yaratık, başarısız save’de 10d6 lightning hasar alır veya başarılı save’de yarısı kadar hasar alır. Bu katman, ona en az 60 force hasar verilerek yok edilebilir.\n***4. Yeşil.*** Yaratık, başarısız save’de 10d6 poison hasar alır veya başarılı save’de yarısı kadar hasar alır. Bir geçiş duvarı büyüsü veya katı bir yüzeyde bir portal açabilen eşit veya daha yüksek seviyedeki başka bir büyü bu katmanı yok eder.\n***5. Mavi.*** Yaratık, başarısız save’de 10d6 cold hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Bu katman, ona en az 25 fire hasar verilerek yok edilebilir.\n***6. Indigo.*** Başarısız bir kaydetme işleminde yaratığın adı restrained'dir. Daha sonra her turun sonunda bir CON saving throw yapması gerekir. Üç kez başarılı bir şekilde kurtarırsa büyü sona erer. Üç kez kurtarmayı başaramazsa kalıcı olarak taşa döner ve petrified koşuluna tabi tutulur. Başarıların ve başarısızlıkların ardışık olması gerekmez; Yaratık aynı türden üç tane toplayana kadar ikisini de takip edin.\nBu katman yerindeyken duvarın içinden büyü yapılamaz. Katman, bir gün ışığı büyüsü veya eşit veya daha yüksek düzeyde benzer bir büyü tarafından yayılan parlak ışıkla yok edilir.\n***7. Menekşe.*** Başarısız bir kaydetme işleminde yaratığın adı blinded'dir. Daha sonra bir sonraki turunuzun başlangıcında WIS saving throw yapmalıdır. Başarılı bir kurtarma körlüğe son verir. Bu kurtarma başarısız olursa, yaratık GM'nin seçeceği başka bir uçağa nakledilir ve artık blinded olmaz. (Genellikle, ana düzlemi olmayan bir düzlemde bulunan bir yaratık eve sürgün edilirken, diğer yaratıklar genellikle Astral veya Ethereal düzlemlere atılır.) Bu katman, büyüleri ve büyülü etkileri sona erdirebilen, etkisizleştirme büyüsü veya eşit veya daha yüksek seviyedeki benzer bir büyü ile yok edilir.","higher":"","sourceText":"A shimmering, multicolored plane of light forms a vertical opaque wall--up to 90 feet long, 30 feet high, and 1 inch thick--centered on a point you can see within range. Alternatively, you can shape the wall into a sphere up to 30 feet in diameter centered on a point you choose within range. The wall remains in place for the duration. If you position the wall so that it passes through a space occupied by a creature, the spell fails, and your action and the spell slot are wasted.\n\nThe wall sheds bright light out to a range of 100 feet and dim light for an additional 100 feet. You and creatures you designate at the time you cast the spell can pass through and remain near the wall without harm. If another creature that can see the wall moves to within 20 feet of it or starts its turn there, the creature must succeed on a constitution saving throw or become blinded for 1 minute.\n\nThe wall consists of seven layers, each with a different color. When a creature attempts to reach into or pass through the wall, it does so one layer at a time through all the wall's layers. As it passes or reaches through each layer, the creature must make a dexterity saving throw or be affected by that layer's properties as described below.\n\nThe wall can be destroyed, also one layer at a time, in order from red to violet, by means specific to each layer. Once a layer is destroyed, it remains so for the duration of the spell. A rod of cancellation destroys a prismatic wall, but an antimagic field has no effect on it.\n\n***1. Red.*** The creature takes 10d6 fire damage on a failed save, or half as much damage on a successful one. While this layer is in place, nonmagical ranged attacks can't pass through the wall. The layer can be destroyed by dealing at least 25 cold damage to it.\n\n***2. Orange.*** The creature takes 10d6 acid damage on a failed save, or half as much damage on a successful one. While this layer is in place, magical ranged attacks can't pass through the wall. The layer is destroyed by a strong wind.\n\n***3. Yellow.*** The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 60 force damage to it.\n\n***4. Green.*** The creature takes 10d6 poison damage on a failed save, or half as much damage on a successful one. A passwall spell, or another spell of equal or greater level that can open a portal on a solid surface, destroys this layer.\n\n***5. Blue.*** The creature takes 10d6 cold damage on a failed save, or half as much damage on a successful one. This layer can be destroyed by dealing at least 25 fire damage to it.\n\n***6. Indigo.*** On a failed save, the creature is restrained. It must then make a constitution saving throw at the end of each of its turns. If it successfully saves three times, the spell ends. If it fails its save three times, it permanently turns to stone and is subjected to the petrified condition. The successes and failures don't need to be consecutive; keep track of both until the creature collects three of a kind.\n\nWhile this layer is in place, spells can't be cast through the wall. The layer is destroyed by bright light shed by a daylight spell or a similar spell of equal or higher level.\n\n***7. Violet.*** On a failed save, the creature is blinded. It must then make a wisdom saving throw at the start of your next turn. A successful save ends the blindness. If it fails that save, the creature is transported to another plane of the GM's choosing and is no longer blinded. (Typically, a creature that is on a plane that isn't its home plane is banished home, while other creatures are usually cast into the Astral or Ethereal planes.) This layer is destroyed by a dispel magic spell or a similar spell of equal or higher level that can end spells and magical effects.","higherSource":""},{"id":"private-sanctum","name":"Private Sanctum","nameTr":"Özel Kutsal Alan","level":4,"school":"Abjuration","schoolTr":"Koruma","classes":["Wizard"],"subclasses":[],"castingTime":"10 minutes","range":"120 feet","duration":"24 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"İnce bir kurşun levha, bir parça opak cam, bir tomar pamuk veya kumaş ve toz krizolit.","materialSource":"A thin sheet of lead, a piece of opaque glass, a wad of cotton or cloth, and powdered chrysolite.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":100},"description":"Menzil içindeki bir alanı sihirli bir şekilde güvenli hale getirirsiniz. Alan, her iki tarafı 5 ft kadar küçük veya 100 ft kadar büyük olabilen bir küptür. Büyü, süre boyunca veya siz onu yok etmek için bir eylem kullanana kadar sürer.\nBüyüyü yaptığınızda, aşağıdaki özelliklerden herhangi birini veya tümünü seçerek büyünün ne tür bir güvenlik sağlayacağına karar verirsiniz:\n- Muhafazalı alanın kenarındaki bariyerden ses geçemez.\n- Korunan alanın bariyeri karanlık ve sisli görünür ve bu sayede görüş (karanlık görüş dahil) engellenir.\n- Kehanet büyüleriyle oluşturulan sensörler, korunan alanın içinde görünemez veya çevredeki bariyeri geçemez.\n- Bölgedeki yaratıklar kehanet büyüleriyle hedef alınamaz.\n- Muhafazalı alana hiçbir şey ışınlanamaz veya bu alanın dışına ışınlanamaz.\n- Korunan alan içerisinde düzlemsel hareket engellendi.\nBir yıl boyunca her gün aynı noktaya bu büyünün yapılması bu etkinin kalıcı olmasını sağlar.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 4. seviyenin ötesindeki her yuva seviyesi için küpün boyutunu 100 ft artırabilirsiniz. Böylece bir tarafı 200 ft'ye kadar olabilen bir küpü 5. seviye spell slot kullanarak koruyabilirsiniz.","sourceText":"You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it.\n\nWhen you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties:\n\n- Sound can't pass through the barrier at the edge of the warded area.\n\n- The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it.\n\n- Sensors created by divination spells can't appear inside the protected area or pass through the barrier at its perimeter.\n\n- Creatures in the area can't be targeted by divination spells.\n\n- Nothing can teleport into or out of the warded area.\n\n- Planar travel is blocked within the warded area.\n\nCasting this spell on the same spot every day for a year makes this effect permanent.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, you can increase the size of the cube by 100 feet for each slot level beyond 4th. Thus you could protect a cube that can be up to 200 feet on one side by using a spell slot of 5th level."},{"id":"produce-flame","name":"Produce Flame","nameTr":"Alev Üret","level":0,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Elinizde titreyen bir alev belirir. Alev bu süre boyunca orada kalır ve ne size ne de ekipmanınıza zarar verir. Alev, 10 ft yarıçapında parlak ışık ve ek bir 10 ft için loş ışık saçar. Büyüyü bir eylem olarak reddederseniz veya tekrar yaparsanız büyü sona erer.\nAyrıca alevle de saldırabilirsiniz, ancak bunu yaptığınızda büyü sona erer. Bu büyüyü yaptığınızda veya sonraki bir turda bir eylem olarak, alevi 30 ft içindeki bir yaratığa fırlatabilirsiniz. Bir menzilli spell attack yapın. Bir vuruşta hedef 1d8 fire hasarı alır.\nBu büyünün hasarı, 5. seviyeye (2d8), 11. seviyeye (3d8) ve 17. seviyeye (4d8) ulaştığınızda 1d8 artar.","higher":"","sourceText":"A flickering flame appears in your hand. The flame remains there for the duration and harms neither you nor your equipment. The flame sheds bright light in a 10-foot radius and dim light for an additional 10 feet. The spell ends if you dismiss it as an action or if you cast it again.\n\nYou can also attack with the flame, although doing so ends the spell. When you cast this spell, or as an action on a later turn, you can hurl the flame at a creature within 30 feet of you. Make a ranged spell attack. On a hit, the target takes 1d8 fire damage.\n\nThis spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","higherSource":""},{"id":"programmed-illusion","name":"Programmed Illusion","nameTr":"Programlanmış İllüzyon","level":6,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"En az 25 gp değerinde bir miktar yapağı ve yeşim tozu.","materialSource":"A bit of fleece and jade dust worth at least 25 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":30},"description":"Belirli bir durum oluştuğunda etkinleşen, menzil içindeki bir nesnenin, bir yaratığın veya başka bir görünür olgunun yanılsamasını yaratırsınız. O zamana kadar yanılsama algılanamaz. Bir 30 ft küpünden daha büyük olmamalıdır ve büyüyü ne zaman yapacağınıza illüzyonun nasıl davranacağına ve hangi sesleri çıkaracağına siz karar verirsiniz. Bu senaryolu performans 5 dakikaya kadar sürebilir.\nBelirttiğiniz durum ortaya çıktığında yanılsama ortaya çıkar ve tanımladığınız şekilde gerçekleşir. İllüzyon performansı bittiğinde kaybolur ve 10 dakika boyunca hareketsiz kalır. Bu sürenin sonunda illüzyon tekrar etkinleştirilebilir.\nTetikleme koşulu istediğiniz kadar genel veya ayrıntılı olabilir, ancak alanın 30 ft dahilinde meydana gelen görsel veya işitsel koşullara dayanması gerekir. Örneğin, kapana kısılmış bir kapıyı açmaya çalışan diğer kişileri uyarmak ve onları uyarmak için kendinizin bir yanılsamasını yaratabilir veya yanılsamayı yalnızca bir yaratık doğru kelimeyi veya ifadeyi söylediğinde tetiklenecek şekilde ayarlayabilirsiniz.\nGörüntüyle fiziksel etkileşim onun bir yanılsama olduğunu ortaya koyuyor çünkü nesneler onun içinden geçebiliyor. Görüntüyü incelemek için eylemini kullanan bir yaratık, DC'yi kaydetme büyünüze karşı başarılı bir INT (Soruşturma) kontrolü ile bunun bir illüzyon olduğunu belirleyebilir. Bir yaratık illüzyonun ne olduğunu anlarsa, yaratık görüntünün arkasını görebilir ve çıkardığı her türlü ses, yaratığa boş geliyor.","higher":"","sourceText":"You create an illusion of an object, a creature, or some other visible phenomenon within range that activates when a specific condition occurs. The illusion is imperceptible until then. It must be no larger than a 30-foot cube, and you decide when you cast the spell how the illusion behaves and what sounds it makes. This scripted performance can last up to 5 minutes.\n\nWhen the condition you specify occurs, the illusion springs into existence and performs in the manner you described. Once the illusion finishes performing, it disappears and remains dormant for 10 minutes. After this time, the illusion can be activated again.\n\nThe triggering condition can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the area. For example, you could create an illusion of yourself to appear and warn off others who attempt to open a trapped door, or you could set the illusion to trigger only when a creature says the correct word or phrase.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","higherSource":""},{"id":"project-image","name":"Project Image","nameTr":"Proje Görseli","level":7,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Wizard"],"subclasses":[],"castingTime":"1 action","range":"500 miles","duration":"Up to 24 hours","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"En az 5 GP değerindeki malzemelerden yapılmış küçük bir kopyanız.","materialSource":"A small replica of you made from materials worth at least 5 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Süre boyunca sürecek olan kendinizin yanıltıcı bir kopyasını yaratırsınız. Kopya, aradaki engellere bakılmaksızın, daha önce gördüğünüz menzil içindeki herhangi bir yerde görünebilir. İllüzyon size benziyor ve ses çıkarıyor ancak soyuttur. İllüzyon herhangi bir hasar alırsa kaybolur ve büyü sona erer.\nBu yanılsamayı hızınızın iki katına çıkarmak için eyleminizi kullanabilir ve onun istediğiniz şekilde hareket etmesini, konuşmasını ve davranmasını sağlayabilirsiniz. Davranışlarınızı mükemmel bir şekilde taklit eder.\nSanki onun alanındaymış gibi onun gözleriyle görebilir ve kulaklarıyla duyabilirsiniz. Bonus Action olarak sıra size geldiğinde, duyularınızı kullanmaktan kendi duyularınızı kullanmaya veya tekrar duyularınızı kullanmaya geçiş yapabilirsiniz. Onun duyularını kullanırken, kendi çevrenize göre blinded ve deafened olursunuz.\nGörüntüyle fiziksel etkileşim onun bir yanılsama olduğunu ortaya koyuyor çünkü nesneler onun içinden geçebiliyor. Görüntüyü incelemek için eylemini kullanan bir yaratık, DC'yi kaydetme büyünüze karşı başarılı bir INT (Soruşturma) kontrolü ile bunun bir illüzyon olduğunu belirleyebilir. Bir yaratık illüzyonun ne olduğunu anlarsa, yaratık görüntünün arkasını görebilir ve çıkardığı her türlü ses, yaratığa boş geliyor.","higher":"","sourceText":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, regardless of intervening obstacles. The illusion looks and sounds like you but is intangible. If the illusion takes any damage, it disappears, and the spell ends.\n\nYou can use your action to move this illusion up to twice your speed, and make it gesture, speak, and behave in whatever way you choose. It mimics your mannerisms perfectly.\n\nYou can see through its eyes and hear through its ears as if you were in its space. On your turn as a bonus action, you can switch from using its senses to using your own, or back again. While you are using its senses, you are blinded and deafened in regard to your own surroundings.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image, and any noise it makes sounds hollow to the creature.","higherSource":""},{"id":"protection-from-energy","name":"Protection From Energy","nameTr":"Enerjiden Koruma","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca dokunduğunuz istekli yaratık, seçtiğiniz bir hasar türüne karşı dirence sahip olur: acid, cold, fire, lightning veya thunder.","higher":"","sourceText":"For the duration, the willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder.","higherSource":""},{"id":"protection-from-evil-and-good","name":"Protection from Evil and Good","nameTr":"Kötülükten ve İyilikten Korunma","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin","Warlock","Wizard"],"subclasses":["Devotion","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği kutsal su veya toz gümüş ve demir.","materialSource":"Holy water or powdered silver and iron, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü sona erene kadar, dokunduğunuz istekli bir yaratık belirli yaratık türlerine karşı korunur: sapkınlar, gökseller, elementaller, periler, iblisler ve ölümsüzler.\nKoruma çeşitli faydalar sağlar. Bu tür yaratıkların hedefe karşı saldırı atışlarında dezavantaj bulunur. Hedef ayrıca charmed, frightened olamaz veya onlar tarafından ele geçirilemez. Hedef zaten charmed, frightened ise veya böyle bir yaratık tarafından ele geçirilmişse hedef, ilgili etkiye karşı herhangi bir yeni saving throw üzerinde avantaj'ye sahiptir.","higher":"","sourceText":"Until the spell ends, one willing creature you touch is protected against certain types of creatures: aberrations, celestials, elementals, fey, fiends, and undead.\n\nThe protection grants several benefits. Creatures of those types have disadvantage on attack rolls against the target. The target also can't be charmed, frightened, or possessed by them. If the target is already charmed, frightened, or possessed by such a creature, the target has advantage on any new saving throw against the relevant effect.","higherSource":""},{"id":"protection-from-poison","name":"Protection from Poison","nameTr":"Zehirden Korunma","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Druid","Paladin","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsun. poisoned ise poison'yi etkisiz hale getirirsiniz. Birden fazla poison hedefi etkiliyorsa, mevcut olduğunu bildiğiniz bir poison'yi etkisiz hale getirirsiniz veya rastgele birini etkisiz hale getirirsiniz.\nBu süre boyunca hedef, saving throw’lar üzerinde poisoned olmaya karşı avantaj'ye sahiptir ve poison hasarına karşı dirence sahiptir.","higher":"","sourceText":"You touch a creature. If it is poisoned, you neutralize the poison. If more than one poison afflicts the target, you neutralize one poison that you know is present, or you neutralize one at random.\n\nFor the duration, the target has advantage on saving throws against being poisoned, and it has resistance to poison damage.","higherSource":""},{"id":"purify-food-and-drink","name":"Purify Food and Drink","nameTr":"Yiyecek ve İçecekleri Arındırın","level":1,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid","Paladin"],"subclasses":["Lore"],"castingTime":"1 action","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil dahilinde seçtiğiniz bir noktaya odaklanan bir 5 ft yarıçaplı küre içindeki tüm sihirli olmayan yiyecek ve içecekler saflaştırılır ve poison ve hastalıklardan arındırılır.","higher":"","sourceText":"All nonmagical food and drink within a 5-foot radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease.","higherSource":""},{"id":"raise-dead","name":"Raise Dead","nameTr":"Ölüleri Kaldır","level":5,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Cleric","Paladin"],"subclasses":["Life"],"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 500gp değerinde bir elmas.","materialSource":"A diamond worth at least 500gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuz ölü bir canlıyı, 10 günden fazla ölmemiş olması koşuluyla hayata döndürüyorsunuz. Eğer yaratığın ruhu bedene yeniden katılmaya hem istekli hem de özgürse, yaratık 1 can puanıyla hayata döner.\nBu büyü aynı zamanda her türlü zehiri etkisiz hale getirir ve öldüğü sırada yaratığın etkilendiği büyü dışı hastalıkları da iyileştirir. Ancak bu büyü, büyülü hastalıkları, lanetleri veya benzer etkileri ortadan kaldırmaz; bunlar büyüyü yapmadan önce kaldırılmazsa, yaratık hayata döndüğünde etkili olurlar. Büyü, ölümsüz bir yaratığı hayata döndüremez.\nBu büyü tüm ölümcül yaraları kapatır ancak eksik vücut parçalarını onarmaz. Yaratığın hayatta kalması için gerekli vücut parçaları veya organları (örneğin kafası) eksikse, büyü otomatik olarak başarısız olur.\nÖlümden geri dönmek bir çiledir. Hedef, tüm saldırı atışlarına (saving throw’lar ve ability check’ler) -4 ceza alır. Hedefin uzun bir dinlenmeyi tamamladığı her defasında, hedef kayboluncaya kadar ceza 1 azaltılır.","higher":"","sourceText":"You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature's soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 hit point.\n\nThis spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn't, however, remove magical diseases, curses, or similar effects; if these aren't first removed prior to casting the spell, they take effect when the creature returns to life. The spell can't return an undead creature to life.\n\nThis spell closes all mortal wounds, but it doesn't restore missing body parts. If the creature is lacking body parts or organs integral for its survival--its head, for instance--the spell automatically fails.\n\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.","higherSource":""},{"id":"ray-of-enfeeblement","name":"Ray of Enfeeblement","nameTr":"Zayıflama Işını","level":2,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"CON","saves":["CON"],"saveSuccess":"none","area":null,"description":"Parmağınızdan menzil içindeki bir yaratığa doğru siyah bir sinir bozucu enerji ışını yayılıyor. Hedefe karşı bir menzilli spell attack yapın. Bir vuruşta hedef, büyü bitene kadar STR kullanan silah saldırılarıyla yalnızca yarı hasar verir.\nHedef her turun sonunda büyüye karşı CON saving throw yapabilir. Başarılı olunduğunda büyü sona erer.","higher":"","sourceText":"A black beam of enervating energy springs from your finger toward a creature within range. Make a ranged spell attack against the target. On a hit, the target deals only half damage with weapon attacks that use Strength until the spell ends.\n\nAt the end of each of the target's turns, it can make a constitution saving throw against the spell. On a success, the spell ends.","higherSource":""},{"id":"ray-of-frost","name":"Ray of Frost","nameTr":"Don Işını","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"Soğuk bir mavi-beyaz ışık huzmesi menzil içindeki bir yaratığa doğru ilerliyor. Hedefe karşı bir menzilli spell attack yapın. Vuruşta 1d8 cold hasarı alır ve bir sonraki turunuzun başlangıcına kadar hızı 10 ft kadar azalır.\nBüyünün hasarı, 5. seviyeye (2d8), 11. seviyeye (3d8) ve 17. seviyeye (4d8) ulaştığınızda 1d8 artar.","higher":"","sourceText":"A frigid beam of blue-white light streaks toward a creature within range. Make a ranged spell attack against the target. On a hit, it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","higherSource":""},{"id":"regenerate","name":"Regenerate","nameTr":"Yenile","level":7,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Cleric","Druid"],"subclasses":[],"castingTime":"1 minute","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir dua çarkı ve kutsal su.","materialSource":"A prayer wheel and holy water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir yaratığa dokunuyorsunuz ve onun doğal iyileştirme yeteneğini harekete geçiriyorsunuz. Hedef, 4d8+15 HP'yi yeniden kazanır. Büyü süresi boyunca hedef, her turun başlangıcında 1 vuruş puanı yeniden kazanır (dakikada 10 HP).\nHedefin kopmuş vücut parçaları (parmaklar, bacaklar, kuyruklar vb.) 2 dakika sonra eski durumuna getirilir. Kesilen kısmı elinizde tutarsanız ve onu kütüğe doğru tutarsanız, büyü anında uzvun kütüğe yapışmasına neden olur.","higher":"","sourceText":"You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 hit point at the start of each of its turns (10 hit points each minute).\n\nThe target's severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump.","higherSource":""},{"id":"reincarnate","name":"Reincarnate","nameTr":"Reenkarnasyon","level":5,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":[],"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 1.000 gp değerindeki nadir yağlar ve merhemler.","materialSource":"Rare oils and unguents worth at least 1,000 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Ölü bir insansıya veya ölü bir insansı parçasına dokunuyorsunuz. Yaratığın 10 günden daha uzun bir süre önce ölmemesi koşuluyla, büyü onun için yeni bir yetişkin bedeni oluşturur ve ardından ruhu bu bedene girmeye çağırır. Hedefin ruhu özgür değilse veya buna istekli değilse büyü başarısız olur.\nBüyü, yaratığın yaşaması için yeni bir vücut oluşturur ve bu da muhtemelen yaratığın ırkının değişmesine neden olur. GM d 100 atar ve yaratığın hayata döndürüldüğünde hangi formu alacağını belirlemek için aşağıdaki tabloya başvurur veya GM bir form seçer.\n| d100 | Yarış |\n|---|---|\n| 01-04 | Dragonborn |\n| 05-13 | Cüce, tepe |\n| 14-21 | Cüce, dağ |\n| 22-25 | Elf, karanlık |\n| 26-34 | Elf, yüksek |\n| 35-42 | Elf, ahşap |\n| 43-46 | Cüce, orman |\n| 47-52 | Cüce, kaya |\n| 53-56 | Yarımelf |\n| 57-60 | Yarı ork |\n| 61-68 | Buçukluk, hafif ayak |\n| 69-76 | Buçukluk, yiğit |\n| 77-96 | İnsan |\n| 97-00 | Tiefling |\nReenkarnasyona uğrayan yaratık, önceki yaşamını ve deneyimlerini anımsar. Orijinal ırkını yenisiyle değiştirmesi ve ırksal özelliklerini buna göre değiştirmesi dışında, orijinal formunda sahip olduğu yetenekleri korur.","higher":"","sourceText":"You touch a dead humanoid or a piece of a dead humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target's soul isn't free or willing to do so, the spell fails.\n\nThe magic fashions a new body for the creature to inhabit, which likely causes the creature's race to change. The GM rolls a d 100 and consults the following table to determine what form the creature takes when restored to life, or the GM chooses a form.\n\n| d100 | Race |\n\n|---|---|\n\n| 01-04 | Dragonborn |\n\n| 05-13 | Dwarf, hill |\n\n| 14-21 | Dwarf, mountain |\n\n| 22-25 | Elf, dark |\n\n| 26-34 | Elf, high |\n\n| 35-42 | Elf, wood |\n\n| 43-46 | Gnome, forest |\n\n| 47-52 | Gnome, rock |\n\n| 53-56 | Half-elf |\n\n| 57-60 | Half-orc |\n\n| 61-68 | Halfling, lightfoot |\n\n| 69-76 | Halfling, stout |\n\n| 77-96 | Human |\n\n| 97-00 | Tiefling |\n\nThe reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original race for the new one and changes its racial traits accordingly.","higherSource":""},{"id":"remove-curse","name":"Remove Curse","nameTr":"Laneti Kaldır","level":3,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dokunduğunuzda, bir yaratığı veya nesneyi etkileyen tüm lanetler sona erer. Eğer nesne lanetli bir büyülü eşyaysa, laneti kalır, ancak büyü, sahibinin nesneye olan uyumunu bozar, böylece nesne kaldırılabilir veya atılabilir.","higher":"","sourceText":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but the spell breaks its owner's attunement to the object so it can be removed or discarded.","higherSource":""},{"id":"resilient-sphere","name":"Resilient Sphere","nameTr":"Esnek Küre","level":4,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Yarım küre şeklinde berrak bir kristal parçası ve buna uygun yarım küre şeklinde bir parça arap zamkı.","materialSource":"A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":null,"description":"Parıldayan bir force küresi, menzil içindeki Büyük veya daha küçük bir yaratığı veya nesneyi çevreler. İsteksiz bir yaratığın bir DEX saving throw yapması gerekir. Başarısız bir kaydetme durumunda yaratık bu süre boyunca kapalı kalır.\nKüredeki bir yaratık orada nefes alsa da hiçbir şey (fiziksel nesneler, enerji veya diğer büyü etkileri) bariyerden içeri veya dışarı geçemez. Küre her türlü hasara karşı bağışık olup, içindeki bir yaratık veya nesne dışarıdan gelecek saldırı veya etkilerden zarar göremeyeceği gibi, kürenin içindeki bir yaratık da onun dışındaki hiçbir şeye zarar veremez.\nKüre ağırlıksızdır ve içindeki yaratığı veya nesneyi içerecek kadar büyüktür. Kapalı bir yaratık, hareketini kürenin duvarlarına doğru itmek için kullanabilir ve böylece küreyi, yaratığın yarısı kadar bir hızda yuvarlayabilir. Benzer şekilde yerküre diğer canlılar tarafından alınıp hareket ettirilebilir.\nKüreyi hedef alan parçalayıcı bir büyü, içindeki hiçbir şeye zarar vermeden onu yok eder.","higher":"","sourceText":"A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature must make a dexterity saving throw. On a failed save, the creature is enclosed for the duration.\n\nNothing--not physical objects, energy, or other spell effects--can pass through the barrier, in or out, though a creature in the sphere can breathe there. The sphere is immune to all damage, and a creature or object inside can't be damaged by attacks or effects originating from outside, nor can a creature inside the sphere damage anything outside it.\n\nThe sphere is weightless and just large enough to contain the creature or object inside. An enclosed creature can use its action to push against the sphere's walls and thus roll the sphere at up to half the creature's speed. Similarly, the globe can be picked up and moved by other creatures.\n\nA disintegrate spell targeting the globe destroys it without harming anything inside it.","higherSource":""},{"id":"resistance","name":"Resistance","nameTr":"Direnç","level":0,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Druid"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Minyatür bir pelerin.","materialSource":"A miniature cloak.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"İstekli bir yaratığa dokunuyorsun. Büyü sona ermeden önce, hedef bir d4 atabilir ve atılan sayıyı kendi seçtiği bir saving throw'ye ekleyebilir. saving throw'yi yapmadan önce veya sonra kalıbı yuvarlayabilir. Büyü daha sonra sona erer.","higher":"","sourceText":"You touch one willing creature. Once before the spell ends, the target can roll a d4 and add the number rolled to one saving throw of its choice. It can roll the die before or after making the saving throw. The spell then ends.","higherSource":""},{"id":"resurrection","name":"Resurrection","nameTr":"Diriliş","level":7,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Cleric"],"subclasses":[],"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 1.000 gp değerinde bir elmas.","materialSource":"A diamond worth at least 1,000gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir asırdan fazla süredir ölü olmayan, yaşlılıktan ölmemiş ve ölümsüz olmayan ölü bir yaratığa dokunuyorsunuz. Eğer ruhu özgür ve istekli ise hedef tüm HP ile hayata döner.\nBu büyü, her türlü zehiri etkisiz hale getirir ve öldüğünde yaratığa etki eden normal hastalıkları iyileştirir. Ancak büyülü hastalıkları, lanetleri ve benzerlerini ortadan kaldırmaz; eğer bu tür etkiler büyü yapılmadan önce ortadan kaldırılmazsa, hedefin hayata dönmesine etki ederler.\nBu büyü tüm ölümcül yaraları kapatır ve eksik vücut parçalarını onarır.\nÖlümden geri dönmek bir çiledir. Hedef, tüm saldırı atışlarına (saving throw’lar ve ability check’ler) -4 ceza alır. Hedefin uzun bir dinlenmeyi tamamladığı her defasında, hedef kayboluncaya kadar ceza 1 azaltılır.\nBir yıl veya daha uzun süredir ölü olan bir yaratığa yeniden hayat vermek için bu büyüyü yapmak size büyük yük getirir. Uzun bir dinlenmeyi bitirene kadar tekrar büyü yapamazsınız ve tüm saldırı atışlarında ability check’ler ve saving throw’lar dezavantaj'ye sahipsiniz.","higher":"","sourceText":"You touch a dead creature that has been dead for no more than a century, that didn't die of old age, and that isn't undead. If its soul is free and willing, the target returns to life with all its hit points.\n\nThis spell neutralizes any poisons and cures normal diseases afflicting the creature when it died. It doesn't, however, remove magical diseases, curses, and the like; if such effects aren't removed prior to casting the spell, they afflict the target on its return to life.\n\nThis spell closes all mortal wounds and restores any missing body parts.\n\nComing back from the dead is an ordeal. The target takes a -4 penalty to all attack rolls, saving throws, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears.\n\nCasting this spell to restore life to a creature that has been dead for one year or longer taxes you greatly. Until you finish a long rest, you can't cast spells again, and you have disadvantage on all attack rolls, ability checks, and saving throws.","higherSource":""},{"id":"reverse-gravity","name":"Reverse Gravity","nameTr":"Ters Yerçekimi","level":7,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"100 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir mıknatıs taşı ve demir talaşı.","materialSource":"A lodestone and iron filings.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"other","area":{"type":"cylinder","size":50},"description":"Bu büyü, menzil içindeki bir noktaya odaklanan 50 ft yarıçap, 100 ft yüksek silindirindeki yerçekimini tersine çevirir. Bu büyüyü yaptığınızda, alanda herhangi bir şekilde yere sabitlenmemiş tüm yaratıklar ve nesneler yukarıya doğru düşerek alanın tepesine ulaşır. Bir yaratık, DEX saving throw'yi ulaşabildiği sabit bir nesneye tutunarak düşmeyi önleyebilir.\nBu düşüşte herhangi bir katı cisimle (tavan gibi) karşılaşılırsa, düşen cisimler ve yaratıklar, normal bir düşüşte olduğu gibi ona çarparlar. Bir nesne veya yaratık herhangi bir şeye çarpmadan alanın tepesine ulaşırsa, bu süre boyunca orada hafifçe salınarak kalır.\nSürenin sonunda etkilenen nesneler ve yaratıklar tekrar yere düşer.","higher":"","sourceText":"This spell reverses gravity in a 50-foot-radius, 100-foot high cylinder centered on a point within range. All creatures and objects that aren't somehow anchored to the ground in the area fall upward and reach the top of the area when you cast this spell. A creature can make a dexterity saving throw to grab onto a fixed object it can reach, thus avoiding the fall.\n\nIf some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it just as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, for the duration.\n\nAt the end of the duration, affected objects and creatures fall back down.","higherSource":""},{"id":"revivify","name":"Revivify","nameTr":"Canlandır","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric","Paladin"],"subclasses":["Life","Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği 300gp değerindeki elmaslar.","materialSource":"Diamonds worth 300gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Son dakikada ölen bir yaratığa dokunuyorsunuz. O yaratık 1 can puanıyla hayata döner. Bu büyü, yaşlılıktan ölen bir yaratığı hayata döndüremez veya eksik vücut parçalarını geri getiremez.","higher":"","sourceText":"You touch a creature that has died within the last minute. That creature returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore any missing body parts.","higherSource":""},{"id":"rope-trick","name":"Rope Trick","nameTr":"Halat Hilesi","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Toz mısır özü ve bükülmüş bir parşömen halkası.","materialSource":"Powdered corn extract and a twisted loop of parchment.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"60 ft uzunluğa kadar olan bir ipe dokunuyorsunuz. İpin bir ucu daha sonra tüm ip yere dik olarak asılı kalana kadar havaya yükselir. İpin üst ucunda, invisible girişi, büyü bitene kadar sürecek olan boyut dışı bir alana açılıyor.\nHalatın tepesine tırmanılarak ekstra boyutsal alana ulaşılabilir. Alan sekize kadar Orta boy veya daha küçük yaratıkları barındırabilir. Halat alanın içine çekilerek ipin alanın dışında gözden kaybolması sağlanır.\nSaldırılar ve büyüler, ekstra boyutsal alanın girişinden veya dışına geçemez, ancak içeridekiler, sanki ipin üzerinde merkezlenmiş bir 3 ft-by-5 ft penceresinden dışarıyı görebilirler.\nBüyü sona erdiğinde, ekstra boyutlu uzayın içindeki her şey dışarı çıkar.","higher":"","sourceText":"You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.\n\nThe extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.\n\nAttacks and spells can't cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.\n\nAnything inside the extradimensional space drops out when the spell ends.","higherSource":""},{"id":"sacred-flame","name":"Sacred Flame","nameTr":"Kutsal Alev","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"none","area":null,"description":"Alev benzeri bir parlaklık, menzil içinde görebileceğiniz bir yaratığın üzerine iner. Hedef bir DEX saving throw üzerinde başarılı olmalı veya 1d8 radiant hasarı almalıdır. Hedef, bu saving throw için korumadan hiçbir fayda elde etmez.\nBüyünün hasarı, 5. seviyeye (2d8), 11. seviyeye (3d8) ve 17. seviyeye (4d8) ulaştığınızda 1d8 artar.","higher":"","sourceText":"Flame-like radiance descends on a creature that you can see within range. The target must succeed on a dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","higherSource":""},{"id":"sanctuary","name":"Sanctuary","nameTr":"Kutsal alan","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric"],"subclasses":["Devotion","Lore"],"castingTime":"1 bonus action","range":"30 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük gümüş bir ayna.","materialSource":"A small silver mirror.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Menzil içindeki bir yaratığı saldırıya karşı korursunuz. Büyü sona erene kadar, muhafaza edilen yaratığı bir saldırı veya zararlı bir büyüyle hedef alan herhangi bir yaratık, önce bir WIS saving throw yapmalıdır. Başarısız bir kurtarma durumunda yaratığın yeni bir hedef seçmesi veya saldırıyı veya büyüyü kaybetmesi gerekir. Bu büyü, muhafaza edilen yaratığı ateş topu patlaması gibi alan etkilerinden korumaz.\nMuhafaza edilen yaratık bir düşman yaratığını etkileyen bir saldırı yaparsa veya bir büyü yaparsa, bu büyü sona erer.","higher":"","sourceText":"You ward a creature within range against attack. Until the spell ends, any creature who targets the warded creature with an attack or a harmful spell must first make a wisdom saving throw. On a failed save, the creature must choose a new target or lose the attack or spell. This spell doesn't protect the warded creature from area effects, such as the explosion of a fireball.\n\nIf the warded creature makes an attack or casts a spell that affects an enemy creature, this spell ends.","higherSource":""},{"id":"scorching-ray","name":"Scorching Ray","nameTr":"Kavurucu Işın","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Fiend","Lore"],"castingTime":"1 action","range":"120 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"ranged","save":"","saves":[],"saveSuccess":"","area":null,"description":"fire'nin üç ışınını yaratır ve bunları menzil içindeki hedeflere fırlatırsınız. Bunları bir veya birkaç hedefe fırlatabilirsiniz.\nHer ışın için bir menzilli spell attack yapın. Bir vuruşta hedef 2d6 fire hasarı alır.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 2. seviyenin üzerindeki her yuva seviyesi için bir ek ışın yaratırsınız.","sourceText":"You create three rays of fire and hurl them at targets within range. You can hurl them at one target or several.\n\nMake a ranged spell attack for each ray. On a hit, the target takes 2d6 fire damage.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, you create one additional ray for each slot level above 2nd."},{"id":"scrying","name":"Scrying","nameTr":"Ağlayan","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Druid","Warlock","Wizard"],"subclasses":["Land"],"castingTime":"10 minutes","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Kristal küre, gümüş ayna veya kutsal suyla dolu yazı tipi gibi en az 1.000 GP değerinde bir odak noktası.","materialSource":"A focus worth at least 1,000 gp, such as a crystal ball, a silver mirror, or a font filled with holy water.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Sizinle aynı varoluş düzleminde bulunan, seçtiğiniz belirli bir yaratığı görebilir ve duyabilirsiniz. Hedef, hedefi ne kadar iyi bildiğinize ve onunla sahip olduğunuz fiziksel bağlantının türüne göre değişen bir WIS saving throw yapmalıdır. Hedef bu büyüyü yaptığınızı biliyorsa, gözlemlenmek istiyorsa saving throw'yi gönüllü olarak başarısızlığa uğratabilir.\n| Bilgi | Değiştiriciyi Kaydet |\n|---|---|\n| İkinci el (hedefi duymuşsunuzdur) | +5 |\n| İlk elden (hedefe ulaştınız) | +0 |\n| Tanıdık (hedefi iyi biliyorsunuz) | -5 |\n| Bağlantı | Değiştiriciyi Kaydet |\n|---|---|\n| Benzerlik veya resim | -2 |\n| Mülkiyet veya giysi | -4 |\n| Vücut kısmı, bir tutam saç, bir parça tırnak veya benzeri | -10 |\nBaşarılı bir kaydetme durumunda hedef etkilenmez ve bu büyüyü 24 saat boyunca hedefe karşı tekrar kullanamazsınız.\nBaşarısız bir kaydetme durumunda büyü, hedefin 10 ft içinde bir invisible sensörü oluşturur. Sensör aracılığıyla sanki oradaymışsınız gibi görebilir ve duyabilirsiniz. Sensör hedefle birlikte hareket eder ve bu süre boyunca hedefin 10 ft dahilinde kalır. invisible nesnelerini görebilen bir yaratık, sensörü yaklaşık yumruğunuz büyüklüğünde parlak bir küre olarak görür.\nBir yaratığı hedeflemek yerine daha önce gördüğünüz bir konumu bu büyünün hedefi olarak seçebilirsiniz. Bunu yaptığınızda sensör o konumda görünür ve hareket etmez.","higher":"","sourceText":"You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a wisdom saving throw, which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you're casting this spell, it can fail the saving throw voluntarily if it wants to be observed.\n\n| Knowledge | Save Modifier |\n\n|---|---|\n\n| Secondhand (you have heard of the target) | +5 |\n\n| Firsthand (you have met the target) | +0 |\n\n| Familiar (you know the target well) | -5 |\n\n\n\n| Connection | Save Modifier |\n\n|---|---|\n\n| Likeness or picture | -2 |\n\n| Possession or garment | -4 |\n\n| Body part, lock of hair, bit of nail, or the like | -10 |\n\nOn a successful save, the target isn't affected, and you can't use this spell against it again for 24 hours.\n\nOn a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist.\n\nInstead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn't move.","higherSource":""},{"id":"secret-chest","name":"Secret Chest","nameTr":"Gizli Sandık","level":4,"school":"Conjuration","schoolTr":"Çağırma","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"En az 5.000 gp değerinde nadir malzemelerden yapılmış zarif bir sandık, 3 ft by 2 ft ve aynı malzemelerden yapılmış en az 50 gp değerinde Minik bir kopya.","materialSource":"An exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp, and a Tiny replica made from the same materials worth at least 50 gp.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bir sandığı ve içindekileri Ethereal Plane'da saklıyorsunuz. Büyü için maddi bir bileşen görevi gören sandığa ve minyatür kopyaya dokunmalısınız. Sandık, 12 fit küp kadar canlı olmayan malzeme içerebilir (3 ft, 2 ft, 2 ft).\nSandık Ethereal Plane'da kalırken, bir eylem kullanabilir ve sandığı geri çağırmak için kopyaya dokunabilirsiniz. 5 ft içinde yerdeki boş bir alanda belirir. Bir eylem kullanarak ve hem sandığa hem de kopyaya dokunarak sandığı Ethereal Plane'a geri gönderebilirsiniz.\n60 gün sonra, büyünün etkisinin sona ermesi için günlük kümülatif yüzde 5 şans vardır. Bu etki, bu büyüyü tekrar yaptığınızda, daha küçük olan kopya sandığı yok edildiğinde veya büyüyü bir eylem olarak sonlandırmayı seçtiğinizde sona erer. Büyü sona ererse ve daha büyük olan sandık Ethereal Plane'daysa, geri dönüşü olmayacak şekilde kaybolur.","higher":"","sourceText":"You hide a chest, and all its contents, on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet).\n\nWhile the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica.\n\nAfter 60 days, there is a cumulative 5 percent chance per day that the spell's effect ends. This effect ends if you cast this spell again, if the smaller replica chest is destroyed, or if you choose to end the spell as an action. If the spell ends and the larger chest is on the Ethereal Plane, it is irretrievably lost.","higherSource":""},{"id":"see-invisibility","name":"See Invisibility","nameTr":"Görünmezliği görün","level":2,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir miktar talk ve az miktarda gümüş tozu.","materialSource":"A dash of talc and a small amount of silver powder.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü süresince invisible yaratıkları ve nesneleri görünürmüş gibi görürsünüz ve Ethereal'in içini görebilirsiniz. Ruhani nesneler ve yaratıklar hayalet gibi yarı saydam görünüyor.","higher":"","sourceText":"For the duration of the spell, you see invisible creatures and objects as if they were visible, and you can see through Ethereal. The ethereal objects and creatures appear ghostly translucent.","higherSource":""},{"id":"seeming","name":"Seeming","nameTr":"Görünüşe göre","level":5,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"","area":null,"description":"Bu büyü, menzil içinde görebileceğiniz istediğiniz sayıda yaratığın görünümünü değiştirmenizi sağlar. Seçtiğiniz her hedefe yeni, yanıltıcı bir görünüm veriyorsunuz. İsteksiz bir hedef CHA saving throw yapabilir ve eğer başarılı olursa bu büyüden etkilenmez.\nBüyü, fiziksel görünümün yanı sıra kıyafet, zırh, silah ve ekipmanı da gizler. Her yaratığın 1 ft daha kısa veya daha uzun görünmesini ve zayıf, şişman veya bu ikisinin arasında görünmesini sağlayabilirsiniz. Hedefin vücut tipini değiştiremezsiniz, dolayısıyla aynı temel uzuv düzenine sahip bir form seçmelisiniz. Aksi takdirde illüzyonun boyutu size bağlıdır. Büyüyü daha erken yok etmek için eyleminizi kullanmadığınız sürece, büyü bu süre boyunca sürer.\nBu büyünün yarattığı değişiklikler fiziksel incelemeye dayanamaz. Örneğin, bu büyüyü bir yaratığın kıyafetine şapka eklemek için kullanırsanız, nesneler şapkanın içinden geçer ve ona dokunan kişi hiçbir şey hissetmez veya yaratığın kafasını ve saçını hisseder. Bu büyüyü olduğunuzdan daha zayıf görünmek için kullanırsanız, size dokunmak için uzanan birinin eli, sanki hala havadayken size çarpacaktır.\nBir yaratık, eylemini bir hedefi incelemek ve DC'yi kurtaran büyünüze karşı bir INT (Soruşturma) kontrolü yapmak için kullanabilir. Başarılı olursa hedefin gizlendiğinin farkına varır.","higher":"","sourceText":"This spell allows you to change the appearance of any number of creatures that you can see within range. You give each target you choose a new, illusory appearance. An unwilling target can make a charisma saving throw, and if it succeeds, it is unaffected by this spell.\n\nThe spell disguises physical appearance as well as clothing, armor, weapons, and equipment. You can make each creature seem 1 foot shorter or taller and appear thin, fat, or in between. You can't change a target's body type, so you must choose a form that has the same basic arrangement of limbs. Otherwise, the extent of the illusion is up to you. The spell lasts for the duration, unless you use your action to dismiss it sooner.\n\nThe changes wrought by this spell fail to hold up to physical inspection. For example, if you use this spell to add a hat to a creature's outfit, objects pass through the hat, and anyone who touches it would feel nothing or would feel the creature's head and hair. If you use this spell to appear thinner than you are, the hand of someone who reaches out to touch you would bump into you while it was seemingly still in midair.\n\nA creature can use its action to inspect a target and make an Intelligence (Investigation) check against your spell save DC. If it succeeds, it becomes aware that the target is disguised.","higherSource":""},{"id":"sending","name":"Sending","nameTr":"Gönderiliyor","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Cleric","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Unlimited","duration":"1 round","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Kısa bir ince bakır tel parçası.","materialSource":"A short piece of fine copper wire.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Tanıdığınız bir yaratığa yirmi beş veya daha az kelimeden oluşan kısa bir mesaj gönderiyorsunuz. Canlı, mesajı zihninde duyar, tanıyorsa sizi gönderen olarak tanır ve anında aynı şekilde cevap verebilir. Büyü, INT puanı en az 1 olan yaratıkların mesajınızın anlamını anlamasını sağlar.\nMesajı istediğiniz mesafeye, hatta diğer varoluş düzlemlerine bile gönderebilirsiniz, ancak hedef sizden farklı bir düzlemdeyse, mesajın ulaşmama ihtimali yüzde 5'tir.","higher":"","sourceText":"You send a short message of twenty-five words or less to a creature with which you are familiar. The creature hears the message in its mind, recognizes you as the sender if it knows you, and can answer in a like manner immediately. The spell enables creatures with Intelligence scores of at least 1 to understand the meaning of your message.\n\nYou can send the message across any distance and even to other planes of existence, but if the target is on a different plane than you, there is a 5 percent chance that the message doesn't arrive.","higherSource":""},{"id":"sequester","name":"Sequester","nameTr":"Tecritçi","level":7,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 5.000 gp değerinde elmas, zümrüt, yakut ve safir tozundan oluşan bir toz.","materialSource":"A powder composed of diamond, emerald, ruby, and sapphire dust worth at least 5,000 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü sayesinde istekli bir yaratık veya bir nesne, bu süre boyunca tespit edilmeden saklanabilir. Büyüyü yapıp hedefe dokunduğunuzda invisible olur ve kehanet büyüleri tarafından hedef alınamaz veya kehanet büyülerinin oluşturduğu tarama sensörleri aracılığıyla algılanamaz.\nHedef bir yaratıksa, animasyonun askıya alınması durumuna düşer. Zaman onun için akmayı bırakır ve yaşlanmaz.\nBüyünün erken bitmesi için bir koşul belirleyebilirsiniz. Koşul, seçtiğiniz herhangi bir şey olabilir ancak hedefin 1 mil içinde oluşması veya görünür olması gerekir. Örnekler arasında \"1000 yıl sonra\" veya \"tarrask uyandığında\" yer alır. Bu büyü, hedefin herhangi bir hasar alması durumunda da sona erer.","higher":"","sourceText":"By means of this spell, a willing creature or an object can be hidden away, safe from detection for the duration. When you cast the spell and touch the target, it becomes invisible and can't be targeted by divination spells or perceived through scrying sensors created by divination spells.\n\nIf the target is a creature, it falls into a state of suspended animation. Time ceases to flow for it, and it doesn't grow older.\n\nYou can set a condition for the spell to end early. The condition can be anything you choose, but it must occur or be visible within 1 mile of the target. Examples include \"after 1,000 years\" or \"when the tarrasque awakens.\" This spell also ends if the target takes any damage.","higherSource":""},{"id":"shapechange","name":"Shapechange","nameTr":"Şekil değiştirme","level":9,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Büyüyü yapmadan önce kafanıza yerleştirmeniz gereken, en az 1.500 gp değerinde bir yeşim tacı.","materialSource":"A jade circlet worth at least 1,500 gp, which you must place on your head before you cast the spell.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca farklı bir yaratığın şeklini alırsınız. Yeni form, seviyenize eşit veya daha düşük bir meydan okuma derecesine sahip herhangi bir yaratıktan oluşabilir. Yaratık bir yapı ya da ölümsüz olamaz ve bu türden bir yaratığı en az bir kez görmüş olmalısınız. Herhangi bir sınıf seviyesi veya Büyü Yapma özelliği olmayan, o yaratığın ortalama bir örneğine dönüşürsünüz.\nOyun istatistikleriniz seçilen yaratığın istatistikleriyle değiştirilir, ancak hizalamanızı ve INT, WIS ve CHA puanlarınızı korursunuz. Ayrıca yaratığın yeteneklerini kazanmanın yanı sıra tüm becerilerinizi ve saving throw yeterliliklerinizi de korursunuz. Yaratık sizinle aynı yeterliliğe sahipse ve istatistiklerinde listelenen bonus sizinkinden yüksekse, sizinki yerine yaratığın bonusunu kullanın. Yeni formun efsanevi eylemlerini veya sığınak eylemlerini kullanamazsınız.\nYeni formun HP ve Hit Dice'larını üstleniyorsunuz. Normal formunuza döndüğünüzde, dönüşmeden önce sahip olduğunuz HP sayısına geri dönersiniz. 0 HP'ye düşme sonucunda geri dönerseniz, fazla hasar normal formunuza aktarılır. Aşırı hasar normal formunuzu 0 HP'ye düşürmediği sürece unconscious devrilmezsiniz.\nYeni formunuzun fiziksel olarak bunu yapabilecek kapasiteye sahip olması koşuluyla, sınıfınızın, ırkınızın veya başka bir kaynağınızın tüm özelliklerinden yararlanmaya devam edersiniz ve bunları kullanabilirsiniz. Yeni formunuz aynı anlama sahip olmadığı sürece, sahip olduğunuz herhangi bir özel duyuyu (örneğin, karanlık görüş) kullanamazsınız. Yalnızca yaratık normal şekilde konuşabiliyorsa konuşabilirsiniz.\nDönüştürdüğünüzde ekipmanınızın yere düşüp düşmeyeceğini, yeni forma girip girmeyeceğini veya onun tarafından aşınıp yıpranmayacağını siz seçersiniz. Aşınmış ekipman normal şekilde çalışır. GM, yaratığın şekline ve boyutuna göre yeni formun bir ekipman giymesinin pratik olup olmadığına karar verir. Ekipmanınızın şekli veya boyutu yeni forma uyacak şekilde değişmez ve yeni formun giyemeyeceği herhangi bir ekipman ya yere düşmeli ya da yeni formunuza karışmalıdır. Birleşen ekipmanın bu durumda hiçbir etkisi yoktur.\nBu büyünün süresi boyunca, bir istisna dışında, orijinal form için aynı kısıtlamaları ve kuralları izleyerek farklı bir form almak için eyleminizi kullanabilirsiniz: yeni formunuz mevcut formunuzdan daha fazla HP içeriyorsa, HP'niz mevcut değerinde kalır.","higher":"","sourceText":"You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating equal to your level or lower. The creature can't be a construct or an undead, and you must have seen the sort of creature at least once. You transform into an average example of that creature, one without any class levels or the Spellcasting trait.\n\nYour game statistics are replaced by the statistics of the chosen creature, though you retain your alignment and Intelligence, Wisdom, and Charisma scores. You also retain all of your skill and saving throw proficiencies, in addition to gaining those of the creature. If the creature has the same proficiency as you and the bonus listed in its statistics is higher than yours, use the creature's bonus in place of yours. You can't use any legendary actions or lair actions of the new form.\n\nYou assume the hit points and Hit Dice of the new form. When you revert to your normal form, you return to the number of hit points you had before you transformed. If you revert as a result of dropping to 0 hit points, any excess damage carries over to your normal form. As long as the excess damage doesn't reduce your normal form to 0 hit points, you aren't knocked unconscious.\n\nYou retain the benefit of any features from your class, race, or other source and can use them, provided that your new form is physically capable of doing so. You can't use any special senses you have (for example, darkvision) unless your new form also has that sense. You can only speak if the creature can normally speak.\n\nWhen you transform, you choose whether your equipment falls to the ground, merges into the new form, or is worn by it. Worn equipment functions as normal. The GM determines whether it is practical for the new form to wear a piece of equipment, based on the creature's shape and size. Your equipment doesn't change shape or size to match the new form, and any equipment that the new form can't wear must either fall to the ground or merge into your new form. Equipment that merges has no effect in that state.\n\nDuring this spell's duration, you can use your action to assume a different form following the same restrictions and rules for the original form, with one exception: if your new form has more hit points than your current one, your hit points remain at their current value.","higherSource":""},{"id":"shatter","name":"Shatter","nameTr":"Paramparça","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir mika patlaması.","materialSource":"A burst of mica.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"sphere","size":10},"description":"Menzil içinde seçtiğiniz bir noktadan acı verici derecede yoğun, ani, yüksek bir çınlama sesi geliyor. Bu noktaya odaklanan 10 ft yarıçaplı küredeki her yaratık, CON saving throw atmalıdır. Bir yaratık, başarısız save’de 3d8 thunder hasar alır veya başarılı save’de bunun yarısı kadar hasar alır. Taş, kristal veya metal gibi inorganik malzemeden yapılmış bir yaratık, bu saving throw'de dezavantaj'ye sahiptir.\nBüyülü olmayan, giyilmeyen veya taşınmayan bir eşya da büyünün etki alanı içerisindeyse zarar görür.","higher":"Bu büyüyü 3 veya daha yüksek seviyeli bir spell slot kullanarak yaptığınızda, büyünün hasarı daha yüksek spell slot 2'nin her seviyesi için 1d8 artar.","sourceText":"A sudden loud ringing noise, painfully intense, erupts from a point of your choice within range. Each creature in a 10-foot-radius sphere centered on that point must make a Constitution saving throw. A creature takes 3d8 thunder damage on a failed save, or half as much damage on a successful one. A creature made of inorganic material such as stone, crystal, or metal has disadvantage on this saving throw.\n\nA non-magical item that is not worn or carried also suffers damage if it is in the area of the spell.","higherSource":"When you cast this spell using a 3 or higher level spell slot, the damage of the spell increases by 1d8 for each level of higher spell slot 2."},{"id":"shield","name":"Shield","nameTr":"Kalkan","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 reaction","range":"Self","duration":"1 round","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyülü force'den oluşan invisible bariyeri belirir ve sizi korur. Bir sonraki turunuzun başlangıcına kadar, tetikleyici saldırıya karşı da dahil olmak üzere AC'ye +5 bonusunuz vardır ve sihirli füzeden hasar almazsınız.","higher":"","sourceText":"An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile.","higherSource":""},{"id":"shield-of-faith","name":"Shield of Faith","nameTr":"İnanç Kalkanı","level":1,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric","Paladin"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Üzerinde kutsal metinlerin yazılı olduğu küçük bir parşömen.","materialSource":"A small parchment with a bit of holy text written on it.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Parıldayan bir alan belirir ve menzil içindeki seçtiğiniz bir yaratığı çevreler, bu süre boyunca ona AC'ye +2 bonus kazandırır.","higher":"","sourceText":"A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.","higherSource":""},{"id":"shillelagh","name":"Shillelagh","nameTr":"Shillelagh","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":["Lore"],"castingTime":"1 bonus action","range":"Touch","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Ökseotu, yonca yaprağı ve sopa ya da çeyrek asa.","materialSource":"Mistletoe, a shamrock leaf, and a club or quarterstaff.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Elinizde tuttuğunuz bir sopanın veya çeyrek asanın odunu doğanın gücüyle doludur. Bu süre boyunca, bu silahı kullanarak yakın dövüş saldırılarının saldırı ve hasar atışları için STR yerine büyü yapma yeteneğinizi kullanabilirsiniz ve silahın hasar kalıbı d8 olur. Silah da büyülü hale geliyor, eğer zaten değilse. Tekrar yaptığınızda ya da silahı bıraktığınız takdirde büyü sona erer.","higher":"","sourceText":"The wood of a club or a quarterstaff you are holding is imbued with nature's power. For the duration, you can use your spellcasting ability instead of Strength for the attack and damage rolls of melee attacks using that weapon, and the weapon's damage die becomes a d8. The weapon also becomes magical, if it isn't already. The spell ends if you cast it again or if you let go of the weapon.","higherSource":""},{"id":"shocking-grasp","name":"Shocking Grasp","nameTr":"Şok edici Kavrama","level":0,"school":"Evocation","schoolTr":"Yıkım","classes":["Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"lightning elinizden fırlayarak dokunmaya çalıştığınız yaratığa şok verir. Hedefe karşı bir yakın spell attack yapın. Hedef metalden yapılmış zırh giyiyorsa avantaj saldırı zarı'ye sahiptir. Hedef bir vuruşta 1d8 lightning hasarı alır ve bir sonraki turun başlangıcına kadar Reaction’lar'yi alamaz.\nBüyünün hasarı, 5. seviyeye (2d8), 11. seviyeye (3d8) ve 17. seviyeye (4d8) ulaştığınızda 1d8 artar.","higher":"","sourceText":"Lightning springs from your hand to deliver a shock to a creature you try to touch. Make a melee spell attack against the target. You have advantage on the attack roll if the target is wearing armor made of metal. On a hit, the target takes 1d8 lightning damage, and it can't take reactions until the start of its next turn.\n\nThe spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).","higherSource":""},{"id":"silence","name":"Silence","nameTr":"Sessizlik","level":2,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Cleric","Ranger"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":20},"description":"Bu süre boyunca, menzil içinde seçtiğiniz bir noktanın merkezinde bulunan 20 ft yarıçap küresinin içinde hiçbir ses oluşturulamaz veya içinden geçilemez. Tamamen kürenin içinde olan herhangi bir yaratık veya nesne, thunder hasarına karşı bağışıklıdır ve yaratıklar, tamamen kürenin içindeyken deafened'dir.\nSözlü bileşen içeren bir büyünün yapılması burada imkansızdır.","higher":"","sourceText":"For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point you choose within range. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it.\n\nCasting a spell that includes a verbal component is impossible there.","higherSource":""},{"id":"silent-image","name":"Silent Image","nameTr":"Sessiz Görüntü","level":1,"school":"Illusion","schoolTr":"İllüzyon","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz yün.","materialSource":"A bit of fleece.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":15},"description":"Bir 15 ft küpünden daha büyük olmayan bir nesnenin, bir yaratığın veya başka bir görünür olgunun görüntüsünü yaratırsınız. Görüntü menzil içindeki bir noktada belirir ve bu süre boyunca devam eder. Görüntü tamamen görseldir; buna ses, koku veya diğer duyusal etkiler eşlik etmez.\nEyleminizi, görüntünün menzil içindeki herhangi bir noktaya taşınmasını sağlamak için kullanabilirsiniz. Görüntünün konumu değiştikçe, hareketlerinin görüntü için doğal görünmesini sağlayacak şekilde görünümünü değiştirebilirsiniz. Örneğin, bir yaratığın görüntüsünü oluşturup onu hareket ettirirseniz, görüntüyü yürüyormuş gibi görünecek şekilde değiştirebilirsiniz.\nGörüntüyle fiziksel etkileşim onun bir yanılsama olduğunu ortaya koyuyor çünkü nesneler onun içinden geçebiliyor. Görüntüyü incelemek için eylemini kullanan bir yaratık, DC'yi kaydetme büyünüze karşı başarılı bir INT (Soruşturma) kontrolü ile bunun bir illüzyon olduğunu belirleyebilir. Bir yaratık illüzyonun ne olduğunu anlarsa, yaratık görüntünün arkasını görebilir.","higher":"","sourceText":"You create the image of an object, a creature, or some other visible phenomenon that is no larger than a 15-foot cube. The image appears at a spot within range and lasts for the duration. The image is purely visual; it isn't accompanied by sound, smell, or other sensory effects.\n\nYou can use your action to cause the image to move to any spot within range. As the image changes location, you can alter its appearance so that its movements appear natural for the image. For example, if you create an image of a creature and move it, you can alter the image so that it appears to be walking.\n\nPhysical interaction with the image reveals it to be an illusion, because things can pass through it. A creature that uses its action to examine the image can determine that it is an illusion with a successful Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through the image.","higherSource":""},{"id":"simulacrum","name":"Simulacrum","nameTr":"Simülakr","level":7,"school":"Illusion","schoolTr":"İllüzyon","classes":["Wizard"],"subclasses":[],"castingTime":"12 hours","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Kopyalanan yaratığın gerçek boyutlu bir kopyasını oluşturmaya yetecek miktarda kar veya buz; kar veya buzun içine yerleştirilmiş bir miktar saç, tırnak kırpıntısı veya o yaratığın vücudunun başka bir parçası; ve 1.500 gp değerindeki toz yakut, kopyanın üzerine serpilir ve büyü tarafından tüketilir.","materialSource":"Snow or ice in quantities sufficient to made a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature's body placed inside the snow or ice; and powdered ruby worth 1,500 gp, sprinkled over the duplicate and consumed by the spell.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyünün tüm kullanım süresi boyunca menzil içinde olan bir canavarın veya insansı bir kopyanın hayali bir kopyasını şekillendirirsiniz. Kopya, kısmen gerçek, buz veya kardan oluşan bir yaratıktır ve normal bir yaratık gibi harekete geçebilir ve diğer durumlarda etkilenebilir. Orijinaliyle aynı gibi görünüyor ancak yaratığın maksimum can puanının yarısına sahip ve herhangi bir ekipman olmadan oluşturulmuş. Aksi takdirde illüzyon, kopyaladığı yaratığın tüm istatistiklerini kullanır.\nSimulacrum size ve belirlediğiniz yaratıklara karşı dosttur. Söylediğiniz komutlara uyar, istekleriniz doğrultusunda hareket eder ve hareket eder, savaşta sıranız geldiğinde hareket eder. Simulacrum, öğrenme veya daha güçlü olma yeteneğinden yoksun olduğundan, seviyesini veya diğer yeteneklerini asla artırmaz ve harcanan spell slot’ları'yi geri kazanamaz.\nSimulacrum hasar görürse, onu bir simya laboratuvarında, geri kazandığı isabet noktası başına 100 gp değerindeki nadir şifalı otları ve mineralleri kullanarak onarabilirsiniz. Simülakr, 0 HP'ye düşene kadar devam ediyor, bu noktada kara dönüyor ve anında eriyor.\nBu büyüyü tekrar yaparsanız, bu büyüyle oluşturduğunuz mevcut etkin kopyalar anında yok edilir.","higher":"","sourceText":"You shape an illusory duplicate of one beast or humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature's hit point maximum and is formed without any equipment. Otherwise, the illusion uses all the statistics of the creature it duplicates.\n\nThe simulacrum is friendly to you and creatures you designate. It obeys your spoken commands, moving and acting in accordance with your wishes and acting on your turn in combat. The simulacrum lacks the ability to learn or become more powerful, so it never increases its level or other abilities, nor can it regain expended spell slots.\n\nIf the simulacrum is damaged, you can repair it in an alchemical laboratory, using rare herbs and minerals worth 100 gp per hit point it regains. The simulacrum lasts until it drops to 0 hit points, at which point it reverts to snow and melts instantly.\n\nIf you cast this spell again, any currently active duplicates you created with this spell are instantly destroyed.","higherSource":""},{"id":"sleep","name":"Sleep","nameTr":"Uyku","level":1,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"90 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam ince kum, gül yaprakları veya bir cırcır böceği.","materialSource":"A pinch of fine sand, rose petals, or a cricket.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":20},"description":"Bu büyü yaratıkları büyülü bir uykuya sokar. Rulo 5d8; toplam, bu büyünün kaç HP yaratığı etkileyebileceğini gösterir. Menzil içinde seçtiğiniz bir noktanın 20 ft içindeki yaratıklar, mevcut HP'lerine göre artan sırada etkilenir (unconscious yaratıkları göz ardı edilir).\nEn düşük akım HP'ye sahip yaratıktan başlayarak, bu büyüden etkilenen her yaratık, büyü bitene, uyuyan hasar alana veya birisi uyuyan kişiyi sarsmak veya tokatlamak için bir eylem kullanana kadar unconscious düşer. Bir sonraki en düşük HP'ye sahip yaratığa geçmeden önce her yaratığın HP'sini toplamdan çıkarın. Bir yaratığın etkilenebilmesi için HP'nin kalan toplam değere eşit veya daha az olması gerekir.\nZombi ve charmed olmaya bağışıklı yaratıklar bu büyüden etkilenmez.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 1. seviyenin üzerindeki her yuva seviyesi için ek bir 2d8 yuvarlayın.","sourceText":"This spell sends creatures into a magical slumber. Roll 5d8; the total is how many hit points of creatures this spell can affect. Creatures within 20 feet of a point you choose within range are affected in ascending order of their current hit points (ignoring unconscious creatures).\n\nStarting with the creature that has the lowest current hit points, each creature affected by this spell falls unconscious until the spell ends, the sleeper takes damage, or someone uses an action to shake or slap the sleeper awake. Subtract each creature's hit points from the total before moving on to the creature with the next lowest hit points. A creature's hit points must be equal to or less than the remaining total for that creature to be affected.\n\nUndead and creatures immune to being charmed aren't affected by this spell.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, roll an additional 2d8 for each slot level above 1st."},{"id":"sleet-storm","name":"Sleet Storm","nameTr":"Karla karışık yağmur fırtınası","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"150 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir tutam toz ve birkaç damla su.","materialSource":"A pinch of dust and a few drops of water.","attackType":"","save":"DEX","saves":["DEX","CON"],"saveSuccess":"","area":{"type":"cylinder","size":40},"description":"Büyü sona erene kadar, menzil içinde seçtiğiniz bir noktaya odaklanan 40 ft yarıçaplı bir 20 ft yükseklik silindirinde dondurucu yağmur ve karla karışık yağmur yağıyor. Alan büyük ölçüde gizlenmiş durumda ve bölgedeki açıkta kalan alevler söndürülüyor.\nBölgedeki zeminin kaygan buzla kaplı olması araziyi zorlaştırıyor. Bir yaratık büyü alanına ilk kez bir turda girdiğinde veya dönüşüne orada başladığında, bir DEX saving throw yapmalıdır. Başarısız bir kaydetme durumunda prone düşer.\nBir yaratık büyü alanında yoğunlaşıyorsa, yaratığın büyünüze karşı başarılı bir CON saving throw yapması gerekir, DC'yi kurtarmalı veya concentration'yi kaybetmelidir.","higher":"","sourceText":"Until the spell ends, freezing rain and sleet fall in a 20-foot-tall cylinder with a 40-foot radius centered on a point you choose within range. The area is heavily obscured, and exposed flames in the area are doused.\n\nThe ground in the area is covered with slick ice, making it difficult terrain. When a creature enters the spell's area for the first time on a turn or starts its turn there, it must make a dexterity saving throw. On a failed save, it falls prone.\n\nIf a creature is concentrating in the spell's area, the creature must make a successful constitution saving throw against your spell save DC or lose concentration.","higherSource":""},{"id":"slow","name":"Slow","nameTr":"Yavaş","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla pekmez.","materialSource":"A drop of molasses.","attackType":"","save":"WIS","saves":["WIS","DEX"],"saveSuccess":"none","area":{"type":"cube","size":40},"description":"Menzil içindeki bir 40 ft küpünde seçtiğiniz altı yaratığa kadar zamanı değiştiriyorsunuz. Her hedefin bir WIS saving throw üzerinde başarılı olması veya bu süre boyunca bu büyüden etkilenmesi gerekir.\nEtkilenen bir hedefin hızı yarıya düşer, AC ve DEX saving throw’lar'ye -2 ceza alır ve Reaction’lar'yi kullanamaz. Sırasıyla, bir eylemi veya bir Bonus Action'yi kullanabilir, ikisini birden kullanamaz. Yaratığın yetenekleri veya büyü eşyaları ne olursa olsun, sırası geldiğinde birden fazla yakın dövüş veya menzilli saldırı yapamaz.\nYaratık, kullanım süresi 1 eylem olan bir büyü yapmaya çalışırsa, d20 yuvarlayın. 11 veya daha yüksek bir puanda büyü, yaratığın bir sonraki turuna kadar etkili olmaz ve yaratığın, büyüyü tamamlamak için o turdaki eylemini kullanması gerekir. Eğer başaramazsa büyü boşa gider.\nBu büyüden etkilenen yaratık, sırasının sonunda başka bir WIS saving throw yapar. Başarılı bir kaydetme durumunda efekt sona erer.","higher":"","sourceText":"You alter time around up to six creatures of your choice in a 40-foot cube within range. Each target must succeed on a wisdom saving throw or be affected by this spell for the duration.\n\nAn affected target's speed is halved, it takes a -2 penalty to AC and dexterity saving throws, and it can't use reactions. On its turn, it can use either an action or a bonus action, not both. Regardless of the creature's abilities or magic items, it can't make more than one melee or ranged attack during its turn.\n\nIf the creature attempts to cast a spell with a casting time of 1 action, roll a d20. On an 11 or higher, the spell doesn't take effect until the creature's next turn, and the creature must use its action on that turn to complete the spell. If it can't, the spell is wasted.\n\nA creature affected by this spell makes another wisdom saving throw at the end of its turn. On a successful save, the effect ends for it.","higherSource":""},{"id":"spare-the-dying","name":"Spare the Dying","nameTr":"Ölmeyi Koruyun","level":0,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"0 HP'ye sahip bir canlıya dokunuyorsunuz. Yaratık stabil hale gelir. Bu büyünün ölümsüzler veya yapılar üzerinde hiçbir etkisi yoktur.","higher":"","sourceText":"You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs.","higherSource":""},{"id":"speak-with-animals","name":"Speak with Animals","nameTr":"Hayvanlarla Konuşun","level":1,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"10 minutes","concentration":false,"ritual":true,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu süre boyunca canavarları anlama ve sözlü olarak iletişim kurma yeteneğini kazanırsınız. Pek çok canavarın bilgisi ve farkındalığı INT ile sınırlıdır, ancak hayvanlar en azından size yakın konumlar ve canavarlar hakkında, son gün içinde algılayabildikleri veya algıladıkları bilgiler dahil olmak üzere bilgi verebilir. GM'nin takdirine bağlı olarak, bir canavarı sizin için küçük bir iyilik yapmaya ikna edebilirsiniz.","higher":"","sourceText":"You gain the ability to comprehend and verbally communicate with beasts for the duration. The knowledge and awareness of many beasts is limited by their intelligence, but at a minimum, beasts can give you information about nearby locations and monsters, including whatever they can perceive or have perceived within the past day. You might be able to persuade a beast to perform a small favor for you, at the GM's discretion.","higherSource":""},{"id":"speak-with-dead","name":"Speak with Dead","nameTr":"Ölüyle Konuş","level":3,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Bard","Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"10 feet","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Tütsü yakmak.","materialSource":"Burning incense.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içindeki seçtiğiniz bir cesede yaşam görünümü ve INT verirsiniz ve onun sorduğunuz soruları yanıtlamasına olanak tanırsınız. Cesedin hala bir ağzı olmalı ve ölümsüz olamaz. Ceset son 10 gün içinde bu büyünün hedefi ise büyü başarısız olur.\nBüyü bitene kadar cesede en fazla beş soru sorabilirsiniz. Ceset, bildiği diller dahil, yalnızca hayatta bildiği kadarını biliyor. Cevaplar genellikle kısa, şifreli veya tekrarlayıcıdır ve eğer ona düşmansanız veya sizi düşman olarak tanıyorsa, cesedin doğru bir cevap verme zorunluluğu yoktur. Bu büyü, yaratığın ruhunu bedenine geri döndürmez, yalnızca canlandırıcı ruhunu geri getirir. Böylece ceset yeni bilgiler öğrenemez, öldüğü andan itibaren olup bitenleri kavrayamaz ve gelecek olaylar hakkında tahminde bulunamaz.","higher":"","sourceText":"You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can't be undead. The spell fails if the corpse was the target of this spell within the last 10 days.\n\nUntil the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn't return the creature's soul to its body, only its animating spirit. Thus, the corpse can't learn new information, doesn't comprehend anything that has happened since it died, and can't speculate about future events.","higherSource":""},{"id":"speak-with-plants","name":"Speak with Plants","nameTr":"Bitkilerle Konuşun","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"30 ft içinizdeki bitkilere sınırlı bir duyarlılık ve animasyon aşılayarak onlara sizinle iletişim kurma ve basit komutlarınızı takip etme yeteneği verirsiniz. Geçen gün içinde büyü alanında meydana gelen olaylar hakkında bitkileri sorgulayabilir, geçen yaratıklar, hava durumu ve diğer koşullar hakkında bilgi edinebilirsiniz.\nAyrıca bitki büyümesinden kaynaklanan zorlu arazileri (çalılıklar ve çalılıklar gibi) bu süre boyunca süren sıradan arazilere dönüştürebilirsiniz. Veya bitkilerin bulunduğu sıradan araziyi, örneğin sarmaşıkların ve dalların takipçileri engellemesine neden olacak şekilde, süre boyunca zorlu araziye dönüştürebilirsiniz.\nTesisler, GM'nin takdirine bağlı olarak sizin adınıza başka görevleri de yerine getirebilir. Büyü, bitkilerin kendilerini köklerinden söküp hareket etmelerini sağlamaz ancak dalları, filizleri ve sapları serbestçe hareket ettirebilirler.\nEğer bölgede bir bitki canlı varsa, onunla ortak bir dili paylaşıyormuş gibi iletişim kurabilirsiniz ancak onu etkilemek için hiçbir sihirli yetenek kazanamazsınız.\nBu büyü, dolaştırma büyüsü tarafından oluşturulan bitkilerin bir restrained yaratığını serbest bırakmasına neden olabilir.","higher":"","sourceText":"You imbue plants within 30 feet of you with limited sentience and animation, giving them the ability to communicate with you and follow your simple commands. You can question plants about events in the spell's area within the past day, gaining information about creatures that have passed, weather, and other circumstances.\n\nYou can also turn difficult terrain caused by plant growth (such as thickets and undergrowth) into ordinary terrain that lasts for the duration. Or you can turn ordinary terrain where plants are present into difficult terrain that lasts for the duration, causing vines and branches to hinder pursuers, for example.\n\nPlants might be able to perform other tasks on your behalf, at the GM's discretion. The spell doesn't enable plants to uproot themselves and move about, but they can freely move branches, tendrils, and stalks.\n\nIf a plant creature is in the area, you can communicate with it as if you shared a common language, but you gain no magical ability to influence it.\n\nThis spell can cause the plants created by the entangle spell to release a restrained creature.","higherSource":""},{"id":"spider-climb","name":"Spider Climb","nameTr":"Örümcek Tırmanışı","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Warlock","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla bitüm ve bir örümcek.","materialSource":"A drop of bitumen and a spider.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Büyü sona erene kadar, dokunduğunuz istekli bir yaratık, ellerini serbest bırakarak yukarı, aşağı, dikey yüzeyler boyunca ve tavanlar boyunca baş aşağı hareket etme yeteneği kazanır. Hedef aynı zamanda yürüme hızına eşit bir tırmanma hızı da kazanır.","higher":"","sourceText":"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed.","higherSource":""},{"id":"spike-growth","name":"Spike Growth","nameTr":"Ani Büyüme","level":2,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"150 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Yedi keskin diken ya da yedi küçük dal; her biri bir noktaya kadar sivrilmişti.","materialSource":"Seven sharp thorns or seven small twigs, each sharpened to a point.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cylinder","size":20},"description":"Menzil dahilindeki bir noktaya odaklanan 20 ft yarıçapındaki zemin bükülüyor ve sert sivri uçlar ve dikenler filizleniyor. Bölge bu süre boyunca zorlu bir arazi haline gelir. Bir yaratık alanın içine veya içinde hareket ettiğinde, seyahat ettiği her 5 ft için 2d4 piercing hasarı alır.\nZeminin dönüşümü doğal görünecek şekilde kamufle edilmiştir. Büyü yapıldığı sırada bölgeyi göremeyen herhangi bir yaratık, araziye girmeden önce araziyi tehlikeli olarak tanımak için büyü tasarruf DC'nize karşı bir WIS (Algı) kontrolü yapabilir.","higher":"","sourceText":"The ground in a 20-foot radius centered on a point within range twists and sprouts hard spikes and thorns. The area becomes difficult terrain for the duration. When a creature moves into or within the area, it takes 2d4 piercing damage for every 5 feet it travels.\n\nThe transformation of the ground is camouflaged to look natural. Any creature that can't see the area at the time the spell is cast can make a Wisdom (Perception) check against your spell save DC to recognize the terrain as hazardous before entering it.","higherSource":""},{"id":"spirit-guardians","name":"Spirit Guardians","nameTr":"Ruh Muhafızları","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Kutsal bir sembol.","materialSource":"A holy symbol.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Sizi korumak için ruhları çağırıyorsunuz. Bu süre boyunca etrafınızda 15 ft mesafeye kadar uçarlar. İyi ya da tarafsızsanız, onların spektral formu meleksi ya da fey (seçiminiz) görünür. Eğer kötüysen, onlar şeytani görünürler.\nBu büyüyü yaptığınızda, görebildiğiniz sayıda yaratığın bundan etkilenmeyeceğini belirleyebilirsiniz. Etkilenen yaratığın bölgedeki hızı yarıya düşer ve yaratık bölgeye ilk kez bir dönüşle girdiğinde veya dönüşüne orada başladığında WIS saving throw yapması gerekir. Başarısız bir kurtarma durumunda, yaratık 3d8 radiant hasarı (eğer iyi veya tarafsızsanız) veya 3d8 necrotic hasarı (eğer kötüyseniz) alır. Başarılı bir kurtarışta yaratık, yarısı kadar hasar alır.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 3. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"You call forth spirits to protect you. They flit around you to a distance of 15 feet for the duration. If you are good or neutral, their spectral form appears angelic or fey (your choice). If you are evil, they appear fiendish.\n\nWhen you cast this spell, you can designate any number of creatures you can see to be unaffected by it. An affected creature's speed is halved in the area, and when the creature enters the area for the first time on a turn or starts its turn there, it must make a wisdom saving throw. On a failed save, the creature takes 3d8 radiant damage (if you are good or neutral) or 3d8 necrotic damage (if you are evil). On a successful save, the creature takes half as much damage.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."},{"id":"spiritual-weapon","name":"Spiritual Weapon","nameTr":"Ruhsal Silah","level":2,"school":"Evocation","schoolTr":"Yıkım","classes":["Cleric"],"subclasses":["Life","Lore"],"castingTime":"1 bonus action","range":"60 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde, bu büyüyü tekrar yapana kadar veya bu süre boyunca süren, süzülen, hayalet bir silah yaratırsınız. Büyüyü yaptığınızda, silahın 5 ft içindeki bir yaratığa karşı yakın spell attack yapabilirsiniz. Bir vuruşta hedef, force hasarı, 1d8 + büyü yapma yeteneği değiştiricinize eşit alır.\nSıra size geldiğinde Bonus Action olarak silahı 20 ft'ye taşıyabilir ve 5 ft içindeki bir yaratığa karşı saldırıyı tekrarlayabilirsiniz.\nSilah seçtiğiniz herhangi bir formu alabilir. Belirli bir silahla ilişkilendirilen tanrıların din adamları (St. Cuthbert'in gürzüyle ve Thor'un çekiciyle tanınması gibi) bu büyünün etkisinin o silaha benzemesini sağlar.","higher":"Bu büyüyü 3. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 2. seviyenin üzerindeki her iki yuva seviyesi için 1d8 artar.","sourceText":"You create a floating, spectral weapon within range that lasts for the duration or until you cast this spell again. When you cast the spell, you can make a melee spell attack against a creature within 5 feet of the weapon. On a hit, the target takes force damage equal to 1d8 + your spellcasting ability modifier.\n\nAs a bonus action on your turn, you can move the weapon up to 20 feet and repeat the attack against a creature within 5 feet of it.\n\nThe weapon can take whatever form you choose. Clerics of deities who are associated with a particular weapon (as St. Cuthbert is known for his mace and Thor for his hammer) make this spell's effect resemble that weapon.","higherSource":"When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for every two slot levels above the 2nd."},{"id":"stinking-cloud","name":"Stinking Cloud","nameTr":"Kokuşmuş Bulut","level":3,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Sorcerer","Wizard"],"subclasses":["Fiend","Land","Lore"],"castingTime":"1 action","range":"90 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Çürük bir yumurta veya birkaç kokarca lahana yaprağı.","materialSource":"A rotten egg or several skunk cabbage leaves.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"none","area":{"type":"sphere","size":20},"description":"Menzil içindeki bir noktaya odaklanmış sarı, mide bulandırıcı gazdan oluşan bir 20 ft yarıçap küresi yaratırsınız. Bulut köşelere yayılıyor ve alanı oldukça karanlık. Bulut bu süre boyunca havada kalır.\nSırasının başlangıcında tamamen bulutun içinde olan her yaratık, poison'ye karşı bir CON saving throw yapmalıdır. Başarısız bir kurtarma durumunda yaratık, öğürerek ve sersemleten eylemini gerçekleştirir. Nefes alması gerekmeyen veya poison'ye bağışıklığı olan yaratıklar, bu saving throw'de otomatik olarak başarılı olur.\nOrta şiddette bir rüzgar (saatte en az 10 mil) 4 turdan sonra bulutu dağıtır. Güçlü bir rüzgar (saatte en az 20 mil) 1 turdan sonra onu dağıtır.","higher":"","sourceText":"You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The cloud spreads around corners, and its area is heavily obscured. The cloud lingers in the air for the duration.\n\nEach creature that is completely within the cloud at the start of its turn must make a constitution saving throw against poison. On a failed save, the creature spends its action that turn retching and reeling. Creatures that don't need to breathe or are immune to poison automatically succeed on this saving throw.\n\nA moderate wind (at least 10 miles per hour) disperses the cloud after 4 rounds. A strong wind (at least 20 miles per hour) disperses it after 1 round.","higherSource":""},{"id":"stone-shape","name":"Stone Shape","nameTr":"Taş Şekli","level":4,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Taş nesne için istenilen şekle kabaca işlenecek yumuşak kil.","materialSource":"Soft clay, to be crudely worked into the desired shape for the stone object.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Orta büyüklükte veya daha küçük bir taş nesneye veya 5 ft'yi aşmayan bir taş bölümüne herhangi bir boyutta dokunup onu amacınıza uygun herhangi bir şekle sokuyorsunuz. Yani, örneğin duvarın kalınlığı 5 ft'den az olduğu sürece büyük bir kayayı silaha, idole ya da sandığa dönüştürebilirsiniz ya da duvardan küçük bir geçiş yapabilirsiniz. Ayrıca kapıyı kapatmak için taş bir kapıyı veya çerçevesini de şekillendirebilirsiniz. Oluşturduğunuz nesnenin en fazla iki menteşesi ve bir mandalı olabilir, ancak daha ince mekanik ayrıntılar mümkün değildir.","higher":"","sourceText":"You touch a stone object of Medium size or smaller or a section of stone no more than 5 feet in any dimension and form it into any shape that suits your purpose. So, for example, you could shape a large rock into a weapon, idol, or coffer, or make a small passage through a wall, as long as the wall is less than 5 feet thick. You could also shape a stone door or its frame to seal the door shut. The object you create can have up to two hinges and a latch, but finer mechanical detail isn't possible.","higherSource":""},{"id":"stoneskin","name":"Stoneskin","nameTr":"Taş Derisi","level":4,"school":"Abjuration","schoolTr":"Koruma","classes":["Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"Touch","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği 100 gp değerindeki elmas tozu.","materialSource":"Diamond dust worth 100 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, dokunduğunuz istekli bir yaratığın etini taş gibi sertleştirir. Büyü bitene kadar hedefin, büyülü olmayan bludgeoning, piercing ve slashing hasarına karşı direnci vardır.","higher":"","sourceText":"This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage.","higherSource":""},{"id":"storm-of-vengeance","name":"Storm of Vengeance","nameTr":"İntikam Fırtınası","level":9,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"Sight","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON","DEX"],"saveSuccess":"none","area":{"type":"sphere","size":360},"description":"Görebileceğiniz bir noktaya odaklanan ve 360 ft yarıçapına yayılan çalkantılı bir fırtına bulutu oluşuyor. Bölgede lightning şimşek çakar, thunder patlamalar olur ve kuvvetli rüzgarlar kükrer. Bulutun altındaki her yaratık (bulutun altında en fazla 5,000 ft) göründüğünde CON saving throw atmalıdır. Başarısız bir kaydetme durumunda, yaratık 2d6 thunder hasarı alır ve 5 dakika boyunca deafened olur.\nBu büyüde concentration'yi sürdürdüğünüz her turda, fırtına sizin sıranızda ek etkiler üretir.\n***2. Tur*** Buluttan asidik yağmur yağıyor. Bulutun altındaki her yaratık ve nesne 1d6 acid hasarı alır.\n***3. Tur*** Buluttan altı lightning cıvatasını çağırarak bulutun altındaki altı yaratığa veya seçtiğiniz nesneye saldırın. Belirli bir yaratığa veya nesneye birden fazla cıvata vurulamaz. Vurulmuş bir yaratığın DEX saving throw yapması gerekir. Yaratık, başarısız save’de 10d6 lightning hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\n***4. Tur*** Buluttan dolu yağıyor. Bulutun altındaki her yaratık 2d6 bludgeoning hasarı alır.\n***5-10. Tur*** Rüzgar ve dondurucu yağmur, bulutun altındaki bölgeye hücum ediyor. Alan zorlu bir arazi haline gelir ve yoğun bir şekilde gizlenir. Oradaki her yaratık 1d6 cold hasarı alıyor. Bölgede menzilli silahlarla saldırı yapılması imkansızdır. Rüzgar ve yağmur, concentration'nin büyüleri sürdürmesi açısından ciddi bir dikkat dağıtıcı unsur olarak kabul edilir. Son olarak, kuvvetli rüzgarlar (saatte 20 ila 50 mil arasında değişen), ister sıradan ister büyülü olsun, bölgedeki sisi, sisi ve benzeri olayları otomatik olarak dağıtır.","higher":"","sourceText":"A churning storm cloud forms, centered on a point you can see and spreading to a radius of 360 feet. Lightning flashes in the area, thunder booms, and strong winds roar. Each creature under the cloud (no more than 5,000 feet beneath the cloud) when it appears must make a constitution saving throw. On a failed save, a creature takes 2d6 thunder damage and becomes deafened for 5 minutes.\n\nEach round you maintain concentration on this spell, the storm produces additional effects on your turn.\n\n***Round 2.*** Acidic rain falls from the cloud. Each creature and object under the cloud takes 1d6 acid damage.\n\n***Round 3.*** You call six bolts of lightning from the cloud to strike six creatures or objects of your choice beneath the cloud. A given creature or object can't be struck by more than one bolt. A struck creature must make a dexterity saving throw. The creature takes 10d6 lightning damage on a failed save, or half as much damage on a successful one.\n\n***Round 4.*** Hailstones rain down from the cloud. Each creature under the cloud takes 2d6 bludgeoning damage.\n\n***Round 5-10.*** Gusts and freezing rain assail the area under the cloud. The area becomes difficult terrain and is heavily obscured. Each creature there takes 1d6 cold damage. Ranged weapon attacks in the area are impossible. The wind and rain count as a severe distraction for the purposes of maintaining concentration on spells. Finally, gusts of strong wind (ranging from 20 to 50 miles per hour) automatically disperse fog, mists, and similar phenomena in the area, whether mundane or magical.","higherSource":""},{"id":"suggestion","name":"Suggestion","nameTr":"Öneri","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 8 hours","concentration":true,"ritual":false,"components":["V","M"],"materialTr":"Bir yılanın dili ve ya bir parça bal peteği ya da bir damla tatlı yağ.","materialSource":"A snake's tongue and either a bit of honeycomb or a drop of sweet oil.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Bir etkinlik planı önerirsiniz (bir veya iki cümleyle sınırlı) ve menzil içinde görebileceğiniz, sizi duyabilen ve anlayabilen bir yaratığı sihirli bir şekilde etkilersiniz. charmed olamayacak yaratıklar bu etkiye karşı bağışıklıdır. Öneri, eylem planının makul görünmesini sağlayacak şekilde ifade edilmelidir. Yaratığın kendisini bıçaklamasını, bir mızrağa atmasını, kendisini yakmasını veya açıkça zararlı başka bir eylem yapmasını istemek, büyüyü sona erdirir.\nHedefin bir WIS saving throw yapması gerekir. Başarısız bir kaydetme durumunda, tanımladığınız eylem planını elinden gelen en iyi şekilde takip eder. Önerilen eylem planı tüm süre boyunca devam edebilir. Önerilen aktivite daha kısa sürede tamamlanabiliyorsa, deneğin kendisinden isteneni tamamlamasıyla büyü sona erer.\nSüre boyunca özel bir etkinliği tetikleyecek koşulları da belirtebilirsiniz. Örneğin bir şövalyeye savaş atını karşılaştığı ilk dilenciye vermesini önerebilirsiniz. Büyünün süresi dolmadan koşul karşılanmazsa etkinlik gerçekleştirilmez.\nSiz veya arkadaşlarınızdan herhangi biri hedefe zarar verirseniz büyü sona erer.","higher":"","sourceText":"You suggest a course of activity (limited to a sentence or two) and magically influence a creature you can see within range that can hear and understand you. Creatures that can't be charmed are immune to this effect. The suggestion must be worded in such a manner as to make the course of action sound reasonable. Asking the creature to stab itself, throw itself onto a spear, immolate itself, or do some other obviously harmful act ends the spell.\n\nThe target must make a wisdom saving throw. On a failed save, it pursues the course of action you described to the best of its ability. The suggested course of action can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do.\n\nYou can also specify conditions that will trigger a special activity during the duration. For example, you might suggest that a knight give her warhorse to the first beggar she meets. If the condition isn't met before the spell expires, the activity isn't performed.\n\nIf you or any of your companions damage the target, the spell ends.","higherSource":""},{"id":"sunbeam","name":"Sunbeam","nameTr":"Güneş ışını","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir büyüteç.","materialSource":"A magnifying glass.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"line","size":60},"description":"5 ft genişlik, 60 ft uzunluk hattında elinizden parlak bir ışık huzmesi yanıp sönüyor. Sıradaki her yaratık bir CON saving throw yapmalıdır. Başarısız bir kaydetme durumunda, bir yaratık 6d8 radiant hasarı alır ve bir sonraki turunuza kadar blinded olur. Başarılı bir kurtarışta, yarısı kadar hasar alır ve bu büyüyle blinded olmaz. Bu saving throw'de ölümsüzler ve sızıntılar dezavantaj'ye sahiptir.\nBüyü sona erene kadar herhangi bir turda eyleminiz olarak yeni bir parlaklık çizgisi oluşturabilirsiniz.\nBu süre boyunca elinizde bir parça parlak parlaklık parlıyor. 30 ft yarıçapında parlak ışık tutar ve ek bir 30 ft için loş ışık tutar. Bu ışık güneş ışığıdır.","higher":"","sourceText":"A beam of brilliant light flashes out from your hand in a 5-foot-wide, 60-foot-long line. Each creature in the line must make a constitution saving throw. On a failed save, a creature takes 6d8 radiant damage and is blinded until your next turn. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nYou can create a new line of radiance as your action on any turn until the spell ends.\n\nFor the duration, a mote of brilliant radiance shines in your hand. It sheds bright light in a 30-foot radius and dim light for an additional 30 feet. This light is sunlight.","higherSource":""},{"id":"sunburst","name":"Sunburst","nameTr":"Güneş patlaması","level":8,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"150 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"fire ve bir parça güneş taşı.","materialSource":"Fire and a piece of sunstone.","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"cylinder","size":60},"description":"Parlak güneş ışığı, menzil içinde seçtiğiniz bir noktanın merkezinde yer alan 60 ft yarıçapında yanıp söner. Bu ışıktaki her yaratık bir CON saving throw yapmalıdır. Başarısız bir kaydetme durumunda, yaratık 12d6 radiant hasarı alır ve 1 dakika boyunca blinded olur. Başarılı bir kurtarışta, yarısı kadar hasar alır ve bu büyüyle blinded olmaz. Bu saving throw'de ölümsüzler ve sızıntılar dezavantaj'ye sahiptir.\nBu büyüyle bir yaratık blinded, her turunun sonunda başka bir CON saving throw yapar. Başarılı bir kaydetme işleminde artık blinded olmaz.\nBu büyü, bir büyünün bölgede yarattığı karanlığı yok eder.","higher":"","sourceText":"Brilliant sunlight flashes in a 60-foot radius centered on a point you choose within range. Each creature in that light must make a constitution saving throw. On a failed save, a creature takes 12d6 radiant damage and is blinded for 1 minute. On a successful save, it takes half as much damage and isn't blinded by this spell. Undead and oozes have disadvantage on this saving throw.\n\nA creature blinded by this spell makes another constitution saving throw at the end of each of its turns. On a successful save, it is no longer blinded.\n\nThis spell dispels any darkness in its area that was created by a spell.","higherSource":""},{"id":"symbol","name":"Symbol","nameTr":"Sembol","level":7,"school":"Abjuration","schoolTr":"Koruma","classes":["Bard","Cleric","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"Touch","duration":"Until dispelled","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği toplam değeri en az 1.000 gp olan cıva, fosfor ve elmas tozu ve opal.","materialSource":"Mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes.","attackType":"","save":"CON","saves":["CON","WIS","CHA","INT"],"saveSuccess":"","area":{"type":"cube","size":10},"description":"Bu büyüyü yaptığınızda, zararlı bir glifi ya bir yüzeye (zeminin bir bölümü, duvar veya masa gibi) ya da glifi gizlemek için kapatılabilen bir nesnenin (kitap, parşömen veya hazine sandığı gibi) içine yazarsınız. Bir yüzey seçerseniz glif, yüzeyin çapı 10 ft'den büyük olmayan bir alanı kapsayabilir. Bir nesneyi seçerseniz o nesnenin yerinde kalması gerekir; nesne bu büyüyü yaptığınız yerden 10 ft'den daha fazla hareket ettirilirse glif bozulur ve büyü tetiklenmeden sona erer.\nGlif neredeyse invisible'dir ve onu bulmak için DC'deki büyü kaydınıza karşı bir INT (Soruşturma) kontrolü gerektirir.\nBüyüyü yaptığınızda glifi neyin tetikleyeceğine siz karar verirsiniz. Bir yüzeye yazılan glifler için en tipik tetikleyiciler, glife dokunmak veya üzerine basmak, onu kaplayan başka bir nesneyi kaldırmak, ona belirli bir mesafeye yaklaşmak veya onu tutan nesneyi manipüle etmektir. Bir nesnenin içine yazılan glifler için en yaygın tetikleyiciler nesnenin açılması, ona belirli bir mesafeye yaklaşmak veya glifi görmek veya okumaktır.\nBüyünün yalnızca belirli koşullar altında veya bir yaratığın fiziksel özelliklerine (boy veya kilo gibi) veya fiziksel türüne (örneğin, totem cadıları veya şekil değiştiricileri etkileyecek şekilde ayarlanabilir) göre etkinleştirilmesi için tetiği daha da hassaslaştırabilirsiniz. Belirli bir şifreyi söyleyenler gibi glifi tetiklemeyen yaratıkları da belirtebilirsiniz.\nGlifi yazdığınızda etkisi için aşağıdaki seçeneklerden birini seçin. Bir kez tetiklendiğinde, glif parlayarak 60 ft yarıçap küresini 10 dakika boyunca loş ışıkla doldurur ve bu sürenin sonunda büyü sona erer. Glif etkinleştirildiğinde küredeki her yaratık, etkisi ile hedef alınır; tıpkı bir dönüşte küreye ilk kez giren veya sırasını burada bitiren bir yaratık gibi.\n***Ölüm.*** Her hedef bir CON saving throw yapmalı, başarısız bir kaydetmede 10d 10 necrotic hasarı veya başarılı bir kaydetmede yarısı kadar hasar almalıdır.\n***Discord.*** Her hedef bir CON saving throw yapmalıdır. başarısız save’de, hedef 1 dakika boyunca diğer yaratıklarla çekişir ve tartışır. Bu süre zarfında anlamlı iletişim kuramaz ve saldırı atışlarında ability check’ler ve ability check’ler'ye sahiptir.\n***Korku.*** Her hedef bir WIS saving throw yapmalı ve başarısız bir kaydetme durumunda 1 dakika boyunca frightened haline gelmelidir. frightened sırasında, hedef tuttuğu şeyi düşürür ve mümkünse her dönüşünde en azından 30 ft gliften uzaklaşmalıdır.\n***Umutsuzluk.*** Her hedef bir CHA saving throw yapmalıdır. başarısız save’de hedef 1 dakika boyunca umutsuzluğa kapılır. Bu süre zarfında zararlı yeteneklere, büyülere veya diğer büyülü etkilere sahip hiçbir yaratığa saldıramaz veya hedef alamaz.\n***Delilik.*** Her hedef bir INT saving throw yapmalıdır. Başarısız bir kaydetme durumunda hedef 1 dakika boyunca çılgına döner. Deli bir yaratık harekete geçemez, diğer canlıların ne dediğini anlayamaz, okuyamaz ve sadece anlamsız konuşur. GM düzensiz olan hareketini kontrol ediyor.\n***Acı.*** Her hedef bir CON saving throw yapmalı ve başarısız bir kurtarma sonrasında 1 dakika boyunca dayanılmaz bir acıyla incapacitated haline gelmelidir.\n***Uyku.*** Başarısız bir kaydetme işleminde her hedef bir WIS saving throw yapmalı ve 10 dakika boyunca unconscious düşmelidir. Bir yaratık hasar alırsa veya birisi onu sarsmak veya tokatlamak için bir hareket kullanırsa uyanır.\n***Çarpıcı.*** Her hedef bir WIS saving throw yapmalı ve başarısız bir kaydetme durumunda 1 dakika boyunca stunned haline gelmelidir.","higher":"","sourceText":"When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered.\n\nThe glyph is nearly invisible, requiring an Intelligence (Investigation) check against your spell save DC to find it.\n\nYou decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph.\n\nYou can further refine the trigger so the spell is activated only under certain circumstances or according to a creature's physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don't trigger the glyph, such as those who say a certain password.\n\nWhen you inscribe the glyph, choose one of the options below for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activates is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there.\n\n***Death.*** Each target must make a constitution saving throw, taking 10d 10 necrotic damage on a failed save, or half as much damage on a successful save.\n\n***Discord.*** Each target must make a constitution saving throw. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks.\n\n***Fear.*** Each target must make a wisdom saving throw and becomes frightened for 1 minute on a failed save. While frightened, the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able.\n\n***Hopelessness.*** Each target must make a charisma saving throw. On a failed save, the target is overwhelmed with despair for 1 minute. During this time, it can't attack or target any creature with harmful abilities, spells, or other magical effects.\n\n***Insanity.*** Each target must make an intelligence saving throw. On a failed save, the target is driven insane for 1 minute. An insane creature can't take actions, can't understand what other creatures say, can't read, and speaks only in gibberish. The GM controls its movement, which is erratic.\n\n***Pain.*** Each target must make a constitution saving throw and becomes incapacitated with excruciating pain for 1 minute on a failed save.\n\n***Sleep.*** Each target must make a wisdom saving throw and falls unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake.\n\n***Stunning.*** Each target must make a wisdom saving throw and becomes stunned for 1 minute on a failed save.","higherSource":""},{"id":"telekinesis","name":"Telekinesis","nameTr":"Telekinezi","level":5,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":30},"description":"Düşünce yoluyla yaratıkları veya nesneleri hareket ettirme veya manipüle etme yeteneğini kazanırsınız. Büyüyü yaptığınızda ve bu süre boyunca her turda eyleminiz olarak, menzil içinde görebileceğiniz bir yaratık veya nesne üzerinde iradenizi uygulayarak aşağıdaki uygun etkiyi oluşturabilirsiniz. Her turda aynı hedefi etkileyebilir veya istediğiniz zaman yeni bir hedef seçebilirsiniz. Hedefleri değiştirirseniz önceki hedef artık büyüden etkilenmez.\n***Yaratık.*** Büyük veya daha küçük bir yaratığı hareket ettirmeyi deneyebilirsiniz. Büyü yapma yeteneğinizin, yaratığın STR kontrolüyle yarıştığı bir ability check yapın. Yarışmayı kazanırsanız, yaratığı 30 ft'ye, yukarı dahil ancak bu büyünün menzilinin dışına çıkmayacak şekilde herhangi bir yönde hareket ettirirsiniz. Bir sonraki turunuzun sonuna kadar yaratık, telekinetik tutuşunuzda restrained'dir. Yukarı doğru kaldırılan bir yaratık havada asılı kalır.\nSonraki turlarda, yarışmayı tekrarlayarak yaratık üzerindeki telekinetik tutuşunuzu korumaya çalışmak için eyleminizi kullanabilirsiniz.\n***Nesne.*** Ağırlığı 1,000 lb'ye kadar olan bir nesneyi taşımayı deneyebilirsiniz. Nesne giyilmiyor veya taşınmıyorsa, onu herhangi bir yönde otomatik olarak 30 ft'ye taşırsınız, ancak bu büyünün menzilinin dışına çıkamazsınız.\nNesne bir yaratık tarafından giyilirse veya taşınırsa, o yaratığın STR kontrolüyle itiraz edilen büyü yapma yeteneğinizle bir ability check yapmalısınız. Başarılı olursanız, nesneyi o yaratıktan uzaklaştırırsınız ve onu herhangi bir yönde 30 ft'ye taşıyabilirsiniz ancak bu büyünün menzilinin dışına çıkamazsınız.\nBasit bir aleti kullanmak, bir kapıyı veya kabı açmak, açık bir kaptan bir öğeyi istiflemek veya almak veya bir şişenin içeriğini dökmek gibi telekinetik tutuşunuzla nesneler üzerinde hassas kontrol uygulayabilirsiniz.","higher":"","sourceText":"You gain the ability to move or manipulate creatures or objects by thought. When you cast the spell, and as your action each round for the duration, you can exert your will on one creature or object that you can see within range, causing the appropriate effect below. You can affect the same target round after round, or choose a new one at any time. If you switch targets, the prior target is no longer affected by the spell.\n\n***Creature.*** You can try to move a Huge or smaller creature. Make an ability check with your spellcasting ability contested by the creature's Strength check. If you win the contest, you move the creature up to 30 feet in any direction, including upward but not beyond the range of this spell. Until the end of your next turn, the creature is restrained in your telekinetic grip. A creature lifted upward is suspended in mid-air.\n\nOn subsequent rounds, you can use your action to attempt to maintain your telekinetic grip on the creature by repeating the contest.\n\n***Object.*** You can try to move an object that weighs up to 1,000 pounds. If the object isn't being worn or carried, you automatically move it up to 30 feet in any direction, but not beyond the range of this spell.\n\nIf the object is worn or carried by a creature, you must make an ability check with your spellcasting ability contested by that creature's Strength check. If you succeed, you pull the object away from that creature and can move it up to 30 feet in any direction but not beyond the range of this spell.\n\nYou can exert fine control on objects with your telekinetic grip, such as manipulating a simple tool, opening a door or a container, stowing or retrieving an item from an open container, or pouring the contents from a vial.","higherSource":""},{"id":"telepathic-bond","name":"Telepathic Bond","nameTr":"Telepatik Bağ","level":5,"school":"Divination","schoolTr":"Kehanet","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"İki farklı canlıya ait yumurta kabuğu parçaları","materialSource":"Pieces of eggshell from two different kinds of creatures","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil dahilinde seçtiğiniz en fazla sekiz istekli yaratık arasında telepatik bir bağlantı kurarsınız ve bu süre boyunca her bir yaratığı psişik olarak diğerlerine bağlarsınız. INT puanı 2 veya daha düşük olan yaratıklar bu büyüden etkilenmez.\nBüyü bitene kadar hedefler, ortak bir dile sahip olsun ya da olmasın, bağ aracılığıyla telepatik olarak iletişim kurabilirler. İletişim herhangi bir mesafe üzerinden mümkündür, ancak diğer varoluş düzlemlerine uzanamaz.","higher":"","sourceText":"You forge a telepathic link among up to eight willing creatures of your choice within range, psychically linking each creature to all the others for the duration. Creatures with Intelligence scores of 2 or less aren't affected by this spell.\n\nUntil the spell ends, the targets can communicate telepathically through the bond whether or not they have a common language. The communication is possible over any distance, though it can't extend to other planes of existence.","higherSource":""},{"id":"teleport","name":"Teleport","nameTr":"Işınlanma","level":7,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"10 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"cube","size":10},"description":"Bu büyü, sizi ve menzil içinde görebileceğiniz seçeceğiniz sekiz adede kadar istekli yaratığı veya menzil içinde görebileceğiniz tek bir nesneyi seçtiğiniz bir hedefe anında taşır. Bir nesneyi hedef alırsanız, bu nesnenin 10 ft küpün içine tamamen sığabilmesi gerekir ve isteksiz bir yaratık tarafından tutulamaz veya taşınamaz.\nSeçtiğiniz hedef sizin tarafınızdan bilinmeli ve sizinle aynı varoluş düzleminde olmalıdır. Hedefe olan aşinalığınız oraya başarılı bir şekilde varıp varmayacağınızı belirler. GM d100 atar ve tabloya bakar.\n| Aşinalık | Kaza | Benzer Alan | Hedef Dışı | Hedefte |\n|---|---|---|---|---|\n| Kalıcı daire | -- | -- | -- | 01-100 |\n| İlişkili nesne | -- | -- | -- | 01-100 |\n| Çok tanıdık | 01-05 | 06-13 | 14-24 | 25-100 |\n| Rasgele görüldü | 01-33 | 34-43 | 44-53 | 54-100 |\n| Bir kez görüntülendi | 01-43 | 44-53 | 54-73 | 74-100 |\n| Açıklama | 01-43 | 44-53 | 54-73 | 74-100 |\n| Yanlış hedef | 01-50 | 51-100 | -- | -- |\n***Aşinalık.*** \"Kalıcı daire\", armasını bildiğiniz kalıcı ışınlanma dairesi anlamına gelir.\n\"İlişkili nesne\", bir büyücünün kütüphanesinden bir kitap, bir kraliyet dairesinden yatak çarşafı veya bir lich'in gizli mezarından bir parça mermer gibi son altı ay içinde istediğiniz yerden alınmış bir nesneye sahip olduğunuz anlamına gelir.\n\"Çok tanıdık\", çok sık gittiğiniz, dikkatle incelediğiniz veya büyü yaptığınızda görebileceğiniz bir yerdir.\n\"Rastgele görüldü\", birden fazla kez gördüğünüz ancak pek aşina olmadığınız bir yerdir.\n\"Bir kez görüntülendi\", muhtemelen büyü kullanarak bir kez gördüğünüz yerdir.\n\"Açıklama\", konumunu ve görünümünü başka birinin açıklamasından, belki de bir haritadan bildiğiniz bir yerdir.\n\"Yanlış hedef\" var olmayan bir yerdir. Belki bir düşmanın sığınağını taramaya çalıştınız ama bunun yerine bir illüzyon gördünüz ya da artık var olmayan tanıdık bir konuma ışınlanmaya çalışıyorsunuz.\n***Hedefte.*** Siz ve grubunuz (veya hedef nesne) istediğiniz yerde görünürsünüz.\n***Hedef Dışı.*** Siz ve grubunuz (veya hedef nesne), hedeften rastgele bir yönde, rastgele bir mesafede görünürsünüz. Hedef dışındaki mesafe, kat edilecek mesafenin yüzde 1d10 x 1d10'sidir. Örneğin, 120 mil ile ilerlemeyi denediyseniz, hedefin dışına indiyseniz ve iki d10'da 5 ve 3'lük bir atış yaptıysanız, o zaman hedefin yüzde 15'i kadar veya 18 mil sapmış olursunuz. GM, pusulanın noktaları etrafında bir d8 yuvarlayarak ve 1'i kuzey, 2'yi kuzeydoğu, 3'ü doğu vb. olarak belirleyerek hedefin dışındaki yönü rastgele belirler.  Bir kıyı şehrine ışınlanıyorsanız ve 18 mil'yi denizde bulursanız başınız dertte olabilir.\n***Benzer Alan.*** Siz ve grubunuz (veya hedef nesne), görsel veya tematik olarak hedef alana benzeyen farklı bir alanda bulursunuz. Örneğin ev laboratuvarınıza gidiyorsanız, kendinizi başka bir büyücünün laboratuvarında veya laboratuvarınızla aynı araç ve gereçlerin bulunduğu bir simya malzemesi dükkanında bulabilirsiniz. Genellikle en yakın benzer yerde görünürsünüz, ancak büyünün menzil sınırı olmadığından uçağın herhangi bir yerine gitmeniz muhtemeldir.\n***Talih.*** Büyünün öngörülemeyen büyüsü zorlu bir yolculuğa neden olur. Işınlanan her yaratık (veya hedef nesne) 3d10 force hasarı alır ve GM, nereye gittiğinizi görmek için masayı yeniden kontrol eder (her seferinde hasar veren birden fazla aksilik meydana gelebilir).","higher":"","sourceText":"This spell instantly transports you and up to eight willing creatures of your choice that you can see within range, or a single object that you can see within range, to a destination you select. If you target an object, it must be able to fit entirely inside a 10-foot cube, and it can't be held or carried by an unwilling creature.\n\nThe destination you choose must be known to you, and it must be on the same plane of existence as you. Your familiarity with the destination determines whether you arrive there successfully. The GM rolls d100 and consults the table.\n\n| Familiarity | Mishap | Similar Area | Off Target | On Target |\n\n|---|---|---|---|---|\n\n| Permanent circle | -- | -- | -- | 01-100 |\n\n| Associated object | -- | -- | -- | 01-100 |\n\n| Very familiar | 01-05 | 06-13 | 14-24 | 25-100 |\n\n| Seen casually | 01-33 | 34-43 | 44-53 | 54-100 |\n\n| Viewed once | 01-43 | 44-53 | 54-73 | 74-100 |\n\n| Description | 01-43 | 44-53 | 54-73 | 74-100 |\n\n| False destination | 01-50 | 51-100 | -- | -- |\n\n***Familiarity.*** \"Permanent circle\" means a permanent teleportation circle whose sigil sequence you know.\n\n\"Associated object\" means that you possess an object taken from the desired destination within the last six months, such as a book from a wizard's library, bed linen from a royal suite, or a chunk of marble from a lich's secret tomb.\n\n\"Very familiar\" is a place you have been very often, a place you have carefully studied, or a place you can see when you cast the spell.\n\n\"Seen casually\" is someplace you have seen more than once but with which you aren't very familiar.\n\n\"Viewed once\" is a place you have seen once, possibly using magic.\n\n\"Description\" is a place whose location and appearance you know through someone else's description, perhaps from a map.\n\n\"False destination\" is a place that doesn't exist. Perhaps you tried to scry an enemy's sanctum but instead viewed an illusion, or you are attempting to teleport to a familiar location that no longer exists.\n\n***On Target.*** You and your group (or the target object) appear where you want to.\n\n***Off Target.*** You and your group (or the target object) appear a random distance away from the destination in a random direction. Distance off target is 1d10 x 1d10 percent of the distance that was to be traveled. For example, if you tried to travel 120 miles, landed off target, and rolled a 5 and 3 on the two d10s, then you would be off target by 15 percent, or 18 miles. The GM determines the direction off target randomly by rolling a d8 and designating 1 as north, 2 as northeast, 3 as east, and so on around the points of the compass.  If you were teleporting to a coastal city and wound up 18 miles out at sea, you could be in trouble.\n\n***Similar Area.*** You and your group (or the target object) wind up in a different area that's visually or thematically similar to the target area. If you are heading for your home laboratory, for example, you might wind up in another wizard's laboratory or in an alchemical supply shop that has many of the same tools and implements as your laboratory. Generally, you appear in the closest similar place, but since the spell has no range limit, you could conceivably wind up anywhere on the plane.\n\n***Mishap.*** The spell's unpredictable magic results in a difficult journey. Each teleporting creature (or the target object) takes 3d10 force damage, and the GM rerolls on the table to see where you wind up (multiple mishaps can occur, dealing damage each time).","higherSource":""},{"id":"teleportation-circle","name":"Teleportation Circle","nameTr":"Işınlanma Çemberi","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 minute","range":"10 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V","M"],"materialTr":"Büyünün tükettiği, 50 gp'lik değerli taşlarla aşılanmış nadir tebeşirler ve mürekkepler.","materialSource":"Rare chalks and inks infused with precious gems with 50 gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":10},"description":"Büyüyü yaparken, zemine 10 ft çapında bir daire çizersiniz ve bu daire, konumunuzu, arması sırasını bildiğiniz ve sizinle aynı varoluş düzleminde olan, seçtiğiniz kalıcı bir ışınlanma dairesine bağlayan mühürlerle yazılıdır. Çizdiğiniz dairenin içinde parıldayan bir portal açılır ve bir sonraki turunuzun sonuna kadar açık kalır. Portala giren herhangi bir yaratık anında hedef dairenin 5 ft yakınında veya eğer o alan doluysa en yakın boş alanda belirir.\nPek çok büyük tapınak, lonca ve diğer önemli yerlerin sınırları içinde bir yerde kalıcı ışınlanma daireleri yazılıdır. Bu tür dairelerin her biri benzersiz bir mühür dizisi içerir; belirli bir düzende düzenlenmiş bir dizi sihirli rün. Bu büyüyü yapma yeteneğini ilk kez kazandığınızda, GM tarafından belirlenen Malzeme Düzlemindeki iki hedef için mühür dizilerini öğrenirsiniz. Maceralarınız sırasında ek mühür dizilerini öğrenebilirsiniz. Yeni bir mühür dizisini 1 dakika çalıştıktan sonra hafızaya kaydedebilirsiniz.\nBu büyüyü bir yıl boyunca her gün aynı yere yaparak kalıcı bir ışınlanma çemberi oluşturabilirsiniz. Büyüyü bu şekilde yaptığınızda ışınlanmak için daireyi kullanmanıza gerek yoktur.","higher":"","sourceText":"As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied.\n\nMany major temples, guilds, and other important places have permanent teleportation circles inscribed somewhere within their confines. Each such circle includes a unique sigil sequence--a string of magical runes arranged in a particular pattern. When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You can learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute.\n\nYou can create a permanent teleportation circle by casting this spell in the same location every day for one year. You need not use the circle to teleport when you cast the spell in this way.","higherSource":""},{"id":"thaumaturgy","name":"Thaumaturgy","nameTr":"Thaumaturji","level":0,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 minute","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Menzil içinde küçük bir mucize, doğaüstü bir gücün işareti ortaya çıkıyor. Menzil içinde aşağıdaki sihirli efektlerden birini yaratırsınız.\n- Sesiniz 1 dakika boyunca normalin üç katına kadar gürler.\n- Alevlerin 1 dakika boyunca titreşmesine, parlamasına, kararmasına veya renginin değişmesine neden olursunuz.\n- 1 dakika boyunca yerde zararsız sarsıntılara sebep olursunuz.\n- thunder'nin gürültüsü, bir kuzgunun çığlığı veya uğursuz fısıltılar gibi menzil içindeki seçtiğiniz bir noktadan kaynaklanan anlık bir ses yaratırsınız.\n- Anında kilidi açılmış bir kapının veya pencerenin hızla açılmasına veya çarparak kapanmasına neden olursunuz.\n- 1 dakika boyunca gözlerinizin görünümünü değiştiriyorsunuz.\nBu büyüyü birden fazla kez yaparsanız, aynı anda 1 dakikalık efektlerinin en fazla üçünü aktif hale getirebilirsiniz ve böyle bir etkiyi eylem olarak göz ardı edebilirsiniz.","higher":"","sourceText":"You manifest a minor wonder, a sign of supernatural power, within range. You create one of the following magical effects within range.\n\n- Your voice booms up to three times as loud as normal for 1 minute.\n\n- You cause flames to flicker, brighten, dim, or change color for 1 minute.\n\n- You cause harmless tremors in the ground for 1 minute.\n\n- You create an instantaneous sound that originates from a point of your choice within range, such as a rumble of thunder, the cry of a raven, or ominous whispers.\n\n- You instantaneously cause an unlocked door or window to fly open or slam shut.\n\n- You alter the appearance of your eyes for 1 minute.\n\nIf you cast this spell multiple times, you can have up to three of its 1-minute effects active at a time, and you can dismiss such an effect as an action.","higherSource":""},{"id":"thunderwave","name":"Thunderwave","nameTr":"Gök gürültüsü dalgası","level":1,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Druid","Sorcerer","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CON","saves":["CON"],"saveSuccess":"half","area":{"type":"cube","size":15},"description":"Gök gürültüsü gibi bir force dalgası sizden uzaklaşıyor. Sizden kaynaklanan bir 15 ft küpündeki her yaratık bir CON saving throw yapmalıdır. Başarısız bir kaydetme durumunda, bir yaratık 2d8 thunder hasarı alır ve 10 ft'yi sizden uzaklaştırır. Başarılı bir kurtarışta yaratık, yarısı kadar hasar alır ve itilmez.\nBuna ek olarak, tamamen etki alanı içinde bulunan güvenli olmayan nesneler, 10 ft, büyünün etkisi ile otomatik olarak sizden uzağa itilir ve büyü, 300 ft tarafından duyulabilen şiddetli bir patlama yayar.","higher":"Bu büyüyü 2. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 1. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube originating from you must make a constitution saving throw. On a failed save, a creature takes 2d8 thunder damage and is pushed 10 feet away from you. On a successful save, the creature takes half as much damage and isn't pushed.\n\nIn addition, unsecured objects that are completely within the area of effect are automatically pushed 10 feet away from you by the spell's effect, and the spell emits a thunderous boom audible out to 300 feet.","higherSource":"When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."},{"id":"time-stop","name":"Time Stop","nameTr":"Zaman Durdurma","level":9,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Kendiniz dışında herkes için zamanın akışını kısa süreliğine durdurursunuz. 1d4+1 sıralı dönüşler yaparken, diğer yaratıklar için zaman geçmiyor, bu sırada eylemleri kullanabiliyor ve normal şekilde hareket edebiliyorsunuz.\nBu süre içerisinde yapacağınız bir hareketin ya da bu süre içerisinde oluşturduğunuz herhangi bir etkinin sizden başka bir canlıya ya da başkasının giydiği ya da taşıdığı bir nesneye etki etmesi durumunda bu büyü sona erer. Ayrıca büyüyü yaptığınız yerden 1,000 ft'den daha uzak bir yere giderseniz büyü sona erer.","higher":"","sourceText":"You briefly stop the flow of time for everyone but yourself. No time passes for other creatures, while you take 1d4 + 1 turns in a row, during which you can use actions and move as normal.\n\nThis spell ends if one of the actions you use during this period, or any effects that you create during this period, affects a creature other than you or an object being worn or carried by someone other than you. In addition, the spell ends if you move to a place more than 1,000 feet from the location where you cast it.","higherSource":""},{"id":"tiny-hut","name":"Tiny Hut","nameTr":"Minik Kulübe","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Bard","Wizard"],"subclasses":["Lore"],"castingTime":"1 minute","range":"Self","duration":"8 hours","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Küçük bir kristal boncuk.","materialSource":"A small crystal bead.","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":10},"description":"10 ft yarıçap hareketsiz bir force kubbesi etrafınızda ve üzerinizde ortaya çıkar ve bu süre boyunca sabit kalır. Büyü, bulunduğu bölgeyi terk ettiğinizde sona erer.\nOrta büyüklükte veya daha küçük dokuz yaratık kubbenin içine sizinle birlikte sığabilir. Alanında daha büyük bir yaratık veya dokuzdan fazla yaratık varsa büyü başarısız olur. Bu büyüyü yaptığınızda kubbe içindeki yaratıklar ve nesneler serbestçe hareket edebilir. Diğer tüm canlıların ve nesnelerin buradan geçmesi yasaktır. Büyüler ve diğer büyülü etkiler kubbenin içinden geçemez veya içinden geçemez. Dışarıdaki hava nasıl olursa olsun, mekanın içindeki atmosfer rahat ve kurudur.\nBüyü bitene kadar iç mekanın loş veya karanlık olmasını emredebilirsiniz. Kubbe dışarıdan seçtiğiniz renkte opaktır, ancak içeriden şeffaftır.","higher":"","sourceText":"A 10-foot-radius immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area.\n\nNine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can't extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside.\n\nUntil the spell ends, you can command the interior to become dimly lit or dark. The dome is opaque from the outside, of any color you choose, but it is transparent from the inside.","higherSource":""},{"id":"tongues","name":"Tongues","nameTr":"Diller","level":3,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","M"],"materialTr":"Ziguratın küçük kil modeli.","materialSource":"A small clay model of a ziggurat.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, dokunduğunuz yaratığa duyduğu herhangi bir konuşulan dili anlama yeteneği verir. Üstelik hedef konuştuğunda, en az bir dil bilen ve hedefin sesini duyabilen her canlı, hedefin ne söylediğini anlar.","higher":"","sourceText":"This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear the target understands what it says.","higherSource":""},{"id":"transport-via-plants","name":"Transport via Plants","nameTr":"Bitkiler Yoluyla Taşıma","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"10 feet","duration":"1 round","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, menzil içindeki Büyük veya daha büyük cansız bir bitki ile herhangi bir mesafede, aynı varoluş düzleminde bulunan başka bir bitki arasında sihirli bir bağlantı oluşturur. Hedef bitkiyi daha önce en az bir kez görmüş veya dokunmuş olmalısınız. Bu süre boyunca herhangi bir yaratık, 5 ft hareketini kullanarak hedef bitkiye adım atabilir ve hedef bitkiden çıkabilir.","higher":"","sourceText":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, at any distance, on the same plane of existence. You must have seen or touched the destination plant at least once before. For the duration, any creature can step into the target plant and exit from the destination plant by using 5 feet of movement.","higherSource":""},{"id":"tree-stride","name":"Tree Stride","nameTr":"Ağaç Yürüyüşü","level":5,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid","Ranger"],"subclasses":["Land"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"500 ft içerisinde bir ağaca girme ve onun içinden aynı türden başka bir ağacın içine geçme yeteneğini kazanırsınız. Her iki ağaç da canlı olmalı ve en azından sizinle aynı büyüklükte olmalıdır. Bir ağaca girmek için 5 ft hareketini kullanmalısınız. 500 ft içindeki aynı türden diğer tüm ağaçların konumunu anında bilirsiniz ve ağaca girmek için kullanılan hareketin bir parçası olarak, bu ağaçlardan birine geçebilir veya içinde bulunduğunuz ağaçtan dışarı çıkabilirsiniz. Başka bir 5 ft hareketini kullanarak hedef ağacın 5 ft içinde seçtiğiniz bir noktada belirirsiniz. Eğer hareketiniz kalmadıysa girdiğiniz ağacın 5 ft içerisinde belirirsiniz.\nBu taşıma yeteneğini, bu süre boyunca tur başına bir kez kullanabilirsiniz. Her dönüşü bir ağacın dışında sonlandırmalısınız.","higher":"","sourceText":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You must use 5 feet of movement to enter a tree. You instantly know the location of all other trees of the same kind within 500 feet and, as part of the move used to enter the tree, can either pass into one of those trees or step out of the tree you're in. You appear in a spot of your choice within 5 feet of the destination tree, using another 5 feet of movement. If you have no movement left, you appear within 5 feet of the tree you entered.\n\nYou can use this transportation ability once per round for the duration. You must end each turn outside a tree.","higherSource":""},{"id":"true-polymorph","name":"True Polymorph","nameTr":"Gerçek Polimorf","level":9,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Bard","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir damla cıva, bir tutam arap zamkı ve bir tutam duman.","materialSource":"A drop of mercury, a dollop of gum arabic, and a wisp of smoke.","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"","area":null,"description":"Menzil içinde görebileceğiniz bir yaratık veya sihirli olmayan bir nesne seçin. Yaratığı farklı bir yaratığa, yaratığı bir nesneye, nesneyi bir yaratığa dönüştürüyorsunuz (nesne başka bir canlı tarafından giyilmemeli ve taşınmamalıdır). Dönüşüm, süre boyunca veya hedef 0 HP'ye düşene veya ölene kadar sürer. Tüm süre boyunca bu büyüye konsantre olursanız dönüşüm kalıcı hale gelir.\nŞekil değiştiriciler bu büyüden etkilenmez. İsteksiz bir yaratık WIS saving throw yapabilir ve eğer başarılı olursa bu büyüden etkilenmez.\n***Yaratıktan Yaratığa.*** Bir yaratığı başka türde bir yaratığa dönüştürürseniz, yeni form, meydan okuma derecesi hedefinkine eşit veya ondan daha düşük olan (veya hedefin meydan okuma derecesi yoksa seviyesi) seçeceğiniz herhangi bir tür olabilir. Zihinsel yetenek puanları da dahil olmak üzere hedefin oyun istatistiklerinin yerini yeni formun istatistikleri alır. Uyumluluğunu ve kişiliğini korur.\nHedef, HP'nin yeni formunu alır ve normal formuna döndüğünde yaratık, dönüşmeden önceki HP sayısına geri döner. 0 HP'ye düşme sonucu geri dönerse, fazla hasar normal formuna taşınır. Aşırı hasar yaratığın normal formunu 0 HP'ye düşürmediği sürece, unconscious devrilmez.\nYaratık, yeni formunun doğası gereği yapabileceği eylemlerle sınırlıdır ve yeni formu bu tür eylemlere muktedir olmadığı sürece konuşamaz, büyü yapamaz, el veya konuşma gerektiren başka bir eylemde bulunamaz.\nHedefin donanımı yeni forma dönüşür. Yaratık, ekipmanlarından herhangi birini etkinleştiremez, kullanamaz, kullanamaz veya başka bir şekilde yararlanamaz.\n***Nesneden Yaratığa.*** Yaratığın boyutu nesnenin boyutundan büyük olmadığı ve yaratığın zorluk derecesi 9 veya daha düşük olduğu sürece bir nesneyi herhangi bir tür yaratığa dönüştürebilirsiniz. Yaratık size ve arkadaşlarınıza dosttur. Her dönüşünüzde hareket eder. Hangi eylemi gerçekleştireceğine ve nasıl hareket edeceğine siz karar verirsiniz. GM, yaratığın istatistiklerine sahiptir ve onun tüm eylemlerini ve hareketlerini çözer.\nBüyü kalıcı hale gelirse, artık yaratığı kontrol edemezsiniz. Ona nasıl davrandığınıza bağlı olarak size dost kalabilir.\n***Yaratık Nesneye Dönüşür.*** Bir canlıyı nesneye dönüştürürseniz, giydiği, taşıdığı her şeyle birlikte o forma dönüşür. Yaratığın istatistikleri nesnenin istatistikleri haline gelir ve büyü sona erdikten ve normal formuna döndükten sonra yaratığın bu formda geçirdiği zamana dair hiçbir hafızası kalmaz.","higher":"","sourceText":"Choose one creature or nonmagical object that you can see within range. You transform the creature into a different creature, the creature into an object, or the object into a creature (the object must be neither worn nor carried by another creature). The transformation lasts for the duration, or until the target drops to 0 hit points or dies. If you concentrate on this spell for the full duration, the transformation becomes permanent.\n\nShapechangers aren't affected by this spell. An unwilling creature can make a wisdom saving throw, and if it succeeds, it isn't affected by this spell.\n\n***Creature into Creature.*** If you turn a creature into another kind of creature, the new form can be any kind you choose whose challenge rating is equal to or less than the target's (or its level, if the target doesn't have a challenge rating). The target's game statistics, including mental ability scores, are replaced by the statistics of the new form. It retains its alignment and personality.\n\nThe target assumes the hit points of its new form, and when it reverts to its normal form, the creature returns to the number of hit points it had before it transformed. If it reverts as a result of dropping to 0 hit points, any excess damage carries over to its normal form. As long as the excess damage doesn't reduce the creature's normal form to 0 hit points, it isn't knocked unconscious.\n\nThe creature is limited in the actions it can perform by the nature of its new form, and it can't speak, cast spells, or take any other action that requires hands or speech unless its new form is capable of such actions.\n\nThe target's gear melds into the new form. The creature can't activate, use, wield, or otherwise benefit from any of its equipment.\n\n***Object into Creature.*** You can turn an object into any kind of creature, as long as the creature's size is no larger than the object's size and the creature's challenge rating is 9 or lower. The creature is friendly to you and your companions. It acts on each of your turns. You decide what action it takes and how it moves. The GM has the creature's statistics and resolves all of its actions and movement.\n\nIf the spell becomes permanent, you no longer control the creature. It might remain friendly to you, depending on how you have treated it.\n\n***Creature into Object.*** If you turn a creature into an object, it transforms along with whatever it is wearing and carrying into that form. The creature's statistics become those of the object, and the creature has no memory of time spent in this form, after the spell ends and it returns to its normal form.","higherSource":""},{"id":"true-resurrection","name":"True Resurrection","nameTr":"Gerçek Diriliş","level":9,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Cleric","Druid"],"subclasses":[],"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Büyünün tükettiği, en az 25.000 gp değerinde kutsal su ve elmas serpintisi.","materialSource":"A sprinkle of holy water and diamonds worth at least 25,000gp, which the spell consumes.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Henüz 200 yıldır ölü olan ve yaşlılık dışında herhangi bir nedenle ölen bir canlıya dokunuyorsunuz. Eğer yaratığın ruhu özgür ve istekliyse, yaratık tüm HP ile hayata döndürülür.\nBu büyü tüm yaraları kapatır, tüm poison'yi etkisiz hale getirir, tüm hastalıkları iyileştirir ve yaratık öldüğünde onu etkileyen tüm lanetleri kaldırır. Büyü, hasarlı veya eksik organların ve uzuvların yerini alır.\nOrijinal beden artık mevcut değilse, büyü yeni bir beden bile sağlayabilir; bu durumda yaratığın adını söylemeniz gerekir. Yaratık daha sonra 10 ft içinde seçtiğiniz boş bir alanda belirir.","higher":"","sourceText":"You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature's soul is free and willing, the creature is restored to life with all its hit points.\n\nThis spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs.\n\nThe spell can even provide a new body if the original no longer exists, in which case you must speak the creature's name. The creature then appears in an unoccupied space you choose within 10 feet of you.","higherSource":""},{"id":"true-seeing","name":"True Seeing","nameTr":"Gerçek Görme","level":6,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"25 gp'ye mal olan gözler için bir merhem; mantar tozu, safran ve yağdan yapılır; ve büyü tarafından tüketilir.","materialSource":"An ointment for the eyes that costs 25gp; is made from mushroom powder, saffron, and fat; and is consumed by the spell.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, dokunduğunuz istekli yaratığa, her şeyi gerçekte olduğu gibi görme yeteneği verir. Bu süre boyunca yaratık gerçek görüşe sahip olur, büyüyle gizlenmiş gizli kapıları fark eder ve 120 ft menziline kadar Ethereal Plane'ın içini görebilir.","higher":"","sourceText":"This spell gives the willing creature you touch the ability to see things as they actually are. For the duration, the creature has truesight, notices secret doors hidden by magic, and can see into the Ethereal Plane, all out to a range of 120 feet.","higherSource":""},{"id":"true-strike","name":"True Strike","nameTr":"Gerçek Saldırı","level":0,"school":"Divination","schoolTr":"Kehanet","classes":["Bard","Sorcerer","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"30 feet","duration":"Up to 1 round","concentration":true,"ritual":false,"components":["S"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Elinizi uzatırsınız ve parmağınızı menzildeki bir hedefe doğrultursunuz. Büyünüz size hedefin savunması hakkında kısa bir fikir verir. Bir sonraki turunuzda, bu büyünün sona ermemesi koşuluyla, hedefe karşı ilk saldırı zarı'nizde avantaj kazanırsınız.","higher":"","sourceText":"You extend your hand and point a finger at a target in range. Your magic grants you a brief insight into the target's defenses. On your next turn, you gain advantage on your first attack roll against the target, provided that this spell hasn't ended.","higherSource":""},{"id":"unseen-servant","name":"Unseen Servant","nameTr":"Görünmeyen Hizmetçi","level":1,"school":"Conjuration","schoolTr":"Çağırma","classes":["Bard","Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"60 feet","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir parça ip ve bir parça tahta.","materialSource":"A piece of string and a bit of wood.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, büyü bitene kadar emrinizde basit görevleri yerine getiren, akılsız, şekilsiz bir invisible force yaratır. Hizmetçi, menzil içinde yerdeki boş bir alanda var olur. AC 10, 1 can puanı ve STR 2'ye sahiptir ve saldıramaz. 0 HP'ye düşerse büyü sona erer.\nBir Bonus Action olarak her sıranızda, hizmetkarınıza 15 ft'ye gitmesini ve bir nesneyle etkileşime geçmesini zihinsel olarak emredebilirsiniz. Hizmetçi, bir insan hizmetçinin yapabileceği, bir şeyler getirmek, temizlik yapmak, onarmak, kıyafetleri katlamak, ateş yakmak, yemek servisi yapmak ve şarap dökmek gibi basit görevleri yerine getirebilir. Komutu verdiğinizde hizmetçi, görevi tamamlayana kadar elinden gelen en iyi şekilde yerine getirir ve ardından bir sonraki emrinizi bekler.\nHizmetçiye onu sizden 60 ft'den daha fazla uzaklaştıracak bir görevi gerçekleştirmesini emrederseniz büyü sona erer.","higher":"","sourceText":"This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends.\n\nOnce on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\n\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends.","higherSource":""},{"id":"vampiric-touch","name":"Vampiric Touch","nameTr":"Vampir Dokunuşu","level":3,"school":"Necromancy","schoolTr":"Nekromansi","classes":["Warlock","Wizard"],"subclasses":["Lore"],"castingTime":"1 action","range":"Self","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"melee","save":"","saves":[],"saveSuccess":"","area":null,"description":"Gölgelerle kaplı elinizin dokunuşu, yaralarınızı iyileştirmek için başkalarının hayatını çekebilir force. Ulaşabileceğiniz bir yaratığa karşı yakın spell attack yapın. Bir vuruşta hedef 3d6 necrotic hasarı alır ve verilen necrotic hasarının yarısı kadar HP'yi yeniden kazanırsınız. Büyü bitene kadar her turda bir eylem olarak tekrar saldırı yapabilirsiniz.","higher":"Bu büyüyü 4. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 3. seviyenin üzerindeki her yuva seviyesi için 1d6 artar.","sourceText":"The touch of your shadow-wreathed hand can siphon life force from others to heal your wounds. Make a melee spell attack against a creature within your reach. On a hit, the target takes 3d6 necrotic damage, and you regain hit points equal to half the amount of necrotic damage dealt. Until the spell ends, you can make the attack again on each of your turns as an action.","higherSource":"When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 for each slot level above 3rd."},{"id":"vicious-mockery","name":"Vicious Mockery","nameTr":"Kötü Alay","level":0,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard"],"subclasses":[],"castingTime":"1 action","range":"60 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":null,"description":"Menzilde görebileceğiniz bir yaratığa incelikli büyülerle süslenmiş bir dizi hakaret yağdırırsınız. Hedef sizi duyabiliyorsa (ancak sizi anlamasına gerek yok), WIS saving throw'de başarılı olmalı veya 1d4 psychic hasarı almalı ve bir sonraki adımda dezavantaj'ye sahip olmalıdır. saldırı zarı bir sonraki turun bitiminden önce yapar.\nBu büyünün hasarı, 5. seviyeye (2d4), 11. seviyeye (3d4) ve 17. seviyeye (4d4) ulaştığınızda 1d4 artar.","higher":"","sourceText":"You unleash a string of insults laced with subtle enchantments at a creature you can see within range. If the target can hear you (though it need not understand you), it must succeed on a wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn.\n\nThis spell's damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4).","higherSource":""},{"id":"wall-of-fire","name":"Wall of Fire","nameTr":"Ateş Duvarı","level":4,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":["Fiend"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir fosfor parçası.","materialSource":"A small piece of phosphorus.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"line","size":60},"description":"Menzil dahilindeki katı bir yüzey üzerinde fire'den bir duvar oluşturursunuz. Duvarı 60 ft uzunluğunda, 20 ft yüksekliğinde ve 1 ft kalınlığında veya 20 ft çapında, 20 ft yüksekliğinde halkalı bir duvar yapabilirsiniz. 1 ft kalın. Duvar opaktır ve süre boyunca dayanır.\nDuvar göründüğünde, bölgesindeki her canlı bir DEX saving throw yapmalıdır. başarısız save’de, bir yaratık 5d8 fire hasar alır veya başarılı save’de yarısı kadar hasar alır.\nBu büyüyü yaptığınızda duvarın sizin tarafınızdan seçilen bir tarafı, o tarafın 10 ft içinde veya duvarın içinde sırasını bitiren her yaratığa 5d8 fire hasar verir. Bir yaratık bir dönüşte ilk kez duvara girdiğinde veya sırasını burada bitirdiğinde aynı hasarı alır. Duvarın diğer tarafı hasar vermez.\nDuvarın diğer tarafı hasar vermez.","higher":"Bu büyüyü 5. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, hasar 4. seviyenin üzerindeki her yuva seviyesi için 1d8 artar.","sourceText":"You create a wall of fire on a solid surface within range. You can make the wall up to 60 feet long, 20 feet high, and 1 foot thick, or a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall is opaque and lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a Dexterity saving throw. On a failed save, a creature takes 5d8 fire damage, or half as much damage on a successful save.\n\nOne side of the wall, selected by you when you cast this spell, deals 5d8 fire damage to each creature that ends its turn within 10 feet o f that side or inside the wall. A creature takes the same damage when it enters the wall for the first time on a turn or ends its turn there. The other side of the wall deals no damage.\n\nThe other side of the wall deals no damage.","higherSource":"When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d8 for each slot level above 4th."},{"id":"wall-of-force","name":"Wall of Force","nameTr":"Güç Duvarı","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Berrak bir değerli taşın ezilmesiyle elde edilen bir tutam toz.","materialSource":"A pinch of powder made by crushing a clear gemstone.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"invisible force duvarı, menzil içinde seçtiğiniz bir noktada ortaya çıkar. Duvar, seçtiğiniz herhangi bir yönde, yatay veya dikey bariyer olarak veya açılı olarak görünür. Serbest yüzebilir veya katı bir yüzey üzerinde durabilir. Bunu yarı küresel bir kubbe veya 10 ft'ye kadar yarıçaplı bir küre şeklinde oluşturabilir veya on adet 10 ft-by-10 ft panelden oluşan düz bir yüzey şekillendirebilirsiniz. Her panel başka bir panelle bitişik olmalıdır. Herhangi bir biçimde duvar 1/4 inç kalınlığındadır. Süresi boyunca devam eder. Duvar, ortaya çıktığında bir yaratığın alanını keserse, yaratık duvarın bir tarafına itilir (hangi tarafa sizin seçiminiz).\nHiçbir şey fiziksel olarak duvardan geçemez. Tüm hasarlara karşı bağışıklıdır ve etkisizleştirme büyüsüyle ortadan kaldırılamaz. Ancak parçalayıcı bir büyü duvarı anında yok eder. Duvar aynı zamanda Eterik Düzlem'e kadar uzanır ve duvar boyunca ruhani yolculuğu engeller.","higher":"","sourceText":"An invisible wall of force springs into existence at a point you choose within range. The wall appears in any orientation you choose, as a horizontal or vertical barrier or at an angle. It can be free floating or resting on a solid surface. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-by-10-foot panels. Each panel must be contiguous with another panel. In any form, the wall is 1/4 inch thick. It lasts for the duration. If the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice which side).\n\nNothing can physically pass through the wall. It is immune to all damage and can't be dispelled by dispel magic. A disintegrate spell destroys the wall instantly, however. The wall also extends into the Ethereal Plane, blocking ethereal travel through the wall.","higherSource":""},{"id":"wall-of-ice","name":"Wall of Ice","nameTr":"Buz Duvarı","level":6,"school":"Evocation","schoolTr":"Yıkım","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir kuvars parçası.","materialSource":"A small piece of quartz.","attackType":"","save":"DEX","saves":["DEX","CON"],"saveSuccess":"half","area":{"type":"sphere","size":10},"description":"Menzil içindeki katı bir yüzey üzerinde buzdan bir duvar oluşturursunuz. Bunu yarı küresel bir kubbe veya yarıçapı 10 ft'ye kadar olan bir küre şeklinde oluşturabilir veya on adet 10 ft kare panelden oluşan düz bir yüzey şekillendirebilirsiniz. Her panel başka bir panelle bitişik olmalıdır. Hangi biçimde olursa olsun, duvar 1 ft kalınlığındadır ve bu süre boyunca dayanır.\nDuvar, ortaya çıktığında bir yaratığın alanını keserse, alanı içindeki yaratık duvarın bir tarafına itilir ve bir DEX saving throw yapması gerekir. başarısız save’de, yaratık 10d6 cold hasar alır, ya da başarılı save’de yarısı kadar hasar alır.\nDuvar hasar görebilecek ve dolayısıyla delinebilecek bir nesnedir. 10 ft bölümü başına AC 12 ve 30 HP'ye sahiptir ve fire hasarına karşı savunmasızdır. Duvarın 10 ft bölümünü 0 HP'ye düşürmek onu yok eder ve duvarın kapladığı alanda arkasında soğuk bir hava tabakası bırakır. Soğuk hava tabakasında ilk kez bir dönüş yaparak hareket eden bir yaratığın bir CON saving throw yapması gerekir. Bu yaratık, başarısız save’de 5d6 cold hasar alır veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, göründüğünde duvarın verdiği hasar 2d6 artar ve 6. seviyenin üzerindeki her yuva seviyesi için soğuk hava tabakasından geçmenin verdiği hasar 1d6 artar.","sourceText":"You create a wall of ice on a solid surface within range. You can form it into a hemispherical dome or a sphere with a radius of up to 10 feet, or you can shape a flat surface made up of ten 10-foot-square panels. Each panel must be contiguous with another panel. In any form, the wall is 1 foot thick and lasts for the duration.\n\nIf the wall cuts through a creature's space when it appears, the creature within its area is pushed to one side of the wall and must make a dexterity saving throw. On a failed save, the creature takes 10d6 cold damage, or half as much damage on a successful save.\n\nThe wall is an object that can be damaged and thus breached. It has AC 12 and 30 hit points per 10-foot section, and it is vulnerable to fire damage. Reducing a 10-foot section of wall to 0 hit points destroys it and leaves behind a sheet of frigid air in the space the wall occupied. A creature moving through the sheet of frigid air for the first time on a turn must make a constitution saving throw. That creature takes 5d6 cold damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, the damage the wall deals when it appears increases by 2d6, and the damage from passing through the sheet of frigid air increases by 1d6, for each slot level above 6th."},{"id":"wall-of-stone","name":"Wall of Stone","nameTr":"Taş Duvar","level":5,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Sorcerer","Wizard"],"subclasses":["Land"],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Küçük bir granit bloğu.","materialSource":"A small block of granite.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":null,"description":"Menzil içinde seçtiğiniz bir noktada masif taştan sihirli olmayan bir duvar ortaya çıkıyor. Duvar 6 inç kalınlığındadır ve on adet 10 ft-by-10 ft panelden oluşur. Her panel en az bir diğer panelle bitişik olmalıdır. Alternatif olarak, yalnızca 3 inç kalınlığında 10 ft-by-20 ft panelleri oluşturabilirsiniz.\nDuvar, bir yaratığın ortaya çıktığı alanı keserse, yaratık duvarın bir tarafına itilir (seçiminiz). Bir canlının her tarafı duvarla (veya duvarla ve başka bir katı yüzeyle) çevrelenmişse, o yaratık bir DEX saving throw yapabilir. Başarılı olursa Reaction'yi kullanarak hızına ulaşabilir ve artık duvarlarla çevrili kalmaz.\nDuvar istediğiniz herhangi bir şekle sahip olabilir ancak bir yaratık veya nesneyle aynı alanı kaplayamaz. Duvarın dikey olmasına veya herhangi bir sağlam temele dayanmasına gerek yoktur. Ancak mevcut taşla birleşmeli ve sağlam bir şekilde desteklenmelidir. Böylece bu büyüyü bir uçurumu kapatmak veya bir rampa oluşturmak için kullanabilirsiniz.\nUzunluğu 20 ft'den daha uzun bir açıklık oluşturursanız, destek oluşturmak için her panelin boyutunu yarıya indirmeniz gerekir. Mazgallar, siperler vb. oluşturmak için duvarı kabaca şekillendirebilirsiniz.\nDuvar, hasar görebilecek ve dolayısıyla delinebilecek taştan yapılmış bir nesnedir. Her panelde inç kalınlık başına AC 15 ve 30 HP bulunur. Bir paneli 0 HP'ye düşürmek onu yok eder ve GM'nin takdirine bağlı olarak bağlı panellerin çökmesine neden olabilir.\nconcentration'nizi bu büyünün tüm süresi boyunca sürdürürseniz duvar kalıcı hale gelir ve ortadan kaldırılamaz. Aksi halde büyü bittiğinde duvar ortadan kaybolur.","higher":"","sourceText":"A nonmagical wall of solid stone springs into existence at a point you choose within range. The wall is 6 inches thick and is composed of ten 10-foot-by-10-foot panels. Each panel must be contiguous with at least one other panel. Alternatively, you can create 10-foot-by-20-foot panels that are only 3 inches thick.\n\nIf the wall cuts through a creature's space when it appears, the creature is pushed to one side of the wall (your choice). If a creature would be surrounded on all sides by the wall (or the wall and another solid surface), that creature can make a dexterity saving throw. On a success, it can use its reaction to move up to its speed so that it is no longer enclosed by the wall.\n\nThe wall can have any shape you desire, though it can't occupy the same space as a creature or object. The wall doesn't need to be vertical or rest on any firm foundation. It must, however, merge with and be solidly supported by existing stone. Thus, you can use this spell to bridge a chasm or create a ramp.\n\nIf you create a span greater than 20 feet in length, you must halve the size of each panel to create supports. You can crudely shape the wall to create crenellations, battlements, and so on.\n\nThe wall is an object made of stone that can be damaged and thus breached. Each panel has AC 15 and 30 hit points per inch of thickness. Reducing a panel to 0 hit points destroys it and might cause connected panels to collapse at the GM's discretion.\n\nIf you maintain your concentration on this spell for its whole duration, the wall becomes permanent and can't be dispelled. Otherwise, the wall disappears when the spell ends.","higherSource":""},{"id":"wall-of-thorns","name":"Wall of Thorns","nameTr":"Dikenler Duvarı","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Druid"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 10 minutes","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Bir avuç diken.","materialSource":"A handful of thorns.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"half","area":{"type":"line","size":60},"description":"İğne keskinliğinde dikenlerle dolu, sert, esnek, birbirine dolanmış fırçalardan bir duvar yaratırsınız. Duvar, katı bir yüzey üzerinde menzil dahilinde görünür ve bu süre boyunca varlığını sürdürür. Duvarı 60 ft uzunluğunda, 10 ft yüksekliğinde ve 5 ft kalınlığında veya 20 ft çapına sahip ve 20 ft yüksekliğinde bir daire yapmayı seçersiniz ve 5 ft kalın. Duvar görüş alanını kapatıyor.\nDuvar göründüğünde, bölgesindeki her canlı bir DEX saving throw yapmalıdır. başarısız save’de, bir yaratık 7d8 piercing hasar alır, ya da başarılı save’de yarısı kadar hasar alır.\nBir yaratık yavaş ve acı verici de olsa duvarın içinden geçebilir. Bir yaratığın duvarda hareket ettiği her 1 ft için 4 ft hareket harcaması gerekir. Ayrıca, bir yaratık ilk kez bir dönüşte duvara girdiğinde veya sırasını orada bitirdiğinde, yaratığın bir DEX saving throw yapması gerekir. başarısız save’de 7d8 slashing hasar alır veya başarılı save’de yarısı kadar hasar alır.","higher":"Bu büyüyü 7. seviye veya daha yüksek bir spell slot kullanarak yaptığınızda, 6. seviyenin üzerindeki her slot seviyesi için her iki hasar türü de 1d8 artar.","sourceText":"You create a wall of tough, pliable, tangled brush bristling with needle-sharp thorns. The wall appears within range on a solid surface and lasts for the duration. You choose to make the wall up to 60 feet long, 10 feet high, and 5 feet thick or a circle that has a 20-foot diameter and is up to 20 feet high and 5 feet thick. The wall blocks line of sight.\n\nWhen the wall appears, each creature within its area must make a dexterity saving throw. On a failed save, a creature takes 7d8 piercing damage, or half as much damage on a successful save.\n\nA creature can move through the wall, albeit slowly and painfully. For every 1 foot a creature moves through the wall, it must spend 4 feet of movement. Furthermore, the first time a creature enters the wall on a turn or ends its turn there, the creature must make a dexterity saving throw. It takes 7d8 slashing damage on a failed save, or half as much damage on a successful one.","higherSource":"When you cast this spell using a spell slot of 7th level or higher, both types of damage increase by 1d8 for each slot level above 6th."},{"id":"warding-bond","name":"Warding Bond","nameTr":"Muhafaza Tahvili","level":2,"school":"Abjuration","schoolTr":"Koruma","classes":["Cleric"],"subclasses":["Lore"],"castingTime":"1 action","range":"Touch","duration":"1 hour","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"Her biri en az 50gp değerinde olan ve sizin ve hedefin bu süre boyunca takması gereken bir çift platin yüzük.","materialSource":"A pair of platinum rings worth at least 50gp each, which you and the target must wear for the duration.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, dokunduğunuz istekli bir yaratığı korur ve büyü bitene kadar sizinle hedef arasında mistik bir bağlantı oluşturur. Hedef 60 ft yakınınızdayken AC ve saving throw’lar'ye +1 bonus kazanır ve tüm hasarlara karşı dirence sahiptir. Ayrıca her hasar aldığında aynı miktarda hasar alırsınız.\nHP 0'a düşerseniz veya siz ve hedef 60 ft'den daha fazla farkla ayrılırsanız büyü sona erer.\nBüyünün bağlı yaratıklardan herhangi birine tekrar yapılması durumunda da sona erer. Ayrıca büyüyü bir eylem olarak da reddedebilirsiniz.","higher":"","sourceText":"This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\n\nThe spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet.\n\nIt also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action.","higherSource":""},{"id":"water-breathing","name":"Water Breathing","nameTr":"Su Solunumu","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid","Ranger","Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"30 feet","duration":"24 hours","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Kısa bir kamış veya saman parçası.","materialSource":"A short piece of reed or straw.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, menzil içinde bulunan ve görebileceğiniz en fazla on istekli yaratığa, süresi sonuna kadar su altında nefes alma yeteneği verir. Etkilenen canlılar aynı zamanda normal nefes alma düzenlerini de korurlar.","higher":"","sourceText":"This spell gives a maximum of ten willing creatures within range and you can see, the ability to breathe underwater until the end of its term. Affected creatures also retain their normal breathing pattern.","higherSource":""},{"id":"water-walk","name":"Water Walk","nameTr":"Su Yürüyüşü","level":3,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Cleric","Druid","Ranger","Sorcerer"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"30 feet","duration":"1 hour","concentration":false,"ritual":true,"components":["V","S","M"],"materialTr":"Bir parça mantar.","materialSource":"A piece of cork.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Bu büyü, su, acid, çamur, kar, bataklık kumu veya lav gibi herhangi bir sıvı yüzey üzerinde sanki zararsız katı bir zeminmiş gibi hareket etme yeteneği sağlar (erimiş lavdan geçen yaratıklar yine de ısıdan hasar alabilir). Menzil içinde görebileceğiniz en fazla on istekli yaratık, bu süre boyunca bu yeteneği kazanır.\nSıvıya batırılmış bir yaratığı hedef alırsanız büyü, tur başına 60 ft oranında hedefi sıvının yüzeyine taşır.","higher":"","sourceText":"This spell grants the ability to move across any liquid surface--such as water, acid, mud, snow, quicksand, or lava--as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration.\n\nIf you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round.","higherSource":""},{"id":"web","name":"Web","nameTr":"ağ","level":2,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Wizard"],"subclasses":["Land","Lore"],"castingTime":"1 action","range":"60 feet","duration":"Up to 1 hour","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Biraz örümcek ağı.","materialSource":"A bit of spiderweb.","attackType":"","save":"DEX","saves":["DEX"],"saveSuccess":"","area":{"type":"cube","size":20},"description":"Menzil dahilinde seçtiğiniz bir noktada kalın, yapışkan bir ağ oluşturursunuz. Ağlar bu süre boyunca bir 20 ft küpünü bu noktadan doldurur. Ağlar zorlu arazilerdir ve alanlarını hafifçe gizlerler.\nAğlar iki katı kütle (duvarlar veya ağaçlar gibi) arasına sabitlenmezse veya bir zemin, duvar veya tavan boyunca katmanlı değilse, oluşturulan ağ kendi üzerine çöker ve büyü bir sonraki turunuzun başlangıcında sona erer. Düz bir yüzey üzerinde katmanlanan ağların derinliği 5 ft'dir.\nAğlarda sırasını başlatan veya sırası geldiğinde ağlara giren her canlı, bir DEX saving throw yapmalıdır. Başarısız bir kaydetme durumunda yaratık, ağlarda kaldığı sürece veya serbest kalana kadar restrained olur.\nAğlar tarafından oluşturulan restrained yaratık, DC'yi büyü kaydetmenize karşı bir STR kontrolü yapmak için eylemini kullanabilir. Başarılı olursa artık restrained olmaz.\nAğlar yanıcıdır. 5 ft ağ küpü, fire'ye maruz bırakılır ve 1 turda yanar ve 2d4 fire, fire'de sırasını başlatan herhangi bir yaratığa hasar verir.","higher":"","sourceText":"You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.\n\nIf the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.\n\nEach creature that starts its turn in the webs or that enters them during its turn must make a dexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.\n\nA creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\n\nThe webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire.","higherSource":""},{"id":"weird","name":"Weird","nameTr":"Garip","level":9,"school":"Illusion","schoolTr":"İllüzyon","classes":["Wizard"],"subclasses":[],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"WIS","saves":["WIS"],"saveSuccess":"none","area":{"type":"sphere","size":30},"description":"Bir grup yaratığın en derin korkularından yararlanarak, onların zihinlerinde yalnızca onların görebileceği hayali yaratıklar yaratırsınız. Menzil dahilinde seçtiğiniz bir noktaya merkezlenen 30 ft yarıçap küresindeki her yaratık, bir WIS saving throw yapmalıdır. Başarısız bir kaydetme durumunda yaratık, bu süre boyunca frightened olur. İllüzyon, yaratığın en derin korkularını çağırıyor ve en kötü kabuslarını amansız bir tehdit olarak ortaya koyuyor. frightened yaratığın her dönüşünün başlangıcında, bir WIS saving throw üzerinde başarılı olmalı veya 4d10 psychic hasarı almalıdır. Başarılı bir kurtarmanın ardından o yaratığın büyüsü sona erer.","higher":"","sourceText":"Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds, visible only to them. Each creature in a 30-foot-radius sphere centered on a point of your choice within range must make a wisdom saving throw. On a failed save, a creature becomes frightened for the duration. The illusion calls on the creature's deepest fears, manifesting its worst nightmares as an implacable threat. At the start of each of the frightened creature's turns, it must succeed on a wisdom saving throw or take 4d10 psychic damage. On a successful save, the spell ends for that creature.","higherSource":""},{"id":"wind-walk","name":"Wind Walk","nameTr":"Rüzgar Yürüyüşü","level":6,"school":"Transmutation","schoolTr":"Dönüşüm","classes":["Druid"],"subclasses":[],"castingTime":"1 minute","range":"30 feet","duration":"8 hours","concentration":false,"ritual":false,"components":["V","S","M"],"materialTr":"fire ve kutsal su.","materialSource":"Fire and holy water.","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Siz ve menzil içinde görebileceğiniz on kadar istekli yaratık, bu süre boyunca gaz halinde bir forma bürünür ve bulut tutamları gibi görünür. Bu bulut formundayken, bir yaratığın uçma hızı 300 ft'dir ve büyülü olmayan silahların vereceği hasara karşı dirence sahiptir. Bir yaratığın bu formda yapabileceği tek eylem, Dash eylemi veya normal formuna dönmektir. Geri dönüş 1 dakika sürer; bu süre zarfında yaratık incapacitated olur ve hareket edemez. Büyü sona erene kadar yaratık bulut formuna dönebilir ve bu da 1 dakikalık dönüşüm gerektirir.\nEtki sona erdiğinde bir yaratık bulut formundaysa ve uçuyorsa, yaratık yere inene kadar her turda 1 dakika boyunca 60 ft alçalır ve bunu güvenli bir şekilde yapar. 1 dakika sonunda yere inemezse yaratık kalan mesafeye düşer.","higher":"","sourceText":"You and up to ten willing creatures you can see within range assume a gaseous form for the duration, appearing as wisps of cloud. While in this cloud form, a creature has a flying speed of 300 feet and has resistance to damage from nonmagical weapons. The only actions a creature can take in this form are the Dash action or to revert to its normal form. Reverting takes 1 minute, during which time a creature is incapacitated and can't move. Until the spell ends, a creature can revert to cloud form, which also requires the 1-minute transformation.\n\nIf a creature is in cloud form and flying when the effect ends, the creature descends 60 feet per round for 1 minute until it lands, which it does safely. If it can't land after 1 minute, the creature falls the remaining distance.","higherSource":""},{"id":"wind-wall","name":"Wind Wall","nameTr":"Rüzgar Duvarı","level":3,"school":"Evocation","schoolTr":"Yıkım","classes":["Druid","Ranger"],"subclasses":["Lore"],"castingTime":"1 action","range":"120 feet","duration":"Up to 1 minute","concentration":true,"ritual":false,"components":["V","S","M"],"materialTr":"Minik bir yelpaze ve egzotik kökenli bir tüy.","materialSource":"A tiny fan and a feather of exotic origin.","attackType":"","save":"STR","saves":["STR"],"saveSuccess":"half","area":{"type":"line","size":50},"description":"Menzil içinde seçtiğiniz bir noktada yerden kuvvetli bir rüzgar duvarı yükseliyor. Duvarı 50 ft uzunluğa, 15 ft yüksekliğe ve 1 ft kalınlığa kadar yapabilirsiniz. Zemin boyunca sürekli bir yol oluşturduğu sürece duvarı istediğiniz şekilde şekillendirebilirsiniz. Duvar bu süre boyunca dayanır.\nDuvar göründüğünde, bölgesindeki her canlı bir STR saving throw yapmalıdır. Bir yaratık, başarısız save’de 3d8 bludgeoning hasar alır veya başarılı save’de bunun yarısı kadar hasar alır.\nGüçlü rüzgar sisi, dumanı ve diğer gazları uzakta tutar. Küçük veya daha küçük uçan yaratıklar veya nesneler duvardan geçemez. Duvara getirilen gevşek, hafif malzemeler yukarı doğru uçar. Duvarın arkasındaki hedeflere fırlatılan oklar, cıvatalar ve diğer sıradan mermiler yukarı doğru saptırılır ve otomatik olarak ıskalanır. (Devlerin veya kuşatma makinelerinin fırlattığı kayalar ve benzeri mermiler etkilenmez.) Gaz halindeki canlılar buradan geçemez.","higher":"","sourceText":"A wall of strong wind rises from the ground at a point you choose within range. You can make the wall up to 50 feet long, 15 feet high, and 1 foot thick. You can shape the wall in any way you choose so long as it makes one continuous path along the ground. The wall lasts for the duration.\n\nWhen the wall appears, each creature within its area must make a strength saving throw. A creature takes 3d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nThe strong wind keeps fog, smoke, and other gases at bay. Small or smaller flying creatures or objects can't pass through the wall. Loose, lightweight materials brought into the wall fly upward. Arrows, bolts, and other ordinary projectiles launched at targets behind the wall are deflected upward and automatically miss. (Boulders hurled by giants or siege engines, and similar projectiles, are unaffected.) Creatures in gaseous form can't pass through it.","higherSource":""},{"id":"wish","name":"Wish","nameTr":"Dilek","level":9,"school":"Conjuration","schoolTr":"Çağırma","classes":["Sorcerer","Wizard"],"subclasses":[],"castingTime":"1 action","range":"Self","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":null,"description":"Dilek, ölümlü bir yaratığın yapabileceği en güçlü büyüdür. Sadece yüksek sesle konuşarak gerçekliğin temellerini arzularınıza göre değiştirebilirsiniz.\nBu büyünün temel kullanımı, 8. seviye veya daha düşük herhangi bir büyüyü çoğaltmaktır. Bu büyüde, pahalı bileşenler de dahil olmak üzere herhangi bir gereksinimi karşılamanıza gerek yoktur. Büyü basitçe etkili olur.\nAlternatif olarak aşağıdaki efektlerden dilediğinizi oluşturabilirsiniz:\n- Sihirli bir öğe olmayan, değeri 25.000 gp'ye kadar olan bir nesne yaratırsınız. Nesne herhangi bir boyutta 300 ft'den fazla olamaz ve yerde görebileceğiniz boş bir alanda görünür.\n- Görebildiğiniz en fazla yirmi yaratığın tüm HP'yi geri kazanmasına izin verirsiniz ve onlar üzerinde daha büyük yenileme büyüsünde açıklanan tüm etkileri sona erdirirsiniz.\n- Seçtiğiniz hasar türüne karşı direnci görebileceğiniz en fazla on yaratığa hak verirsiniz.\n- Görebildiğiniz en fazla on yaratığa 8 saat boyunca tek bir büyüye veya başka bir büyülü etkiye karşı bağışıklık kazandırırsınız. Örneğin, kendinizi ve tüm arkadaşlarınızı bir lich'in can tüketen saldırısına karşı bağışık hale getirebilirsiniz.\n- Son turda (son turunuz dahil) yapılan herhangi bir zarın yeniden atılmasını zorlayarak yakın zamanda gerçekleşen tek bir olayı geri alırsınız. Gerçeklik, yeni sonuca uyum sağlamak için kendini yeniden şekillendirir. Örneğin bir dilek büyüsü, rakibin başarılı kurtarmasını, düşmanın kritik vuruşunu veya bir arkadaşının başarısız kurtarmasını geri alabilir. force avantaj veya dezavantaj ile yapılacak yeniden ruloyu force yapabilirsiniz ve yeniden ruloyu veya orijinal ruloyu kullanmayı seçebilirsiniz.\nYukarıdaki örneklerin kapsamının ötesinde bir şey başarabilirsiniz. GM'ye isteğinizi mümkün olduğunca açık bir şekilde belirtin. GM böyle bir durumda ne olacağına karar verme konusunda büyük bir serbestliğe sahiptir; Dilek ne kadar büyük olursa, bir şeylerin ters gitme olasılığı da o kadar artar. Bu büyü başarısız olabilir, istediğiniz etki yalnızca kısmen elde edilebilir veya dileğinizi nasıl ifade ettiğinizin bir sonucu olarak öngörülemeyen bazı sonuçlara maruz kalabilirsiniz. Örneğin, bir kötü adamın ölmesini dilemek sizi zamanda ileriye doğru, o kötü adamın artık hayatta olmadığı bir döneme itebilir ve bu da sizi etkili bir şekilde oyundan uzaklaştırabilir. Benzer şekilde, efsanevi bir büyülü eşyayı veya eseri arzulamak sizi anında eşyanın mevcut sahibinin huzuruna taşıyabilir.\nBaşka bir büyüyü kopyalamaktan başka bir etki yaratmak için bu büyüyü yapmanın stresi sizi zayıflatır. Bu strese katlandıktan sonra, uzun bir dinlenmeyi bitirene kadar her büyü yaptığınızda, o büyünün seviyesi başına 1d10 necrotic hasar alırsınız. Bu zarar hiçbir şekilde azaltılamaz veya önlenemez. Ayrıca STR'niz, 2d4 günleri boyunca 3 veya daha düşük değilse 3'e düşer. Dinlenerek ve hafif aktivite dışında hiçbir şey yapmayarak geçirdiğiniz her gün için, kalan iyileşme süreniz 2 gün azalır. Son olarak, eğer bu strese maruz kalırsanız bir daha dilek tutamama ihtimaliniz yüzde 33'tür.","higher":"","sourceText":"Wish is the mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality in accord with your desires.\n\nThe basic use of this spell is to duplicate any other spell of 8th level or lower. You don't need to meet any requirements in that spell, including costly components. The spell simply takes effect.\n\nAlternatively, you can create one of the following effects of your choice:\n\n- You create one object of up to 25,000 gp in value that isn't a magic item. The object can be no more than 300 feet in any dimension, and it appears in an unoccupied space you can see on the ground.\n\n- You allow up to twenty creatures that you can see to regain all hit points, and you end all effects on them described in the greater restoration spell.\n\n- You grant up to ten creatures that you can see resistance to a damage type you choose.\n\n- You grant up to ten creatures you can see immunity to a single spell or other magical effect for 8 hours. For instance, you could make yourself and all your companions immune to a lich's life drain attack.\n\n- You undo a single recent event by forcing a reroll of any roll made within the last round (including your last turn). Reality reshapes itself to accommodate the new result. For example, a wish spell could undo an opponent's successful save, a foe's critical hit, or a friend's failed save. You can force the reroll to be made with advantage or disadvantage, and you can choose whether to use the reroll or the original roll.\n\nYou might be able to achieve something beyond the scope of the above examples. State your wish to the GM as precisely as possible. The GM has great latitude in ruling what occurs in such an instance; the greater the wish, the greater the likelihood that something goes wrong. This spell might simply fail, the effect you desire might only be partly achieved, or you might suffer some unforeseen consequence as a result of how you worded the wish. For example, wishing that a villain were dead might propel you forward in time to a period when that villain is no longer alive, effectively removing you from the game. Similarly, wishing for a legendary magic item or artifact might instantly transport you to the presence of the item's current owner.\n\nThe stress of casting this spell to produce any effect other than duplicating another spell weakens you. After enduring that stress, each time you cast a spell until you finish a long rest, you take 1d10 necrotic damage per level of that spell. This damage can't be reduced or prevented in any way. In addition, your Strength drops to 3, if it isn't 3 or lower already, for 2d4 days. For each of those days that you spend resting and doing nothing more than light activity, your remaining recovery time decreases by 2 days. Finally, there is a 33 percent chance that you are unable to cast wish ever again if you suffer this stress.","higherSource":""},{"id":"word-of-recall","name":"Word of Recall","nameTr":"Geri Çağırma Sözü","level":6,"school":"Conjuration","schoolTr":"Çağırma","classes":["Cleric"],"subclasses":[],"castingTime":"1 action","range":"5 feet","duration":"Instantaneous","concentration":false,"ritual":false,"components":["V"],"materialTr":"","materialSource":"","attackType":"","save":"","saves":[],"saveSuccess":"","area":{"type":"sphere","size":5},"description":"Siz ve 5 ft içindeki en fazla beş istekli yaratık, önceden belirlenmiş bir sığınağa anında ışınlanırsınız. Siz ve sizinle ışınlanan yaratıklar, sığınağınızı hazırlarken belirlediğiniz noktaya en yakın boş alanda görünürsünüz (aşağıya bakın). Bu büyüyü önce bir sığınak hazırlamadan yaparsanız, büyünün hiçbir etkisi olmaz.\nBu büyüyü, tanrınıza adanmış veya onunla güçlü bir şekilde bağlantılı olan bir tapınak gibi bir yerde yaparak bir sığınak belirlemelisiniz. Eğer büyüyü tanrınıza adanmamış bir alanda bu şekilde yapmaya çalışırsanız, büyünün hiçbir etkisi olmaz.","higher":"","sourceText":"You and up to five willing creatures within 5 feet of you instantly teleport to a previously designated sanctuary. You and any creatures that teleport with you appear in the nearest unoccupied space to the spot you designated when you prepared your sanctuary (see below). If you cast this spell without first preparing a sanctuary, the spell has no effect.\n\nYou must designate a sanctuary by casting this spell within a location, such as a temple, dedicated to or strongly linked to your deity. If you attempt to cast the spell in this manner in an area that isn't dedicated to your deity, the spell has no effect.","higherSource":""},{"id":"zone-of-truth","name":"Zone of Truth","nameTr":"Hakikat Bölgesi","level":2,"school":"Enchantment","schoolTr":"Etkileme","classes":["Bard","Cleric","Paladin"],"subclasses":["Devotion","Lore"],"castingTime":"1 action","range":"60 feet","duration":"10 minutes","concentration":false,"ritual":false,"components":["V","S"],"materialTr":"","materialSource":"","attackType":"","save":"CHA","saves":["CHA"],"saveSuccess":"","area":{"type":"sphere","size":15},"description":"Menzil dahilinde seçtiğiniz bir noktaya odaklanan 15 ft yarıçap küresinde aldatmaya karşı koruma sağlayan büyülü bir bölge yaratırsınız. Büyü bitene kadar, bir turda büyü alanına ilk kez giren veya orada dönüşüne başlayan bir yaratığın CHA saving throw yapması gerekir. başarısız save’de, bir yaratık yarıçap içindeyken kasıtlı olarak yalan söyleyemez. Her yaratığın saving throw'de başarılı olup olmadığını biliyorsunuz.\nEtkilenen yaratık büyünün farkındadır ve bu nedenle normalde yalanla yanıt vereceği soruları yanıtlamaktan kaçınabilir. Böyle bir yaratık, gerçeğin sınırları içinde kaldığı sürece cevaplarında kaçamak kalabilir.","higher":"","sourceText":"You create a magical zone that guards against deception in a 15-foot-radius sphere centered on a point of your choice within range. Until the spell ends, a creature that enters the spell's area for the first time on a turn or starts its turn there must make a Charisma saving throw. On a failed save, a creature can't speak a deliberate lie while in the radius. You know whether each creature succeeds or fails on its saving throw.\n\nAn affected creature is aware of the spell and can thus avoid answering questions to which it would normally respond with a lie. Such a creature can remain evasive in its answers as long as it remains within the boundaries of the truth.","higherSource":""}];root.V47_SPELL_SCHOOLS=Object.freeze(schools);root.V47_SCROLL_TABLE=Object.freeze(scrollTable);root.V47_SPELLS=Object.freeze(spells.map(spell=>Object.freeze(spell)));})(typeof window!=='undefined'?window:globalThis);
